-- ============================================================================
-- Launchpad Mini MK3 — native colour driver (optional)
-- ============================================================================
-- midigrid emulates a MONOCHROME grid, so on a launchpad every state shows as
-- one hue at different brightness ("shades of yellow"). This driver talks to a
-- Mini MK3 DIRECTLY in Programmer mode and lights each pad with a real RGB
-- colour, while still feeding pad presses to the same grid_key handler. It
-- takes priority over midigrid when a Mini MK3 is attached; every device call
-- is guarded (pcall) so a missing/renamed/odd device falls back to midigrid/
-- native cleanly — it can't brick. Protocol verified against Novation's
-- "Launchpad Mini MK3 Programmer's Reference" (SysEx, note grid, RGB lighting).

-- SysEx: enter Programmer mode / return to Live (device id 0x0D); RGB LED
-- header (command 0x03) is followed by colourspecs `03 <note> <R> <G> <B>`.
local LP_PROG    = { 0xF0, 0x00, 0x20, 0x29, 0x02, 0x0D, 0x0E, 0x01, 0xF7 }
local LP_LIVE    = { 0xF0, 0x00, 0x20, 0x29, 0x02, 0x0D, 0x0E, 0x00, 0xF7 }
local LP_RGB_HDR = { 0xF0, 0x00, 0x20, 0x29, 0x02, 0x0D, 0x03 }

-- Colour language (two layers, each value 0-127):
--  * LP_HUE — named SEMANTIC colours the draw code asks for BY MEANING via the
--    4th arg of gg:led (red = recording, green = playing, purple = destructive,
--    …). A pad's brightness (0-15) scales the hue's intensity, so a blink or a
--    pulse still reads — and the monome/midigrid path, which ignores the hue
--    arg, still gets sensible brightness. Chosen with the user; tweak freely.
--  * LP_RGB — the fallback for pads drawn with NO hue (spatial things: piano
--    keys, octave pads), coloured by plain brightness.
local LP_HUE = {              -- indexed by LP_HUE_ID
  { 118, 28, 30 },   -- 1  red     recording / write head (STOP pulses it); softer, rose-leaning
  { 28, 120, 42 },   -- 2  green   playing / running / placed step / capture
  { 30, 46, 122 },   -- 3  blue    available / empty / DRY
  { 120, 120, 120 }, -- 4  white   playhead / selection / cursor
  { 122, 104, 26 },  -- 5  yellow  mode selected / queued recall
  { 127, 64, 6 },    -- 6  orange  selected slice
  { 26, 112, 122 },  -- 7  cyan    frozen / held
  { 104, 26, 127 },  -- 8  purple  destructive (clear / chaos) / reverse
  { 26, 100, 104 },  -- 9  teal    active region (window / loop / morph travel)
  { 52, 92, 127 },   -- 10 ice     frozen (a periwinkle blue, apart from the slate "available" blue)
}
local LP_HUE_ID = {
  red = 1, green = 2, blue = 3, white = 4, yellow = 5,
  orange = 6, cyan = 7, purple = 8, teal = 9, ice = 10,
}
local LP_RGB = {              -- brightness-only fallback (uncoloured pads)
  [0] = { 0, 0, 0 },    [1] = { 7, 7, 13 },    [2] = { 14, 14, 28 },
  [3] = { 20, 20, 44 }, [4] = { 34, 34, 48 },  [5] = { 40, 46, 62 },
  [6] = { 46, 58, 74 }, [7] = { 56, 64, 82 },  [8] = { 66, 74, 92 },
  [9] = { 78, 86, 104 },[10] = { 88, 96, 112 },[11] = { 96, 104, 118 },
  [12] = { 104, 110, 120 }, [13] = { 110, 116, 122 }, [14] = { 116, 118, 124 },
  [15] = { 120, 120, 120 },
}

-- the Mini MK3's top-row arrows in Programmer mode (CC numbers)
local LP_UP, LP_DOWN, LP_LEFT, LP_RIGHT = 91, 92, 93, 94

-- triangle wave 0..1 over `p` frames — for the STOP breathing pulse
local function tri(f, p)
  local ph = (f % p) / p
  return ph < 0.5 and ph * 2 or (2 - ph * 2)
end

-- programmer-mode pad note <-> (x,y); y=1 is the TOP row, LP row 8 (notes 81-88)
local function lp_note(x, y) return (9 - y) * 10 + x end
local function lp_xy(note)
  local x, row = note % 10, floor(note / 10)
  if x < 1 or x > 8 or row < 1 or row > 8 then return nil end
  return x, 9 - row
end

-- find the Mini MK3's MIDI (surface) port, NOT the DAW port. ALSA names vary,
-- so match "mk3" + a launchpad marker and prefer the MIDI/2nd interface.
-- `gone`: a device being unplugged. norns runs midi.remove BEFORE it deletes
-- the device from midi.devices, so the search has to skip it by hand.
local function lp_find_device(gone)
  if type(midi) ~= "table" or type(midi.devices) ~= "table" then return nil end
  local best
  for _, dev in pairs(midi.devices) do
    local n = (dev ~= gone and type(dev) == "table" and type(dev.name) == "string")
      and dev.name:lower() or ""
    if n:find("mk3", 1, true)
        and (n:find("mini", 1, true) or n:find("lpmini", 1, true)) then
      local is_daw = n:find("daw", 1, true) ~= nil
      if not is_daw and (n:find("midi", 1, true) or n:find("2")) then
        return dev                       -- the surface/MIDI port: take it
      end
      if not is_daw then best = best or dev end
    end
  end
  return best
end

-- a monome-grid-shaped backend over the Mini MK3: mgrid's draw code calls
-- gg:led/all/refresh with brightness; we buffer, diff, and push RGB SysEx.
local function lp_make_backend(dev)
  return { connect = function()
    if not pcall(function() dev:send(LP_PROG) end) then return nil end
    local gg = { device = dev, rows = 8, cols = 8, key = nil }
    local lvlbuf, huebuf, sent = {}, {}, {}
    function gg:led(x, y, z, color)      -- 4th arg = semantic hue name (optional)
      if x >= 1 and x <= 8 and y >= 1 and y <= 8 then
        local note = lp_note(x, y)
        lvlbuf[note] = max(0, min(15, floor((z or 0) + 0.5)))
        huebuf[note] = color and LP_HUE_ID[color] or 0
      end
    end
    function gg:all(z)
      local lvl = max(0, min(15, floor((z or 0) + 0.5)))
      for yy = 1, 8 do for xx = 1, 8 do
        local note = lp_note(xx, yy); lvlbuf[note] = lvl; huebuf[note] = 0
      end end
    end
    -- the SysEx message buffer, reused every frame. This is the 15fps grid
    -- path, and it allocated a fresh table (and a fresh pcall closure below)
    -- on every refresh — in a codebase that hoisted closures out of the redraw
    -- loop for exactly this reason on the Pi.
    local msg = {}
    local function send_msg() dev:send(msg) end

    function gg:refresh()                -- one SysEx carries every changed pad
      local m = msg
      local n = #LP_RGB_HDR
      for i = 1, n do m[i] = LP_RGB_HDR[i] end
      for i = #m, n + 1, -1 do m[i] = nil end   -- drop last frame's tail
      local changed = false
      for yy = 1, 8 do for xx = 1, 8 do
        local note = lp_note(xx, yy)
        local lvl = lvlbuf[note] or 0
        local hue = huebuf[note] or 0
        local key = lvl + hue * 16       -- a number: no per-frame allocation
        if sent[note] ~= key then
          sent[note] = key
          m[#m + 1] = 0x03               -- colourspec: RGB
          m[#m + 1] = note
          if hue > 0 and lvl > 0 then     -- a semantic colour, scaled by level
            local b = LP_HUE[hue]
            local s = 0.4 + 0.6 * lvl / 15
            m[#m + 1] = floor(b[1] * s); m[#m + 1] = floor(b[2] * s); m[#m + 1] = floor(b[3] * s)
          elseif hue > 0 then             -- hue but level 0 = off
            m[#m + 1] = 0; m[#m + 1] = 0; m[#m + 1] = 0
          else                            -- no hue: plain brightness ramp
            local c = LP_RGB[lvl] or LP_RGB[0]
            m[#m + 1] = c[1]; m[#m + 1] = c[2]; m[#m + 1] = c[3]
          end
          changed = true
        end
      end end
      if not changed then return end
      m[#m + 1] = 0xF7
      pcall(send_msg)
    end
    function gg:shutdown() pcall(function() dev:send(LP_LIVE) end) end
    dev.event = function(data)           -- pad presses -> the grid_key handler
      local ok, msg = pcall(midi.to_msg, data)
      if not ok or type(msg) ~= "table" then return end
      if msg.type == "note_on" or msg.type == "note_off" then
        local x, y = lp_xy(msg.note or -1)
        if x and gg.key then
          gg.key(x, y, (msg.type == "note_on" and (msg.vel or 0) > 0) and 1 or 0)
        end
      elseif msg.type == "cc" and gg.button then
        -- the top row and the side column arrive as CCs in Programmer mode
        gg.button(msg.cc, msg.val or 0)
      end
    end
    -- light the four arrows once: they are fixed controls (page and slot)
    local m = {}
    for i = 1, #LP_RGB_HDR do m[i] = LP_RGB_HDR[i] end
    local w = LP_HUE[LP_HUE_ID.white]
    for cc = LP_UP, LP_RIGHT do
      m[#m + 1] = 0x03; m[#m + 1] = cc
      m[#m + 1] = floor(w[1] * 0.5); m[#m + 1] = floor(w[2] * 0.5); m[#m + 1] = floor(w[3] * 0.5)
    end
    m[#m + 1] = 0xF7
    pcall(function() dev:send(m) end)
    return gg
  end }
end

local gg  -- connected grid; no device attached until one is

local C     -- shared ctx, bound at init
local pget, ptoggle, clamp, window_bounds, FPS

-- semitone offsets per column, root-relative (nil = no black key there)
local GRID_WHITE = { 0, 2, 4, 5, 7, 9, 11, 12 }
local GRID_BLACK = { nil, 1, 3, nil, 6, 8, 10, nil }

-- region slice pads: track what's held per row so a second press while the
-- first is down stretches the region between them. A row is keyed by its
-- START param id, which also names the pair.
local slice_held = {}

local function slice_key(sid, eid, x, z)
  local h = slice_held[sid]
  if not h then h = {}; slice_held[sid] = h end
  if z == 1 then
    local anchor = h[1] or x   -- first held pad anchors the span
    h[#h + 1] = x
    local lo, hi = min(anchor, x), max(anchor, x)
    -- through the one pair writer (widening edge first: a crossed pair is a
    -- region that is neither the old one nor the new one)
    C.set_pair(sid, eid, (lo - 1) / 8, hi / 8)
  else
    for i = #h, 1, -1 do
      if h[i] == x then table.remove(h, i) end
    end
  end
end

-- one piano octave, rows 7 (black) / 8 (white); gap pads = octave -/+
local function grid_note_key(x, y, z)
  -- the gate applies to PRESSES only. A release belongs to the press that
  -- opened it, so keys_enable going off mid-hold must never swallow a note-off
  -- and strand a polyphonic voice sounding forever — the same trap already
  -- guarded for MIDI and for the typing keyboard in lib/minput.lua. A release
  -- for a note we never opened is a no-op inside route_note/pad_trigger.
  if z == 1 and pget("keys_enable", 1) == 0 then return end
  local st
  if y == 8 then
    st = GRID_WHITE[x]
  else
    st = GRID_BLACK[x]
    if not st then
      if z == 1 and (x == 1 or x == 8) then
        params:delta("kb_octave", x == 8 and 1 or -1)
      end
      return
    end
  end
  -- a note pad: route to the drone `pitch` or a polyphonic voice, per
  -- pad_input. both edges, so a voice releases on lift. id 2000+ keeps grid
  -- voice ids distinct from MIDI (1000+) and the screen bank (0..8).
  local oct = pget("kb_octave", 0)
  C.route_note(2000 + (y * 8 + x), 2 ^ ((st + 12 * oct) / 12), st + 12 * oct, z)
  -- in pad mode `pitch` does not move, so do not swell a value that is not
  -- changing (the typing keyboard learned the same thing)
  if z == 1 and pget("pad_input", 0) == 0 then
    C.flash_id, C.flash_until = "pitch", C.frame + FPS
  end
end

-- ============================================================================
-- row 1 — scenes, under the punch law (tap = recall, hold = peek)
-- ============================================================================
local scene_mod = { cap = false, clr = false }
local srow_frame = {}     -- per-slot press frame, for the tap/punch split
local peek_pad = nil      -- which scene pad OWNS the peek (one morph, one owner)

local function scene_row_key(x, z)
  -- CAP/CLR only capture/clear while the SCENE workspace is showing (that's the
  -- only place their modifier pads live); from any other page row 1 is a plain
  -- recall/peek, so a modifier held while navigating away can't overwrite.
  local on_scene = C.PAGES[C.page] == "SCENE"
  if z == 1 then
    params:set("scene_slot", x)              -- the screen follows the finger
    if scene_mod.cap and on_scene then
      C.scene.capture(x)
      srow_frame[x] = nil
    elseif scene_mod.clr and on_scene then
      C.scene.clear(x)
      srow_frame[x] = nil
    elseif C.scene.slots[x] then
      -- begin the PEEK: the ramp in mangler's tick drives the morph param.
      -- this pad becomes the owner (a later pad press takes over) so releasing
      -- the FIRST of two held pads can't cancel the second's peek.
      C.peek_on, C.peek_back, C.peek_at = true, false, C.frame
      peek_pad = x
      srow_frame[x] = C.frame
    else
      -- empty slot: recall it anyway so the page says SLOT EMPTY
      C.pulse("scene_recall")
      srow_frame[x] = nil
    end
  else
    local f = srow_frame[x]
    srow_frame[x] = nil
    -- only the pad that OWNS the peek ends it; a superseded pad's release is a
    -- no-op (else it recalls whatever slot is now selected, not its own)
    if f and peek_pad == x then
      C.peek_on = false
      peek_pad = nil
      params:set("scene_slot", x)            -- recall THIS pad's slot
      if C.frame - f < (C.TAP_FRAMES or 5) then
        -- a tap: COMMIT the recall; the scene is the new LIVE (the landing
        -- zeroes the morph amount itself, once the scene has actually landed)
        C.pulse("scene_recall")
      else
        C.peek_back = true                   -- borrowed: sweep home
      end
    end
  end
end

-- ============================================================================
-- row 2 — the state strip (identical on every page)
-- ============================================================================
local function state_row_key(x, z)
  if x == 3 then
    params:set("tape_reverse", z)            -- momentary, like TAPE K3 held
    return
  end
  if z ~= 1 then return end
  if x == 1 then ptoggle("rec")
  elseif x == 2 then ptoggle("tape_rec")
  elseif x == 4 then ptoggle("pv_freeze")
  elseif x == 5 then ptoggle("tape_freeze")
  elseif x == 6 then ptoggle("pad_input")   -- notes -> pads/drone (was seq run)
  elseif x == 7 then C.fx_dry()
  elseif x == 8 then ptoggle("stop_all") end
end

-- ============================================================================
-- workspaces (rows 3-6)
-- ============================================================================
local function is_pads_page() return C.PAGES[C.page] == "PADS" end
local function is_scene_page() return C.PAGES[C.page] == "SCENE" end
local function is_layers_page() return C.PAGES[C.page] == "LAYERS" end

-- a layer deck's param id, through the deck module's own resolver (row 3 is
-- layer 1, row 4 layer 2, the same order the screen draws them)
local function lay(n, k) return C.deck_p(C.layers[n], k) end

-- the beat repeat on the main workspace's row 6: hold a pad to repeat at its
-- division (x1 1/2 .. x5 1/32). A second pad while one is held changes the
-- division (a re-capture: a roll), and letting go of it goes back to the one
-- still held. The repeat ends when the last pad comes up, and only if a pad
-- started it: a footswitch holding `beat_repeat` keeps it.
local rep_held = {}         -- x -> the order it was pressed in
local rep_seq, rep_owned = 0, false
local function repeat_key(x, z)
  if z == 1 then
    rep_seq = rep_seq + 1
    rep_held[x] = rep_seq
    params:set("repeat_div", x)
    if pget("beat_repeat", 0) ~= 1 then
      rep_owned = true
      params:set("beat_repeat", 1)
    end
    return
  end
  rep_held[x] = nil
  local last, lx = 0, nil
  for k, n in pairs(rep_held) do
    if n > last then last, lx = n, k end
  end
  if lx then
    params:set("repeat_div", lx)
  elseif rep_owned then
    rep_owned = false
    params:set("beat_repeat", 0)
  end
end
M.repeat_key = repeat_key
-- the grid went away mid-hold: its releases will never come, so forget the
-- held pads and end a repeat the grid started
function M.repeat_drop()
  for k in pairs(rep_held) do rep_held[k] = nil end
  if rep_owned then
    rep_owned = false
    params:set("beat_repeat", 0)
  end
end

local function main_ws_key(x, y, z)
  if y == 6 then
    if x <= 5 then repeat_key(x, z)
    elseif x == 8 then params:set("vis_flash", z)          -- a hit on the visuals, held
    elseif z == 1 then                                       -- x6 / x7: the visuals look, back / next
      local n = #Mosc_LOOKS
      local cur = floor(pget("vis_look", 1) + 0.5)
      params:set("vis_look", (cur - 1 + (x == 7 and 1 or -1)) % n + 1)
    end
    return
  end
  if y == 3 then
    slice_key("pos_start", "pos_end", x, z)
  elseif y == 4 then
    slice_key("loop_start", "loop_end", x, z)
  elseif y == 5 and z == 1 then
    if x <= 5 then params:set("mode", x)     -- OFF GRAIN WARP PV PLAY
    elseif x == 7 then
      params:set("pitch", 1.0)
      C.flash_id, C.flash_until = "pitch", C.frame + FPS
    elseif x == 8 then ptoggle("pitch_quant") end
  end
end

local function pads_ws_key(x, y, z)
  -- row 3 = the 8 slice pads: finger-drum the chops as HELD voices (press on,
  -- release off — so it needs both edges, unlike the rest of the workspace).
  -- ids 2600+ clear the note (2000+) / MIDI (1000+) / screen (0-8) namespaces.
  if y == 3 then C.pad_trigger(2600 + x, x - 1, z); return end
  if z ~= 1 then return end
  if y == 5 then params:set("seq_slice", x - 1)         -- select a slice to edit
  elseif y == 6 then
    if x == 1 then params:set("pad_voice", pget("pad_voice", 1) == 1 and 2 or 1)
    elseif x == 3 then ptoggle("step_run")               -- the sequencer
    elseif x == 5 then params:delta("step_fill", -1)     -- fewer hits
    elseif x == 6 then params:delta("step_fill", 1)      -- more hits
    elseif x == 8 then ptoggle("pad_input") end          -- notes -> pads/drone
  end
end

-- LAYERS: one loop-span row per deck (the same two-pad gesture the window and
-- the tape loop use), then rec and mute per deck. The decks are independent, so
-- each gets its own row rather than sharing a selector — on a grid you want to
-- reach the other deck without changing what the screen is showing.
local function layers_ws_key(x, y, z)
  if y == 3 or y == 4 then
    local n = y - 2
    if C.layers[n] then slice_key(lay(n, "start"), lay(n, "end"), x, z) end
    return
  end
  if z ~= 1 then return end
  if y == 5 then                      -- rec: x1-2 = deck 1/2
    if C.layers[x] then ptoggle(lay(x, "rec")) end
  elseif y == 6 then                  -- mute: x1-2 = deck 1/2, snap: x4-5
    if x <= 2 and C.layers[x] then ptoggle(lay(x, "play"))
    elseif (x == 4 or x == 5) and C.layers[x - 3] then C.pulse(lay(x - 3, "snap")) end
  end
end

local function scene_ws_key(x, y, z)
  if y == 6 then                             -- modifier / momentary pads
    if x == 1 then scene_mod.cap = (z == 1)
    elseif x == 2 then scene_mod.clr = (z == 1)
    elseif x == 4 then params:set("chaos_throw", z)
    elseif x == 6 and z == 1 then            -- ORBIT run/stop (page merge:
      C.ptoggle("orbit_on")                  -- the wander has no key of its own)
    elseif x == 8 and z == 1 then            -- ◄ the way back
      C.pulse("scene_safe_restore")
    end
    return
  end
  if z ~= 1 then return end
  if y == 3 then params:set("scene_slot", x)               -- aim, don't jump
  elseif y == 5 then params:set("scene_morph_amt", (x - 1) / 7) end
end

-- which workspace the grid is showing (the surface follows the screen page)
local function surface()
  if is_pads_page() then return "pads" end
  if is_scene_page() then return "scene" end
  if is_layers_page() then return "layers" end
  return "main"
end

-- a pad's RELEASE belongs to the surface that took its PRESS.
-- rows 1-2 and 7-8 are page-independent, but the workspace is not — without
-- this, changing page mid-hold hands the release to a layout that doesn't
-- know the pad, and whatever it was holding LATCHES (learned the hard way on device).
local key_surface = {}

-- the Mini MK3's arrows (other grids have none): left/right step the page
-- the way E1 does, so the workspace rows follow without reaching for the
-- encoder; up/down step the scene selector. Presses only.
local function lp_button(cc, val)
  if val == 0 then return end
  C.touch_input()
  if cc == LP_LEFT then C.step_page(-1)
  elseif cc == LP_RIGHT then C.step_page(1)
  elseif cc == LP_UP then params:delta("scene_slot", 1)
  elseif cc == LP_DOWN then params:delta("scene_slot", -1) end
end

local function grid_key(x, y, z)
  if x > 8 or y > 8 then return end  -- wider/taller grids: top-left 8x8
  C.touch_input()                    -- the grid counts as presence (idle dim)
  if y == 1 then return scene_row_key(x, z) end
  if y == 2 then return state_row_key(x, z) end
  if y >= 7 then return grid_note_key(x, y, z) end
  local k = y * 8 + x
  local s
  if z == 1 then
    s = surface()
    key_surface[k] = s
  else
    s = key_surface[k] or surface()
    key_surface[k] = nil
  end
  if s == "pads" then return pads_ws_key(x, y, z) end
  if s == "scene" then return scene_ws_key(x, y, z) end
  if s == "layers" then return layers_ws_key(x, y, z) end
  return main_ws_key(x, y, z)
end

function M.init(ctx)
  C = ctx
  pget, ptoggle, clamp, window_bounds =
    ctx.pget, ctx.ptoggle, ctx.clamp, ctx.window_bounds
  FPS = ctx.FPS
end

-- ============================================================================
-- LEDs
-- ============================================================================
-- a state-strip pad (row 2): dim when off, bright + its hue when on
local function strip_led(x, on, hue, onlvl)
  gg:led(x, 2, on and (onlvl or 12) or 2, on and hue or nil)
end

local pad_on = {}   -- reused: which of the 8 pads are sounding this frame

local function draw_spine()
  -- row 1: the scene bank. queued blinks YELLOW, selected WHITE, filled a soft
  -- blue, empty barely there.
  local sc = C.scene
  local sel = floor(pget("scene_slot", 1) + 0.5)
  for x = 1, 8 do
    local filled = sc.slots[x] ~= nil
    if sc.pending == x then
      gg:led(x, 1, (C.frame % FPS) < (FPS / 2) and 15 or 4, "yellow")
    elseif x == sel then
      gg:led(x, 1, filled and 15 or 6, "white")
    elseif filled then
      gg:led(x, 1, 8, "blue")
    else
      gg:led(x, 1, 1)
    end
  end
  -- row 2: the state strip. RED = recording, GREEN = playing, ICE BLUE = frozen,
  -- PURPLE = reverse, BLUE = DRY; STOP PULSES red so it reads apart from a
  -- steady recording-red. writes carry the fast blink (matching the header).
  local wblink = (C.frame % 4) < 2
  strip_led(1, pget("rec", 0) == 1, "red", wblink and 15 or 5)
  strip_led(2, pget("tape_rec", 0) == 1, "red", wblink and 15 or 5)
  strip_led(3, pget("tape_reverse", 0) == 1, "purple")
  strip_led(4, pget("pv_freeze", 0) == 1, "ice")
  strip_led(5, pget("tape_freeze", 0) == 1, "ice")
  strip_led(6, pget("pad_input", 0) == 1, "yellow")      -- notes routed to pads
  gg:led(7, 2, 7, "blue")                                -- DRY: an action
  local stopped = pget("stop_all", 0) == 1
  gg:led(8, 2, stopped and (5 + floor(9 * tri(C.frame, 22))) or 2,
    stopped and "red" or nil)                            -- STOP: pulsing red
  -- rows 7-8: one piano octave; the block dims when note input is off so
  -- it's visible why pads are dead. What lights is what the keys DO: the
  -- drone's current pitch in WHITE, or in pad mode every key whose pad
  -- (semitone mod 8) is sounding, in the slice ORANGE
  local en = pget("keys_enable", 1) == 1
  local oct = pget("kb_octave", 0)
  local padmode = pget("pad_input", 0) == 1
  local st_cur = util.round(12 * log(pget("pitch", 1), 2))
  if padmode then
    for k = 0, 7 do pad_on[k] = false end
    for _, i in pairs(C.pad_held) do pad_on[i] = true end
  end
  for x = 1, 8 do
    local w = GRID_WHITE[x] + 12 * oct
    if not en then gg:led(x, 8, 1)
    elseif padmode and pad_on[w % 8] then gg:led(x, 8, 15, "orange")
    elseif not padmode and w == st_cur then gg:led(x, 8, 15, "white")
    elseif x == 1 or x == 8 then gg:led(x, 8, 6)
    else gg:led(x, 8, 4) end
    if GRID_BLACK[x] then
      local b = GRID_BLACK[x] + 12 * oct
      if not en then gg:led(x, 7, 1)
      elseif padmode and pad_on[b % 8] then gg:led(x, 7, 15, "orange")
      elseif not padmode and b == st_cur then gg:led(x, 7, 15, "white")
      else gg:led(x, 7, 2) end
    end
  end
  gg:led(1, 7, en and 3 or 1)  -- octave -
  gg:led(8, 7, en and 3 or 1)  -- octave +
end

local function draw_main_ws()
  -- rows 3/4: slices lit TEAL across the active window / loop region
  local wlo, whi = window_bounds()
  local la, lb = pget("loop_start", 0), pget("loop_end", 1)
  local llo, lhi = min(la, lb), max(la, lb)
  for x = 1, 8 do
    local a, b = (x - 1) / 8, x / 8
    local inw = a < whi and b > wlo
    local inl = a < lhi and b > llo
    gg:led(x, 3, inw and 10 or 1, inw and "teal" or nil)
    gg:led(x, 4, inl and 10 or 1, inl and "teal" or nil)
  end
  -- the write head glows RED while capturing; playheads are WHITE (drawn after,
  -- so a playhead wins a shared pad), full only while that deck is AUDIBLE:
  -- the screen's rule, so a stopped or thrown-away deck cannot look playing
  if pget("rec", 0) == 1 and pget("freeze", 0) == 0 then
    gg:led(floor(clamp(C.rec_phase, 0, 0.999) * 8) + 1, 3, 15, "red")
  end
  local eg, tg = C.mix_gains()
  local eng_on = pget("mode", 5) > 1 and eg > 0.001 and C.wave_any
  local tape_on = C.twave_any and tg > 0.001
  gg:led(floor(clamp(C.play_phase, 0, 0.999) * 8) + 1, 3, eng_on and 15 or 4, "white")
  gg:led(floor(clamp(C.tape_phase, 0, 0.999) * 8) + 1, 4, tape_on and 15 or 4, "white")
  -- row 5: mode radio (selected YELLOW) + pitch utilities
  local mode = pget("mode", 5)
  for x = 1, 5 do gg:led(x, 5, x == mode and 15 or 3, x == mode and "yellow" or nil) end
  local en = pget("keys_enable", 1) == 1
  local quant = en and pget("pitch_quant", 0) == 1
  gg:led(7, 5, en and 3 or 1)
  gg:led(8, 5, quant and 15 or (en and 3 or 1), quant and "yellow" or nil)
  -- row 6: the beat repeat. The held division CYAN (a hold), the division
  -- set but not held a dim cyan, the rest barely there
  local on = pget("beat_repeat", 0) == 1
  local div = floor(pget("repeat_div", 3) + 0.5)
  for x = 1, 5 do
    if on and x == div then gg:led(x, 6, 15, "cyan")
    elseif x == div then gg:led(x, 6, 5, "cyan")
    else gg:led(x, 6, 2) end
  end
  -- x6 / x7 step the visuals look (violet, the brighter one lit while AUTO is off),
  -- x8 is a held FLASH on the picture. Brightness follows the look's place in the list.
  local look = floor(pget("vis_look", 1) + 0.5)
  local lv = 3 + floor(9 * (look - 1) / math.max(1, #Mosc_LOOKS - 1))
  gg:led(6, 6, look == 1 and 3 or lv, "purple")
  gg:led(7, 6, look == 1 and 3 or lv, "purple")
  gg:led(8, 6, pget("vis_flash", 0) == 1 and 15 or 4, "white")
end

-- Grid PADS LED map, in the colour language: row 3 = the 8 slice pads (ORANGE,
-- bright while sounding); row 5 = the edit cursor (WHITE selection over dim
-- blue); row 6 = the selected slice's voice type + the note routing. Brightness
-- reads on the monome/midigrid path too (which ignores the hue).
local function draw_pads_ws()
  local held = C.pad_held
  local cur = floor(pget("seq_slice", 0) + 0.5)
  for x = 1, 8 do
    local sounding = held[2600 + x] ~= nil
    gg:led(x, 3, sounding and 15 or 4, sounding and "orange" or "blue")   -- play
    local sel = (x - 1) == cur
    gg:led(x, 5, sel and 15 or 6, sel and "white" or "blue")             -- select
  end
  gg:led(1, 6, 12, pget("pad_voice", 1) == 2 and "orange" or "cyan")     -- voice: SLICE/GRAIN
  gg:led(3, 6, pget("step_run", 0) == 1 and 12 or 4, "green")           -- sequencer run
  gg:led(5, 6, 3)                                                       -- fewer hits
  gg:led(6, 6, 3)                                                       -- more hits
  gg:led(8, 6, pget("pad_input", 0) == 1 and 15 or 5, "yellow")          -- route
end

-- LAYERS: a span row per deck showing where its loop sits and where its head
-- is, then rec and mute. Recording BLINKS, the way every write flag in this
-- instrument does; a muted deck's row dims, so what you hear is what is lit.
local function draw_layers_ws()
  local decks = C.layers or {}
  for n = 1, math.min(#decks, 2) do
    local d = decks[n]
    local y = n + 2                       -- deck 1 -> row 3, deck 2 -> row 4
    local a = clamp(pget(C.deck_p(d, "start"), 0), 0, 1)
    local b = clamp(pget(C.deck_p(d, "end"), 1), 0, 1)
    local lo, hi = min(a, b), max(a, b)
    local playing = pget(C.deck_p(d, "play"), 1) == 1
    local recing = pget(C.deck_p(d, "rec"), 0) == 1
    local head = floor(clamp(d.phase, 0, 0.999) * 8) + 1
    for x = 1, 8 do
      -- the OVERLAP law, same as draw_main_ws's window/loop rows: a pad lights
      -- when the region touches any of its eighth. The old containment test
      -- left a loop narrower than one eighth entirely dark on its own row.
      local inside = (x - 1) / 8 < hi and x / 8 > lo
      local lvl = inside and (playing and 8 or 3) or 1
      if x == head and inside then lvl = 15 end
      gg:led(x, y, lvl, x == head and "white" or (recing and "red" or "teal"))
    end
    -- rec and mute, one column per deck
    -- the write blink is the state strip's (and the header's) phase
    gg:led(n, 5, recing and ((C.frame % 4) < 2 and 15 or 5) or 3, "red")
    gg:led(n, 6, playing and 9 or 3, "green")
    -- SNAP: round this deck's loop length to match what else is playing.
    -- LAYERS has no key free for it (K2 and K3 are taken, and holding K1 is
    -- stop and erase on every page), so the grid and MIDI are where you reach
    -- it. The automatic snap when a recording ends needs no button at all.
    gg:led(n + 3, 6, d.any and 6 or 2, "yellow")
  end
end

local function draw_scene_ws()
  local sc = C.scene
  local sel = floor(pget("scene_slot", 1) + 0.5)
  -- row 3: where the morph is aimed (selected WHITE, filled soft blue)
  for x = 1, 8 do
    if x == sel then gg:led(x, 3, 15, "white")
    elseif sc.slots[x] then gg:led(x, 3, 8, "blue")
    else gg:led(x, 3, 1) end
  end
  -- row 5: the morph amount as a TEAL bar with a white head (travel = active)
  local head = floor(pget("scene_morph_amt", 0) * 7 + 0.5) + 1
  for x = 1, 8 do
    if x == head then gg:led(x, 5, 15, "white")
    elseif x < head then gg:led(x, 5, 8, "teal")
    else gg:led(x, 5, 1) end
  end
  -- row 6: CAP (green, save), CLR + CHAOS (purple, destructive), ◄ way back
  gg:led(1, 6, scene_mod.cap and 15 or 4, scene_mod.cap and "green" or nil)
  gg:led(2, 6, scene_mod.clr and 15 or 4, scene_mod.clr and "purple" or nil)
  gg:led(4, 6, pget("chaos_throw", 0) == 1 and 15 or 5, "purple")
  -- the orbit: yellow = mode, blinking while the wander runs
  local orb = pget("orbit_on", 0) == 1
  gg:led(6, 6, orb and ((C.frame % 8) < 5 and 15 or 6) or 3, "yellow")
  gg:led(8, 6, sc.safe and 10 or 2, sc.safe and "white" or nil)
end

function M.redraw()
  -- a hot-plug asked for a fresh connect (see M.hotplug)
  if M.reconnect_due then
    M.reconnect_due = false
    M.connect()
  end
  if not (gg and gg.device) then return end
  local s = surface()
  -- CAP/CLR are SCENE-workspace modifiers (row 6). If we've navigated off the
  -- SCENE page they must not linger held — otherwise a page-independent
  -- scene-bank (row 1) tap silently captures/clears instead of recalling.
  if s ~= "scene" then scene_mod.cap, scene_mod.clr = false, false end
  gg:all(0)
  draw_spine()
  if s == "pads" then draw_pads_ws()
  elseif s == "layers" then draw_layers_ws()
  elseif s == "scene" then draw_scene_ws()
  else draw_main_ws() end
  gg:refresh()
end

function M.connect()
  gg = nil
  M.have_launchpad = false
  -- prefer a native Launchpad Mini MK3 colour driver over midigrid/native when
  -- no monome grid is attached; on ANY failure fall back — can't brick.
  if no_monome then
    local lp = lp_find_device()
    if lp then
      local ok, cand = pcall(function() return lp_make_backend(lp).connect() end)
      if ok and cand then
        gg = cand
        M.have_launchpad = true
        print("mangler: Launchpad Mini MK3 colour driver — " .. tostring(lp.name))
      else
        print("mangler: Mini MK3 found but colour driver failed; using fallback")
      end
    end
  end
  if not gg then gg = grid_mod.connect() end   -- midigrid or native grid
  M.gg = gg
  if gg then
    gg.key = grid_key
    gg.button = lp_button
  end
end

-- a MIDI device came or went. A Mini MK3 plugged in after the script loaded
-- takes over from the fallback grid; unplugged, the fallback comes back. A
-- fresh connect also starts a fresh LED diff, so the pads all repaint.
-- `gone`: the device being removed (midi.remove passes it), still listed.
-- The connect itself waits for the next grid frame: norns deletes a leaving
-- device only after midi.remove returns, and midigrid's own search, which
-- cannot be told to skip it, would bind to the Launchpad that is leaving.
-- A leaving Launchpad is dropped at once, so nothing draws to it meanwhile.
function M.hotplug(gone)
  if not no_monome then return end
  local lp = lp_find_device(gone)
  local on_lp = M.have_launchpad and gg and gg.device
  if (lp and on_lp ~= lp) or (not lp and on_lp) then
    if on_lp then
      gg.key, gg.button = nil, nil
      gg, M.gg, M.have_launchpad = nil, nil, false
      -- a repeat pad held on the grid that left will never come up
      M.repeat_drop()
    end
    M.reconnect_due = true
  end
end

function M.cleanup()
  if gg then
    gg.key = nil
    if gg.device then
      gg:all(0)
      gg:refresh()
    end
    if gg.shutdown then gg:shutdown() end        -- LP: return to Live mode
    if M.have_launchpad and gg.device then gg.device.event = nil end
  end
end

return M

end)()
local Mmotion = (function()  -- inlined lib/mmotion.lua
-- mmotion: the gesture looper — a fourth driver for the params.
--
-- keys/encoders/MIDI are three drivers of the single source of truth (the
-- params). this module adds a fourth that RECORDS the param stream and
-- REPLAYS it: a modulation loop pedal for a 3-knob instrument. each param you
-- move becomes its own automation lane, overdubbed independently. no engine
-- change — it just re-issues params:set, so the fingerprint is untouched and
-- it can never brick loading.
--
-- data model: one loop, per-param lanes.
--   loop_len   loop length in FRAMES (the 15fps redraw grid is the timeline;
--              no new clock). 0 until the first take sets it (free length).
--   lanes[id]  { f={}, v={}, n, cur } — flat, pre-grown arrays of
--              {frame-offset, value} events over [0, loop_len). sparse: only
--              params you actually moved exist, so they layer independently.
--   punch-in replace: the first time a param moves in a record pass its lane
--   is cleared, then events append — re-recording a param overwrites ONLY
--   that lane.
--
-- CAPTURE by POLLING (not by intercepting calls). every frame while armed,
-- tick() reads the current value of each recordable param and, if it changed
-- since last frame, appends an event. this catches EVERY driver — encoder
-- (params:delta), key throw, MIDI CC, typing keyboard — because it only reads
-- values; it never depends on HOW they changed. (an earlier version wrapped
-- params.set/params.delta, but that missed the encoder delta path on the real
-- norns paramset — nothing recorded. polling is robust to all of it.)
--
-- no runaway: when playback fires params:set for an owned lane it immediately
-- writes that value into last_val, so the next poll doesn't see the playback
-- change as a live move — only genuinely-live moves enter a lane.

local min, floor = math.min, math.floor

local C            -- shared ctx, bound at init
local pget, clamp, FPS
local MAX_LEN      -- cap the loop at 60s so a forgotten arm can't run away
local MIN_LEN      -- floor on a SETTABLE loop (0.5s) so a tiny motion_len can't
                   -- collapse the loop to a single frame

-- the params whose motion is recordable — the performance / mangle knobs and
-- toggles, in a stable order (first-touch lane order follows it). NOT here:
-- system levels, keys_* config, pad_input, the transports (rec/tape_rec/
-- stop_all), and motion_* itself. add new mangle params here to automate them.
local MOTION_IDS = {
  "mix",
  "pos_start", "pos_end", "scan", "pos_jitter",
  "size", "density", "pitch", "spread", "pan", "grain_level",
  "grain_jitter", "grain_pitch_spread",
  "clouds_pos", "clouds_tex", "clouds_fb", "clouds_lofi", "clouds_mode",
  "mode", "warp_window", "warp_rand", "pv_freeze", "freeze",
  "tape_rate", "loop_start", "loop_end", "tape_pre", "tape_freeze",
  "tape_reverse",
  "cutoff", "resonance", "drive", "filt_type", "dry_wet",
  "erode", "wear",
  "delay_time", "delay_fb", "delay_mix", "delay_sync",
  "rev_decay", "rev_damp", "rev_size", "rev_early", "rev_moddepth",
  "rev_modfreq", "rev_low", "rev_mid", "rev_high", "rev_lowcut",
  "rev_highcut", "rev_mix", "shimmer", "shimmer_pitch", "shimmer_tone",
  "voice_atk", "voice_rel", "pad_level",
  "cut_source",
  -- the layer decks (transports excluded, same rule as tape_rec)
  "lay1_level", "lay1_rate", "lay1_reverse", "lay1_start", "lay1_end", "lay1_pre",
  "lay1_width",
  "lay2_level", "lay2_rate", "lay2_reverse", "lay2_start", "lay2_end", "lay2_pre",
  "lay2_width",
  -- the scene morph knob. recording THIS records a whole-instrument
  -- sweep in ONE lane — mscenes re-derives every param from it on replay
  -- (and tells us it did, via M.account, so the sweep never punches forty
  -- lanes of its own). appended, so existing lane order is unchanged.
  "scene_morph_amt",
  -- track 2 (mangler2), appended so the lane order above is unchanged.
  -- The same choices as track 1: grain_shape and warp_overlaps stay out.
  "t2_level", "t2_pos_start", "t2_pos_end", "t2_scan", "t2_pitch", "t2_pan",
  "t2_pos_jitter", "t2_size", "t2_density", "t2_spread", "t2_grain_jitter",
  "t2_grain_pitch_spread", "t2_clouds_pos", "t2_clouds_tex", "t2_clouds_fb",
  "t2_clouds_lofi", "t2_clouds_mode", "t2_mode", "t2_warp_window",
  "t2_warp_rand", "t2_pv_freeze", "t2_cutoff", "t2_resonance", "t2_filt_type",
}
-- mangler2: tracks 3 and 4 the same as track 2 (appended, lane order kept),
-- then the twelve sends
do
  local t2 = {}
  for i = 1, #MOTION_IDS do
    local rest = MOTION_IDS[i]:match("^t2_(.+)$")
    if rest then t2[#t2 + 1] = rest end
  end
  for _, n in ipairs({ 3, 4 }) do
    for i = 1, #t2 do MOTION_IDS[#MOTION_IDS + 1] = "t" .. n .. "_" .. t2[i] end
  end
  for from = 1, 4 do
    for to = 1, 4 do
      if from ~= to then MOTION_IDS[#MOTION_IDS + 1] = "send_" .. from .. "_" .. to end
    end
  end
end

-- WHAT THE LOOPER DELIBERATELY DOES NOT RECORD — the other half of the list.
-- membership is TOTAL: test/test_control.lua asserts every param sits in
-- MOTION_IDS or here, never neither and never both, so a new param cannot
-- silently miss the decision. each line names its reason once.
local MOTION_EXCLUDE = {
  -- stage-setting levels + STOP (mix, the performance crossfade, IS recorded)
  "sc_level", "cut_level", "out_level", "stop_all",
  -- capture transports + write plumbing: a replayed arm or blend writes the
  -- buffer, which a loop must never do behind your back
  "rec", "tape_rec", "rec_level", "pre_level", "resample", "regen",
  "rec_wait", "rec_thresh",
  "take_undo", "undo_keep",
  "clear_rec", "sample_file", "export_take", "take_tighten", "print_take",
  "print_len", "pad_chop", "pad_even",
  "lay1_rec", "lay1_play", "lay2_rec", "lay2_play",
  "lay1_file", "lay2_file", "layer_wet",
  "lay1_snap", "lay2_snap",   -- a gesture that MOVES the loop, like pad_chop
  -- PARAMS-only discretes: no performance surface reaches them
  "grain_shape", "warp_overlaps", "tape_fade", "lay1_fade", "lay2_fade",
  "t2_grain_shape", "t2_warp_overlaps",
  "t3_grain_shape", "t3_warp_overlaps", "t4_grain_shape", "t4_warp_overlaps",
  -- routing + structure (see the header: pad_input re-points the keyboard,
  -- the voices cap re-caps the allocator)
  "pad_input", "voices",
  -- UI cursors + the per-pad lock editors
  "seq_slice", "layer_sel", "pad_voice", "pad_pitch",
  "track_sel",   -- mangler2: which track VOICE and FILTER address
  "route_sel",   -- mangler2: the ROUTE grid's cursor
  -- a clock rule, set and left (a replayed one would jump the window)
  "win_beats",
  -- config / keys
  "keys_enable", "midi_channel", "root_note", "kb_octave", "pitch_quant",
  -- motion itself, and the scene/orbit machinery (scene_morph_amt is the ONE
  -- scene param that IS recorded — the whole-sweep lane above)
  "motion_rec", "motion_play", "motion_lane", "motion_depth", "motion_len",
  "mod_focus",
  "scene_slot", "scene_recall_mode", "scene_scope", "scene_glide", "scene_capture",
  "scene_recall",
  "scene_next", "scene_clear", "scene_safe_capture", "scene_safe_restore",
  "chaos_throw", "orbit_on", "orbit_rate", "orbit_reach",
  -- the sequencer: a second machine on the clock. A loop replaying its knobs
  -- would fight it, so they are left to the hand, like the orbit's
  "step_run", "step_div", "step_len", "step_fill", "step_order",
  "step_chance", "step_gate",
  -- the beat repeat: a hold you play live (a replayed one would stutter on its own)
  "beat_repeat", "repeat_div",
  -- the modulation out: routing to other gear
  "out_src", "out_midi", "out_ch", "out_cc", "out_crow",
  -- the visuals link: routing to a computer, not sound
  "osc_on", "osc_host", "osc_port", "vis_look", "vis_flash", "vis_midi",
  -- the modulators: a loop of their knobs would fight them
  "lfo1_target", "lfo1_shape", "lfo1_period", "lfo1_rate", "lfo1_depth",
  "lfo2_target", "lfo2_shape", "lfo2_period", "lfo2_rate", "lfo2_depth",
}

local M = {
  loop_len = 0,     -- frames; 0 = empty (no take yet). the PLAYBACK length —
                    -- motion_len may retime it away from the recorded length.
  rec_len = 0,      -- the natural recorded length = the EVENT timebase. events
                    -- are stored against this; playback reads them through a
                    -- rec_len/loop_len ratio, so retiming is lossless.
  playhead = 0,     -- current loop frame while playing (0 .. loop_len)
  lane_ids = {},    -- ordered active param ids (first-touch order)
  lanes = {},       -- lanes[id] = { f, v, n, cur }
  -- exposed for the harness's totality check (see MOTION_EXCLUDE above)
  MOTION_IDS = MOTION_IDS,
  MOTION_EXCLUDE = MOTION_EXCLUDE,
}

-- purely-internal state (not read by the page)
local rec_start_frame = 0       -- ctx.frame when the first pass armed
local touched_this_pass = {}    -- ids already punched-in this pass
local last_val = {}             -- last accounted value per param (for the poll)

-- ===========================================================================
-- lane bookkeeping
-- ===========================================================================

local function reset_cursors()
  local ids = M.lane_ids
  for i = 1, #ids do M.lanes[ids[i]].cur = 1 end
end

-- clear every lane (structures only — param VALUES are left untouched)
local function wipe()
  local ids = M.lane_ids
  for i = #ids, 1, -1 do
    M.lanes[ids[i]] = nil
    ids[i] = nil
  end
  M.loop_len = 0
  M.rec_len = 0
  M.playhead = 0
end

-- motion_len (seconds) -> a settable playback length in frames, or nil for
-- AUTO (0 = use the natural recorded length). clamped to [0.5s, 60s].
local function len_frames(secs)
  if not secs or secs <= 0 then return nil end
  return clamp(floor(secs * FPS + 0.5), MIN_LEN, MAX_LEN)
end

-- map a playback frame (loop_len timebase) to the event timebase (rec_len).
-- IDENTITY when the loop isn't retimed, so default playback is bit-for-bit
-- the pre-retime behaviour (loop_len == rec_len -> src == playhead, integer).
--
-- The ENDPOINTS are what matter when it IS retimed: this maps the last
-- playback frame onto the last event frame, so the tail of every gesture is
-- reached. Scaling by rec_len/loop_len and flooring instead left the final
-- rec_len/loop_len event frames past the end of the sweep — shortening a loop
-- with motion_len silently dropped the end of every recorded gesture.
local function src_of(ph)
  if M.loop_len == M.rec_len then return ph end
  if M.loop_len <= 1 then return M.rec_len - 1 end
  return floor(ph * (M.rec_len - 1) / (M.loop_len - 1) + 0.5)
end

-- baseline: remember every recordable param's current value, so the poll only
-- records CHANGES made after this point (called on arm).
local function snapshot()
  for i = 1, #MOTION_IDS do
    local id = MOTION_IDS[i]
    if params.lookup[id] then last_val[id] = params:get(id) end
  end
end

-- ===========================================================================
-- capture — poll live param moves and append events at `offset`
-- ===========================================================================

local function capture_poll(offset)
  for i = 1, #MOTION_IDS do
    local id = MOTION_IDS[i]
    if params.lookup[id] then
      local v = params:get(id)
      local lv = last_val[id]
      if lv ~= nil and v ~= lv then
        local L = M.lanes[id]
        -- punch-in replace: first move this pass clears (or creates) the lane
        if not touched_this_pass[id] then
          if not L then
            L = { f = {}, v = {}, n = 0, cur = 1 }
            M.lanes[id] = L
            M.lane_ids[#M.lane_ids + 1] = id
          else
            L.n = 0
          end
          touched_this_pass[id] = true
        end
        L.n = L.n + 1
        L.f[L.n] = offset
        L.v[L.n] = v
      end
      last_val[id] = v
    end
  end
end

-- another driver (a scene recall or a morph sweep) is about to move `id` itself: fold the
-- resulting value into our baseline so the next poll doesn't read it as a
-- live hand on a knob. this is the same trick playback uses on its own
-- writes — a scene recall or a morph sweep is a JUMP, not a gesture, and
-- must never punch itself into a lane. no-op for ids we don't track.
function M.account(id)
  if last_val[id] ~= nil then last_val[id] = params:get(id) end
end

-- ===========================================================================
-- transport — driven by the motion_rec / motion_play param actions
-- ===========================================================================

function M.set_armed(on)
  if on then
    touched_this_pass = {}
    snapshot()                                  -- only moves AFTER arming record
    if M.loop_len == 0 then
      rec_start_frame = C.frame                 -- first pass: start the clock
    else
      -- overdub: replay the existing loop from the top while we punch in
      M.playhead = 0
      reset_cursors()
      if pget("motion_play", 0) ~= 1 then params:set("motion_play", 1) end
    end
  else
    if M.loop_len == 0 then
      -- finalize the first pass: its natural length is the EVENT timebase;
      -- motion_len (>0) sets the PLAYBACK length, 0 = AUTO (= natural).
      local elapsed = C.frame - rec_start_frame
      if #M.lane_ids > 0 and elapsed >= 2 then
        M.rec_len = min(elapsed, MAX_LEN) + 1   -- +1 so the last frame plays
        local fixed = len_frames(pget("motion_len", 0))
        -- AUTO: a pass played close to a musical length is put ON it (the
        -- layers' snap law), so the loop stays in time with the clock, the
        -- synced delay and the decks. The gesture itself is untouched:
        -- playback reads it through src_of, so this only retimes it.
        if not fixed and C.clock_length then
          local s = C.clock_length(M.rec_len / FPS)
          if s then
            fixed = clamp(floor(s * FPS + 0.5), MIN_LEN, MAX_LEN)
            print(string.format("mangler: MOTION loop %.2fs -> %.2fs, on the clock",
              M.rec_len / FPS, fixed / FPS))
          end
        end
        M.loop_len = fixed or M.rec_len
        M.playhead = 0
        reset_cursors()
        if pget("motion_play", 0) ~= 1 then params:set("motion_play", 1) end
      else
        wipe()                                  -- nothing captured: stay empty
        if pget("motion_play", 0) == 1 then params:set("motion_play", 0) end
      end
    else
      touched_this_pass = {}                     -- overdub done
    end
  end
end

function M.set_playing(on)
  if on and M.loop_len > 0 then
    M.playhead = 0
    reset_cursors()
  end
end

-- motion_len (K1+E2 on the MOTION page) retimes the loop's PLAYBACK length in
-- seconds; 0 = AUTO (the natural recorded length). retiming changes the loop's
-- SPEED, not the stored gesture — events live in the rec_len timebase and are
-- read through src_of(), so you can dial the length up and down losslessly.
-- resettles from the top so the new length takes hold cleanly. no-op until a
-- loop exists (before that the finalize branch reads motion_len).
function M.set_len(secs)
  if M.rec_len == 0 then return end
  M.loop_len = len_frames(secs) or M.rec_len
  M.playhead = 0
  reset_cursors()
end

-- ===========================================================================
-- clear (CLR-L / CLR on the MOTION page)
-- ===========================================================================

-- clear the selected lane (E2 picks it; 0 = the newest). params keep their
-- current values — clearing removes the automation, not the sound.
function M.clear_lane()
  local n = #M.lane_ids
  if n == 0 then return end
  local sel = clamp(floor(pget("motion_lane", 0) + 0.5), 0, n)
  if sel == 0 then sel = n end
  local id = M.lane_ids[sel]
  if not id then return end
  M.lanes[id] = nil
  table.remove(M.lane_ids, sel)
  if #M.lane_ids == 0 then
    -- the loop is empty again: ALL of its timing goes, rec_len included, or
    -- a later motion_len move builds a phantom loop with no lanes and the
    -- next arm becomes a fixed-length overdub instead of a free first pass
    wipe()
    if pget("motion_play", 0) == 1 then params:set("motion_play", 0) end
  else
    reset_cursors()
  end
end

-- ===========================================================================
-- tick — one per redraw frame: capture live moves, then replay the loop
-- ===========================================================================

-- motion_depth scales a continuous lane toward its first value in the
-- controlspec's WARPED space, the same space the scene morph blends in
-- (ctx.warped_lerp), so half depth sits half way up the knob on an
-- exponential param too. discrete params pass through.
local function at_depth(id, L, v, depth)
  local p = params:lookup_param(id)
  local cs = p and p.controlspec
  if not cs then return v end
  return (C.warped_lerp(cs, L.v[1], v, depth))
end

-- this frame's due values, reused (the replay is on the 15fps hot path)
local due_ids, due_val = {}, {}

local function write_back(id, v)
  params:set(id, v)
  -- account for our own change so the poll skips it. read the value BACK
  -- rather than storing what we asked for: a Control stores map(unmap(v)),
  -- which differs from v in the last bit for a large share of values on an
  -- exponential spec. storing v left the next poll seeing a mismatch, reading
  -- it as a live hand on the knob, and punch-in REPLACING the very lane an
  -- overdub was meant to extend. M.account re-reads for the same reason.
  last_val[id] = params:get(id)
end

function M.tick()
  local armed = pget("motion_rec", 0) == 1
  -- 1) capture: poll for live param moves (before playback overwrites them)
  if armed then
    if M.loop_len == 0 then
      local offset = C.frame - rec_start_frame
      if offset >= 0 and offset <= MAX_LEN then capture_poll(offset) end
    elseif pget("motion_play", 0) == 1 then
      -- overdub: punch in at the loop position, mapped to the EVENT timebase so
      -- new events line up with the old ones even when the loop is retimed
      capture_poll(src_of(M.playhead))
    else
      -- armed over an existing loop with the transport STOPPED. The playhead
      -- is frozen, so every move would punch-in-clear the lane and then stack
      -- at one identical offset — an automation curve replaced by a single
      -- step. There is no timebase to record against, so disarm and say so
      -- (arming an overdub starts playback; getting here means it was stopped
      -- afterwards, by hand).
      params:set("motion_rec", 0)
      print("mangler: MOTION overdub needs the loop running — disarmed")
    end
  end
  -- 2) playback: advance the playhead and fire each lane's due events
  if pget("motion_play", 0) == 1 and M.loop_len > 0 then
    M.playhead = M.playhead + 1
    if M.playhead >= M.loop_len then
      M.playhead = 0
      reset_cursors()
      -- an overdub that ran a full loop auto-disarms (keeps events sorted)
      if armed then params:set("motion_rec", 0) end
    end
    local src = src_of(M.playhead)       -- read the lanes in their own timebase
    -- motion_depth (0..1): a global "amount" for the whole loop (at_depth)
    local depth = pget("motion_depth", 1)
    local blend = depth < 0.999
    local ids = M.lane_ids
    -- 1) what each lane says NOW: the last event due by this frame (a
    --    retimed loop can pass several in one frame; only the last one is
    --    the value the param should hold)
    local nd = 0
    for i = 1, #ids do
      local id = ids[i]
      local L = M.lanes[id]
      local n, cur, v = L.n, L.cur, nil
      while cur <= n and L.f[cur] <= src do
        v = L.v[cur]
        cur = cur + 1
      end
      L.cur = cur
      if v ~= nil then
        nd = nd + 1
        due_ids[nd] = id
        due_val[id] = blend and at_depth(id, L, v, depth) or v
      end
    end
    -- 2) write them. A region's two edges due together go through the one
    --    pair writer (widening edge first): replayed in lane order, a slide
    --    right crossed the pair for one write every pass, and the deck's
    --    100ms floor turned that into a jump of the head.
    -- (the pair maps live in mscenes, which initialises after this module,
    -- so they are read here rather than bound at init)
    local sc = C.scene
    local pm = nd > 1 and sc and sc.PARTNER or nil
    for k = 1, nd do
      local id = due_ids[k]
      local v = due_val[id]
      if v ~= nil then
        local partner = pm and pm[id]
        local pv = partner and due_val[partner] or nil
        if pv ~= nil then
          local sid, eid = id, partner
          if not sc.EDGE_PAIRS[id] then sid, eid = partner, id end
          C.set_pair(sid, eid, due_val[sid], due_val[eid])
          last_val[sid], last_val[eid] = params:get(sid), params:get(eid)
          due_val[partner] = nil
        else
          write_back(id, v)
        end
        due_val[id] = nil
      end
      due_ids[k] = nil
    end
  end
end

-- ===========================================================================
-- the loop rides the PSET
-- ===========================================================================
-- Scenes, the take, the tape and the layers all come back with a session; the
-- gesture loop does too. The lanes save as a plain table beside the pset
-- (motion-N.lua). A loop with no lanes deletes the file, and a pset with no
-- file loads with no loop: the loop belongs to the session being loaded.

local function path_for(number)
  return norns.state.data .. "motion-" .. number .. ".lua"
end

function M.pset_write(number)
  if #M.lane_ids == 0 then os.remove(path_for(number)); return end
  local t = { v = 1, loop_len = M.loop_len, rec_len = M.rec_len,
              ids = {}, lanes = {} }
  for i, id in ipairs(M.lane_ids) do
    local L = M.lanes[id]
    local f, v = {}, {}
    for e = 1, L.n do f[e], v[e] = L.f[e], L.v[e] end
    t.ids[i], t.lanes[id] = id, { f = f, v = v }
  end
  local ok, err = pcall(tab.save, t, path_for(number))
  if not ok then print("mangler: motion save failed — " .. tostring(err)) end
end

function M.pset_read(number)
  -- params:read has already restored the transports. A saved ARM must not
  -- start recording over the restored loop, and the play state applies to
  -- the loop loaded here, not to whatever was running before the load.
  local play = pget("motion_play", 0) == 1
  if pget("motion_rec", 0) == 1 then params:set("motion_rec", 0) end
  wipe()
  local path = path_for(number)
  if util.file_exists(path) then
    local ok, t = pcall(tab.load, path)
    if ok and type(t) == "table" and type(t.ids) == "table"
        and type(t.lanes) == "table" then
      for _, id in ipairs(t.ids) do
        local s = t.lanes[id]
        if params.lookup[id] and type(s) == "table" and type(s.f) == "table"
            and type(s.v) == "table" then
          local L = { f = {}, v = {}, n = 0, cur = 1 }
          for e = 1, #s.f do L.f[e], L.v[e], L.n = s.f[e], s.v[e], e end
          M.lanes[id] = L
          M.lane_ids[#M.lane_ids + 1] = id
        end
      end
      if #M.lane_ids > 0 then
        M.rec_len = t.rec_len or 0
        M.loop_len = t.loop_len or M.rec_len
      end
    end
  end
  play = play and M.loop_len > 0
  if (pget("motion_play", 0) == 1) ~= play then
    params:set("motion_play", play and 1 or 0)
  end
  M.playhead = 0
  reset_cursors()
end

function M.pset_delete(number)
  os.remove(path_for(number))
end

-- ===========================================================================
-- lifecycle
-- ===========================================================================

function M.init(ctx)
  C = ctx
  pget, clamp, FPS = ctx.pget, ctx.clamp, ctx.FPS
  MAX_LEN = 60 * FPS
  MIN_LEN = math.max(4, floor(FPS * 0.5))     -- a settable loop is >= 0.5s
end

return M

end)()
local Mseq = (function()  -- inlined lib/mseq.lua
-- mseq: the pad sequencer. A pattern on the clock plays the pads through the
-- same voice path a hand does (ctx.pad_trigger), so the sound-locks, the
-- voice cap and the PADS picture all apply to it.
--
-- An earlier, percussive step sequencer was removed in the 49th change: the
-- least used part, "not a percussive idea but a way to sequence the different
-- kinds of pad sounds / drones" (doc/ux-feedback.md §28). This one starts
-- from that note. By default it steps through four pads a bar each, legato,
-- so the pads' own voices and pitches become a slow drone progression. The
-- short divisions are there for rhythm when you want it.
--
-- The pattern is GENERATED, not drawn, so the keys, the encoders and MIDI
-- reach all of it through the params (no grid needed): `step_fill` hits
-- spread as evenly as they go over `step_len` steps (a euclidean rhythm), and
-- each hit plays the next slice in `step_order`. `step_chance` skips hits at
-- random, and `step_gate` is how much of a step a hit holds.
--
-- ONE voice id (VOICE_ID). Every step boundary releases it before anything
-- else, so a pattern can never strand a voice, whatever is cancelled when.
-- The step is read off the clock's beat count, so a start, a tempo change or
-- MIDI clock keeps the pattern on the bar. One clock coroutine, cancelled on
-- stop and in cleanup (the norns clock-race gotcha in CLAUDE.md). An external
-- clock that stops stops the steps with it: a legato hit then holds until the
-- clock moves, STOP, or the run is turned off.

local floor = math.floor
local C, pget

-- clear of every other voice id range: the screen bank (0..8), MIDI (1000+),
-- the grid (2000+ notes, 2600+ slices) and the typing keyboard (3000+)
local VOICE_ID = 4000
-- a gated hit releases at least this long before the next boundary, so a
-- late wake from the sleep can never miss that boundary's clock.sync
local GATE_MARGIN = 0.03
-- beats per step, matching the step_div option names
local DIVS = { 8, 4, 2, 1, 0.5, 0.25 }   -- 2 BAR, 1 BAR, 1/2, 1/4, 1/8, 1/16
local ORDERS = { "UP", "DOWN", "BOUNCE", "RANDOM" }
local NSTEP = 16

local M = {
  step = -1,      -- the step that last fired (0-based), -1 = stopped
  hits = {},      -- hits[1..16]: true = a hit (the PADS page draws it)
  slices = {},    -- slices[1..16]: the pad a hit plays (nil on a rest)
  VOICE_ID = VOICE_ID, DIVS = DIVS, ORDERS = ORDERS,
}
local co          -- the running clock coroutine, nil when stopped

-- k hits over n steps, as evenly as they go, the first step always a hit
-- (the Bresenham form of a euclidean rhythm). Writes M.hits in place.
local function build_hits(k, n)
  for i = 1, NSTEP do M.hits[i] = false end
  if k > n then k = n end
  if k <= 0 then return end
  for i = 0, n - 1 do
    M.hits[i + 1] = floor(i * k / n) ~= floor((i - 1) * k / n)
  end
end

-- which pad the h-th hit of a pass plays (h from 0). RANDOM is drawn when
-- the hit fires, not here, so it differs pass to pass.
local function slice_for(h, order)
  if order == 1 then return h % 8 end
  if order == 2 then return 7 - h % 8 end
  if order == 3 then
    local p = h % 14
    return p < 8 and p or 14 - p
  end
  return nil
end

-- rebuild the pattern from the params. Run by their actions, never per frame.
function M.rebuild()
  local n = floor(pget("step_len", 4) + 0.5)
  build_hits(floor(pget("step_fill", 4) + 0.5), n)
  local order = floor(pget("step_order", 1) + 0.5)
  local h = 0
  for i = 1, NSTEP do
    if M.hits[i] and i <= n then
      M.slices[i] = slice_for(h, order)
      h = h + 1
    else
      M.slices[i] = nil
    end
  end
end

local function div_beats()
  return DIVS[floor(pget("step_div", 2) + 0.5)] or 4
end

local function release()
  if C.pad_held[VOICE_ID] then C.pad_trigger(VOICE_ID, 0, 0, true) end
end

-- one step boundary, at clock beat `beats`. Returns the seconds the hit
-- should hold before its release, or nil when the next boundary releases it.
function M.fire(beats)
  release()
  local div = div_beats()
  local n = floor(pget("step_len", 4) + 0.5)
  local q = floor(beats / div + 0.5)
  -- far off the grid is not a step: the next sync lands on it. A quarter of
  -- a step, so a coroutine woken late (matron busy, MIDI clock) still plays
  if math.abs(beats / div - q) > 0.25 then return nil end
  local step = q % n
  M.step = step
  if not M.hits[step + 1] then return nil end
  -- a STOP silences everything and an empty take has nothing to slice
  if pget("stop_all", 0) == 1 or not C.wave_any then return nil end
  if math.random() >= pget("step_chance", 1) then return nil end
  local pad = M.slices[step + 1] or math.random(0, 7)
  C.pad_trigger(VOICE_ID, pad, 1, true)
  local gate = pget("step_gate", 1)
  if gate >= 0.999 then return nil end
  local tempo = (C.tempo and C.tempo()) or 120
  local step_s = div * 60 / tempo
  return math.max(0, math.min(step_s * gate, step_s - GATE_MARGIN))
end

local function run()
  while true do
    clock.sync(div_beats())
    local hold = M.fire(clock.get_beats())
    if hold then
      clock.sleep(hold)
      release()
    end
  end
end

function M.start()
  if co then return end
  M.rebuild()
  co = clock.run(run)
end

-- a new step length takes effect at once: the running sync waits on the OLD
-- division (up to two bars), so the coroutine is started again on the new one
function M.restart()
  if not co then return end
  M.stop()
  M.start()
end

function M.stop()
  if co then clock.cancel(co) end
  co = nil
  M.step = -1
  release()
end

function M.running() return co ~= nil end

function M.init(ctx)
  C = ctx
  pget = ctx.pget
end

return M

end)()
local Mlfo = (function()  -- inlined lib/mlfo.lua
-- mlfo: two modulators that each move the SOUND of one knob.
--
-- A modulator never writes its target param. The param stays where the hand,
-- MIDI, a scene, the morph or a motion lane left it: that is the knob, the
-- single source of truth, and everything that reads or stores it (scene
-- capture, the safe snapshot and UNDO, the throws, the motion looper, a PSET
-- save) sees the knob and never the wave. Each frame the modulator sends the
-- ENGINE the knob's value plus depth x wave, in the param's own 0..1
-- (unmapped) space, so a curve-mapped knob such as cutoff swings evenly, and
-- through the same send map the param's action uses (`ctx.eng_map`).
-- An earlier version wrote the param and tracked a "base" by polling. A
-- reviewer found what that costs: an encoder nudge moved the centre by the
-- whole swing, a hand on the knob could not be recorded, two modulators on
-- one knob ran away, and every snapshot stored where the wave happened to be.
--
-- So only ENGINE controls are targets (a plain `engine[id](v)` action). Two
-- modulators on one knob add their swings. A target that the engine frees at
-- 0 (delay and reverb mix) is held just above 0 while modulated, or the FX
-- synth would be freed and spawned again every cycle; at depth 0 the knob's
-- own value goes back to the engine, so a mix at 0 frees it as before.
-- Pages draw the knob, not the swing; the header's LF says a modulator runs.
--
-- Shapes: SINE, TRI, SQUARE, RAMP, RANDOM (a new level each cycle), and ENV,
-- the input's envelope. Depth is -1..1; negative inverts, so ENV with a
-- negative depth ducks. A period other than FREE locks the phase to the
-- clock's beat count, so a modulator stays on the bar through a tempo change.
--
-- The TARGETS list is APPEND-ONLY: the target param stores an index into it,
-- so a PSET or a PMAP names a target by its position here.

local floor, min, max, sin, pi = math.floor, math.min, math.max, math.sin, math.pi
local C, pget, FPS

local TARGETS = {
  "cutoff", "resonance", "drive", "dry_wet",
  "delay_mix", "delay_fb", "rev_mix", "rev_size", "shimmer",
  "scan", "size", "density", "spread", "pan", "grain_jitter",
  "pos_jitter", "warp_window", "clouds_pos", "clouds_tex", "wear",
}
-- kept above 0 while modulated: the engine frees these synths at 0
local FLOOR = { delay_mix = 0.001, rev_mix = 0.001 }
local SHAPES = { "SINE", "TRI", "SQUARE", "RAMP", "RANDOM", "ENV" }
local ENV_SHAPE = 6
-- beats per cycle, matching the lfoN_period option names (false = FREE)
local PERIODS = { false, 1, 2, 4, 8, 16, 32 }
local PERIOD_NAMES = { "FREE", "1 BEAT", "2 BEAT", "1 BAR", "2 BAR", "4 BAR", "8 BAR" }
local N = 2

local M = {
  TARGETS = TARGETS, SHAPES = SHAPES, PERIOD_NAMES = PERIOD_NAMES, N = N,
  env = 0,        -- the input envelope, 0..1, shared by every ENV modulator
  mods = {},      -- mods[i] = { id, phase, cycle, held, out (0..1) }
}
for i = 1, N do
  M.mods[i] = { id = nil, phase = 0, cycle = -1, held = 0, out = 0.5 }
end
local sum = {}    -- this frame's swing per target id (reused, never rebuilt)

-- the param ids, built once (the redraw path asks active() every frame)
local PID = {}
for i = 1, N do
  PID[i] = {}
  for _, w in ipairs({ "target", "shape", "period", "rate", "depth" }) do
    PID[i][w] = "lfo" .. i .. "_" .. w
  end
end

-- the target param id of modulator i, or nil when it is OFF
local function target_of(i)
  return TARGETS[floor(pget(PID[i].target, 1) + 0.5) - 1]
end

local function depth_of(i)
  local d = pget(PID[i].depth, 0)
  return math.abs(d) >= 0.001 and d or 0
end

-- one value of the wave, -1..1 (ENV is 0..1, handled by the caller)
local function wave(shape, ph, m)
  if shape == 1 then return sin(ph * 2 * pi) end
  if shape == 2 then return ph < 0.5 and (ph * 4 - 1) or (3 - ph * 4) end
  if shape == 3 then return ph < 0.5 and 1 or -1 end
  if shape == 4 then return ph * 2 - 1 end
  return m.held                      -- RANDOM: the level drawn this cycle
end

-- the shape of a wave for drawing (MOTION's modulator rows): SINE to RAMP
-- only, since RANDOM and ENV have no shape to draw ahead of time
function M.wave(shape, ph) return wave(shape, ph) end

-- send the engine a value for param `id`, through the param's own send map
local function send(id, v)
  local f = engine[id]
  if not f then return end
  local map = C.eng_map and C.eng_map[id]
  f(map and map(v) or v)
end

local function beats_now()
  return (clock.get_beats and clock.get_beats()) or 0
end

-- one frame. `amp`: the input level now (max of the two ADC polls).
function M.tick(amp)
  -- the envelope: fast up, slower down, on a square-root scale so a quiet
  -- source still moves the knob
  local a = math.sqrt(min(max(amp or 0, 0), 1))
  M.env = M.env + (a - M.env) * (a > M.env and 0.6 or 0.15)
  for id in pairs(sum) do sum[id] = nil end
  for i = 1, N do
    local m = M.mods[i]
    local depth = depth_of(i)
    local id = depth ~= 0 and target_of(i) or nil
    if id ~= m.id then
      -- the knob it left gets its own value back (unless the other one
      -- still swings it: that one's send below then wins)
      if m.id then send(m.id, pget(m.id, 0)) end
      if id then print("mangler: LFO " .. i .. " moves " .. params:lookup_param(id).name) end
      m.id = id
    end
    -- the wave runs whether or not it moves a knob: `out` (0..1) is also a
    -- source for the modulation outputs (lib/mout.lua)
    local shape = floor(pget(PID[i].shape, 1) + 0.5)
    local per = PERIODS[floor(pget(PID[i].period, 1) + 0.5)]
    -- a RANDOM level is drawn only for a RANDOM wave, so the other shapes,
    -- which run whether or not they move a knob, leave the orbit's random
    -- sequence alone. Switched to RANDOM, it draws at once, not a cycle late.
    local rnd = shape == 5
    if rnd and m.shape ~= 5 then m.held = math.random() * 2 - 1 end
    m.shape = shape
    if per then
      local b = beats_now() / per
      m.phase = b - floor(b)
      local cyc = floor(b)
      if cyc ~= m.cycle then
        m.cycle = cyc
        if rnd then m.held = math.random() * 2 - 1 end
      end
    else
      local ph = m.phase + pget(PID[i].rate, 0.5) / FPS
      if ph >= 1 and rnd then m.held = math.random() * 2 - 1 end
      m.phase = ph - floor(ph)
    end
    local w = shape == ENV_SHAPE and M.env or wave(shape, m.phase, m)
    m.out = shape == ENV_SHAPE and w or (w + 1) * 0.5
    if id then
      local off = shape == ENV_SHAPE and depth * w or depth * 0.5 * w
      sum[id] = (sum[id] or 0) + off
    end
  end
  for id in pairs(sum) do send(id, M.swung(id, pget(id, 0))) end
end

-- the delay's feedback HOLD: with the delay mix at 0 the engine keeps the
-- delay synth alive only while the (curved) feedback is above 0.9, so a
-- held loop survives a KILL. A swing across that line would free the synth
-- and drop the loop each cycle, so it is kept on the knob's own side of it.
local FB_HOLD = 0.9
local function fb_sent(v)
  local map = C.eng_map and C.eng_map.delay_fb
  return map and map(v) or v
end

-- is param `id` swung this frame (its action asks, before it sends)
function M.swinging(id) return sum[id] ~= nil end

-- knob value `v` of param `id` with this frame's swing on it, as the engine
-- should get it (before the send map)
function M.swung(id, v)
  local off = sum[id]
  if not off then return v end
  local cs = params:lookup_param(id).controlspec
  local w = cs:map(min(max(cs:unmap(v) + off, 0), 1))
  if FLOOR[id] then w = max(w, FLOOR[id]) end
  if id == "delay_fb" and pget("delay_mix", 0) <= 0 then
    local above = fb_sent(v) > FB_HOLD
    -- step back toward the knob until the sent value is on its side
    for _ = 1, 20 do
      if (fb_sent(w) > FB_HOLD) == above then break end
      w = (w + v) / 2
    end
    if (fb_sent(w) > FB_HOLD) ~= above then w = v end
  end
  return w
end


-- any modulator set to move a knob (the purity mark and the header ask). Read
-- from the params, so it is true from the moment it is set.
function M.active()
  for i = 1, N do
    if depth_of(i) ~= 0 and target_of(i) then return true end
  end
  return false
end

-- every modulated knob's own value back to the engine (cleanup)
function M.restore_all()
  for i = 1, N do
    local m = M.mods[i]
    if m.id then send(m.id, pget(m.id, 0)) end
    m.id = nil
  end
end

function M.init(ctx)
  C = ctx
  pget, FPS = ctx.pget, ctx.FPS
end

-- the params, added by mangler2.lua's init_params after every target exists
-- (an option's names are the targets' own names)
function M.add_params(add_group)
  local names = { "OFF" }
  for k = 1, #TARGETS do
    local p = params:lookup_param(TARGETS[k])
    names[k + 1] = p and p.name or TARGETS[k]
  end
  add_group("grp_lfo", "modulators", 5 * N)
  for i = 1, N do
    params:add_option(PID[i].target, "LFO " .. i .. " target", names, 1)
    params:add_option(PID[i].shape, "LFO " .. i .. " shape", SHAPES, 1)
    params:add_option(PID[i].period, "LFO " .. i .. " period", PERIOD_NAMES, 1)
    params:add_control(PID[i].rate, "LFO " .. i .. " rate",
      controlspec.new(0.01, 10, "exp", 0, 0.5, "Hz"))
    params:add_control(PID[i].depth, "LFO " .. i .. " depth",
      controlspec.new(-1, 1, "lin", 0, 0, ""))
  end
end

return M

end)()
local Mout = (function()  -- inlined lib/mout.lua
-- mout: the modulation OUTPUT. One source of the instrument's movement, sent
-- to other gear as a MIDI CC, and to crow's output 1 as 0..5 V when a crow is
-- connected. The sources are what already moves on its own: the scene morph
-- (so the orbit and a GLIDE drive the outboard too), the input envelope, and
-- the two LFOs' waves (lib/mlfo.lua), which run even when they move no knob.
--
-- It writes nothing in the instrument. A CC goes out only when its 7-bit value
-- changes, so a still source sends nothing; crow only when the voltage moves
-- by more than a millivolt or so. A new port, CC number, channel or device
-- (a hot-plug), and a crow that comes back or is switched on, all resend the
-- value once, so a still source is never left unsent.
-- At cleanup nothing is sent: the outboard keeps the last value, as it would
-- after any controller stopped moving.
-- The default CC is 20, an undefined controller, so it does not land on a
-- mod wheel (CC 1) that an outboard synth, or this script's own MIDI map,
-- may have learned. A CC learned back onto the param that drives the source
-- (an LFO's rate with that LFO as the source) is a loop: do not map it so.

local floor = math.floor
local C, pget

local SOURCES = { "OFF", "MORPH", "ENV", "LFO 1", "LFO 2" }

local M = { SOURCES = SOURCES, last_cc = -1, last_v = -1, dev = nil, dev_port = 0,
  dest = nil, crow_on = false }

-- the source's value now, 0..1, or nil when OFF
function M.value()
  local s = floor(pget("out_src", 1) + 0.5)
  if s == 2 then return pget("scene_morph_amt", 0) end
  local lfo = C.lfo
  if not lfo then return nil end
  if s == 3 then return lfo.env end
  if s == 4 or s == 5 then return lfo.mods[s - 3].out end
  return nil
end

local function device()
  local port = floor(pget("out_midi", 0) + 0.5)
  if port ~= M.dev_port then
    M.dev_port = port
    M.dev = port > 0 and midi.connect(port) or nil
  end
  return M.dev
end

function M.tick()
  local v = M.value()
  if not v then return end
  v = math.min(math.max(v, 0), 1)
  local dev = device()
  if dev and dev.cc then
    local num, ch = floor(pget("out_cc", 20) + 0.5), floor(pget("out_ch", 1) + 0.5)
    -- where it goes: a change of any part of it resends. `dest` is a number,
    -- so this allocates nothing per frame (the device object is compared)
    local dest = num * 16 + ch
    if dest ~= M.dest or dev.device ~= M.dest_dev then
      M.dest, M.dest_dev, M.last_cc = dest, dev.device, -1
    end
    local cc = floor(v * 127 + 0.5)
    if cc ~= M.last_cc and dev.device ~= nil then
      M.last_cc = cc
      dev:cc(num, cc, ch)
    end
  end
  local on = pget("out_crow", 0) == 1 and crow and crow.output and crow.connected
    and crow.connected() or false
  if on ~= M.crow_on then M.crow_on, M.last_v = on, -1 end
  if on then
    local volts = v * 5
    if math.abs(volts - M.last_v) > 0.002 then
      M.last_v = volts
      crow.output[1].volts = volts
    end
  end
end

function M.init(ctx)
  C = ctx
  pget = ctx.pget
end

function M.add_params()
  params:add_group("grp_out", "modulation out", 5)
  params:add_option("out_src", "out source", SOURCES, 1)
  params:add_number("out_midi", "out midi port", 0, 16, 0,
    function(p) local v = p:get(); return v == 0 and "OFF" or tostring(v) end)
  params:add_number("out_ch", "out midi channel", 1, 16, 1)
  params:add_number("out_cc", "out cc number", 0, 127, 20)
  params:add_binary("out_crow", "out to crow 1", "toggle", 0)
end

return M

end)()
local Mosc = (function()  -- inlined lib/mosc.lua
-- mosc: the visuals link. The instrument's state goes out as OSC (UDP, over
-- Wi-Fi) to a computer running visuals/bridge.js, which hands it to Hydra.
-- MIDI stays in lib/mout.lua: one CC carries one 7-bit value, this carries all
-- of the fields below at full precision.
--
-- It writes nothing in the instrument. Every field is its own message,
-- /mangler/<key> with one argument, sent only when its value changed. A new
-- address, port or switch-on, and a refresh every two seconds, send every
-- field again: UDP drops packets, and a visual that starts late must still
-- learn the state. A param field goes out normalised 0..1 through its own
-- controlspec, so the filter cutoff is a position on the knob, not a number
-- of Hz. Floats are rounded to 3 decimals. The tick runs at the frame rate
-- (15 Hz); the browser smooths between messages.

local floor = math.floor

local C, pget

local REFRESH = 2          -- seconds between full resends
local FIELDS = {}          -- { key, path, id | read, norm, last }

local function add(key, id_or_fn, norm)
  local f = { key = key, path = "/mangler/" .. key, norm = norm }
  if type(id_or_fn) == "string" then f.id = id_or_fn else f.read = id_or_fn end
  FIELDS[#FIELDS + 1] = f
end

-- the fields. A string is a param id (read through pget, normalised when
-- `true`), a function reads anything else. The key is the OSC address.
add("page", function() return C.page end)
add("page_name", function() return C.PAGES[C.page] or "" end)
add("scene", "scene_slot")
add("look", "vis_look")
add("flash", "vis_flash")
add("mode", "mode")
add("rec", "rec")
add("freeze", "freeze")
add("env", function() return C.lfo and C.lfo.env or 0 end)
add("lfo1", function() return C.lfo and C.lfo.mods[1].out or 0 end)
add("lfo2", function() return C.lfo and C.lfo.mods[2].out or 0 end)
add("morph", "scene_morph_amt")
add("in_l", function() return C.amp_in[1] end)
add("in_r", function() return C.amp_in[2] end)
add("out_l", function() return C.amp_out[1] end)
add("out_r", function() return C.amp_out[2] end)
add("beat", function()
  local b = clock and clock.get_beats and clock.get_beats()
  return b and (b % 1) or 0
end)
add("tempo", function() return C.tempo() end)
add("play", function() return C.play_phase end)
add("rec_phase", function() return C.rec_phase end)
add("win_start", "pos_start")
add("win_end", "pos_end")
add("size", "size", true)
add("density", "density", true)
add("spread", "spread", true)
add("jitter", "grain_jitter", true)
add("pitch", "pitch", true)
add("cutoff", "cutoff", true)
add("resonance", "resonance", true)
add("drive", "drive", true)
add("dry_wet", "dry_wet", true)
add("delay_mix", "delay_mix", true)
add("rev_mix", "rev_mix", true)
-- track 2 (mangler2): on = switched on and audible, then its own head,
-- window and knobs, so the visuals can give it a layer of its own
add("t2_on", function()
  return (pget("t2_mode", 1) ~= 1 and pget("t2_level", 1) > 0.001) and 1 or 0
end)
add("t2_mode", "t2_mode")
add("t2_level", "t2_level")
add("t2_play", function() return C.play_phase2 or 0 end)
add("t2_win_start", "t2_pos_start")
add("t2_win_end", "t2_pos_end")
add("t2_size", "t2_size", true)
add("t2_density", "t2_density", true)
add("t2_pitch", "t2_pitch", true)
add("t2_cutoff", "t2_cutoff", true)

local M = { FIELDS = FIELDS, on = false, host = nil, port = nil, errors = 0 }

-- A host given as a name (the computer's name.local) is resolved here, once a
-- minute, and the number is what osc.send gets. osc.send looks a name up on
-- every message, which would be 100 lookups a second on the frame clock. A
-- name that cannot be resolved keeps the last number. A computer whose
-- address changed overnight is found again within a minute.
local RESOLVE_EVERY = 60   -- seconds
local resolved, resolved_name, resolved_at = nil, nil, -1e9

local function is_number_host(h)
  return h:match("^%d+%.%d+%.%d+%.%d+$") ~= nil
end

local function resolve(h)
  if is_number_host(h) then return h end
  local now = C.frame / C.FPS
  if resolved_name == h and now - resolved_at < RESOLVE_EVERY then return resolved end
  resolved_name, resolved_at = h, now
  local ok, p = pcall(io.popen, "getent ahostsv4 '" .. h:gsub("[^%w%.%-_]", "") .. "' 2>/dev/null")
  if ok and p then
    local line = p:read("l")
    p:close()
    local ip = line and line:match("^(%d+%.%d+%.%d+%.%d+)")
    if ip then
      if ip ~= resolved then print("mangler: osc host " .. h .. " is " .. ip) end
      resolved = ip
    end
  end
  return resolved
end
M.resolve = resolve

local dest = { "", 0 }     -- handed to osc.send; rebuilt in place on a change
local one = { 0 }          -- the argument list, reused for every message

local function value(f)
  local v
  if f.id then
    v = pget(f.id, 0)
    if f.norm then
      local p = params:lookup_param(f.id)
      local cs = p and p.controlspec
      if cs and cs.unmap then v = cs:unmap(v) end
    end
  else
    v = f.read()
  end
  if type(v) == "number" and v ~= floor(v) then v = floor(v * 1000 + 0.5) / 1000 end
  return v
end

function M.tick()
  if pget("osc_on", 0) ~= 1 or not (osc and osc.send) then
    M.on = false
    return
  end
  local name = params:get("osc_host")
  local port = floor(pget("osc_port", 9000) + 0.5)
  local host = name ~= nil and name ~= "" and resolve(name) or nil
  if host == nil then M.on = false; return end
  local full = not M.on or host ~= M.host or port ~= M.port
    or C.frame % (REFRESH * C.FPS) == 0
  if host ~= M.host or port ~= M.port then
    M.host, M.port = host, port
    dest[1], dest[2] = host, port
  end
  M.on = true
  sent_ev = 0
  for i = 1, #FIELDS do
    local f = FIELDS[i]
    local v = value(f)
    if full or v ~= f.last then
      f.last = v
      one[1] = v
      if not pcall(osc.send, dest, f.path, one) then
        M.errors = M.errors + 1
        if M.errors == 1 then print("mangler: osc send failed to " .. host .. ":" .. port) end
      end
    end
  end
end

function M.init(ctx)
  C = ctx
  pget = ctx.pget
end

-- MIDI events for the picture (an Octatrack on the TRS MIDI input, or any
-- other MIDI source). lib/minput.lua hands every message of every port here.
-- A note, a CC, a program change and the transport go out at once as
-- /mangler/ev/<name> with integer arguments, so a hit lands on the beat
-- instead of waiting for the next frame. A CC that did not change is not
-- sent again. At most EVENT_CAP events leave per frame, so a knob sweep or a
-- busy pattern cannot flood the Wi-Fi. Clock messages are never forwarded.
local EVENT_CAP = 24
local sent_ev = 0
local last_cc = {}
local evargs = { 0, 0, 0 }
local evrun = { 0 }

local function ev_send(name, args)
  if sent_ev >= EVENT_CAP then return end
  sent_ev = sent_ev + 1
  if not pcall(osc.send, dest, "/mangler/ev/" .. name, args) then
    M.errors = M.errors + 1
  end
end

function M.midi_in(msg, vport)
  if not (M.on and osc and osc.send) or pget("vis_midi", 1) ~= 1 then return end
  local t = msg.type
  if t == "note_on" and (msg.vel or 0) > 0 then
    evargs[1], evargs[2], evargs[3] = msg.ch or 1, msg.note or 0, msg.vel or 0
    ev_send("note", evargs)
  elseif t == "cc" then
    local key = (msg.ch or 1) * 128 + (msg.cc or 0)
    if last_cc[key] == msg.val then return end
    last_cc[key] = msg.val
    evargs[1], evargs[2], evargs[3] = msg.ch or 1, msg.cc or 0, msg.val or 0
    ev_send("cc", evargs)
  elseif t == "program_change" then
    evargs[1], evargs[2], evargs[3] = msg.ch or 1, msg.val or 0, 0
    ev_send("pc", evargs)
  elseif t == "start" or t == "continue" or t == "stop" then
    evrun[1] = t == "stop" and 0 or 1
    ev_send("run", evrun)
  end
end

-- the look the visuals show. Option 1 lets the visuals pick one by the page.
-- The order is mirrored by NAMES in visuals/hydra.js. It is a scene param
-- (lib/mscenes.lua), so a scene or a preset can bring its own look.
M.LOOKS = { "AUTO", "BARS", "FILTER", "SHAPES", "RINGS", "MOSAIC", "TUNNEL", "WAVES", "FACETS" }

-- The three connection params are remembered in a small file, so a norns that
-- is switched on tomorrow sends to the same computer with no setup. A pset
-- does not carry them: they are about this room, not about a sound.
local function cfg_path()
  return (_path and _path.data or "/home/we/dust/data/") .. "mangler/osc.cfg"
end

local loading, reading = false, false
local function cfg_save()
  if loading or reading then return end
  local f = io.open(cfg_path(), "w")
  if not f then return end
  f:write(string.format("%d\n%s\n%d\n", pget("osc_on", 0), params:get("osc_host") or "",
    floor(pget("osc_port", 9000) + 0.5)))
  f:close()
end

local function cfg_load()
  local f = io.open(cfg_path(), "r")
  if not f then return end
  local on, host, port = f:read("n"), nil, nil
  f:read("l"); host = f:read("l"); port = f:read("n")
  f:close()
  loading = true
  if host and host ~= "" then params:set("osc_host", host) end
  if port then params:set("osc_port", port) end
  if on then params:set("osc_on", on) end
  loading = false
end

M.cfg_reload = cfg_load   -- after a PSET read, which would put the old values back

function M.add_params()
  params:add_group("grp_osc", "visuals out (osc)", 6)
  params:add_option("vis_look", "visuals look", M.LOOKS, 1)
  params:add_binary("vis_flash", "visuals flash", "momentary", 0)   -- a hit on the picture, held
  params:add_binary("vis_midi", "midi to visuals", "toggle", 1)   -- notes, CCs, program changes, transport
  params:add_binary("osc_on", "osc out", "toggle", 0)
  params:add_text("osc_host", "osc host (ip or name.local)", "192.168.1.100")
  params:add_number("osc_port", "osc port", 1, 65535, 9000)
  for _, id in ipairs({ "osc_on", "osc_host", "osc_port" }) do params:set_action(id, cfg_save) end
  -- a PSET read puts its own values in these params (one saved after this
  -- change carries them): while it runs, nothing is written to the file, and
  -- the action_read hook restores the file's values afterwards
  local read = params.read
  if read then
    params.read = function(self, ...)
      reading = true
      local ok, err = pcall(read, self, ...)
      reading = false
      if not ok then error(err, 0) end
    end
  end
  cfg_load()
end

return M

end)()
local Mscenes = (function()  -- inlined lib/mscenes.lua
-- mscenes: scenes, scene morphing, and the safe-state snapshot — the
-- "remember this / go back to that" layer.
--
-- three features, one data model:
--   SCENES   8 slots, each a flat map { param_id = value } captured from the
--            live params. recall writes them back through params:set, so the
--            engine, the tape and the display all follow for free — a scene
--            is not a second source of truth, it's a photograph of the one
--            that exists.
--   MORPH    a continuous sweep from the sound you have now toward a stored
--            slot, over the subset of params that can be interpolated. one
--            knob (scene_morph_amt) moves the whole instrument along that line.
--   SAFE     one "last known good" snapshot + an instant restore. capture it
--            before you do something reckless (see the chaos throw below);
--            restore drops you straight back on your feet.
--
-- NOTHING here stores audio. scenes are control state only: a recall does not
-- bring back the take you have since overdubbed (that's what PSETs + the tape
-- wav are for, see mtape). that's also what makes it cheap — 8 slots is ~600
-- numbers, and a recall is ~80 params:set calls.
--
-- WHAT IS AND ISN'T IN A SCENE — the lists are right below and they are
-- deliberate. in: everything that shapes the sound of the take (window,
-- grain/clouds, stretch, tape loop, filter, delay, reverb, shimmer, voices).
-- out: the hardware/config layer (midi channel, keys, root note), the SYSTEM
-- levels (in/out/monitor/hp), the capture transports (rec, tape_rec), the
-- master STOP, the motion transport, and the UI selectors (slice cursor).
-- a scene changes how it sounds, never how it's plumbed or whether it's
-- running.
--
-- THE MORPH IS FRAME-COALESCED. scene_morph_amt's action only marks the sweep
-- dirty; M.tick() applies it at most once per redraw frame (the existing 15fps
-- clock — no new process, same modulation grid the gesture looper runs on).
-- a fast CC sweep would otherwise fire ~40 params x 128 CC steps at the engine
-- in a second; this caps it at 15 passes/s, and the per-param deadband below
-- drops the ones that aren't actually moving.

local floor, abs, min, max = math.floor, math.abs, math.min, math.max

local C            -- shared ctx, bound at init
local pget, clamp

local NUM_SLOTS = 8

-- ===========================================================================
-- the curated param lists
-- ===========================================================================
-- SCENE_RECALL_IDS is built from three ORDERED blocks, and recall/restore
-- walk it in order, so a scene lands in the order the engine wants it:
--
--   1 TIMBRE  the continuous voice: source blend, window, grain/clouds,
--             stretch shape, tape loop, voices
--   2 SPACE   the wet path: filter, drive, delay, reverb, shimmer
--   3 SWITCH  the discrete mode/type switches — LAST, on purpose: `mode`
--             respawns the SC voice, so switching it after everything else
--             means the new voice is BORN with the scene's params instead of
--             being born wrong and then jumped to them.
--
-- add a new mangle param to the right block and it joins scenes, morphs and
-- the safe snapshot at once (MOTION_IDS in mmotion is the same idea for the
-- gesture looper — the two lists are siblings, kept separate on purpose).

local TIMBRE_IDS = {
  -- source blend. NOT out_level: a scene must never rewrite your stage
  -- volume. (the safe snapshot does take it — see SAFE_EXTRA_IDS.)
  "mix", "sc_level", "cut_level",
  -- playback path + the output->buffer writers. resample only bites on
  -- the next armed take; regen and erode quietly rewrite the buffer, which
  -- is exactly why a scene should be able to pull them back to 0. wear is
  -- just a tone control and morphs freely. (orbit_* stays OUT of every
  -- list: it is a transport, like motion_*.)
  "dry_wet", "resample", "regen", "erode", "wear",
  -- window / scan
  "pos_start", "pos_end", "scan", "pos_jitter",
  -- grain + clouds (the granular character)
  "size", "density", "pitch", "spread", "pan", "grain_level",
  "grain_jitter", "grain_pitch_spread",
  "clouds_pos", "clouds_tex", "clouds_fb", "clouds_lofi",
  -- stretch shape (mode itself is a SWITCH, below)
  "warp_window", "warp_overlaps", "warp_rand",
  -- tape deck (loop bounds ride along, so a scene = a loop region too).
  -- cut_source is the record-SOURCE blend (dry..wet print) — continuous and
  -- slew-safe, so it morphs; it selects what WOULD be written, never writes.
  "tape_rate", "loop_start", "loop_end", "tape_pre", "tape_fade", "cut_source",
  -- polyphonic pad voices
  "voices", "voice_atk", "voice_rel", "pad_level",
  -- the layer decks: their loops, speeds and levels are performance state and
  -- belong in a scene. rec/play are TRANSPORTS and stay out, exactly like
  -- tape_rec — a scene changes how it sounds, never whether it is running.
  -- layer_sel stays out too: it is a UI cursor, like scene_slot.
  "lay1_level", "lay1_rate", "lay1_start", "lay1_end", "lay1_pre",
  "lay1_fade", "lay1_width",
  "lay2_level", "lay2_rate", "lay2_start", "lay2_end", "lay2_pre",
  "lay2_fade", "lay2_width",
  -- track 2 (mangler2): the same knobs as track 1, so a scene keeps both
  "t2_level", "t2_pos_start", "t2_pos_end", "t2_scan", "t2_pitch", "t2_pan",
  "t2_pos_jitter", "t2_size", "t2_density", "t2_spread", "t2_grain_jitter",
  "t2_grain_pitch_spread", "t2_clouds_pos", "t2_clouds_tex", "t2_clouds_fb",
  "t2_clouds_lofi", "t2_warp_window", "t2_warp_overlaps", "t2_warp_rand",
  "t2_cutoff", "t2_resonance",
  -- NB: seq_slice (the PADS edit cursor) is deliberately NOT captured — it's a
  -- UI selector like scene_slot / motion_lane, not sound; a scene shouldn't
  -- move your cursor, and a morph must never lerp it across slices.
}

local SPACE_IDS = {
  "cutoff", "resonance", "drive",
  "delay_time", "delay_fb", "delay_mix",
  "rev_decay", "rev_damp", "rev_size", "rev_early", "rev_moddepth",
  "rev_modfreq", "rev_low", "rev_mid", "rev_high", "rev_lowcut",
  "rev_highcut", "rev_mix",
  "shimmer", "shimmer_pitch", "shimmer_tone",
}

local SWITCH_IDS = {
  "filt_type", "clouds_mode", "grain_shape",
  "delay_sync",   -- a scene remembers whether the delay follows the clock
  "win_beats",    -- ...and whether the window's length does
  "freeze", "pv_freeze", "tape_freeze", "pad_input",
  "tape_reverse",   -- tape direction is a LATCHING state under the punch law
  "lay1_reverse", "lay2_reverse",   -- ...and so is each layer's
  "vis_look",   -- the look the visuals show: a scene can bring its own
  "t2_filt_type", "t2_clouds_mode", "t2_grain_shape", "t2_pv_freeze",
  "t2_mode",   -- respawns track 2's voice
  "mode",   -- last of the last: this one respawns the voice
}

-- `tape_reverse` IS captured/recalled. The punch law makes TAPE K3 a LATCHING
-- toggle (a tap holds tape_reverse=1 until tapped again), so it is a real state —
-- and the direction lives ONLY here: Mtape.update_tape_rate does
-- `tape_rate * (tape_reverse==1 and -1 or 1)` with tape_rate kept positive, so a
-- backwards scene is NOT stored in tape_rate. It is in MORPH_EXCLUDE, though: a
-- morph must not flip the tape mid-sweep (a hard event, like a freeze).

local function append(dst, src)
  for i = 1, #src do dst[#dst + 1] = src[i] end
end

-- mangler2: tracks 3 and 4 are classified exactly like track 2. Their ids
-- are track 2's with the number changed, appended (TIMBRE) or put beside
-- track 2's (SWITCH, so `mode` stays last of the last).
local function more_tracks(list)
  local out = {}
  for i = 1, #list do
    local id = list[i]
    out[#out + 1] = id
    local rest = id:match("^t2_(.+)$")
    if rest then
      out[#out + 1] = "t3_" .. rest
      out[#out + 1] = "t4_" .. rest
    end
  end
  return out
end
TIMBRE_IDS = more_tracks(TIMBRE_IDS)
SWITCH_IDS = more_tracks(SWITCH_IDS)
-- the sends are sound (what feeds what), so a scene keeps them and a morph
-- crosses them smoothly
for from = 1, 4 do
  for to = 1, 4 do
    if from ~= to then SPACE_IDS[#SPACE_IDS + 1] = "send_" .. from .. "_" .. to end
  end
end

local SCENE_RECALL_IDS = {}
append(SCENE_RECALL_IDS, TIMBRE_IDS)
append(SCENE_RECALL_IDS, SPACE_IDS)
append(SCENE_RECALL_IDS, SWITCH_IDS)

-- MORPH-SAFE = recall MINUS these. the rule, in one line: a morph never
-- flips a hold, never re-routes your notes, never writes the buffer, and
-- never changes the voice structure.
--   freeze / pv_freeze / tape_freeze  holds. crossing 0.5 mid-sweep is a
--     hard event, not a texture — recall the scene if you want the hold.
--   pad_input  note ROUTING. flipping it mid-sweep re-points the keyboard
--     and releases sounding pad voices.
--   resample / regen  the buffer writers. a sweep must stay undo-able, and
--     audio already committed to the buffer is not.
--   voices  the poly CAP. lerping it crosses integers, and every crossing
--     re-caps the engine's allocator — which steals (cuts) held pad notes
--     mid-sweep. structure, not texture: a recall sets it, a morph doesn't.
-- consequence, worth knowing: morph at amt=1 is NOT the same as recall(B) —
-- it moves the morph-safe subset only. sweep to 1, then K2 RCL to land the
-- rest. (the SCENE page says so: see M.unlanded + the "K2 TO LAND THE REST" cue.)
local MORPH_EXCLUDE = {
  freeze = true, pv_freeze = true, tape_freeze = true,
  pad_input = true, resample = true, regen = true, erode = true,
  voices = true,
  -- mode respawns the SC voice: crossing 0.5 mid-sweep is a click + a voice
  -- born with half-morphed params, not a texture. tape_reverse flips playback
  -- direction: also a hard event, not something to cross gradually. recall
  -- carries both; a morph leaves them (sweep to 1, then K2 RCL to land).
  mode = true, tape_reverse = true,
  -- track 2's mode and hold, for the same reasons as track 1's
  t2_mode = true, t2_pv_freeze = true,
  t3_mode = true, t3_pv_freeze = true, t4_mode = true, t4_pv_freeze = true,
  -- the window lock switching mid-sweep re-cuts the window in one frame
  win_beats = true,
  -- a look is a choice, not a texture: it changes at a recall, never mid-sweep
  vis_look = true,
}

-- the two complementary halves of the recall list: what a morph carries, and
-- what it deliberately leaves behind (the latter drives the page's cue).
local SCENE_MORPH_IDS = {}
local MORPH_SKIPPED_IDS = {}
for i = 1, #SCENE_RECALL_IDS do
  local id = SCENE_RECALL_IDS[i]
  if MORPH_EXCLUDE[id] then
    MORPH_SKIPPED_IDS[#MORPH_SKIPPED_IDS + 1] = id
  else
    SCENE_MORPH_IDS[#SCENE_MORPH_IDS + 1] = id
  end
end

-- the safe snapshot is the recall set PLUS the master out: if a throw (or a
-- fat finger) moved your level, the rescue should bring that back too. it
-- still refuses the SYSTEM levels, the transports and stop_all — a restore
-- must never unmute you, re-arm a recording, or undo a STOP you're leaning on.
local SAFE_EXTRA_IDS = { "out_level" }
local SAFE_SNAPSHOT_IDS = {}
append(SAFE_SNAPSHOT_IDS, SAFE_EXTRA_IDS)
append(SAFE_SNAPSHOT_IDS, SCENE_RECALL_IDS)

-- NEVER capture the scene_* params themselves. scene_morph_amt's action
-- re-fires the morph, so a snapshot that restored it would immediately
-- overwrite everything it just restored. (they're also UI selectors — not
-- sound.) this is a note to whoever adds the next param to the lists above.

-- WHAT A SCENE DELIBERATELY LEAVES OUT — the other half of the recall list.
-- membership is TOTAL: test/test_control.lua asserts every param in the
-- paramset is in SCENE_RECALL_IDS or here, never neither and never both, so
-- a NEW param cannot silently miss the decision (the defect that recurred:
-- purity, FINE_IDS, RATE_IDS and these lists each missed a layers param).
-- adding a param now FAILS the harness until it is placed on one side.
local SCENE_EXCLUDE = {
  -- the master + STOP: a scene must never rewrite stage volume or unmute
  -- (out_level is the ONE of these the safe snapshot takes — SAFE_EXTRA_IDS)
  "out_level", "stop_all",
  -- capture transports + write plumbing: a scene changes how it sounds,
  -- never whether or what it is recording
  "rec", "tape_rec", "rec_level", "pre_level", "clear_rec", "sample_file",
  "rec_wait", "rec_thresh",
  "take_undo", "undo_keep",
  "export_take", "take_tighten", "print_take", "print_len",
  "pad_chop", "pad_even",
  "lay1_rec", "lay1_play", "lay2_rec", "lay2_play",
  "lay1_file", "lay2_file", "layer_wet",
  "lay1_snap", "lay2_snap",   -- a gesture, not state: it acts on the loop now
  -- UI cursors + the per-pad lock EDITORS (the locks themselves ride the
  -- padlock pset, not scenes)
  "seq_slice", "layer_sel", "pad_voice", "pad_pitch",
  "track_sel",   -- mangler2: which track VOICE and FILTER address
  "route_sel",   -- mangler2: the ROUTE grid's cursor
  -- config / keys
  "keys_enable", "midi_channel", "root_note", "kb_octave", "pitch_quant",
  -- the other machines' transports, and scene's own params (NEVER capture
  -- scene_*: scene_morph_amt's action re-fires the morph)
  "motion_rec", "motion_play", "motion_lane", "motion_depth", "motion_len",
  "mod_focus",
  "orbit_on", "orbit_rate", "orbit_reach",
  -- the sequencer is a machine like the orbit: its run, and the pattern it
  -- generates, are left where they are by a scene
  "step_run", "step_div", "step_len", "step_fill", "step_order",
  "step_chance", "step_gate",
  -- the beat repeat: a hold you play, not a sound a scene keeps
  "beat_repeat", "repeat_div",
  -- the modulation out: routing to other gear, not sound
  "out_src", "out_midi", "out_ch", "out_cc", "out_crow",
  -- the visuals link: routing to a computer, not sound
  "osc_on", "osc_host", "osc_port", "vis_flash", "vis_midi",
  -- the modulators: machines too. A scene moves the knobs they ride on
  "lfo1_target", "lfo1_shape", "lfo1_period", "lfo1_rate", "lfo1_depth",
  "lfo2_target", "lfo2_shape", "lfo2_period", "lfo2_rate", "lfo2_depth",
  "scene_slot", "scene_morph_amt", "scene_recall_mode", "scene_scope",
  "scene_glide",
  "scene_capture",
  "scene_recall", "scene_next", "scene_clear", "scene_safe_capture",
  "scene_safe_restore", "chaos_throw",
}

-- ===========================================================================
-- module state
-- ===========================================================================

local M = {
  slots = {},         -- slots[1..8] = { id = value } (nil = empty)
  safe = nil,         -- the safe snapshot, same shape
  pending = nil,      -- slot waiting on a quantized recall (nil = none)
  chaos_live = false, -- a chaos throw is currently held
  -- exposed for the harness's classification checks
  SCENE_RECALL_IDS = SCENE_RECALL_IDS,
  SCENE_EXCLUDE = SCENE_EXCLUDE,
}

local dirty = false      -- a morph is pending for the next tick
local morphing = false   -- re-entry guard (a param action must never recurse)
local last_sent = {}     -- morph: the last value/norm we pushed, per param
local pending_clock      -- the quantized-recall coroutine (nil = none)

-- THE MORPH'S OTHER END: the sound you were making when you started sweeping.
-- taken on the rising edge out of 0 and dropped when you come home to 0 (or
-- when something else moves the instrument — see invalidate).
--
-- "from HERE to that slot" needs no A/B selector: recall A (K2) then sweep
-- toward B still does the old A->B, and it makes ONE stored scene immediately
-- useful — with a single capture you can mangle the sound and slide back.
local morph_from = nil

local QUANT_BEATS = { 0, 1, 4 }   -- scene_recall_mode: NOW / BEAT / BAR
local GLIDE_MODE = 4              -- ...and GLIDE (scene_glide beats, then land)

-- ===========================================================================
-- param plumbing
-- ===========================================================================

local function lookup(id)
  return params.lookup[id] and params:lookup_param(id) or nil
end

local function slot_idx(slot)
  return clamp(floor((slot or pget("scene_slot", 1)) + 0.5), 1, NUM_SLOTS)
end

-- EVERY write in this module goes through here.
-- 1) params stay the single source of truth — we set the same ids the
--    encoders, keys and MIDI CCs set, and their actions do the engine work.
-- 2) the gesture looper is told the value came from US. mmotion captures by
--    polling for changes, so without this a scene jump or a morph sweep would
--    look exactly like forty hands on forty knobs and punch a lane for each.
--    scenes and motion stay orthogonal drivers: motion records the MORPH KNOB
--    (scene_morph_amt is in MOTION_IDS) and replays that — one lane, not forty.
local function pset(id, v)
  params:set(id, v)
  local mo = C.motion
  -- account for the RESOLVED value: a control quantizes what you hand it
  if mo and mo.account then mo.account(id) end
end

-- the morph's "already sent" memory is only valid while nothing else moves
-- the instrument, and its origin only while the sweep is the thing driving
-- the sound. reset_morph drops both, so the next amount move departs from
-- wherever we are by then. A capture or a clear needs only this: it changes
-- what a slot holds, and moves no param.
local function reset_morph()
  for k in pairs(last_sent) do last_sent[k] = nil end
  M.engaged = false
  morph_from = nil
end

-- the INSTRUMENT moved (a recall, a restore, a chaos throw, a pset load):
-- reset the morph, and forget the key throws too. OPEN / WASH / INF / HEAL
-- each cache the values they displaced, to put back on un-latch; whatever
-- just moved the instrument moved those params as well, so un-latching would
-- write pre-recall values over the recall. A capture must NOT do this: it
-- moves nothing, and latch-OPEN, capture, un-latch is how a variant is built.
function M.invalidate()
  reset_morph()
  if C and C.throws_forget then C.throws_forget() end
end

-- ===========================================================================
-- feedback — every action says what it did, on screen AND in maiden
-- ===========================================================================
-- a scene action is far too easy to miss. capture moves ONE 13px box; recall
-- of the slot you just captured re-applies the sound you are ALREADY making,
-- so it is inaudible by definition; recall of an empty slot did nothing at all
-- and said nothing about it. that combination reads exactly like "the keys do
-- nothing, there's no sound" — which is what it was reported as, on a page
-- whose code was firing correctly the whole time. a performance page that
-- can't prove it worked is broken, whatever the code does.
--
-- so: one call, two audiences. `msg` is a chip on the page for ~1s; the detail
-- goes to maiden, where you can read the whole story after the fact (the
-- codebase already leans on bring-up prints for exactly this reason).
-- the "- SAME" variants are the important ones: they mean the action landed
-- and NOTHING moved, which is precisely why you can't hear anything.

local function say(msg, detail, slot)
  M.msg, M.msg_at, M.msg_slot = msg, C.frame, slot
  print("mangler: " .. (detail or msg))
end

local function say_recall(slot, n, moved)
  if moved == 0 then
    say("RECALL " .. slot .. " - SAME",
      "scene " .. slot .. " recalled — " .. n .. " params set, NONE moved: the"
      .. " instrument already sounds like this scene, which is why nothing"
      .. " changed. capture a DIFFERENT sound to another slot to hear a recall.",
      slot)
  else
    say("RECALL " .. slot,
      "scene " .. slot .. " recalled — " .. moved .. " of " .. n
      .. " params moved", slot)
  end
end

local function snapshot_ids(ids)
  local t, n = {}, 0
  for i = 1, #ids do
    local id = ids[i]
    if params.lookup[id] then
      t[id] = params:get(id)
      n = n + 1
    end
  end
  return t, n
end

-- region edges: two params that only mean something as a PAIR. setting them
-- one at a time means the consumer reads ONE new edge against ONE old one for
-- an instant — softcut can render up to a block of a region that is neither
-- the old nor the new one (and update_tape_loop's `hi-lo < 0.1` floor turns a
-- crossed pair into a 100ms loop, which jumps the head audibly). so: move the
-- edge that widens the region FIRST, and every intermediate contains a real
-- region instead of a bogus one. `start` key -> `end` key.
local EDGE_PAIRS = { pos_start = "pos_end", loop_start = "loop_end",
                     lay1_start = "lay1_end", lay2_start = "lay2_end",
                     t2_pos_start = "t2_pos_end", t3_pos_start = "t3_pos_end",
                     t4_pos_start = "t4_pos_end" }
M.EDGE_PAIRS = EDGE_PAIRS   -- the harness asserts every _start/_end pair joins

-- A STORED window is clamped to the material before it is applied. Scenes
-- capture pos_start/pos_end verbatim, but the take may be shorter by the time
-- the scene comes back. The classic trap: capture a scene before recording
-- (window = the whole 60s buffer), record a 4s phrase (the rec-stop snaps the
-- window to it), recall the scene, and the window reopens over ~56 seconds of
-- nothing, so what you were listening to comes around once a minute. Beyond
-- C.take_len (the content high-water mark, from frame 0) there is silence BY
-- DEFINITION, so clamping a stored edge into it can only remove silence,
-- never sound. Only STORED values pass through here: a recall, a safe
-- restore, a morph target. Live values stay exact, so the encoder can still
-- open the window wherever it likes, and a sweep coming home restores the
-- origin verbatim (morph_from bypasses this).
--
-- The LOOP DECKS have the same trap: capture a scene while a layer is empty
-- (its loop 0..1), record a 4s pass (the loop closes around it), recall, and
-- the loop reopened over 60 seconds of nothing. A deck's material does not
-- start at 0, so the decks clamp to the EXTENT that was written (C.material:
-- lo, hi in the deck's own 0..1), and only when the stored loop is more than
-- TWICE the material and overlaps it. A loop's LENGTH is musical (SNAP puts
-- it on a grid), so a loop that is merely a little longer than what was
-- played into it is left alone; and a stored loop entirely elsewhere points
-- at something we cannot know about, and stays exactly as stored.
local WINDOW_IDS = { pos_start = true, pos_end = true }
local EXTENT_OF = {
  loop_start = "tape", loop_end = "tape",
  lay1_start = "lay1", lay1_end = "lay1", lay2_start = "lay2", lay2_end = "lay2",
}
-- the same pairs, both ways round (shared with motion replay)
local PARTNER = {}
for a, b in pairs(EDGE_PAIRS) do PARTNER[a], PARTNER[b] = b, a end
M.PARTNER = PARTNER

local function clamp_stored(id, v, tbl)
  if v == nil then return v end
  if WINDOW_IDS[id] then
    local tl = (C and C.wave_any and C.take_len) or 0
    if tl <= 0.002 or tl >= 0.999 then return v end   -- no/full material: exact
    local cap = id == "pos_end" and tl or (tl - 0.002)
    return v < cap and v or cap
  end
  local key = EXTENT_OF[id]
  if not (key and tbl and C and C.material) then return v end
  local mlo, mhi = C.material(key)
  if not mlo then return v end                      -- nothing known: exact
  local is_start = EDGE_PAIRS[id] ~= nil
  local s, e = v, tbl[PARTNER[id]]
  if not is_start then s, e = e, v end
  if s == nil or e == nil or s > e then return v end
  if not (s < mhi and e > mlo) then return v end    -- elsewhere: exact
  if e - s < 2 * (mhi - mlo) then return v end       -- near the material: exact
  local ns, ne = max(s, mlo), min(e, mhi)
  if ne - ns < 0.002 then return v end
  return is_start and ns or ne
end

-- set one param and report whether the value actually MOVED. the count of
-- moved params is what tells a performer why a recall was silent: 0 moved
-- means the scene and the live sound are already the same.
local function set_moved(id, v)
  local before = params:get(id)
  pset(id, v)
  return params:get(id) ~= before and 1 or 0
end

-- apply a stored table, walking `ids` IN ORDER (timbre -> space -> switches;
-- see the list comment). params missing from the table are skipped, so a
-- scene captured by an older version still recalls what it does know.
-- returns: how many params were set, how many of them actually changed.
local function apply(tbl, ids)
  if not tbl then return 0, 0 end
  local n, moved = 0, 0
  local done                      -- edge partners already set (nil until needed)
  for i = 1, #ids do
    local id = ids[i]
    local v = clamp_stored(id, tbl[id], tbl)
    if v ~= nil and params.lookup[id] and not (done and done[id]) then
      local partner = EDGE_PAIRS[id]
      local pv = partner and clamp_stored(partner, tbl[partner], tbl)
      if pv ~= nil and params.lookup[partner] then
        -- outward edge first: if the new start moves LEFT it's the widening
        -- one, else the new end is
        if v < params:get(id) then
          moved = moved + set_moved(id, v) + set_moved(partner, pv)
        else
          moved = moved + set_moved(partner, pv) + set_moved(id, v)
        end
        done = done or {}
        done[partner] = true
        n = n + 2
      else
        moved = moved + set_moved(id, v)
        n = n + 1
      end
    end
  end
  M.invalidate()
  return n, moved
end

-- a recall still on its way (queued for a beat, or gliding) is forgotten by
-- anything that lands something else: another recall, the way back, a load
local function cancel_pending()
  if pending_clock then clock.cancel(pending_clock) end
  pending_clock, M.pending = nil, nil
  M.glide = nil
end

-- A scene LANDED (a recall, the way back): it IS the new LIVE. ONE place does
-- what every landing needs, because each landing path used to remember a
-- different subset of it:
--   the morph amount goes home. apply() has already dropped the sweep's
--     origin, so writing 0 moves nothing; left up, the rail lied and merely
--     selecting another slot at rest jumped the sound toward it.
--   a held chaos throw ENDS. its release restores ◄, and a recall made
--     mid-hold has just re-marked ◄ with the chaos state, so releasing the
--     footswitch would drag you back onto the madness over the scene you chose.
local function land(tbl, ids)
  local n, moved = apply(tbl, ids)
  M.chaos_live = false
  if pget("scene_morph_amt", 0) > 0 then pset("scene_morph_amt", 0) end
  return n, moved
end

-- the orbit's state (declared here: capture reads it)
local orbit = { on = false, live = false, leg_start = 0, leg_len = 1,
                wrote = nil, hand_at = nil }
local capture_free   -- defined below capture, which it calls

-- ===========================================================================
-- scenes — capture / recall / clear
-- ===========================================================================

-- capture the live state of SCENE_RECALL_IDS into a slot (default: the
-- selected one). overwrites without ceremony — like every other throw in this
-- instrument, the key does the thing.
-- slot 0 is the ◄ cell — the way back. capturing into it marks the
-- safe state, recalling it restores, clearing it forgets. the bank proper
-- stays 1..8; every ◄ caller branches here BEFORE slot_idx clamps.
local function is_back(slot)
  return floor((slot or pget("scene_slot", 1)) + 0.5) < 1
end

function M.capture(slot)
  if is_back(slot) then return M.safe_capture() end
  -- while the orbit runs it keeps re-aiming the selector, so a no-slot
  -- capture (SCENE K3, the scene_capture param) would land in whatever
  -- slot the wander just targeted and overwrite a scene it navigates by.
  -- redirect to the first empty slot; an EXPLICIT slot stays explicit.
  if slot == nil and orbit.on then return capture_free() end
  slot = slot_idx(slot)
  -- capture SCOPE (Octatrack-style): ALL = the whole mangle; FX = just the
  -- wet path (SPACE_IDS: filter, drive, delay, reverb, shimmer), so a slot
  -- becomes an effects preset that recalls and morphs OVER whatever material
  -- and voice you have at the time. apply() skips ids a slot does not carry,
  -- so partial slots were always legal; this makes them a supported gesture.
  local fx_only = floor(pget("scene_scope", 1) + 0.5) == 2
  local t, n = snapshot_ids(fx_only and SPACE_IDS or SCENE_RECALL_IDS)
  M.slots[slot] = t
  reset_morph()    -- the target's contents may have just changed under a sweep
  say("SAVED " .. slot .. (fx_only and " FX" or ""),
    "scene " .. slot .. " captured — " .. n .. (fx_only
      and " params (FX only: filter, drive, delay, reverb, shimmer)"
      or " params (the whole mangle: window, grain, stretch, tape loop,"
      .. " filter, FX, voices)"), slot)
  return true
end

-- recall a slot. scene_recall_mode decides when it lands (NOW / next BEAT /
-- next BAR). a queued recall replaces any other queued recall — last press
-- wins.
function M.recall(slot)
  if is_back(slot) then return M.safe_restore() end
  slot = slot_idx(slot)
  local scene = M.slots[slot]
  if not scene then
    -- an empty slot used to be a silent no-op, which reads as a dead key
    say("SLOT " .. slot .. " EMPTY",
      "scene " .. slot .. " is empty — nothing to recall. K3 (CAP) stores the"
      .. " current sound into it first.", slot)
    return false
  end
  local mode = floor(pget("scene_recall_mode", 1) + 0.5)
  local beats = QUANT_BEATS[mode] or 0
  cancel_pending()
  if mode == GLIDE_MODE then
    -- GLIDE: the morph sweeps there over scene_glide beats, then the scene
    -- LANDS (the holds, routing and writers a morph never moves included).
    -- An Octatrack-style crossfade instead of a jump. ◄ marks where it began.
    local b = pget("scene_glide", 4)
    if floor(pget("scene_slot", 1) + 0.5) ~= slot then pset("scene_slot", slot) end
    M.auto_safe()
    -- a held chaos throw ends HERE, as land() ends it for the other modes:
    -- ◄ now holds the chaos state, and the footswitch's release would restore
    -- it over the scene this glide is heading for
    M.chaos_live = false
    M.glide = { slot = slot, from = C.frame, a0 = pget("scene_morph_amt", 0),
      frames = math.max(1, floor(b * 60 / (C.tempo and C.tempo() or 120)
        * (C.FPS or 15) + 0.5)) }
    say("GLIDE " .. slot, "scene " .. slot .. " gliding in over " .. b
      .. " beats, then it lands", slot)
    return true
  end
  if beats > 0 then
    M.pending = slot
    say("QUEUED " .. slot,
      "scene " .. slot .. " queued — lands on the next "
      .. (beats > 1 and "bar" or "beat"), slot)
    -- ONE coroutine, always cancelled on replace / restore / cleanup (the
    -- norns clock-race gotcha: a timer resuming a dead thread wedges clock)
    pending_clock = clock.run(function()
      clock.sync(beats)
      pending_clock, M.pending = nil, nil
      M.auto_safe()   -- ◄ = where you just were, even for a queued landing
      say_recall(slot, land(M.slots[slot], SCENE_RECALL_IDS))
    end)
    return true
  end
  -- every commit auto-captures the pre-state into the ◄ cell — an
  -- undo that never needed arming. (quiet: the recall is the news here.)
  M.auto_safe()
  say_recall(slot, land(scene, SCENE_RECALL_IDS))
  return true
end

-- advance to the NEXT FILLED slot (cycling, skipping empties) and recall it —
-- the stomp-through-a-set gesture (scene_next, MIDI-map a footswitch). moves
-- the ONE selector so the page/grid/morph all follow, then recalls through
-- the normal path (BEAT/BAR quantize and auto-safe both apply).
function M.next()
  -- from the ◄ cell the next slot is 1 (slot_idx would clamp ◄ to 1 and
  -- start the search at 2)
  local start = is_back() and 0 or slot_idx()
  for i = 1, NUM_SLOTS do
    local s = ((start - 1 + i) % NUM_SLOTS) + 1
    if M.slots[s] then
      params:set("scene_slot", s)
      return M.recall(s)
    end
  end
  say("NO SCENES", "no filled slots to advance to — CAP stores one first")
  return false
end

-- capture into the first EMPTY slot (the orbit's CAP: bottling a found
-- sound must never overwrite a scene the wander is navigating by)
capture_free = function()
  for s = 1, NUM_SLOTS do
    if not M.slots[s] then return M.capture(s) end
  end
  say("BANK FULL",
    "all 8 slots hold scenes — clear one to keep the orbit's find")
  return false
end

function M.clear(slot)
  if is_back(slot) then
    local had = M.safe ~= nil
    M.safe = nil
    say(had and "CLEARED <" or "< EMPTY",
      had and "the ◄ way-back state was cleared"
      or "the ◄ cell was already empty")
    return true
  end
  -- the orbit re-aims the selector every leg, so a no-slot clear (the
  -- scene_clear footswitch) would erase whatever the wander picked. The key
  -- path passes the slot it pressed on; an unaddressed clear refuses.
  if slot == nil and orbit.on then
    say("ORBIT RUNNING", "the orbit is moving the selector — stop it (orbit run)"
      .. " before clearing a slot from the footswitch")
    return false
  end
  slot = slot_idx(slot)
  local had = M.slots[slot] ~= nil
  M.slots[slot] = nil   -- in place: the grid and the page read this table
  if M.pending == slot or (M.glide and M.glide.slot == slot) then
    cancel_pending()
  end
  reset_morph()
  say(had and ("CLEARED " .. slot) or ("SLOT " .. slot .. " EMPTY"),
    had and ("scene " .. slot .. " cleared") or
    ("scene " .. slot .. " was already empty"), slot)
  return true
end

-- ===========================================================================
-- morph — from where you are toward a slot, one knob
-- ===========================================================================
-- continuous params interpolate in the controlspec's OWN (warped) space
-- (ctx.warped_lerp): cutoff 20 -> 20000 is exponential, so a raw lerp would
-- sit at "nearly open" for the whole second half of the sweep.
-- numbers (voices, warp_overlaps) lerp and land on integers; options and
-- binaries can't be half-switched, so they flip at the midpoint (amt >= 0.5).

local function morph_value(id, va, vb, amt)
  local p = lookup(id)
  if not p then return nil end
  local cs = p.controlspec
  if cs then
    -- the normalized target doubles as the deadband key below: if a param is
    -- identical in A and B, tn never moves and it never gets sent at all
    return C.warped_lerp(cs, va, vb, amt)
  end
  if p.count then                                  -- option: midpoint switch
    return amt < 0.5 and va or vb
  end
  if p.min and p.max then                          -- number: lerp -> integer
    return clamp(floor(va + (vb - va) * amt + 0.5), p.min, p.max)
  end
  return amt < 0.5 and va or vb                    -- binary / unknown
end

-- normalized deadband: a param must move at least this much (of its full
-- range) before we re-send it. kills duplicate engine commands on a sweep
-- without being coarse enough to see or hear.
local MORPH_EPS = 1 / 400

-- the sweep in progress, read by emit(). Module state rather than a closure
-- per call: the morph runs every frame while a sweep or the orbit moves, and
-- this is the hot path that is meant to allocate nothing.
local sw_amt, sw_force = 0, false
local pair_done = {}       -- edge partners already written this pass (reused)

-- one param's step of the sweep. `vb` arrives already clamped to the
-- material (clamp_stored).
--   va nil              the origin never had it (an older capture): skip.
--   vb nil              the CURRENT aim does not carry it (an FX-only slot,
--                       a partial preset slot). If this sweep already moved it
--                       under an earlier aim, its line now runs from the
--                       origin to itself, so it goes home; otherwise skip.
--   va == vb            the Octatrack rule: a param identical at both ends is
--                       not the morph's to move, so a hand riding it stays
--                       live, even through the forced ends. An id this sweep
--                       already displaced (last_sent) still tracks the line.
local function emit(id, va, vb)
  if va == nil or not params.lookup[id] then return end
  if vb == nil then
    if last_sent[id] == nil then return end
    vb = va
  end
  if va == vb and last_sent[id] == nil then return end
  local v, tn = morph_value(id, va, vb, sw_amt)
  if v == nil then return end
  local key = tn or v          -- continuous: compare norms; discrete: values
  local last = last_sent[id]
  local fire = sw_force or last == nil
    or (tn and abs(tn - last) >= MORPH_EPS)
    or (not tn and v ~= last)
  if fire then
    pset(id, v)
    last_sent[id] = key
  end
end

-- morph `amt` (0..1) of the way from where you were toward `slot`.
--   amt 0   the sound you had when you started sweeping (exactly)
--   amt 1   that slot's stored sound (exactly, for the morph-safe subset)
-- returns false when the slot is empty, or when there's nothing to do (parked
-- at 0 with no sweep in progress — at rest the sound is just the sound).
function M.morph(slot, amt)
  if morphing then return false end    -- a param action can never recurse in
  amt = clamp(amt or 0, 0, 1)
  local B = (not is_back(slot)) and M.slots[slot_idx(slot)] or nil
  if not B then
    -- ◄ / an empty slot can't be swept TOWARD — but a sweep already engaged
    -- must still come HOME: re-aim the selector at a dead target mid-sweep
    -- and turning the knob to 0 restores the origin of everything this sweep
    -- displaced (exactly the ids in last_sent). without this the sweep was
    -- stranded: neither able to move nor to land home.
    if not (amt <= 0 and morph_from) then return false end
    morphing = true
    -- walk the morph list IN ORDER (like every other writer here), restoring
    -- only the ids this sweep displaced (the last_sent filter). the region
    -- pairs go WIDENING EDGE FIRST — the same rule apply() and the sweep
    -- follow: restored in bare list order a pair can cross for one write,
    -- and a crossed pair hits the 100ms loop floor and jumps the head.
    local function back(k)
      if last_sent[k] ~= nil and morph_from[k] ~= nil
          and params.lookup[k] then
        pset(k, morph_from[k])
      end
    end
    local rdone
    for i = 1, #SCENE_MORPH_IDS do
      local id = SCENE_MORPH_IDS[i]
      if not (rdone and rdone[id]) then
        local partner = EDGE_PAIRS[id]
        if partner and morph_from[id] ~= nil and params.lookup[id]
            and morph_from[partner] ~= nil and params.lookup[partner] then
          if morph_from[id] < params:get(id) then back(id); back(partner)
          else back(partner); back(id) end
          rdone = rdone or {}
          rdone[partner] = true
        else
          back(id)
        end
      end
    end
    morphing = false
    M.invalidate()   -- forget the sweep: we are home
    return true
  end
  if amt <= 0 and not morph_from then return false end
  -- rising edge out of 0: where we are RIGHT NOW is the other end of the sweep
  local A = morph_from or snapshot_ids(SCENE_MORPH_IDS)
  morph_from = A
  -- at the ends, land EXACTLY on the stored values (no deadband rounding)
  sw_amt, sw_force = amt, amt <= 0 or amt >= 1
  morphing = true
  local ids = SCENE_MORPH_IDS
  for k in pairs(pair_done) do pair_done[k] = nil end
  for i = 1, #ids do
    local id = ids[i]
    if not pair_done[id] then
      local partner = EDGE_PAIRS[id]
      local bv = clamp_stored(id, B[id], B)   -- a stored loop aims at material
      if partner and params.lookup[partner]
          and A[id] ~= nil and B[id] ~= nil
          and A[partner] ~= nil and B[partner] ~= nil then
        -- a REGION's two edges move together, and the WIDENING one goes first —
        -- the same rule apply() follows, and for the same reason: written in
        -- list order a sweep can momentarily cross the pair, and a crossed pair
        -- hits the 100ms minimum-length floor, which jumps the softcut head.
        -- The morph runs this 15 times a second, so it meets the hazard far
        -- more often than a recall does.
        local pv = clamp_stored(partner, B[partner], B)
        local nv = morph_value(id, A[id], bv, amt)
        if nv ~= nil and nv < params:get(id) then
          emit(id, A[id], bv); emit(partner, A[partner], pv)
        else
          emit(partner, A[partner], pv); emit(id, A[id], bv)
        end
        pair_done[partner] = true
      else
        emit(id, A[id], bv)
      end
    end
  end
  morphing = false
  M.engaged = amt > 0   -- the morph is what's driving the sound... unless home
  if amt <= 0 then
    -- home again, exactly where you started. forget the "from" so the NEXT
    -- sweep departs from wherever you are by then, and forget what we sent so
    -- it re-asserts from scratch.
    morph_from = nil
    for k in pairs(last_sent) do last_sent[k] = nil end
  end
  return true
end

-- does this slot hold state a MORPH can't carry? (the MORPH_SKIPPED_IDS —
-- holds, routing, buffer writers, the voice cap.) true = the sweep has
-- arrived but those are still sitting where you left them, and only a K2
-- recall lands them. drives the SCENE page's "K2 TO LAND THE REST" cue, which
-- exists so `morph(1) ~= recall(B)` is visible instead of mysterious. The ◄
-- cell is never "unlanded": K2 there is the way back, not a landing.
function M.unlanded(slot)
  if is_back(slot) then return false end
  local scene = M.slots[slot_idx(slot)]
  if not scene then return false end
  for i = 1, #MORPH_SKIPPED_IDS do
    local id = MORPH_SKIPPED_IDS[i]
    local v = scene[id]
    if v ~= nil and params.lookup[id]
        and abs(params:get(id) - v) > 1e-6 then
      return true
    end
  end
  return false
end

-- scene_morph_amt's action calls this: mark the sweep dirty and let the next
-- frame do the work (see the coalescing note at the top).
function M.touch()
  dirty = true
end

-- ===========================================================================
-- orbit: the instrument wanders the scene bank by itself
-- ===========================================================================
-- one leg at a time: pick a filled slot, ramp the morph partway toward it
-- (orbit_reach) over orbit_drift seconds, park there, pick another. parking
-- means dropping the sweep origin without applying anything, so the next leg
-- departs from the in-between sound the last one found. everything goes
-- through the same scene_slot and scene_morph_amt params a hand would use:
-- the SCENE page shows the wander live, and CAP bottles any moment of it.
-- with one filled slot each leg halves the remaining distance toward it;
-- with none the orbit idles. math.random stays out of the draw path.

-- (`orbit` itself is declared above capture, which reads it)

-- parking moves no param: it only drops the sweep's origin, so the next leg
-- departs from wherever this one left the sound. It must not forget the key
-- throws (it is not the instrument moving), and it writes the morph amount
-- home silently (with no origin, 0 sends nothing).
local function orbit_park()
  reset_morph()
  pset("scene_morph_amt", 0)
end

local orbit_filled = {}   -- reused: the orbit looks for a target every leg
local function orbit_new_leg()
  local filled, cur = orbit_filled, slot_idx()
  for k = #filled, 1, -1 do filled[k] = nil end
  for s = 1, NUM_SLOTS do
    if M.slots[s] and s ~= cur then filled[#filled + 1] = s end
  end
  if #filled == 0 and not M.slots[cur] then return false end
  local target = #filled > 0 and filled[math.random(#filled)] or cur
  pset("scene_slot", target)
  orbit.leg_start = C.frame
  orbit.leg_len = math.max(2, math.floor(pget("orbit_rate", 12) * (C.FPS or 15)))
  return true
end

function M.orbit_set(on)
  orbit.on = on
  orbit.wrote, orbit.hand_at = nil, nil
  orbit_park()                 -- depart from (or stop on) wherever we stand
  orbit.live = on and orbit_new_leg()
end

-- the orbit YIELDS to anything else that moves the morph amount: a hand on
-- K1+E1 or a MIDI fader, the RCL peek, a glide, a landing. It watches for a
-- value it did not write, stands still while that keeps happening, and two
-- seconds after it stops parks where the other hand left the sound and
-- starts a fresh leg from there.
local ORBIT_YIELD = 2          -- seconds of quiet before the wander resumes

-- `live` = a leg is actually running. With no filled slot to aim at there is
-- no leg: the orbit looks for a target each frame and touches nothing.
local function orbit_tick()
  if not orbit.on then return end
  local amt = pget("scene_morph_amt", 0)
  -- a held RCL peek parks the amount at 1 and stops moving it, but its
  -- release still needs the sweep's origin to go home: until it is home, the
  -- peek is a hand on the morph even while the value stands still
  if (orbit.wrote ~= nil and abs(amt - orbit.wrote) > 1e-9)
      or C.peek_on or C.peek_back then
    orbit.hand_at = C.frame
  end
  orbit.wrote = amt
  if orbit.hand_at then
    if C.frame - orbit.hand_at < ORBIT_YIELD * (C.FPS or 15) then return end
    orbit.hand_at = nil
    orbit_park()
    orbit.wrote = pget("scene_morph_amt", 0)
    orbit.live = false
  end
  local t = (C.frame - orbit.leg_start) / orbit.leg_len
  if t >= 1 or not orbit.live then
    if orbit.live then orbit_park() end
    orbit.live = orbit_new_leg()
    orbit.wrote = pget("scene_morph_amt", 0)
    if not orbit.live then return end
    t = 0
  end
  pset("scene_morph_amt", pget("orbit_reach", 0.5) * t)
  orbit.wrote = pget("scene_morph_amt", 0)
end

-- a GLIDE in progress: ramp the morph from where it stood to 1 over its
-- frames, then land the scene. A hand on the morph or the selector mid-glide
-- wins: the glide stops and the sound stays where the hand put it.
local function glide_tick()
  local g = M.glide
  if not g then return end
  if floor(pget("scene_slot", 1) + 0.5) ~= g.slot
      or (g.wrote ~= nil and abs(pget("scene_morph_amt", 0) - g.wrote) > 1e-9) then
    M.glide = nil
    say("GLIDE STOPPED", "the glide to scene " .. g.slot .. " stopped: the morph"
      .. " or the selected slot was moved by hand", g.slot)
    return
  end
  local t = (C.frame - g.from) / g.frames
  if t >= 1 then
    M.glide = nil
    say_recall(g.slot, land(M.slots[g.slot], SCENE_RECALL_IDS))
    return
  end
  pset("scene_morph_amt", g.a0 + (1 - g.a0) * t)
  g.wrote = pget("scene_morph_amt", 0)
end

-- one per redraw frame, from the existing 15fps clock in mangler2.lua.
-- the target is simply the SELECTED slot — the same one K2 recalls and K3
-- captures into. one selector, three jobs.
function M.tick()
  glide_tick()                 -- a glide moves the morph before the orbit looks
  orbit_tick()                 -- may set the morph params, marking dirty
  if not dirty then return end
  dirty = false
  M.morph(pget("scene_slot", 1), pget("scene_morph_amt", 0))
end

-- ===========================================================================
-- safe snapshot — the undo for live experimentation
-- ===========================================================================

function M.safe_capture()
  local t, n = snapshot_ids(SAFE_SNAPSHOT_IDS)
  M.safe = t
  say("MARKED <",
    "way-back state marked — " .. n .. " params. select the ◄ cell and K2"
    .. " brings this exact sound back.")
  return true
end

-- the quiet version: every commit recall / chaos throw parks the pre-state
-- in ◄ without stealing the headline from the action itself
function M.auto_safe()
  M.safe = snapshot_ids(SAFE_SNAPSHOT_IDS)
end

-- back to the last known good state, now. control state only: it does not
-- touch the buffer, the tape audio, or held voices — this is an undo for
-- knobs, not a panic mute (K1+K2 STOP is the mute, and it stays yours).
function M.safe_restore()
  if not M.safe then
    say("NO SAFE STATE",
      "no safe state marked yet — select the ◄ cell and K3 (CAP) marks one;"
      .. " every recall and every chaos throw also marks it for you")
    return false
  end
  cancel_pending()   -- a queued recall must not undo the rescue a beat later
  local n, moved = land(M.safe, SAFE_SNAPSHOT_IDS)
  say(moved == 0 and "UNDO - SAME" or "UNDO",
    "safe state restored — " .. moved .. " of " .. n .. " params moved")
  return true
end

-- ===========================================================================
-- chaos throw — hold for madness, release for safety
-- ===========================================================================
-- chaos_throw is a MOMENTARY param: press throws, release restores the safe
-- snapshot. map it to a footswitch or hit the grid pad. the throw is bounded
-- per-param in NORMALIZED space, so it lands somewhere wild but never
-- somewhere silent, and (like the morph) it never touches rec/resample/regen
-- or the levels — everything it does is undo-able, which is the whole point.
-- math.random lives here and nowhere near the draw path: the seeded render
-- suite never calls it, so the pages' RNG stream is untouched.

local CHAOS = {
  { "pos_jitter", 0.35, 1.00 },
  { "density", 0.55, 1.00 },
  { "size", 0.00, 0.45 },
  { "grain_jitter", 0.30, 1.00 },
  { "grain_pitch_spread", 0.20, 0.90 },
  { "clouds_tex", 0.00, 1.00 },
  { "clouds_fb", 0.20, 0.70 },
  { "resonance", 0.40, 0.95 },
  { "drive", 0.20, 0.80 },
  { "delay_fb", 0.50, 0.95 },
  { "delay_mix", 0.30, 0.90 },
  { "rev_mix", 0.30, 0.90 },
  { "shimmer", 0.20, 0.90 },
  { "warp_rand", 0.30, 1.00 },
}
M.CHAOS = CHAOS   -- exposed so the harness can flag an entry for a dead param

-- scan is bipolar — normalized 0.5 is STOPPED. throw it to one side or the
-- other so chaos always keeps moving.
local SCAN_FWD = { 0.62, 0.95 }
local SCAN_REV = { 0.05, 0.38 }

local function set_norm(id, n)
  local p = lookup(id)
  if p and p.controlspec then pset(id, p.controlspec:map(clamp(n, 0, 1))) end
end

local function throw(id, lo, hi)
  set_norm(id, lo + math.random() * (hi - lo))
end

function M.chaos()
  -- never strand the performer: the throw parks where-you-were in ◄, so the
  -- release always has somewhere to land (and ◄ is always the LAST ground)
  M.auto_safe()
  for i = 1, #CHAOS do
    local c = CHAOS[i]
    throw(c[1], c[2], c[3])
  end
  local s = math.random() < 0.5 and SCAN_REV or SCAN_FWD
  throw("scan", s[1], s[2])
  M.invalidate()
  M.chaos_live = true
  say("CHAOS", "chaos thrown — release to land back on the safe state")
  return true
end

-- the release edge. it only acts when a throw is actually live, so a stray 0
-- (params:bang at init, a pset read) can never restore out of nowhere.
function M.chaos_release()
  if not M.chaos_live then return false end
  M.chaos_live = false
  return M.safe_restore()
end

-- ===========================================================================
-- persistence — rides along with the PSET
-- ===========================================================================
-- the scene bank + the safe snapshot save as a plain lua table next to the
-- pset, in the same data/ folder the tape audio uses. mangler2.lua's
-- action_write/read/delete call BOTH modules (mtape does the audio, we do
-- the state) — that hook is shared, never replaced.

local function path_for(number)
  return norns.state.data .. "scenes-" .. number .. ".lua"
end

function M.pset_write(number)
  local ok, err = pcall(tab.save,
    { v = 1, slots = M.slots, safe = M.safe }, path_for(number))
  if not ok then print("mangler: scene save failed — " .. tostring(err)) end
end

function M.pset_read(number)
  -- a pset LOAD is authoritative: params:read() has just restored the VALUES
  -- the sound actually had — and in doing so re-set scene_morph_amt, which
  -- fired touch() and armed a sweep. drop it. re-deriving the morph here would
  -- overwrite any param the performer hand-tweaked AFTER their last morph move
  -- and saved, one frame after the load, silently. the morph re-engages on the
  -- next move of the knob. (this runs from action_read, i.e. after the values.)
  dirty = false
  -- a LOAD is authoritative: cancel any queued (BEAT/BAR) recall FIRST, before
  -- any early return — otherwise a coroutine armed just before the load survives
  -- and fires an old slot over the freshly loaded session a beat later.
  cancel_pending()
  -- the load is authoritative even when NO scene file follows: a morph_from /
  -- last_sent left engaged would re-derive the morph from the PRE-load sound
  -- on the next knob move. (covers every path below, including the early
  -- returns — nothing after this touches the morph state again.)
  M.invalidate()
  local path = path_for(number)
  -- no scene file (a pset from before scenes existed): leave the bank alone,
  -- exactly like mtape leaves the tape audio alone when there's no wav
  if not util.file_exists(path) then return end
  local ok, t = pcall(tab.load, path)
  if not (ok and type(t) == "table" and type(t.slots) == "table") then
    print("mangler: scene file unreadable — " .. tostring(t))
    return
  end
  for i = 1, NUM_SLOTS do
    M.slots[i] = type(t.slots[i]) == "table" and t.slots[i] or nil
  end
  -- CLEAR safe when the loaded pset has none, like the slots — otherwise the
  -- previous session's ◄/safe-state bleeds into this one and its recall jumps
  -- the instrument to a sound this session never captured.
  M.safe = type(t.safe) == "table" and t.safe or nil
end

function M.pset_delete(number)
  os.remove(path_for(number))
end

-- ===========================================================================
-- lifecycle
-- ===========================================================================

function M.init(ctx)
  C = ctx
  pget, clamp = ctx.pget, ctx.clamp
  ctx.scene = M          -- the module, like ctx.motion. its bank is M.slots,
                         -- mutated in place and never reassigned
end

function M.cleanup()
  cancel_pending()
end

return M

end)()
local Mwav = (function()  -- inlined lib/mwav.lua
-- mwav: the wav files lua reads and writes. Lua cannot read an SC or softcut
-- buffer, so every picture and every analysis of audio in this instrument
-- comes from a FILE: a loaded sample, a PSET's saved take, or a dump of the
-- live take (ctx.take_to_wav). This module is that layer:
--   the RIFF walker and the sample decoders (16/24/32-bit PCM, 32-bit float,
--     the extensible header resolved to its real format)
--   the async fill queue that paints 128-bin strips from a file
--   the sample-rate converter (a windowed sinc), so an off-rate file loads in
--     tune
--   onset and transient detection (TIGHTEN, CHOP)
--   the stereo interleave for exports
-- It knows nothing about the screen: mpages owns the strips and hands their
-- bins tables in.

local floor, sin, cos = math.floor, math.sin, math.cos
local abs, min, max = math.abs, math.min, math.max

local clamp
local SERVER_SR

local M = {}

-- like every lib module: bound to the shared ctx (the server rate, clamp)
function M.init(ctx)
  SERVER_SR, clamp = ctx.SERVER_SR, ctx.clamp
end

-- THE FILL QUEUE: an async waveform read. The FAST part (the header, so the
-- caller knows the duration at once) runs in queue_fill; the slow per-bin peak
-- read is deferred to load_tick (BINS_PER_TICK bins a frame on the redraw
-- clock), so a long file draws IN over about a second instead of freezing the
-- screen. ONE queue serves every strip — the take, the tape, the layer decks
-- — so a pset restore can repaint all of them; a new fill for the SAME bins
-- table supersedes the queued one, and fills for different targets coexist.
-- cancel_fill stops only ITS strip's fill (a CLR must stop the very repaint
-- that would redraw what it just erased, and nothing else).
local fills = {}
local BINS_PER_TICK = 10
function M.cancel_fill(bins)
  for i = #fills, 1, -1 do
    if fills[i].bins == bins then
      pcall(function() fills[i].f:close() end)
      table.remove(fills, i)
    end
  end
end
local function cancel_all_fills()
  for i = #fills, 1, -1 do
    pcall(function() fills[i].f:close() end)
    fills[i] = nil
  end
end

-- walk a RIFF/WAVE file to its fmt + data chunks, leaving f positioned at the
-- data. returns afmt, ch, bits, sr, dpos, dlen — or nil if not RIFF/WAVE.
-- shared by every reader below (the previews, the converter, the scans and
-- open_pcm_mono for the export).
local function riff_parse(f)
  local hdr = f:read(12)
  if not hdr or #hdr < 12 or hdr:sub(1, 4) ~= "RIFF" or hdr:sub(9, 12) ~= "WAVE" then
    return nil
  end
  local afmt, ch, bits, sr, dpos, dlen = 1, 1, 16, 48000, nil, 0
  while true do
    local c = f:read(8)
    if not c or #c < 8 then break end
    local id, sz = c:sub(1, 4), string.unpack("<I4", c, 5)
    if id == "fmt " then
      local fmt = f:read(sz)
      if not fmt or #fmt < 16 then break end
      afmt = string.unpack("<I2", fmt, 1)     -- 1 = PCM int, 3 = IEEE float
      ch = string.unpack("<I2", fmt, 3)
      sr = string.unpack("<I4", fmt, 5)
      bits = string.unpack("<I2", fmt, 15)
      -- WAVE_FORMAT_EXTENSIBLE: the real format is the first two bytes of the
      -- SubFormat GUID (1 PCM, 3 float). ffmpeg and SoX write this header for
      -- anything over 16 bits, so a float render arrives looking like PCM;
      -- decoding its float bits as int32 drew noise and converted to buzz.
      if afmt == 0xFFFE and #fmt >= 26 then
        afmt = string.unpack("<I2", fmt, 25)
      end
      -- a frame wider than the stated depth (24 valid bits stored in 32):
      -- read the CONTAINER, whose top bits hold the sample. blockAlign is the
      -- frame size the file actually uses.
      local ba = string.unpack("<I2", fmt, 13)
      if ch > 0 and ba > ch * (bits // 8) and ba % ch == 0 then
        bits = (ba // ch) * 8
      end
    elseif id == "data" then
      dpos, dlen = f:seek(), sz
      break
    else
      f:seek("cur", sz + (sz % 2))            -- riff chunks are word-aligned
    end
  end
  return afmt, ch, bits, sr, dpos, dlen
end

-- one sample decoder per (format, bit depth), each returning -1..1. 16/24/32-bit
-- PCM and 32-bit float are what norns itself can produce (the engine's take
-- dump, the system tape's print), and 8-bit is what old sample packs carry. ONE table: the waveform preview and the sample-rate converter below
-- read the same files, and a second copy would mean a format could draw
-- correctly and convert to noise, or the reverse.
local DECODE = {
  [1] = {
    -- 8-bit WAV is UNSIGNED, centred on 128 (the lo-fi and vintage packs)
    [8] = function(s, p) return (s:byte(p) - 128) / 128 end,
    [16] = function(s, p) return string.unpack("<i2", s, p) / 32768 end,
    [24] = function(s, p) return string.unpack("<i3", s, p) / 8388608 end,
    [32] = function(s, p) return string.unpack("<i4", s, p) / 2147483648 end,
  },
  [3] = {
    [32] = function(s, p) return string.unpack("<f", s, p) end,
  },
}

-- the decoder for a format/depth, or nil (callers read nil as "no preview" /
-- "refuse to convert" rather than drawing or writing a lie). riff_parse has
-- already resolved an extensible header to its real format.
local function wav_decoder(afmt, bits)
  return DECODE[afmt] and DECODE[afmt][bits]
end

-- open `path` and queue an async fill of `bins`: 128 peak bins spanning
-- `secs` seconds, so a file shorter than the span occupies only its share of
-- the strip (the engine clamps its reads the same way — a longer file only
-- occupies `secs` of the buffer, and drawing more would misalign every
-- playhead and slice). supersedes any queued fill of the SAME bins table.
-- returns the seconds the file occupies, or nil for a format the shared
-- decoders cannot read (the caller leaves the strip alone rather than lie).
function M.queue_fill(path, bins, secs)
  M.cancel_fill(bins)
  local f = io.open(path, "rb")
  if not f then return nil end
  local afmt, ch, bits, _, dpos, dlen = riff_parse(f)
  if not afmt then f:close(); return nil end
  local readpeak = wav_decoder(afmt, bits)
  if not dpos or ch < 1 or not readpeak then
    f:close()
    return nil
  end
  local bps = bits // 8
  local fbytes = ch * bps
  local SR = SERVER_SR
  local frames = min(floor(dlen / fbytes), floor(SR * secs))
  local span = clamp(frames / (SR * secs), 0, 1)
  local nb = max(1, floor(span * 128 + 0.5))
  -- hand the slow per-bin peak read to load_tick (below). stride the UNPACKS
  -- (not the disk read) so a transient is never skipped — a 40ms drum hit
  -- vanished when this sampled a few windows per bin instead.
  local stride = max(1, floor(frames * ch / 200000))
  -- the stride counts SAMPLES of interleaved audio: an even stride over
  -- stereo lands on the left channel every time, and a right-only hit never
  -- drew. An odd one alternates.
  if ch > 1 and stride % ch == 0 then stride = stride + 1 end
  if frames > 0 then
    fills[#fills + 1] = { f = f, dpos = dpos, fbytes = fbytes, frames = frames,
      nb = nb, bps = bps, step = stride * bps, readpeak = readpeak, i = 0,
      bins = bins }
  else
    f:close()
  end
  return frames / SR
end

-- fill up to BINS_PER_TICK bins of the queue's HEAD per call (driven by the
-- redraw clock), then close its file and move on. bounded work per frame →
-- the reads never block the UI; each strip draws IN over ~nb/10 frames.
function M.load_tick()
  local p = fills[1]
  if not p then return end
  local bins = p.bins
  local last = min(p.i + BINS_PER_TICK, p.nb)
  for i = p.i + 1, last do
    local b0 = floor((i - 1) / p.nb * p.frames)
    local n = floor(i / p.nb * p.frames) - b0
    local peak = 0
    if n > 0 then
      p.f:seek("set", p.dpos + b0 * p.fbytes)
      local chunk = p.f:read(n * p.fbytes)
      if chunk then
        for pp = 1, #chunk - (p.bps - 1), p.step do
          -- magnitude: the decoder is signed, the strip wants height
          local v = p.readpeak(chunk, pp)
          if v < 0 then v = -v end
          if v > peak then peak = v end
        end
      end
    end
    bins[i] = peak > 1 and 1 or peak
  end
  p.i = last
  if p.i >= p.nb then p.f:close(); table.remove(fills, 1) end
end

-- cancel EVERY in-flight fill (script cleanup)
function M.cancel_load() cancel_all_fills() end

-- ============================================================================
-- sample-rate conversion
-- ============================================================================
-- scsynth's Buffer:readChannel does NO sample-rate conversion and norns runs
-- its server at 48k, so a 44.1k wav — which is most of dust/audio and nearly
-- everything off a card — lands in the take buffer playing 8.8% fast, a
-- semitone and change sharp, with every pad, slice and window inheriting the
-- error. This converts a file to the server rate first.
--
-- It is deliberately here in lua and not in the engine: no new SC command, no
-- fingerprint change, no restart, and it yields so the screen stays live.
-- To change a file's sample rate you have to work out what the signal was
-- doing BETWEEN the samples you have. The shape used to do that is the whole
-- quality question. The simple choice is a cubic curve through four
-- neighbouring samples, which is what a sampler uses for varispeed; it is
-- cheap and it filters nothing.
--
-- Filtering nothing is the problem when converting DOWNWARDS. A 96k file can
-- hold sound up to 48 kHz, and 48k can only hold up to 24 kHz. Anything above
-- that has to be REMOVED first, or it does not disappear: it comes back
-- mirrored into the audible range as a tone that was never in the file. A
-- cubic curve leaves it all there. This shape removes it.
--
-- It is built once per conversion and stored as a table of numbers, so the
-- inner loop is lookups and multiplies rather than trigonometry. Measured at
-- 1.9x the cost of the cubic it replaces (ten seconds of 44.1k stereo: 0.68s
-- against 0.37s on a dev Mac). An import happens once, it already yields to
-- keep the screen alive, and a library converted ahead of time never gets
-- here at all.
local SINC_TAPS = 16          -- samples looked at per output sample; more
                              -- are used when converting downwards
local SINC_PHASES = 512       -- how finely we can land between two samples.
                              -- 1/512 of a sample off is inaudible

-- `cutoff` says how much of the sound has to survive. Converting UP, the
-- source file is the limit and nothing needs removing, so it is 1. Converting
-- DOWN, the new rate is the limit, so it is the ratio between them, and
-- everything above that has to go. Skip this and the mirrored-back tones are
-- the loudest thing in the converted file.
local function build_sinc(cutoff)
  local pi = math.pi
  local half = max(2, floor(SINC_TAPS / 2 / cutoff + 0.5))
  local taps = half * 2
  local k = {}
  for ph = 0, SINC_PHASES - 1 do
    local frac = ph / SINC_PHASES
    local base = ph * taps
    local sum = 0
    for t = 0, taps - 1 do
      local x = (t - half + 1) - frac         -- distance in SOURCE samples
      local a = pi * cutoff * x
      local s = (abs(a) < 1e-9) and cutoff or (cutoff * sin(a) / a)
      -- Taper the ends of the shape smoothly to zero (a Blackman window), or
      -- chopping it off at 16 samples rings.
      -- Measured on a 96k to 48k conversion, as how loud a tone comes back
      -- when it can only get through by being mirrored: 26k -13 dB, 30k
      -- -40 dB, 36k -75 dB, 40k -85 dB. The cubic left all four at -0.2 dB.
      -- So it takes until roughly half again above the limit to get really
      -- quiet, which is what 16 samples buys. What does leak through lands at
      -- 22 kHz and up, where the cubic was dropping the lot into the middle
      -- of the music.
      local u = (x + half) / taps
      s = s * (0.42 - 0.5 * cos(2 * pi * u) + 0.08 * cos(4 * pi * u))
      k[base + t + 1] = s
      sum = sum + s
    end
    -- Make each set of numbers add up to exactly 1. Otherwise each one
    -- amplifies very slightly differently, and since we cycle through them as
    -- we go, that is a volume wobble at the rate we cycle. It is an audible
    -- whine, not a rounding error.
    if sum ~= 0 then
      for t = 1, taps do k[base + t] = k[base + t] / sum end
    end
  end
  return k, half, taps
end

-- open a file for random-access frame reads. nil for anything we cannot
-- decode, so a caller refuses rather than working on silence.
local function open_src(path)
  local f = io.open(path, "rb")
  if not f then return nil, "cannot open " .. tostring(path) end
  local afmt, ch, bits, sr, dpos, dlen = riff_parse(f)
  local dec = afmt and wav_decoder(afmt, bits)
  if not (dec and dpos and ch and ch >= 1 and sr and sr > 0) then
    f:close(); return nil, "unsupported format"
  end
  local bps = bits // 8
  local fbytes = ch * bps
  return { f = f, dpos = dpos, ch = ch, bps = bps, fbytes = fbytes, sr = sr,
           dec = dec, frames = floor(dlen / fbytes), path = path }
end

local function close_src(s) if s and s.f then s.f:close(); s.f = nil end end

-- read n frames from `from` into L/R (1-based), zero-padding outside the file
-- so an interpolator may always ask for a neighbour it cannot have.
local function read_frames(src, from, n, L, R)
  local a, b = max(from, 0), min(from + n, src.frames)
  for i = 1, a - from do L[i], R[i] = 0, 0 end
  for i = max(1, b - from + 1), n do L[i], R[i] = 0, 0 end
  if b <= a then return end
  src.f:seek("set", src.dpos + a * src.fbytes)
  -- a file can be SHORTER than its header claims (a truncated copy, an
  -- interrupted write): a short read must still honour the zero-pad contract
  -- above, or a caller indexes nil exactly where the data chunk lied
  local chunk = src.f:read((b - a) * src.fbytes) or ""
  local dec, ch, bps, fb = src.dec, src.ch, src.bps, src.fbytes
  local o = a - from
  local got = #chunk // fb
  for i = 0, got - 1 do
    local p = i * fb + 1
    local l = dec(chunk, p)
    L[o + i + 1] = l
    R[o + i + 1] = ch > 1 and dec(chunk, p + bps) or l
  end
  for i = o + got + 1, b - from do L[i], R[i] = 0, 0 end
end

-- the converted file is written at 24 BITS. It is the last stop before the
-- engine buffer, and writing 16 threw away the bottom 8 bits of every 24-bit
-- source before it ever got there: a conversion that fixed the pitch and
-- quietly cost the depth.
local SRC_BLOCK = 4096
local SRC_BITS = 24
local SRC_BYTES = SRC_BITS // 8
local SRC_PEAK = 8388607
local SRC_PACK = "<" .. string.rep("i3", SRC_BLOCK * 2)

-- channels, duration and declared rate of a wav, from the header alone. nil
-- for anything that is not a readable RIFF/WAVE: the loaders then load it as
-- it is (no conversion, stereo, the whole region) rather than guessing.
function M.wav_info(path)
  local f = io.open(path, "rb")
  if not f then return nil end
  local afmt, ch, bits, sr, _, dlen = riff_parse(f)
  f:close()
  if not afmt or not sr or sr <= 0 or not ch or ch < 1 then return nil end
  local dur = (dlen and dlen > 0 and bits and bits > 0)
    and dlen / (ch * (bits / 8) * sr) or nil
  return ch, dur, sr
end

-- returns true, seconds  — converted and written to out_path
--         false, seconds — already at `sr`, nothing written
--         nil, err       — could not decode (the caller falls back to loading
--                          the file as-is: audible-but-sharp beats silence),
--                          or `yield` returned false ("cancelled")
function M.convert_sr(path, out_path, sr, yield, max_secs)
  local src, err = open_src(path)
  if not src then return nil, err end
  local in_sr, frames = src.sr, src.frames
  if frames < 2 then close_src(src); return nil, "no audio" end
  -- refuse an implausible declared rate HERE, not just via the caller's cap:
  -- a corrupt header claiming 1 Hz turns a 4800-frame file into 230M output
  -- frames, and an opt-in cap is protection a future caller forgets (the
  -- caller falls back to loading the file as-is, which is bounded)
  if in_sr < 4000 or in_sr > 384000 then
    close_src(src); return nil, "implausible sample rate " .. tostring(in_sr)
  end
  if in_sr == sr then close_src(src); return false, frames / sr end

  local of = io.open(out_path, "wb")
  if not of then close_src(src); return nil, "cannot write " .. tostring(out_path) end
  -- header with placeholder sizes, backpatched at the end
  of:write("RIFF", string.pack("<I4", 36), "WAVE")
  local obytes = SRC_BYTES * 2                    -- bytes per stereo frame
  of:write("fmt ", string.pack("<I4", 16), string.pack("<I2", 1),
    string.pack("<I2", 2), string.pack("<I4", sr),
    string.pack("<I4", sr * obytes),
    string.pack("<I2", obytes), string.pack("<I2", SRC_BITS))
  of:write("data", string.pack("<I4", 0))

  local ratio = in_sr / sr
  local kern, half, taps = build_sinc(min(1, sr / in_sr))
  local out_n = floor(frames / ratio)
  -- bound the OUTPUT, not just the input: the take buffer only holds max_secs
  -- anyway, and without this a corrupt header declaring a tiny rate expands a
  -- small file into gigabytes (4800 frames at a claimed 1 Hz = 921 MB out) —
  -- while a long DJ mix converts minutes of audio the buffer would discard
  if max_secs then out_n = min(out_n, floor(sr * max_secs)) end
  local L, R = {}, {}
  local out_v = {}
  local written = 0
  while written < out_n do
    local bn = min(SRC_BLOCK, out_n - written)
    local p0 = written * ratio
    local p1 = (written + bn - 1) * ratio
    local lo = floor(p0) - half
    local hi = floor(p1) + half + 1
    read_frames(src, lo, hi - lo + 1, L, R)
    for k = 0, bn - 1 do
      local pos = (written + k) * ratio
      local ip = floor(pos)
      local ph = floor((pos - ip) * SINC_PHASES)
      if ph >= SINC_PHASES then ph = SINC_PHASES - 1 end
      local base = ph * taps
      -- tap t reads source frame ip + t - half + 1; the kernel is even, so
      -- the same coefficient serves both sides of the output position
      local j = ip - lo - half + 2
      local vl, vr = 0, 0
      for t = 0, taps - 1 do
        local c = kern[base + t + 1]
        vl = vl + c * (L[j + t] or 0)
        vr = vr + c * (R[j + t] or 0)
      end
      vl = vl * SRC_PEAK
      if vl > SRC_PEAK then vl = SRC_PEAK elseif vl < -SRC_PEAK then vl = -SRC_PEAK end
      vr = vr * SRC_PEAK
      if vr > SRC_PEAK then vr = SRC_PEAK elseif vr < -SRC_PEAK then vr = -SRC_PEAK end
      out_v[k * 2 + 1] = floor(vl + 0.5)
      out_v[k * 2 + 2] = floor(vr + 0.5)
    end
    local fmt = bn == SRC_BLOCK and SRC_PACK or ("<" .. string.rep("i3", bn * 2))
    of:write(string.pack(fmt, table.unpack(out_v, 1, bn * 2)))
    written = written + bn
    -- every block: with the sinc kernel one block is 16 to 64 taps per output
    -- sample, tens of ms on a Mac and several times that on a Pi, and a yield
    -- (clock.sleep(0)) costs nothing next to it. Every 4 blocks was a cadence
    -- sized for the old 4-tap cubic, and it froze the screen in jerks.
    -- A yield that returns false cancels: the caller no longer wants the
    -- result, so the files close and the part-written output goes.
    if yield and yield() == false then
      close_src(src); of:close(); os.remove(out_path)
      return nil, "cancelled"
    end
  end

  local datalen = written * obytes
  of:seek("set", 4);  of:write(string.pack("<I4", 36 + datalen))
  of:seek("set", 40); of:write(string.pack("<I4", datalen))
  close_src(src); of:close()
  return true, written / sr
end

-- WHERE THE SOUND ACTUALLY IS. Returns the first and last positions above a
-- threshold, as fractions of a `buf_secs` buffer — the same units the window
-- uses. nil when the file cannot be read, or when nothing clears the floor
-- (silence), so a caller can tell "nothing there" from "could not look".
--
-- The point: pressing REC and then playing leaves your reaction time at the
-- head of every take, and letting go late leaves room tone at the tail. The
-- rec-stop window snaps to where the HEADS were, not to where the sound is.
function M.onset_bounds(path, from01, to01, buf_secs, thresh, yield)
  local src, err = open_src(path)
  if not src then return nil, err end
  local total = floor(buf_secs * src.sr)
  local from = clamp(floor(from01 * total), 0, src.frames)
  local to = clamp(floor(to01 * total), 0, src.frames)
  if to - from < 64 then close_src(src); return nil, "range is empty" end
  thresh = thresh or 0.004                       -- about -48 dBFS
  local L, R = {}, {}
  local CH = 8192
  local first, last = nil, nil
  local i = from
  while i < to do
    local n = min(CH, to - i)
    read_frames(src, i, n, L, R)
    for k = 1, n do
      local a = abs(L[k]); local b = abs(R[k])
      if a > thresh or b > thresh then
        if not first then first = i + k - 1 end
        last = i + k - 1
      end
    end
    i = i + n
    if yield then yield() end
  end
  close_src(src)
  if not first then return nil, "silence" end
  return first / total, (last + 1) / total
end

-- TRANSIENT DETECTION: where does the material actually start hitting?
-- A 10ms energy envelope; an onset is where energy jumps against its neighbour
-- and clears a floor. Energy tolerates a strided decode (a transient is
-- milliseconds wide, i.e. hundreds of frames), so only every 8th frame of a
-- window is decoded at all: decoding them all and then skipping seven of
-- eight spent most of a CHOP on samples the envelope never read.
--
-- `from01`/`to01` bound the search as fractions of a `buf_secs` buffer, and the
-- cuts come back in the same units — so a caller works in the window's own
-- coordinates and never has to know the file's rate or length.
-- Returns nil (not an empty list) when the file cannot be read, so a caller can
-- tell "no transients here" from "could not look".
function M.transient_cuts(path, from01, to01, maxn, buf_secs, yield)
  local src, err = open_src(path)
  if not src then return nil, err end
  local total = floor(buf_secs * src.sr)
  local from = clamp(floor(from01 * total), 0, src.frames)
  local to = clamp(floor(to01 * total), 0, src.frames)
  if to - from < 64 then close_src(src); return nil, "range is empty" end

  local win = max(64, floor(src.sr * 0.01))
  local stride = 8
  local env = {}
  local dec, fb, bps, stereo = src.dec, src.fbytes, src.bps, src.ch > 1
  local i, k = from, 0
  while i < to do
    local n = min(win, to - i)
    src.f:seek("set", src.dpos + i * fb)
    local chunk = src.f:read(n * fb) or ""   -- short read = the file lied: zeros
    local got = #chunk // fb
    local e = 0
    for j = 0, got - 1, stride do
      local p = j * fb + 1
      local l = abs(dec(chunk, p))
      local a = l + (stereo and abs(dec(chunk, p + bps)) or l)
      if a > e then e = a end
    end
    k = k + 1
    env[k] = e * 0.5
    i = i + n
    if yield and (k % 32 == 0) then yield() end
  end
  close_src(src)

  -- floor: a fraction of the loudest window, so quiet material still chops and
  -- room tone does not
  local peak = 0
  for j = 1, k do if env[j] > peak then peak = env[j] end end
  local floorlv = peak * 0.18
  local hits = {}
  local last = -99
  for j = 2, k do
    local prev = env[j - 1]
    if env[j] > floorlv and env[j] > prev * 2.2 and (j - last) > 3 then
      last = j
      hits[#hits + 1] = (from + (j - 1) * win) / total
    end
  end
  -- the first slice always starts at the edge. More hits than pads: take them
  -- evenly across the whole take. Stopping at the first few gave the last pad
  -- most of the take (the device: 3.5s of a 6s drum loop).
  local cuts = { from01 }
  local room = maxn - 1
  for c = 1, math.min(#hits, room) do
    local at = #hits <= room and c or floor((c - 1) * #hits / room) + 1
    cuts[#cuts + 1] = hits[at]
  end
  return cuts
end

-- interleave two MONO wavs (the L/R pair write_take dumps) into one stereo
-- wav. A browsable export that reloads via load sample, ZERO new load code.
-- Lua-only (no engine interleave). Returns true on success.
--
-- The samples are spliced as BYTES and the depth is read from the header, so
-- this follows whatever the engine wrote rather than pinning the export to a
-- depth of its own. write_take moved to 24-bit; this needed no other change.
local function open_pcm_mono(path)
  local f = io.open(path, "rb")
  if not f then return nil end
  local afmt, ch, bits, sr, dpos, dlen = riff_parse(f)
  if not dpos or afmt ~= 1 or ch ~= 1 or not bits
      or (bits ~= 16 and bits ~= 24 and bits ~= 32) then
    f:close(); return nil
  end
  local bps = bits // 8
  f:seek("set", dpos)
  return f, floor(dlen / bps), sr, bps   -- handle, frames, rate, bytes/sample
end

function M.interleave_wav(pathL, pathR, out, yield)
  local fL, nL, sr, bps = open_pcm_mono(pathL)
  if not fL then return false end
  local fR, nR, _, bpsR = open_pcm_mono(pathR)
  if not fR then fL:close(); return false end
  -- a mismatched pair is not a stereo file: refuse rather than interleave
  -- samples of two different widths into a header that can only claim one
  if bpsR ~= bps then fL:close(); fR:close(); return false end
  local frames = min(nL, nR)
  local of = io.open(out, "wb")
  if not of then fL:close(); fR:close(); return false end
  local fb = bps * 2                              -- bytes per stereo frame
  local datalen = frames * fb
  of:write("RIFF", string.pack("<I4", 36 + datalen), "WAVE")
  of:write("fmt ", string.pack("<I4", 16), string.pack("<I2", 1), string.pack("<I2", 2),
    string.pack("<I4", sr), string.pack("<I4", sr * fb), string.pack("<I2", fb),
    string.pack("<I2", bps * 8))
  of:write("data", string.pack("<I4", datalen))
  local CHUNK = 8192                               -- frames per pass
  -- unpack each mono chunk as integers and pack them back interleaved: two
  -- string.sub calls per frame made millions of short strings for the GC
  local code = "i" .. bps
  local mono_full = "<" .. string.rep(code, CHUNK)
  local st_full = "<" .. string.rep(code, CHUNK * 2)
  local out = {}
  local i, since = 0, 0
  while i < frames do
    local n = min(CHUNK, frames - i)
    local lc, rc = fL:read(n * bps), fR:read(n * bps)
    if not lc or not rc or #lc < n * bps or #rc < n * bps then break end
    local mono = n == CHUNK and mono_full or ("<" .. string.rep(code, n))
    local lv = { string.unpack(mono, lc) }
    local rv = { string.unpack(mono, rc) }
    for k = 1, n do out[2 * k - 1] = lv[k]; out[2 * k] = rv[k] end
    of:write(string.pack(n == CHUNK and st_full or ("<" .. string.rep(code, n * 2)),
      table.unpack(out, 1, n * 2)))
    i = i + n
    since = since + 1
    if yield and since >= 2 then since = 0; yield() end   -- ~16k frames / yield
  end
  -- a short read means the declared header over-states the data; backpatch the
  -- RIFF + data sizes to what we actually wrote so the wav isn't malformed.
  if i < frames then
    local dl = i * fb
    of:seek("set", 4); of:write(string.pack("<I4", 36 + dl))
    of:seek("set", 40); of:write(string.pack("<I4", dl))
  end
  fL:close(); fR:close(); of:close()
  return true
end

return M

end)()
local Mpages = (function()  -- inlined lib/mpages.lua
-- mpages: the screen — the wave/twave display models, every page body, the
-- header, the footer, and the redraw composition.
--   header y0..8   the page title (1x), the purity mark, the write/hold flags,
--                  the page dots top-right
--   body   y11..53 one dominant object per page, drawn from real state
--   footer y56..63 four quiet words: K2 K3 | E2 E3. a turning knob brightens
--                  its word and swells its value in a framed 2x box just above
--                  the footer, bottom right, for ~1.2s
-- The strips are painted from files through lib/mwav.lua (lua cannot read an
-- SC or softcut buffer); this module owns the strips, mwav reads the files.

local floor, sin, cos = math.floor, math.sin, math.cos
local abs, sqrt, min, max = math.abs, math.sqrt, math.min, math.max
local log, exp, PI = math.log, math.exp, math.pi

local C     -- shared ctx, bound at init
local W     -- lib/mwav (the file reader), handed in through ctx.wav
local pget, clamp, window_bounds, FPS, PAGES
local ptext, ptext_c, ptext_r, chip, text_w
local amp_in, amp_out

-- waveform display: 128 amplitude bins over the buffer, filled as the write
-- head passes; pre_level decides how much of the old picture survives overdub
local wave = {}
for i = 1, 128 do wave[i] = 0 end
local wave_bin = 0

-- same idea for the tape loop: bins indexed by the tape head while recording
local twave = {}
for i = 1, 128 do twave[i] = 0 end
local twave_bin = 0

-- paint amplitude into display bins between the last-seen head position and
-- the current one, walking the SHORTER way around the (circular) buffer —
-- so bins skipped between frames at high rates get filled, wrap-around is
-- seamless, and reverse playback paints in the right direction. entering a
-- fresh bin, previous content survives by `pre` (the overdub picture).
-- A JUMP is not a walk: no head travels more than a bin per frame (the
-- fastest, a layer at 4x, moves about 0.6), so a gap of several bins is a
-- loop wrapping round or a pass re-armed somewhere else. Walking it painted
-- the whole loop with one moment's level (every seam of a DUB loop drew a
-- solid block). Only the landing bin is painted.
local JUMP_BINS = 3
local function paint_bins(bins, last, bin, amp, pre)
  if last == 0 or last == bin then
    bins[bin] = max(bins[bin], amp)
    return bin
  end
  local fwd = (bin - last) % 128
  local bwd = (last - bin) % 128
  if fwd > JUMP_BINS and bwd > JUMP_BINS then
    bins[bin] = max(bins[bin] * pre, amp)
    return bin
  end
  local step = (fwd <= bwd) and 1 or -1
  local b = last
  repeat
    b = ((b - 1 + step) % 128) + 1
    bins[b] = max(bins[b] * pre, amp)
  until b == bin
  return bin
end
local M = {}
M.paint_bins = paint_bins   -- the layer decks paint their own pictures

-- track the buffer's contents as the write head passes over it. STOP holds
-- the record head (an arm under STOP waits for START), so it holds the
-- picture too: painting the live input over a head that writes nothing set
-- wave_any over an empty buffer, and the next PSET save wrote 60s of silence.
function M.update_wave()
  if pget("rec", 0) == 1 and pget("freeze", 0) == 0
      and pget("stop_all", 0) == 0 then
    local bin = floor(clamp(C.rec_phase, 0, 0.999) * 128) + 1
    if C.rec_amp > 0.01 then C.wave_any = true end
    wave_bin = paint_bins(wave, wave_bin, bin, C.rec_amp, pget("pre_level", 0))
  end
end

-- track the tape loop's contents as the head records (input amplitude,
-- since softcut exposes no per-voice output meter); tape_pre sets survival
function M.update_tape_wave()
  if pget("tape_rec", 0) == 1 and pget("tape_freeze", 0) == 0
      and pget("stop_all", 0) == 0 then
    local bin = floor(clamp(C.tape_phase, 0, 0.999) * 128) + 1
    -- meter what softcut actually records (C.cut_rec_amp — the ADC tap, the
    -- engine output, or the blend): a WET print otherwise painted nothing
    -- and left twave_any false over audible tape
    local a = C.cut_rec_amp()
    if a > 0.01 then C.twave_any = true end
    twave_bin = paint_bins(twave, twave_bin, bin, a, pget("tape_pre", 0))
  end
end

-- wipe ANY strip, cancelling its own queued repaint (the layer decks own
-- their bins and erase through here)
function M.clear_bins(bins)
  W.cancel_fill(bins)
  for i = 1, 128 do bins[i] = 0 end
end

-- wipe the tape picture (the CLR gesture starts the loop over)
function M.clear_twave()
  M.clear_bins(twave)
  twave_bin = 0
  C.twave_any = false
end

-- wipe the engine's picture (the engine `clear` command): the buffer is gone, so the strip
-- must go with it — every page that draws the take goes back to inviting one.
function M.clear_wave()
  M.clear_bins(wave)  -- stops an in-flight TAKE fill first
  wave_bin = 0
  C.wave_any = false
end

-- the TAKE's preview: clear the strip FIRST, so an unsupported-format /
-- unreadable early return leaves a flat strip instead of the previous take's
-- waveform; a 24-bit drop-in draws + windows correctly via the shared decoder
-- (the bug this once had for everything except 16-bit).
function M.load_wave(path, buf_secs)
  for i = 1, 128 do wave[i] = 0 end
  wave_bin = 0
  local dur = W.queue_fill(path, wave, buf_secs)
  if dur ~= nil then C.wave_any = dur > 0 end
  return dur
end

-- fill an ARBITRARY 128-bin strip from a wav — the layer decks own their bins
-- and hand them here when a pset restores their audio (lua cannot read the
-- softcut buffer, but the wav it was restored FROM is right there; without
-- this a restored loop played audibly under a blank picture).
function M.fill_wave_bins(path, bins, secs)
  for i = 1, 128 do bins[i] = 0 end
  return W.queue_fill(path, bins, secs)
end

-- repaint the TAKE's strip from a dump of the buffer, leaving the window and
-- wave_any alone: the material is the same take, changed in place by regen
-- or erosion
function M.repaint_wave(path)
  wave_bin = 0
  return M.fill_wave_bins(path, wave, C.BUF_SECS)
end

-- the tape strip's version of the same (mpages owns twave)
function M.repaint_twave(path, secs)
  twave_bin = 0
  return M.fill_wave_bins(path, twave, secs)
end

-- deterministic dither, same trick as the mockups
local function hash(x, y, sd)
  local f = sin(x * 12.9898 + y * 78.233 + sd * 37.719) * 43758.5453
  return f - floor(f)
end

-- a waveform LANE: the 128 bins of `bins` stretched across columns x0..x1 as
-- vertical strokes around the centre row ym. The height law is the one every
-- strip shares: sqrt so quiet material still reads, times `k`, clamped to
-- [hmin, hmax]. `lo`/`span` (default the whole strip) zoom it onto a part of
-- the bins, which is how PADS draws only the window. The caller sets the level.
local function wave_lane(bins, x0, x1, ym, k, hmin, hmax, lo, span)
  lo, span = lo or 0, span or 1
  local w = x1 - x0
  for x = x0, x1 do
    local a = bins[floor((lo + (x - x0) / w * span) * 127) + 1] or 0
    if a > 0.002 then
      local h = clamp(sqrt(min(a * 2, 1)) * k, hmin, hmax)
      screen.move(x, ym - h)
      screen.line(x, ym + h)
    end
  end
  screen.stroke()
end

-- the record-SOURCE flag: a deck printing PROCESSED audio is never a hidden
-- mode. DRY (the default) draws nothing. Reads the EFFECTIVE source, so a
-- layer bounce throwing it WET shows on every page that records it.
local function src_flag(x, y)
  local src = C.eff_cut_source()
  if src > 0.02 then
    ptext(src > 0.98 and "SRC WET" or ("SRC WET " .. floor(src * 100 + 0.5) .. "%"),
      x, y, 1, 9)
  end
end

-- the framed 2x readout: black pocket, level-12 frame, the text at 2x. The
-- turning knob's value and the page-name pop both use it, so it is legible
-- over any body.
local function framed2x(str, bx, y)
  local w = text_w(str, 2) + 9
  screen.level(0)
  screen.rect(bx, y, w + 2, 15)
  screen.fill()
  screen.level(12)
  screen.rect(bx, y, w + 2, 15)
  screen.stroke()
  ptext(str, bx + 5, y + 3, 2, 15)
end

-- footer words per param id: the owning page's own vocabulary — these are
