  grain_jitter = "GJIT", grain_pitch_spread = "DTUN",
  clouds_pos = "POS", clouds_tex = "TEX", clouds_fb = "FB", clouds_lofi = "LOFI",
  warp_window = "WIN", warp_rand = "RAND",
  tape_rate = "RATE", tape_pre = "PRE", loop_start = "STRT", loop_end = "LOOP",
  cut_source = "SRC",
  cutoff = "CUT", resonance = "RES", drive = "DRV",
  delay_mix = "ECHO", delay_time = "TIME", delay_fb = "FDBK",
  delay_sync = "SYNC",
  rev_size = "SIZE", rev_mix = "VERB",
  rev_decay = "DECAY", rev_damp = "DMP", rev_early = "DIFF",
  rev_moddepth = "MOD", rev_modfreq = "MRAT", rev_low = "LOW",
  rev_mid = "MID", rev_high = "HIGH", rev_lowcut = "LCUT", rev_highcut = "HCUT",
  shimmer = "SHMR", shimmer_pitch = "OCT", shimmer_tone = "AIR",
  voice_atk = "ATK", voice_rel = "REL",
  motion_lane = "LANE", motion_depth = "DPT", motion_len = "LEN",
  ["@mo_sel"] = "LANE", mod_focus = "LANE",
  lfo1_depth = "DPT", lfo1_period = "PER", lfo1_target = "TGT",
  lfo2_depth = "DPT", lfo2_period = "PER", lfo2_target = "TGT",
  seq_slice = "SLICE", pad_pitch = "PTCH", pad_voice = "TYPE",
  pad_level = "PLVL",
  scene_slot = "SLOT", scene_morph_amt = "MRF",
  orbit_rate = "DRFT", orbit_reach = "RCH", erode = "ERO", wear = "WEAR",
  layer_sel = "LAYER",
  lay1_level = "L1 LV", lay1_rate = "L1 RT", lay1_reverse = "L1 REV",
  lay1_start = "L1 ST", lay1_end = "L1 EN", lay1_pre = "L1 DUB",
  lay1_width = "L1 WIDE",
  lay2_level = "L2 LV", lay2_rate = "L2 RT", lay2_reverse = "L2 REV",
  lay2_start = "L2 ST", lay2_end = "L2 EN", lay2_pre = "L2 DUB",
  lay2_width = "L2 WIDE",
  ["@lay_level"] = "LVL", ["@lay_rate"] = "RATE", ["@lay_move"] = "LOOP",
  -- nicer MOTION lane labels for params that aren't footer encoders (safe:
  -- SHORT is only read for the current page's enc ids + MOTION lane names)
  mode = "MODE", filt_type = "FILT", pan = "PAN", freeze = "FRZ",
  pv_freeze = "PVFZ", tape_freeze = "TFRZ", tape_reverse = "TREV",
  clouds_mode = "CMOD",
  -- track 2 (mangler2): the track 1 word after "T2"
  t2_level = "T2 LV", t2_pos_start = "T2 ST", t2_pos_end = "T2 EN",
  t2_scan = "T2 SPD", t2_pitch = "T2 PTCH", t2_pan = "T2 PAN",
  t2_pos_jitter = "T2 JIT", t2_size = "T2 SIZE", t2_density = "T2 DENS",
  t2_spread = "T2 SPRD", t2_grain_jitter = "T2 GJIT",
  t2_grain_pitch_spread = "T2 DTUN", t2_clouds_pos = "T2 POS",
  t2_clouds_tex = "T2 TEX", t2_clouds_fb = "T2 FB", t2_clouds_lofi = "T2 LOFI",
  t2_clouds_mode = "T2 CMOD", t2_mode = "T2 MODE", t2_warp_window = "T2 WIN",
  t2_warp_rand = "T2 RAND", t2_pv_freeze = "T2 PVFZ", t2_cutoff = "T2 CUT",
  t2_resonance = "T2 RES", t2_filt_type = "T2 FILT",
  -- the ROUTE page: its cursor and the selected send's amount
  route_sel = "SEND", ["@route_amt"] = "AMT",
}
-- tracks 3 and 4 (mangler2): track 2's words with the number changed, and the
-- sends as "2>3" (from track 2 into track 3). Built once, at load.
do
  local add = {}
  for k, v in pairs(SHORT) do
    local rest = k:match("^t2_(.+)$")
    if rest then
      add["t3_" .. rest] = "T3" .. v:sub(3)
      add["t4_" .. rest] = "T4" .. v:sub(3)
    end
  end
  for from = 1, 4 do
    for to = 1, 4 do
      if from ~= to then add["send_" .. from .. "_" .. to] = from .. ">" .. to end
    end
  end
  for k, v in pairs(add) do SHORT[k] = v end
end

-- the FULL word for a footer encoder label, shown at REST (you read "START",
-- not "ST"). Only the words that DIFFER from SHORT live here; label_for falls
-- back to SHORT for the rest. A full word that would collide with the key
-- words falls back to SHORT too (flabel_r).
local FULL = {
  input_level = "INPUT", monitor_level = "MONITOR",
  dry_wet = "DRY/WET",
  pos_start = "START", pos_end = "END", pos_jitter = "JITTER",
  ["@win_move"] = "MOVE",
  density = "DENSITY",
  warp_window = "WINDOW", warp_rand = "RANDOM",
  cut_source = "SOURCE",
  cutoff = "CUTOFF", resonance = "RESO", drive = "DRIVE",
  delay_fb = "FEEDBACK",
  delay_mix = "WET", rev_mix = "WET",
  rev_damp = "DAMP",
  voice_rel = "RELEASE",
  motion_depth = "DEPTH", motion_len = "LENGTH",
  lfo1_depth = "DEPTH", lfo1_period = "PERIOD", lfo1_target = "TARGET",
  lfo2_depth = "DEPTH", lfo2_period = "PERIOD", lfo2_target = "TARGET",
  pad_pitch = "PITCH", pad_voice = "VOICE",
  scene_morph_amt = "MORPH",
  orbit_rate = "DRIFT", orbit_reach = "REACH", erode = "ERODE",
  ["@lay_level"] = "LEVEL",
}

-- normalized 0..1 of a value for a param: controlspec unmap, option index,
-- or number range. plots the MOTION lanes' events at their captured heights.
-- pnorm takes the param OBJECT, so a caller plotting many values of one
-- param (a MOTION lane) looks it up once, not once per event.
local function pnorm(p, v)
  if not p then return 0 end
  if p.controlspec then return clamp(p.controlspec:unmap(v), 0, 1)
  elseif p.count then return p.count > 1 and (v - 1) / (p.count - 1) or 0
  elseif p.min and p.max and p.max > p.min then return (v - p.min) / (p.max - p.min) end
  return clamp(v, 0, 1)
end
local function lookup_p(id)
  return params.lookup[id] and params:lookup_param(id) or nil
end
local function value_norm(id, v) return pnorm(lookup_p(id), v) end

-- footer value text for a param: compact, ALL-CAPS abbreviations. a few
-- ids get hand-tuned units (cutoff kHz, pitch semitones, rates x, times);
-- a plain 0..1 linear control reads as a percentage; everything else falls
-- back to the norns string.
local RATE_IDS = { scan = true, tape_rate = true,
                   lay1_rate = true, lay2_rate = true,
                   t2_scan = true, t2_pitch = true,
                   t3_scan = true, t3_pitch = true,
                   t4_scan = true, t4_pitch = true }
local T2_KEY = {}
for k in pairs(SHORT) do
  local b = k:match("^t%d_(.+)$")
  if b then T2_KEY[k] = b end
end
local function fmt_value(id)
  -- compound encoder targets ("@") read as their anchor param
  if id and C.enc_target then id = C.enc_target(id) end
  if not (id and params.lookup[id]) then return "--" end
  -- a track 2 id reads in its track 1 format (mangler2)
  local key = T2_KEY[id] or id
  if key == "route_sel" then                    -- the cell: from > to
    local r = C.route_cur and C.route_cur()
    return r and (r.from .. ">" .. r.to) or "-"
  end
  if key == "seq_slice" then
    return tostring(floor(params:get(id) + 0.5) + 1)   -- slices read 1..8
  end
  if key == "scene_slot" then
    local v = floor(params:get(id) + 0.5)
    return v < 1 and "<" or tostring(v)                -- 0 = the ◄ cell
  end
  if key == "motion_lane" then
    -- show the SELECTED lane's param name (or "-" when none picked)
    local ids = C.motion and C.motion.lane_ids
    local n = ids and #ids or 0
    local sel = clamp(floor(params:get(id) + 0.5), 0, n)
    if n == 0 or sel == 0 then return "-" end
    return SHORT[ids[sel]] or string.upper(ids[sel])
  end
  if key == "pos_start" or key == "pos_end" then
    -- the window's edges in seconds of the buffer, not a percentage
    return string.format("%.2fS", params:get(id) * (C.BUF_SECS or 60))
  end
  if key == "mod_focus" then
    return params:get(id) > 2.5 and "LFO2" or "LFO1"
  end
  if key == "lfo1_target" or id == "lfo2_target" then
    local t = C.lfo and C.lfo.TARGETS[floor(params:get(id) + 0.5) - 1]
    return t and (SHORT[t] or string.upper(t)) or "OFF"
  end
  if key == "lfo1_depth" or id == "lfo2_depth" then
    return string.format("%+d%%", floor(params:get(id) * 100 + 0.5))
  end
  if key == "motion_len" then
    local v = params:get(id)
    return v < 0.05 and "AUTO" or string.format("%.1fS", v)
  end
  if key == "cut_source" then                    -- tape source: DRY .. WET blend
    local v = params:get(id)
    if v < 0.02 then return "DRY" end
    if v > 0.98 then return "WET" end
    return floor(v * 100 + 0.5) .. "%"
  end
  if key == "cutoff" then
    local v = params:get(id)
    return v >= 1000 and string.format("%.1fKHZ", v / 1000)
      or string.format("%dHZ", floor(v + 0.5))
  elseif key == "rev_decay" then
    return string.format("%.1fS", params:get(id))
  elseif key == "rev_size" then
    return string.format("%.1f", params:get(id))
  elseif key == "pitch" then
    local st = floor(12 * log(params:get(id)) / log(2) + 0.5)
    return (st >= 0 and "+" or "") .. st .. "ST"
  elseif RATE_IDS[id] then
    return string.format("%+.2fX", params:get(id))
  elseif key == "delay_time" then
    local v = params:get(id)
    return v >= 0.9995 and string.format("%.2fS", v)
      or string.format("%dMS", floor(v * 1000 + 0.5))
  elseif key == "size" then
    local v = params:get(id)
    return v >= 1 and string.format("%.1fS", v)
      or string.format("%dMS", floor(v * 1000 + 0.5))
  elseif key == "density" then
    return tostring(floor(params:get(id) + 0.5))
  end
  local p = params:lookup_param(id)
  local cs = p.controlspec
  if cs and cs.minval and cs.maxval and cs.minval >= 0 and cs.maxval <= 1 then
    return string.format("%d%%", floor(params:get(id) * 100 + 0.5))
  end
  return string.upper(params:string(id))
end

-- is this param the one currently being turned? (brightens its footer word and
-- swells the big value box; the window is armed in the encoder handler, ~1.2s)
local function is_turning(id)
  return id ~= nil and C.flash_id == id and C.frame < C.flash_until
end

-- selector pages are the one exception to numbers-only-while-turning:
-- the selection IS the state, so it reads at rest (SLICE·3, LANE·…)
local SELECTOR_IDS = {
  route_sel = true,
  seq_slice = true, motion_lane = true, scene_slot = true, layer_sel = true,
  ["@mo_sel"] = true,
}

local FY = 58  -- the footer text row (four quiet words)

-- one key word: rest = dim text, engaged (latched or held) = inverted chip.
-- def.lit() is the truth; a punched key reads identical while the finger is
-- down and reverts on release — the whole temporary/latched language.
-- the frame the arc beside the K3 word started on, or nil: the K1+K3
-- eraser, or a key held on a def with a `hold` (TAKE K3 = UNDO). Its word is
-- the arc's, from the frame the tap window can no longer be a tap.
local function arc_start()
  if C.alt and C.k13_frame and C.page_erase() then
    return C.k13_frame, "ERASE"
  end
  if not C.hold_frame then return end
  local hf, def = C.hold_frame(3)   -- (an `and` here would keep one value)
  if hf then return hf, def.hold_label or "HOLD" end
end
local function fkey_draw(n, x)
  local def = C.key_def(n)
  local lab = def and def.label or "--"
  if n == 3 then
    local f0, word = arc_start()
    if f0 and C.frame - f0 >= 2 then
      ptext(word, x, FY, 1, 15)      -- the tap became the hold
      return text_w(word, 1)
    end
  end
  local on = false
  if def then
    if def.lit and def.lit() then on = true end
    if C.held[n] and not def.dryerase then on = true end
  end
  local w = text_w(lab, 1)
  if on then
    screen.level(15)
    screen.rect(x - 2, 56, w + 5, 8)
    screen.fill()
    ptext(lab, x, FY, 1, 0)
  else
    ptext(lab, x, FY, 1, 6)
  end
  return w
end

-- one encoder word, right-anchored: WORD· — the FULL word, except on the
-- selector pages, where the SHORT word carries the selection beside it
-- (SLICE·3). A turning knob only brightens its word; its value swells in the
-- big box above the footer (draw_big_value). minx is the key words' right
-- edge: a full word that would cross it drops to the abbreviation, so the
-- row never overlaps.
-- hoisted out of flabel_r so the draw path allocates no per-frame closures
local T2_BASE = {}
for k in pairs(SHORT) do
  local b = k:match("^t%d_(.+)$")
  if b and SHORT[b] then T2_BASE[k] = b end
end
local function label_for(id, full)
  if not id then return "--" end
  id = T2_BASE[id] or id
  if full then return FULL[id] or SHORT[id] or string.upper(id) end
  return SHORT[id] or "--"
end
local function label_total(l, val) return text_w(l, 1) + 3 + (val and text_w(val, 1) or 0) end
local function flabel_r(id, rx, minx)
  local turning = is_turning(id)
  -- the footer layout is ALWAYS the at-rest layout: a turning knob only
  -- brightens its word, never widens or moves it, so the neighbor word
  -- stays exactly where it was. the live value shows in the big readout
  -- box instead (draw_footer). selectors keep their small value at rest.
  local val = id and SELECTOR_IDS[id] and fmt_value(id) or nil
  local full = not val
  local lab = label_for(id, full)
  local lvl = turning and 15 or 6
  local x = rx - label_total(lab, val)
  if full and minx and x < minx then
    -- a full word that would cross the key words drops to SHORT
    lab = label_for(id, false)
    x = rx - label_total(lab, val)
  end
  ptext(lab, x, FY, 1, lvl)
  screen.level(lvl)
  screen.rect(x + text_w(lab, 1) + 1, FY + 2, 1, 1)
  screen.fill()
  if val then ptext(val, x + text_w(lab, 1) + 3, FY, 1, lvl) end
  return x
end

-- the big readout: while a knob turns, its value draws at double size in a
-- framed black box just above the footer, right-anchored. the footer never
-- changes shape; this box carries the number and vanishes with the swell.
local function draw_big_value()
  local tid
  local e2, e3 = C.enc_param(2), C.enc_param(3)
  if is_turning(e2) then tid = e2
  elseif is_turning(e3) then tid = e3 end
  if not tid then return end
  local v = fmt_value(tid)
  framed2x(v, 126 - (text_w(v, 2) + 9), 41)
end

-- footer: K2 K3 | E2· E3· — four quiet words that never lie about the keys.
-- M.FOOT keeps the last layout for the tests: `arc` the erase arc's right
-- edge (nil when it is not drawn) and `e2` the E2 word's left edge.
local FOOT = { arc = nil, e2 = 0 }
M.FOOT = FOOT
local function draw_footer()
  local x = 2
  if C.alt then                       -- the shift bar: K1 is held
    screen.level(15)
    screen.rect(0, 57, 2, 6)
    screen.fill()
    x = 5
  end
  local w = fkey_draw(2, x)
  x = x + w + 9
  w = fkey_draw(3, x)
  local keys_right = x + w + 4     -- the key words' right edge (labels clear it)
  FOOT.arc = nil
  -- the hold-arc beside the K3 word (the eraser, or TAKE's UNDO). It
  -- belongs to the key words, so the encoder words clear it too: one that
  -- would cross it drops to its short word while the arc draws.
  local f0 = arc_start()
  if f0 then
    local dt = C.frame - f0
    if dt >= 2 then
      local ax, ay = x + w + 8, FY + 2
      keys_right = ax + 7
      FOOT.arc = ax + 4
      local frac = clamp(dt / C.ERASE_FRAMES, 0, 1)
      screen.level(4)
      for a = 0, 2 * math.pi, 0.22 do
        screen.rect(ax + cos(a) * 3.2, ay + sin(a) * 3.2, 1, 1)
      end
      screen.fill()
      screen.level(15)
      local a = -math.pi / 2
      local a1 = -math.pi / 2 + 2 * math.pi * frac
      while a < a1 do
        screen.rect(ax + cos(a) * 3.2, ay + sin(a) * 3.2, 1, 1)
        a = a + 0.1
      end
      screen.fill()
    end
  end
  local e3x = flabel_r(C.enc_param(3), 126, keys_right)
  FOOT.e2 = flabel_r(C.enc_param(2), e3x - 9, keys_right)
  draw_big_value()
end

-- ============================================================================
-- the dominant objects, one per page (doc/redesign.md §6)
-- ============================================================================
-- one object per page, drawn from REAL state, brightness riding audibility.
-- statics first: everything the 15fps hot path needs preallocated.

-- FILTER: log-frequency axis 20Hz..20kHz over 128 columns, rail columns at
-- 100Hz/1k/10k (labeled), the 0dB row, and a reusable response buffer (the
-- curve approximates the engine's DFM1 build, see body_FILTER; the resonance
-- law mirrors Engine_Mangler2.sc, keep them in sync)
local FILT_FREQ, FILT_Y = {}, {}
for x = 0, 127 do
  FILT_FREQ[x + 1] = 20 * (1000 ^ (x / 127))
  FILT_Y[x + 1] = 0
end
local FILT_GRID_X, FILT_GRID_LBL = {}, { "100", "1K", "10K" }
for i, f in ipairs({ 100, 1000, 10000 }) do
  FILT_GRID_X[i] = floor(log(f / 20) / log(1000) * 127 + 0.5)
end
local FILT_TOP, FILT_BOT = 14, 46
local FILT_DB_TOP, FILT_DB_RANGE = 18, 48
local FILT_DB0_Y = floor(FILT_TOP
  + FILT_DB_TOP * (FILT_BOT - FILT_TOP) / FILT_DB_RANGE + 0.5)

-- MIX: master/input peak-hold pips (slow decay, static state)
local vu_peak = { 0, 0 }
local vu_last_frame = -1

-- PADS: per-pad "a voice is sounding" flags, refilled each frame
local pad_lit = {}

-- ============================================================================
-- 1 · TAKE — the material (one strip: recorded bright, unwritten dotted,
--     window brackets inside; write head + seconds + ready-bracket while
--     armed; hatched while marked by the erase arc)
-- ============================================================================
local TK_MID, TK_HALF = 30, 11

-- TAKE's top row. Right: the window locked to the clock ("1 BAR"), and
-- "ON SND" while a record would wait for sound, so you know before you arm.
-- Left: "<" while an UNDO is kept, then the chips of a writer that re-touches
-- the buffer (RSMP, REGN). What K3's SNAP or UNDO just did takes the whole row
-- for a moment (LAYERS' rule): the action proves it happened.
local function take_top_row(frame, rec)
  if C.take_msg and (frame - (C.take_msg_at or -1e9)) < FPS * 1.2 then
    screen.level(0); screen.rect(0, 11, 128, 7); screen.fill()
    ptext_c(C.take_msg, 64, 12, 1, 12)
    return
  end
  local rx = 126
  local wb = floor(pget("win_beats", 1) + 0.5)
  if wb > 1 then
    local name = C.WIN_BEAT_NAMES[wb]
    ptext_r(name, rx, 12, 1, 6)
    rx = rx - text_w(name, 1) - 5
  end
  if not rec and pget("rec_wait", 0) == 1 and pget("pre_level", 0) < 0.001 then
    ptext_r("ON SND", rx, 12, 1, 5)
  end
  local bx = 2
  if C.undo_ready and C.undo_ready() then
    ptext("<", bx, 12, 1, 6)
    bx = bx + 7
  end
  if not rec then
    -- resample/regen: the buffer is being re-touched by output
    if pget("resample", 0) > 0 then bx = bx + chip("RSMP", bx, 12) + 2 end
    if pget("regen", 0) > 0 then chip("REGN", bx, 12) end
  end
end

local function body_TAKE(frame)
  local rec = pget("rec", 0) == 1 and pget("freeze", 0) == 0
  if not C.wave_any and not rec then
    screen.level(3)
    for x = 2, 125, 3 do screen.rect(x, TK_MID, 1, 1) end
    screen.fill()
    ptext_c("EMPTY - K2 REC", 64, 24, 1, 10)
    ptext_c("OR PARAMS > LOAD", 64, 34, 1, 5)
    take_top_row(frame, rec)
    return
  end
  local lo, hi = window_bounds()
  local wx = clamp(C.rec_phase, 0, 1) * 127
  -- marked for erase: K1+K3 held past the tap window on this page
  local marked = C.k13_frame ~= nil
    and (C.frame - C.k13_frame) >= 2 and not C.k13_fired
  -- the material: bright inside the window, dim outside, hot behind the
  -- write head; the unwritten buffer is a dotted centerline
  local run = 0
  for x = 0, 127 do
    local a = wave[x + 1]
    if a > 0.002 then
      local h = clamp(sqrt(min(a * 2, 1)) * TK_HALF, 1, TK_HALF)
      local nx = x / 127
      local lvl = (nx >= lo and nx <= hi) and 12 or 4
      if rec then
        local d = wx - x
        if d >= 0 and d < 12 then lvl = 15 - floor(d / 3) end
      end
      if marked then lvl = 3 end
      if lvl ~= run then
        if run ~= 0 then screen.stroke() end
        screen.level(lvl)
        run = lvl
      end
      screen.move(x, TK_MID - h)
      screen.line(x, TK_MID + h)
    end
  end
  if run ~= 0 then screen.stroke() end
  screen.level(3)
  for x = 0, 126, 3 do
    if (wave[x + 1] or 0) <= 0.002 then screen.rect(x, TK_MID, 1, 1) end
  end
  screen.fill()
  if marked then                    -- danger hatch: the object, marked
    screen.level(11)
    for y = TK_MID - TK_HALF, TK_MID + TK_HALF do
      for x = 0, 127, 4 do
        local xx = x + (y % 4)
        if (wave[xx + 1] or 0) > 0.002 then screen.rect(xx, y, 1, 1) end
      end
    end
    screen.fill()
  end
  -- window brackets, with feet (the region that plays)
  screen.level(15)
  for k = 1, 2 do
    local e = (k == 1 and lo or hi) * 127
    screen.move(e, TK_MID - TK_HALF - 2)
    screen.line(e, TK_MID + TK_HALF + 2)
  end
  screen.stroke()
  screen.level(15)
  screen.rect(lo * 127 + 1, TK_MID - TK_HALF - 2, 2, 1)
  screen.rect(lo * 127 + 1, TK_MID + TK_HALF + 2, 2, 1)
  screen.rect(hi * 127 - 2, TK_MID - TK_HALF - 2, 2, 1)
  screen.rect(hi * 127 - 2, TK_MID + TK_HALF + 2, 2, 1)
  screen.fill()
  if rec then
    -- no blinking window frame (play-tested as "way too much"): the
    -- sweeping write head, the big elapsed seconds, the IN meter and the header
    -- R flag already say REC. the strip stays calm.
    screen.level(15)                -- the write head
    screen.move(wx, TK_MID - TK_HALF - 2)
    screen.line(wx, TK_MID + TK_HALF + 2)
    screen.stroke()
    -- elapsed seconds: the one number a performer needs
    -- ...or, armed to start on sound and none yet, WAIT
    if C.rec_waiting then
      ptext("WAIT", 88, 46, 2, 12)   -- steady: the header R is the blink
    else
      local el = ((clamp(C.rec_phase, 0, 1) - C.rec_arm_phase) % 1) * C.BUF_SECS
      ptext(string.format("%.1fS", el), 88, 46, 2, 15)
    end
    -- input meter with the record-ready bracket (peak inside = clean take)
    ptext("IN", 2, 47, 1, 5)
    local sig = sqrt(clamp(max(amp_in[1], amp_in[2]), 0, 1))
    screen.level(1)
    screen.rect(12, 48, 55, 5)
    screen.fill()
    screen.level(11)
    screen.rect(12, 48, floor(sig * 55), 5)
    screen.fill()
    screen.level(8)                 -- the -12..-3dB zone, wordless
    screen.rect(40, 46, 18, 1)
    screen.rect(40, 45, 1, 2)
    screen.rect(57, 45, 1, 2)
    screen.fill()
  end
  -- the READ (playback) head, drawn LAST so it never hides behind the solid
  -- WRITE head. distinct SHAPE, not just tone: a
  -- DASHED column + a caret above the strip vs the write head's solid line +
  -- comet-tail glow — so even when they cross you can tell read from write.
  if C.wave_any and pget("mode", 5) ~= 1 then
    local phx = clamp(C.play_phase, 0, 1) * 127
    screen.level(15)
    for y = TK_MID - TK_HALF, TK_MID + TK_HALF, 2 do screen.rect(phx, y, 1, 1) end
    screen.rect(phx, TK_MID - TK_HALF - 3, 1, 1)          -- caret stem
    screen.rect(phx - 1, TK_MID - TK_HALF - 4, 3, 1)      -- caret ▽ above the strip
    screen.fill()
  end
  take_top_row(frame, rec)   -- last: a message's pocket covers the caret
end

-- ============================================================================
-- 2 · VOICE — how the take plays (mode rail + the mode's own texture)
-- ============================================================================
local VOICE_RAIL = { { "PLAY", 5 }, { "GRAIN", 2 }, { "WARP", 3 }, { "PV", 4 } }

local function voice_wy(x, ph, rate)
  return 33 + sin((x + ph) * 0.35 * rate) * 8
end

-- EROSION state: how aged the take is. The generation counter counts
-- completed loop passes while eroding; drawn inside VOICE's PLAY texture
-- (PLAY is the only mode the engine erodes in). Declared BEFORE body_VOICE:
-- referenced from there, and a later local would silently read as a global.
local eros_gen, eros_acc, eros_live = 0, 0, false
-- the one rule for "the erosion head is engaged": erode up, in PLAY. The
-- strip repaint (mangler2.lua's take_writing) asks the same question.
function M.eroding()
  return pget("erode", 0) > 0 and pget("mode", 5) == 5
end
function M.erosion_tick()
  -- the engine spawns its erosion head at the window's start each time
  -- erosion engages (erode up in PLAY), so an engagement starts a new pass
  local live = M.eroding()
  if live and not eros_live then eros_acc = 0 end
  eros_live = live
  -- the erosion head runs at exactly one pass per window length, so a
  -- generation is span times sixty seconds of eroding time. paused under
  -- the same conditions the engine pauses its head (rec, freeze, and a
  -- SILENCED deck: the engine runs the head on level > 0.001, so the GEN
  -- counter must not keep counting through a STOP or a full mix throw).
  if live and pget("rec", 0) == 0 and pget("freeze", 0) == 0
      and (C.mix_gains()) > 0.001 then
    local _, _, span = window_bounds()
    eros_acc = eros_acc + (1 / FPS) / (span * C.BUF_SECS)
    if eros_acc >= 1 then
      eros_gen = eros_gen + 1
      eros_acc = eros_acc - 1
    end
  end
end
function M.erosion_reset() eros_gen, eros_acc = 0, 0 end

-- mangler2: VOICE and FILTER draw the track they address (C.tid picks the
-- id). tp reads the selected track's value of a track 1 id; the read head
-- and the window follow the track too.
-- each extra track's ids, built once (the redraw path must not allocate)
local TK = {}
for n = 2, 4 do
  local pre = "t" .. n .. "_"
  TK[n] = { mode = pre .. "mode", level = pre .. "level",
    pos_start = pre .. "pos_start", pos_end = pre .. "pos_end" }
end
local function cur_track() return C.tsel and C.tsel() or 1 end
local function on_t2() return cur_track() > 1 end
local function tp(id, d) return pget(C.tid and C.tid(id) or id, d) end
local function track_phase()
  local n = cur_track()
  if n > 1 then return C.play_phases and C.play_phases[n] or 0 end
  return C.play_phase
end
local function track_window_n(n)
  if n < 2 then return window_bounds() end
  local a, b = pget(TK[n].pos_start, 0), pget(TK[n].pos_end, 1)
  local lo, hi = min(a, b), max(a, b)
  return lo, hi, max(hi - lo, 0.001)
end
local function track_window() return track_window_n(cur_track()) end
-- an extra track is sounding: switched on and its level up
local function track_live(n)
  return pget(TK[n].mode, 1) ~= 1 and pget(TK[n].level, 1) > 0.001
end
M.on_t2 = on_t2

-- GRAIN: the cloud the knobs make. Each grain is a short tick: DENSITY sets
-- how many (3 to 40), SIZE how long each one is and how long it lives, and
-- grain JITTER how much the lengths differ. The x axis is the buffer, as the
-- window bar below it says, so the cloud sits on the play head and position
-- JITTER widens it over the window. The y axis is the stereo field, left at
-- the top: PAN moves the cloud and SPREAD scatters it. A grain fades in and
-- out over its life and drifts the way SPEED reads, except while a freeze
-- holds the read point (FREEZE, or the PV freeze that Clouds takes as its
-- own). The randoms come from `hash` on the frame, never from math.random,
-- so the orbit keeps its own sequence and a shot repeats.
local GR_MAX, GR_MID, GR_HALF = 40, 34, 11
local function grain_cloud(frame, scan)
  local sn = value_norm("size", tp("size", 0.1))
  local dn = value_norm("density", tp("density", 20))
  local spread = clamp(tp("spread", 0.5), 0, 1)
  local pan = clamp(tp("pan", 0), -1, 1)
  local pj = clamp(tp("pos_jitter", 0), 0, 1)
  local gj = clamp(tp("grain_jitter", 0), 0, 1)
  local lo, hi = track_window()
  local n = 3 + floor(dn * (GR_MAX - 3) + 0.5)
  local life = 2 + floor(sn * 14 + 0.5)
  local reach = 3 + pj * (hi - lo) * 127
  local cx = clamp(track_phase(), 0, 1) * 127
  local held = pget("freeze", 0) == 1 or tp("pv_freeze", 0) == 1
  local drift = held and 0 or scan * 0.6
  for k = 1, n do
    local t = frame + floor(k * life / n)     -- the births are staggered
    local e = floor(t / life)                 -- this grain's generation
    local age = t - e * life
    local len = max(1, floor((1 + sn * 10) * (1 + gj * (hash(k, e, 3) * 2 - 1)) + 0.5))
    local x = (cx + (hash(k, e, 1) * 2 - 1) * reach + age * drift) % 128
    local y = GR_MID + floor(clamp(pan + (hash(k, e, 2) * 2 - 1) * spread, -1, 1)
      * GR_HALF + 0.5)
    screen.level(3 + floor(sin(PI * (age + 0.5) / life) * 12 + 0.5))
    screen.rect(floor(x - len / 2), y, len, 1)
    screen.fill()
  end
end

-- the mode rail: the active word inverted; OFF dims the whole rail
local function mode_rail(mode)
  local x = 4
  for _, m in ipairs(VOICE_RAIL) do
    local w = text_w(m[1], 1)
    if m[2] == mode then
      screen.level(15)
      screen.rect(x - 2, 11, w + 5, 9)
      screen.fill()
      ptext(m[1], x, 13, 1, 0)
    else
      ptext(m[1], x, 13, 1, mode == 1 and 2 or 5)
    end
    x = x + w + 8
  end
end

local function body_VOICE(frame)
  local mode = tp("mode", 5)
  local held_pv = tp("pv_freeze", 0) == 1
  mode_rail(mode)
  -- HELD: the PV freeze is heard in PV, and in GRAIN on the Clouds voice
  -- (it doubles as the Clouds freeze). In PLAY and WARP it waits, dim.
  if mode == 1 then ptext_r("OFF", 126, 13, 1, 8)
  elseif held_pv then
    ptext_r("HELD", 126, 13, 1, (mode == 4 or mode == 2) and 12 or 4)
  end
  -- the texture IS the mode, drawn from the playing motion (drifts with
  -- scan, stands still frozen, lies flat when the voice is freed/silent)
  local scan = tp("scan", 1)
  local rate = max(abs(scan), 0.05)
  local ph = (held_pv and mode == 4) and 0 or frame * 0.8 * scan
  -- silent = nothing recorded, OR the engine deck is choked (STOP, or MIX
  -- thrown fully to tape): the engine halts the read head then, so the
  -- texture lies flat and the playhead goes, as everywhere else
  local silent = not C.wave_any or (C.mix_gains()) <= 0.001
    or (on_t2() and pget(TK[cur_track()].level, 1) <= 0.001)
  if mode == 1 or silent then
    screen.level(1)
    screen.move(0, 33) screen.line(128, 33)
    screen.stroke()
    -- nothing to play: the invitation, in TAKE's voice (K2 here is a freeze)
    if not C.wave_any then ptext_c("EMPTY - REC ON TAKE", 64, 24, 1, 10) end
  elseif mode == 2 then        -- GRAIN: the cloud (grain_cloud)
    grain_cloud(frame, scan)
  elseif mode == 3 then        -- WARP: an overlapped window ghosts behind
    local off = 9 + sin(frame * 0.9) * 6 * tp("warp_rand", 0)
    screen.level(2)
    for gx = 0, 127 do
      screen.rect(gx, voice_wy(gx + off, ph, rate), 1, 1)
    end
    screen.fill()
    screen.level(8)
    for gx = 0, 127 do
      screen.rect(gx, voice_wy(gx, ph, rate), 1, 1)
    end
    screen.fill()
  elseif mode == 4 then        -- PV: spectral columns under the same curve
    screen.level(6)
    for gx = 0, 127, 4 do
      local h = abs(sin((gx + ph) * 0.35 * rate)) * 14 + 1
      screen.rect(gx, 45 - h, 2, h)
    end
    screen.fill()
  else                         -- PLAY: one unbroken wave — the exact sample,
    -- aged by EROSION when it runs (PLAY is the only mode that erodes; the
    -- controls are this page's alt pair). two passes so every pixel fills at
    -- its own level: the base wave dims as erosion deepens, then the fuzz
    -- flecks eat into it. dormant at erode 0 — the wave is untouched.
    local e = on_t2() and 0 or clamp(pget("erode", 0), 0, 1)   -- track 1 only
    screen.level(9 - floor(e * 5))
    for gx = 0, 127 do
      if e <= 0 or hash(gx, frame % 8, 3) >= e * 0.7 then
        screen.rect(gx, voice_wy(gx, ph, rate), 1, 1)
      end
    end
    screen.fill()
    if e > 0 then
      screen.level(2)
      for gx = 0, 127 do
        if hash(gx, frame % 8, 3) < e * 0.7 then
          screen.rect(gx, voice_wy(gx, ph, rate), 1, 1)
        end
      end
      screen.fill()
      -- generation counter + progress through the current pass. the mode
      -- rail runs nearly to the right edge, so the counter sits below it in
      -- its own pocket (the footer's swelling-value rule).
      local gtxt = "GEN " .. eros_gen
      local tw = text_w(gtxt, 1)
      screen.level(0)
      screen.rect(124 - tw, 21, tw + 4, 7)
      screen.fill()
      ptext(gtxt, 126 - tw, 22, 1, 12)
      screen.level(5)
      screen.rect(0, 46, floor(clamp(eros_acc, 0, 1) * 128), 1)
      screen.fill()
    end
  end
  -- window bar + the playhead (nothing moves that can't be heard)
  local lo, hi = track_window()
  screen.level(2)
  screen.move(0, 48) screen.line(128, 48)
  screen.stroke()
  screen.level(6)
  screen.move(lo * 127, 48) screen.line(hi * 127, 48)
  screen.stroke()
  if mode ~= 1 and not silent then
    screen.level(15)
    local phx = clamp(track_phase(), 0, 1) * 127
    screen.move(phx, 24) screen.line(phx, 50)
    screen.stroke()
  end
end

-- ============================================================================
-- TRACK (mangler2): the page's track (2 to 4) on the one take, with the
-- others for reference. The material lies dim; track 1's window is a dim band
-- with its dashed head, the other sounding tracks' heads are short dim ticks
-- above the strip, and this track's window is bright with brackets and a
-- solid head. The rail is its mode, the bar its level. OFF, STOP or a level
-- of 0 lays it flat and dim, like every silent thing on this screen.
-- ============================================================================
local T2_MID, T2_HALF = 34, 8
local function body_TRACK(frame)
  local n = C.page_track and C.page_track() or 2
  local ids = TK[n]
  local mode = pget(ids.mode, 1)
  mode_rail(mode)
  if mode == 1 then ptext_r("OFF", 126, 13, 1, 8) end
  if not C.wave_any then
    screen.level(3)
    for x = 2, 125, 3 do screen.rect(x, T2_MID, 1, 1) end
    screen.fill()
    ptext_c("EMPTY - REC ON TAKE", 64, 24, 1, 10)
    return
  end
  local level = pget(ids.level, 1)
  local audible = (C.mix_gains()) > 0.001
  local live = audible and track_live(n)
  local lo1, hi1 = window_bounds()
  local lo, hi = track_window_n(n)
  local run = 0
  for x = 0, 127 do
    local amp = wave[x + 1]
    if amp > 0.002 then
      local h = clamp(sqrt(min(amp * 2, 1)) * T2_HALF, 1, T2_HALF)
      local nx = x / 127
      local lvl = 2
      if nx >= lo1 and nx <= hi1 then lvl = 4 end
      if nx >= lo and nx <= hi then lvl = live and 12 or 6 end
      if lvl ~= run then
        if run ~= 0 then screen.stroke() end
        screen.level(lvl)
        run = lvl
      end
      screen.move(x, T2_MID - h)
      screen.line(x, T2_MID + h)
    end
  end
  if run ~= 0 then screen.stroke() end
  -- this track's brackets
  screen.level(live and 15 or 6)
  for k = 1, 2 do
    local e = (k == 1 and lo or hi) * 127
    screen.move(e, T2_MID - T2_HALF - 2)
    screen.line(e, T2_MID + T2_HALF + 2)
  end
  screen.stroke()
  -- track 1's head: dashed and dim, as a reference
  if pget("mode", 5) ~= 1 and audible then
    local p1 = clamp(C.play_phase, 0, 1) * 127
    screen.level(5)
    for y = T2_MID - T2_HALF, T2_MID + T2_HALF, 2 do screen.rect(p1, y, 1, 1) end
    screen.fill()
  end
  -- the other extra tracks' heads: short dim ticks above the strip
  for m = 2, 4 do
    if m ~= n and audible and track_live(m) then
      local pm = clamp(C.play_phases[m] or 0, 0, 1) * 127
      screen.level(4)
      screen.rect(pm, T2_MID - T2_HALF - 4, 1, 3)
      screen.fill()
    end
  end
  -- this track's head: solid and bright while it sounds
  if live then
    local p2 = clamp(C.play_phases[n] or 0, 0, 1) * 127
    screen.level(15)
    screen.move(p2, T2_MID - T2_HALF - 2)
    screen.line(p2, T2_MID + T2_HALF + 2)
    screen.stroke()
  end
  -- the level bar (0 to 1.5, unity marked)
  ptext("LV", 2, 47, 1, 5)
  screen.level(1)
  screen.rect(12, 48, 60, 3)
  screen.fill()
  screen.level(live and 11 or 4)
  screen.rect(12, 48, floor(clamp(level / 1.5, 0, 1) * 60), 3)
  screen.fill()
  screen.level(8)
  screen.rect(52, 47, 1, 5)
  screen.fill()
end

-- ============================================================================
-- ROUTE (mangler2): the sends as a grid, the S-4's routing page. A row is
-- where a sound comes FROM, a column where it goes TO; the diagonal is the
-- track itself. A cell fills with its send level and the cursor's cell is
-- framed bright. A row's label is bright while that track sounds (track 1:
-- its mode is on). On the right, the cursor's route in words. Every send
-- dims while STOP or the MIX throw silences the engine.
-- ============================================================================
local RT_X0, RT_Y0, RT_CW, RT_RH = 22, 19, 18, 8
local RT_ROW = { "T1", "T2", "T3", "T4" }
local RT_COL = { "1", "2", "3", "4" }
-- the send ids and the percent words, built once (no allocation per frame)
local RID, PCT = {}, {}
for r = 1, 4 do
  RID[r] = {}
  for c = 1, 4 do RID[r][c] = "send_" .. r .. "_" .. c end
end
for v = 0, 100 do PCT[v] = v .. "%" end
local function track_sounds(n)
  if n == 1 then return pget("mode", 5) ~= 1 end
  return track_live(n)
end
local function body_ROUTE(frame)
  local audible = (C.mix_gains()) > 0.001
  local cur = C.route_cur and C.route_cur()
  ptext("TO", 6, 12, 1, 3)       -- columns: where a send goes
  for c = 1, 4 do
    ptext_c(RT_COL[c], RT_X0 + (c - 1) * RT_CW + 7, 12, 1, 5)
  end
  for r = 1, 4 do
    local y = RT_Y0 + (r - 1) * RT_RH
    ptext(RT_ROW[r], 6, y, 1, (audible and track_sounds(r)) and 13 or 4)
    for c = 1, 4 do
      local x = RT_X0 + (c - 1) * RT_CW
      if r == c then
        screen.level(2)
        screen.rect(x + 6, y + 2, 2, 1)
        screen.fill()
      else
        local v = clamp(pget(RID[r][c], 0), 0, 1)
        screen.level(2)
        screen.rect(x, y, 15, 6)
        screen.stroke()
        if v > 0.001 then
          screen.level(audible and 11 or 4)
          screen.rect(x + 1, y + 1, max(1, floor(v * 13 + 0.5)), 4)
          screen.fill()
        end
        if cur and cur.from == r and cur.to == c then
          screen.level(15)
          screen.rect(x - 1, y - 1, 17, 8)
          screen.stroke()
        end
      end
    end
  end
  -- the cursor's route, in words, on the right
  if cur then
    ptext_c(RT_ROW[cur.from], 110, 19, 1, 12)
    ptext_c(">", 110, 27, 1, 6)
    ptext_c(RT_ROW[cur.to], 110, 35, 1, 12)
    local v = clamp(pget(cur.id, 0), 0, 1)
    ptext_c(v > 0.001 and PCT[floor(v * 100 + 0.5)] or "OFF", 110, 45, 1, v > 0.001 and 10 or 4)
  end
end

-- ============================================================================
-- 3 · TAPE — the second deck: the REELS (two reels spin at the effective
--     rate — reverse spins backward, stopped stands still — above the loop
--     track + head, with the loop readout on the right)
-- ============================================================================
local REEL_X = { 46, 86 }   -- the two reel centers
local reel_angle = 0        -- persistent spin accumulator, driven by tape rate
local function body_TAPE(frame)
  local a2, b2 = pget("loop_start", 0), pget("loop_end", 1)
  local lo, hi = min(a2, b2), max(a2, b2)
  local lspan = max(hi - lo, 0.001)
  -- the reels spin at the effective rate: reverse -> backward, stopped -> still.
  -- STOP halts the tape head (the rate law folds it), so it halts the reels
  local r = pget("tape_rate", 1) * (pget("tape_reverse", 0) == 1 and -1 or 1)
    * (1 - pget("stop_all", 0))
  reel_angle = reel_angle + r * 0.35
  for _, cx in ipairs(REEL_X) do
    screen.level(4)
    screen.circle(cx, 24, 8)
    screen.stroke()
    screen.level(6)                      -- hub
    screen.rect(cx - 1, 23, 3, 3)
    screen.fill()
    screen.level(10)                     -- three spokes, inner r2.5 -> r6.5
    for k = 0, 2 do
      local a = reel_angle + k * 2.094
      local ca, sa = cos(a), sin(a)
      screen.move(cx + ca * 2.5, 24 + sa * 2.5)
      screen.line(cx + ca * 6.5, 24 + sa * 6.5)
    end
    screen.stroke()
  end
  screen.level(4)                        -- straight tape guides between the reels
  screen.move(46, 16) screen.line(86, 16)
  screen.move(46, 32) screen.line(86, 32)
  screen.stroke()
  -- the loop track below: full-width rail, the loop region, the head
  screen.level(2)
  screen.move(0, 40) screen.line(128, 40)
  screen.stroke()
  screen.level(8)
  screen.move(lo * 127, 40) screen.line(hi * 127, 40)
  screen.stroke()
  screen.level(15)
  local tx = clamp(C.tape_phase, 0, 1) * 127
  screen.move(tx, 37) screen.line(tx, 43)
  screen.stroke()
  ptext_r(string.format("%.1fS", lspan * (C.TAPE_LEN or 60)), 126, 12, 1, 5)
  src_flag(2, 46)
  if pget("tape_rec", 0) == 1 and pget("tape_freeze", 0) == 0 then
    chip("REC", 2, 12)                -- steady: the header T is the blink
  elseif not C.twave_any then
    ptext_c("EMPTY - K2 REC", 64, 26, 1, 10)
  end
end

-- ============================================================================
-- 4 · LAYERS - the loop decks beside the tape
-- ============================================================================
-- Two strips, one per deck. Each shows what is actually recorded in it, the
-- loop bracket over that, and the head. The SELECTED deck is bright and the
-- other dim -- the audibility rule everywhere else in this instrument: if a
-- thing is not the one you are working on, it does not compete for your eye.
-- A deck whose level is down, or that is not playing, dims further, so you can
-- always see which of them you are actually hearing.
local function layer_strip(d, y, sel, frame)
  local rec = pget(C.deck_p(d, "rec"), 0) == 1
  local playing = pget(C.deck_p(d, "play"), 1) == 1
  local lv = pget(C.deck_p(d, "level"), 0.8)
  local audible = playing and lv > 0.01 and pget("stop_all", 0) == 0
  local base = sel and (audible and 10 or 6) or (audible and 5 or 3)

  -- name, and the state in words rather than an icon to decode
  ptext(d.name, 3, y - 6, 1, sel and 15 or 6)
  if rec then
    -- steady: the header's L is the one blink that says WRITING
    screen.level(15); screen.rect(15, y - 5, 3, 3); screen.fill()
    ptext(pget(C.deck_p(d, "pre"), 1) > 0.5 and "DUB" or "REP", 20, y - 6, 1, 12)
  elseif not playing then
    -- MUTE, not STOP: the head keeps rolling. That is deliberate — two decks at
    -- different rates only stay in their drifting relationship if neither one
    -- restarts, so silencing a layer must not move it. The word has to say so.
    ptext("MUTE", 20, y - 6, 1, 5)
  end

  local x0, x1 = 38, 124
  local w = x1 - x0
  -- the material
  screen.level(base)
  wave_lane(d.wave, x0, x1, y, 5, 1, 5)
  -- the loop bracket: where this deck actually reads from
  local ls = clamp(pget(C.deck_p(d, "start"), 0), 0, 1)
  local le = clamp(pget(C.deck_p(d, "end"), 1), 0, 1)
  local bx0 = x0 + floor(min(ls, le) * w)
  local bx1 = x0 + floor(max(ls, le) * w)
  screen.level(sel and 12 or 5)
  screen.rect(bx0, y - 6, 1, 13)
  screen.rect(bx1, y - 6, 1, 13)
  screen.rect(bx0, y - 6, bx1 - bx0, 1)
  screen.fill()

  -- the invitation goes over the bracket (which is drawn across the same
  -- space), so it knocks out a pocket first — the rule the footer follows when
  -- a swelling value meets the key words
  if not d.any then
    local msg = sel and "EMPTY - K2 REC" or "EMPTY"
    local tw = text_w(msg, 1)
    local tx = floor((x0 + x1) / 2 - tw / 2)
    screen.level(0)
    screen.rect(tx - 2, y - 2, tw + 4, 9)
    screen.fill()
    ptext(msg, tx, y + 3, 1, sel and 10 or 3)
  end

  -- the head, drawn last so it is never hidden
  screen.level(audible and 15 or 6)
  screen.rect(x0 + floor(clamp(d.phase, 0, 1) * w), y - 5, 1, 11)
  screen.fill()

  -- level, as a short bar under the name
  screen.level(sel and 8 or 4)
  screen.rect(3, y + 4, floor(clamp(lv, 0, 1) * 30), 1)
  screen.fill()
end

local function body_LAYERS(frame)
  local sel = floor(pget("layer_sel", 1) + 0.5)
  local decks = C.layers or {}
  if #decks == 0 then
    ptext_c("NO LAYER DECKS", 64, 30, 1, 5)
    return
  end
  -- the rate of the selected deck, top right: the number that makes two decks
  -- drift against each other, which is the whole reason for having two
  local d = decks[sel] or decks[1]
  local r = pget(C.deck_p(d, "rate"), 1) * (pget(C.deck_p(d, "reverse"), 0) == 1 and -1 or 1)
  ptext_r(string.format("%.2fX", r), 126, 12, 1, 5)
  -- the selected deck's LOOP LENGTH. With its rate on the other side these are
  -- the two numbers that decide whether two decks stay locked or walk apart,
  -- and this is what makes SNAP visible even in the case where it moves
  -- nothing because the loop was already on the grid.
  if C.loop_secs then
    ptext(string.format("%.2fS", C.loop_secs(d)), 2, 12, 1, 5)
  end
  -- what the decks RECORD: the EFFECTIVE source (the knob, or the bounce's
  -- WET override while a layer is armed). Flag a processed print, or the
  -- resample rig is a hidden mode. DRY draws nothing, same law as TAPE's.
  src_flag(44, 12)
  for i = 1, math.min(#decks, 2) do
    layer_strip(decks[i], i == 1 and 27 or 45, sel == i, frame)
  end
  -- what SNAP just did, over the readout row it replaces for a moment. A snap
  -- that lands on the length you already had moves nothing on screen, and a
  -- page that cannot say so is indistinguishable from a key that did nothing.
  if C.lay_msg and (frame - (C.lay_msg_at or -1e9)) < FPS * 1.2 then
    -- the WHOLE row: a pocket cut only behind the words leaves the loop
    -- seconds and the rate peeking out either side of the message, which
    -- reads as garbage. A fresh action is the more urgent news, so it takes
    -- the row outright and the readouts come back when it expires.
    screen.level(0); screen.rect(0, 11, 128, 7); screen.fill()
    ptext_c(C.lay_msg, 64, 12, 1, 12)
  end
end

-- ============================================================================
-- 5 · FILTER — tone (approx DFM1 response, with labeled measurement rails;
--     drive = grit on the line, not a number)
-- ============================================================================
local function body_FILTER(frame)
  local cut = tp("cutoff", 20000)
  local ft = tp("filt_type", 1)
  local res = tp("resonance", 0)
  local drv = pget("drive", 0)
  screen.level(2)
  for i = 1, 3 do
    for y = FILT_TOP, FILT_BOT, 2 do
      screen.rect(FILT_GRID_X[i], y, 1, 1)
    end
  end
  for x = 0, 127, 4 do screen.rect(x, FILT_DB0_Y, 1, 1) end
  screen.fill()
  for i = 1, 3 do
    ptext(FILT_GRID_LBL[i], FILT_GRID_X[i] - 5, FILT_BOT + 2, 1, 3)
  end
  local rq = max(1 - res * 0.92, 0.05)
  local rq2 = rq * rq
  local px_per_db = (FILT_BOT - FILT_TOP) / FILT_DB_RANGE
  for x = 0, 127 do
    local w = FILT_FREQ[x + 1] / cut
    local w2 = w * w
    local d = 1 - w2
    d = d * d + w2 * rq2
    local h2
    if ft == 1 then h2 = 1 / d
    elseif ft == 2 then h2 = (w2 * w2) / d
    else                              -- BP = resonant LP peak, high-passed below cutoff/2
      local u = w + w                 -- freq / (cutoff*0.5), the engine's HP corner
      local u4 = u * u * u * u
      h2 = (1 / d) * u4 / (1 + u4)
    end
    local y = FILT_TOP + (FILT_DB_TOP - 4.342944819 * log(h2)) * px_per_db
    if y < FILT_TOP then y = FILT_TOP elseif y > FILT_BOT then y = FILT_BOT end
    FILT_Y[x + 1] = y
  end
  -- passband filled dim (hiding the rails it covers), curve bright on top
  screen.level(2)
  for x = 0, 127 do
    local y = FILT_Y[x + 1]
    if y < FILT_BOT then
      screen.move(x, y)
      screen.line(x, FILT_BOT)
    end
  end
  screen.stroke()
  local ssd = floor(frame / 4)
  screen.level(4)
  for x = 0, 127, 5 do
    local under = FILT_BOT - FILT_Y[x + 1]
    if under > 1 then
      local th = hash(x, 3, ssd) * under
      screen.rect(x, FILT_BOT - th, 1, th)
    end
  end
  screen.fill()
  screen.level(10)
  for x = 1, 127 do
    screen.move(x - 1, FILT_Y[x])
    screen.line(x, FILT_Y[x + 1])
  end
  screen.stroke()
  if drv > 0.005 then          -- saturation as texture: grit flecks the curve
    screen.level(7)
    for x = 0, 127, 2 do
      if hash(x, 9, ssd) < drv * 0.35 then
        screen.rect(x, FILT_Y[x + 1] - 2 - hash(x, 11, ssd) * 2, 1, 1)
      end
    end
    screen.fill()
  end
  -- the cutoff as a grabbable node: E2 moves exactly this dot
  local nx = floor(clamp(log(cut / 20) / log(1000), 0, 1) * 127 + 0.5)
  screen.level(15)
  screen.rect(nx - 1, FILT_Y[nx + 1] - 1, 3, 3)
  screen.fill()
  chip(params:string(C.tid and C.tid("filt_type") or "filt_type"), 2, 12)
end

-- ============================================================================
-- 6 · DELAY / REVERB — the time-smear, split into two stations. DELAY draws
--     the onset + echo taps decaying by feedback; REVERB draws the tail as a
--     slope + shimmer motes. shared time axis, rails at 1s/2s, dormant flat
--     at mix 0. (was one merged SPACE page, split after play-testing.)
-- ============================================================================
local SPC_BASE, SPC_X0 = 48, 8
local SPC_PPS = 49                    -- pixels per second on the time axis

-- shared chrome: the time baseline, the dormant stub, and the 1s/2s rails.
-- returns true if the page is live (caller draws the effect), false if it
-- already drew the dormant stub and should bail.
local function spc_frame(live)
  screen.level(live and 4 or 2)
  screen.move(4, SPC_BASE) screen.line(124, SPC_BASE)
  screen.stroke()
  if not live then                    -- dormant: a stub of an onset
    screen.level(4)
    screen.rect(SPC_X0, SPC_BASE - 5, 2, 5)
    screen.fill()
    return false
  end
  -- time rails: 1s and 2s, labeled
  screen.level(2)
  for i = 1, 2 do
    local tx = SPC_X0 + i * SPC_PPS
    for y = 14, SPC_BASE - 1, 2 do screen.rect(tx, y, 1, 1) end
  end
  screen.fill()
  ptext("1S", SPC_X0 + SPC_PPS - 3, SPC_BASE + 2, 1, 3)
  ptext("2S", SPC_X0 + 2 * SPC_PPS - 3, SPC_BASE + 2, 1, 3)
  return true
end

local function spc_onset()             -- the shared onset spike
  screen.level(15)
  screen.rect(SPC_X0, SPC_BASE - 34, 2, 34)
  screen.fill()
end

local function body_DELAY(frame)
  local emix = pget("delay_mix", 0)
  if not spc_frame(emix > 0.005) then return end
  spc_onset()
  -- echo taps: spacing = delay_time, height decaying by the ACTUAL feedback
  -- coefficient (the knob is curved through ctx.delay_fb_curve, so the taps
  -- match what you hear — the animation stays honest)
  local sp = max(pget("delay_time", 0.3) * SPC_PPS, 6)
  local fbk = pget("delay_fb", 0.3)
  local fb = max(C.delay_fb_curve and C.delay_fb_curve(fbk) or fbk, 0.05)
  local h = 30 * (0.4 + emix * 0.6)
  local x = SPC_X0 + sp
  while x <= 124 and h >= 1.5 do
    screen.level(max(4, floor(4 + (h / 30) * 10)))
    screen.rect(floor(x), SPC_BASE - h, 2, h)
    screen.fill()
    h = h * fb
    x = x + sp
  end
end

local function body_REVERB(frame)
  local vmix = pget("rev_mix", 0)
  if not spc_frame(vmix > 0.005) then return end
  -- the reverb tail: a filled slope whose reach IS the decay
  local tau = max(pget("rev_decay", 2), 0.1) * SPC_PPS / 6.9
  local A = 4 + vmix * 26
  screen.level(3)
  for x = SPC_X0 + 1, 124 do
    local h = A * exp(-(x - SPC_X0) / tau)
    if h >= 1 then
      screen.move(x, SPC_BASE - h)
      screen.line(x, SPC_BASE - 1)
    end
  end
  screen.stroke()
  -- discrete reflections riding the slope: rev_size spaces them (a bigger
  -- room = sparser, later reflections), rev_damp darkens them toward the
  -- tail-end (high frequencies absorbed) — so both encoders READ on the page.
  local step = 2 + floor(pget("rev_size", 1))          -- 2 (tight) .. 7 (vast)
  local damp = pget("rev_damp", 0.3)
  local span = 124 - SPC_X0
  for x = SPC_X0 + 1, 124, step do
    local h = A * exp(-(x - SPC_X0) / tau)
    if h >= 1 then
      screen.level(max(2, floor(9 - damp * 7 * (x - SPC_X0) / span)))
      screen.rect(x, SPC_BASE - h, 1, 1)
      screen.fill()
    end
  end
  -- "this will not stop soon": the tail runs into the hatched margin
  if A * exp(-(124 - SPC_X0) / tau) >= 1 then
    screen.level(9)
    for y = 14, SPC_BASE do
      local xx = 125 + ((y + 125) % 3)
      if xx <= 127 then screen.rect(xx, y, 1, 1) end
    end
    screen.fill()
  end
  -- shimmer: motes climbing off the tail
  local shim = pget("shimmer", 0)
  if shim > 0.01 then
    local spd = 0.4 + value_norm("shimmer_pitch", pget("shimmer_pitch", 12)) * 1.4
    local n = 3 + floor(shim * 15)
    screen.level(7)
    for i = 1, n do
      local mx = SPC_X0 + 4 + hash(i, 3, 0) * 100
      local ph = (frame * spd + hash(i, 5, 0) * 100) % 28
      screen.rect(mx, SPC_BASE - 4 - ph, 1, 1)
    end
    screen.fill()
  end
  spc_onset()
end

-- ============================================================================
-- 8 · MIX — the console (in meter → the two decks at their REAL gains →
--     master VU). the layer decks live on their own page; this console is
--     the engine <> tape crossfade.
-- ============================================================================
-- one console meter: frame, the signal bar (sqrt law), and a peak pip that
-- decays slowly. `k` picks its peak slot; the pip decays once per frame.
local function vu(x, sig, k, newframe)
  screen.level(1)
  screen.rect(x - 1.5, 18.5, 8, 31)
  screen.stroke()
  if sig > 0.01 then
    screen.level(11)
    screen.rect(x, 48 - sig * 28, 5, sig * 28)
    screen.fill()
  end
  if newframe then vu_peak[k] = max(sig, vu_peak[k] - 0.0045) end
  if vu_peak[k] > 0.02 then
    screen.level(15)
    screen.rect(x, 48 - vu_peak[k] * 28 - 1, 5, 1)
    screen.fill()
  end
end

local function body_MIX(frame)
  -- each lane's energy is its deck's REAL gain: the ONE law itself
  -- (C.mix_gains — trim x crossfade plateau x master x STOP), not a mirror
  local mixv = pget("mix", 0.5)
  local eng_g, tape_g = C.mix_gains()
  local eng_on = pget("mode", 5) ~= 1 and eng_g > 0.001 and C.wave_any
  local tape_on = C.twave_any and tape_g > 0.001
  local newframe = C.frame ~= vu_last_frame
  -- input meter, left
  ptext("IN", 3, 12, 1, 5)
  vu(5, sqrt(clamp(max(amp_in[1], amp_in[2]), 0, 1)), 1, newframe)
  -- the engine deck lane (the real take, at the deck's real gain)
  ptext("ENG", 18, 13, 1, 5)
  if not eng_on then
    screen.level(1)
    screen.move(18, 23.5) screen.line(104, 23.5)
    screen.stroke()
  else
    screen.level(12)
    wave_lane(wave, 18, 104, 23.5, clamp(eng_g, 0, 1) * 5, 0.5, 5)
    if pget("mode", 5) ~= 1 then
      screen.level(15)
      local phx = 18 + clamp(C.play_phase, 0, 1) * 86
      screen.move(phx, 19) screen.line(phx, 28)
      screen.stroke()
    end
  end
  -- the crossfade rail + tick (the tick stays put in STOP: settings held)
  screen.level(2)
  screen.move(18, 32.5) screen.line(104, 32.5)
  screen.stroke()
  screen.level(15)
  screen.rect(18 + mixv * 84, 30, 3, 6)
  screen.fill()
  -- the tape deck lane (the real loop; the head is ALWAYS running on it)
  if not tape_on then
    screen.level(1)
    screen.move(18, 41.5) screen.line(104, 41.5)
    screen.stroke()
  else
    screen.level(10)
    wave_lane(twave, 18, 104, 41.5, clamp(tape_g, 0, 1) * 4, 0.5, 4)
  end
  if C.twave_any then
    screen.level(tape_on and 15 or 4)
    local hx = 18 + clamp(C.tape_phase, 0, 1) * 86
    screen.move(hx, 38) screen.line(hx, 45)
    screen.stroke()
  end
  ptext("TAPE", 18, 47, 1, 5)
  -- master VU, right
  vu(114, sqrt(clamp(max(amp_out[1], amp_out[2]), 0, 1)), 2, newframe)
  if newframe then vu_last_frame = C.frame end
  ptext("OUT", 112, 12, 1, 5)
end

-- ============================================================================
-- 9 · PADS — the take chopped into 8 playable slices: the window zoomed full
--     width over 8 numbered cells, each with its own voice + pitch sound-lock;
--     lit while sounding, the cursor squared for editing.
-- ============================================================================
local function body_PADS(frame)
  for i = 0, 7 do pad_lit[i] = false end
  local used = 0
  for _, padi in pairs(C.pad_held) do
    pad_lit[padi] = true
    used = used + 1
  end
  local routed = pget("pad_input", 0) == 1
  ptext(routed and "PLAY>PADS" or "PLAY>DRONE", 2, 12, 1, routed and 12 or 5)
  -- the SELECTED pad's sound-lock: voice + pitch (the cursor editor). e.g. SLC+5
  local cvi = clamp(floor(pget("seq_slice", 0) + 0.5), 0, 7)
  local cp = C.pad_pitch and (C.pad_pitch[cvi] or 0) or 0
  local lk = ((C.pad_type and C.pad_type[cvi] or 0) == 1 and "SLC" or "GRN")
    .. (cp ~= 0 and ((cp > 0 and "+" or "") .. cp) or "")
  ptext_c(lk, 72, 12, 1, 6)
  ptext_r(used .. "/" .. floor(pget("voices", 8) + 0.5) .. "V", 126, 12, 1, 5)
  if not C.wave_any and pget("rec", 0) == 0 then
    ptext_c("EMPTY - K2 REC", 64, 28, 1, 10)
    return
  end
  -- THE TAKE: the window zoomed full width, divided into 8 (a pad is
  -- self-evidently an eighth of what you recorded)
  local bx0, bx1, by = 4, 124, 22
  local sw = (bx1 - bx0) / 8
  local wlo, _, wspan = window_bounds()
  screen.level(8)
  wave_lane(wave, bx0, bx1, by, 4, 1, 4, wlo, wspan)
  -- the slice boundaries, ON the wave. Even eighths when nothing has been
  -- chopped; the REAL cut positions once something has, because the whole
  -- point of a chop is that the slices are not evenly spaced and the picture
  -- has to say so.
  local cuts = C.pad_cuts
  screen.level(4)
  if cuts then
    for i = 1, #cuts do
      local f = (cuts[i] - wlo) / wspan
      if f >= 0 and f <= 1 then
        screen.rect(bx0 + f * (bx1 - bx0), by - 5, 1, 10)
      end
    end
  else
    for i = 0, 8 do screen.rect(bx0 + i * sw, by - 5, 1, 10) end
  end
  screen.fill()
  if pget("mode", 5) ~= 1 then
    local ph = (clamp(C.play_phase, 0, 1) - wlo) / wspan
    if ph >= 0 and ph <= 1 then
      screen.level(13)
      screen.rect(bx0 + ph * (bx1 - bx0), by - 5, 1, 10)
      screen.fill()
    end
  end
  -- the 8 slice cells, aligned under their eighths
  for i = 0, 7 do
    local cx = bx0 + i * sw
    local cur = i == C.pad_cursor
    local lit = pad_lit[i]
    if cur then
      -- the selected cell is a SQUARE that stands 1px proud on every side, so
      -- it reads as picked instead of as one more small rectangle in the row
      screen.level(15)
      screen.rect(cx + sw / 2 - 7, 26.5, 14, 14)
      screen.stroke()
    else
      screen.level(4)
      screen.rect(cx + 1.5, 28.5, sw - 3, 10)
      screen.stroke()
    end
    if lit then
      screen.level(cur and 15 or 9)
      screen.rect(cx + 3, 30, sw - 6, 7)
      screen.fill()
    end
    local sl = (C.pad_slice_of and C.pad_slice_of(i) or i) + 1
    ptext_c(tostring(sl), cx + sw / 2, 31, 1, lit and 0 or (cur and 15 or 6))
    -- SOUND-LOCK markers: a bottom bar = SLICE voice, a top-corner dot = pitched
    if (C.pad_type and C.pad_type[i] or 0) == 1 then
      screen.level(lit and 0 or (cur and 15 or 6))
      screen.rect(cx + sw / 2 - 2, 36, 4, 1)
      screen.fill()
    end
    if C.pad_pitch and (C.pad_pitch[i] or 0) ~= 0 then
      screen.level(cur and 15 or 6)
      screen.rect(cx + sw / 2 + 3, 28, 1, 1)
      screen.fill()
    end
  end
  -- the row below the slices is the sequencer's, at all times: its steps
  -- under the pads, the hits as bars, the rests as dots. Running, it is
  -- bright and the step the clock is on lights (a tall bar while its pad
  -- sounds, a bright dot on a rest); stopped, the pattern waits dim. A CHOP
  -- in force says so on the line below it: what the pads now mean.
  local seq = C.seq
  if seq then
    local run = pget("step_run", 0) == 1
    local n = floor(pget("step_len", 4) + 0.5)
    local sw2 = floor(112 / n)
    local x0 = 64 - floor(sw2 * n / 2)
    for s = 0, n - 1 do
      local x = x0 + s * sw2
      local now = run and s == seq.step
      if seq.hits[s + 1] then
        screen.level(now and 15 or (run and 6 or 3))
        if now then screen.rect(x + 1, 42, sw2 - 2, 5)
        else screen.rect(x + 1, 43, sw2 - 2, 3) end
      else
        screen.level(now and 15 or (run and 3 or 2))
        screen.rect(x + floor(sw2 / 2), 44, 1, 1)
      end
      screen.fill()
    end
  end
  if C.pad_cuts then
    local n = #C.pad_cuts - 1
    ptext_c(("CHOP - %d SLICES ON THE HITS"):format(n), 64, 49, 1, 5)
  end
end

-- ============================================================================
-- 10 · MOTION — the gesture loop (dynamic lanes: one automation CURVE per
--     recorded param, named with its page's own word; one playhead crosses
--     every lane with a live-value dot)
-- ============================================================================
-- MOTION's modulator rows (MOTION hosts the two LFOs): below the lanes, one
-- row each, selected by the same E2 walk. The name column says which one
-- and what it moves ("1>CUT", "2 OFF"); the row draws two cycles of its
-- wave, as tall as its depth (upside down for a negative depth), with a dot
-- where the wave is now. ENV draws the input's envelope as a bar. A
-- modulator that also goes out to other gear says where on the right (>CC
-- the MIDI CC, >CV crow, >OUT both). Dim and flat while it moves nothing.
local LFO_PID = {}
for k = 1, 2 do
  LFO_PID[k] = { target = "lfo" .. k .. "_target", depth = "lfo" .. k .. "_depth",
    shape = "lfo" .. k .. "_shape" }
end
local LFO_TAG = { "1>", "2>" }
local LFO_OFF = { "1 OFF", "2 OFF" }
local LFO_GX1 = 110
local function lfo_row(k, yb, selected, gx0)
  local L = C.lfo
  if not L then return end
  local P = LFO_PID[k]
  local tid = L.TARGETS[floor(pget(P.target, 1) + 0.5) - 1]
  local depth = pget(P.depth, 0)
  local live = tid ~= nil and abs(depth) >= 0.001
  local lvl = selected and 11 or (live and 7 or 4)
  if tid then
    ptext(LFO_TAG[k], 2, yb - 6, 1, lvl)
    ptext(SHORT[tid] or "?", 2 + text_w(LFO_TAG[k], 1) + 1, yb - 6, 1, lvl)
  else
    ptext(LFO_OFF[k], 2, yb - 6, 1, lvl)
  end
  local w = LFO_GX1 - gx0
  local mid = yb - 4
  local shape = floor(pget(P.shape, 1) + 0.5)
  local m = L.mods[k]
  if not live then
    screen.level(2)
    screen.rect(gx0, mid, w, 1)
    screen.fill()
  else
    local a = max(1, abs(depth) * 4)
    local sg = depth < 0 and -1 or 1
    screen.level(selected and 11 or 6)
    if shape == 6 then                        -- ENV: the envelope, as a bar
      screen.rect(gx0, mid, max(1, floor(L.env * w)), 1)
    else
      for x = 0, w do
        local ph = (x / w * 2) % 1
        local v = shape == 5 and (hash(floor(x / w * 6), k, 7) * 2 - 1)
          or L.wave(shape, ph)
        screen.rect(gx0 + x, floor(mid - v * a * sg + 0.5), 1, 1)
      end
    end
    screen.fill()
    -- where it is now
    local v = shape == 6 and (L.env * 2 - 1) or (m.out * 2 - 1)
    local dx = shape == 6 and gx0 + L.env * w or gx0 + m.phase * w / 2
    screen.level(15)
    screen.rect(floor(dx) - 1, floor(mid - v * a * sg + 0.5) - 1, 3, 3)
    screen.fill()
  end
  -- does it also go out?
  if floor(pget("out_src", 1) + 0.5) == k + 3 then
    local cc = pget("out_midi", 0) > 0
    local cv = pget("out_crow", 0) == 1
    if cc or cv then
      ptext(cc and cv and ">OUT" or (cc and ">CC" or ">CV"), LFO_GX1 + 3, yb - 6, 1, 6)
    end
  end
  if selected then
    screen.level(15)
    screen.move(0, yb - 8) screen.line(0, yb + 2)
    screen.stroke()
    screen.rect(1, yb - 8, 1, 1)
    screen.rect(1, yb + 2, 1, 1)
    screen.fill()
  end
end

local function body_MOTION(frame)
  local mo = C.motion
  local ll = mo.loop_len
  local ids = mo.lane_ids
  local nlane = #ids
  local armed = pget("motion_rec", 0) == 1
  local playing = pget("motion_play", 0) == 1
  local top, rh = 15, 10
  local gx0, gx1 = 33, 124
  -- the selection over every row: 0 none, 1..nlane the lanes, then the
  -- two modulators
  local focus = floor(pget("mod_focus", 1) + 0.5)
  local sel = focus > 1 and nlane + focus - 1
    or clamp(floor(pget("motion_lane", 0) + 0.5), 0, nlane)
  if nlane == 0 then
    -- no lanes: the invitation above, the two modulator rows below it
    if armed then
      chip("REC", 2, 12)              -- steady: the header M is the blink
      ptext_c("MOVE A KNOB TO RECORD", 64, 22, 1, 8)
    else
      ptext_c("EMPTY - K2 ARM", 64, 16, 1, 10)
      ptext_c("THEN MOVE A KNOB", 64, 24, 1, 5)
    end
    for k = 1, 2 do lfo_row(k, top + (k + 1) * rh + 8, sel == k, gx0) end
    return
  end
  if ll > 0 then
    ptext_r(string.format("LOOP %.1fS", ll / FPS), 126, 9, 1, 5)
  end
  local nrow = nlane + 2
  local VIS = 4
  local shown = min(nrow, VIS)
  -- scroll: the VIS-row window follows the selection so every row is
  -- reachable (a scrollbar on the right edge shows where in the stack you are)
  local off = 0
  if nrow > VIS then
    local fsel = sel > 0 and sel or 1
    off = clamp(fsel - VIS, 0, nrow - VIS)     -- keep the selected row visible:
    if fsel - 1 < off then off = fsel - 1 end  --   between the top and bottom row
  end
  -- the lane rows in the window (the rails, the playhead and the armed frame
  -- span these, not the modulators)
  local lshown = clamp(nlane - off, 0, shown)
  -- drawing length: the loop once set, else the furthest event so far
  local dl = ll                          -- playhead / rails denominator (loop_len)
  if dl == 0 then
    for i = 1, nlane do
      local L = mo.lanes[ids[i]]
      if L.n > 0 and L.f[L.n] > dl then dl = L.f[L.n] end
    end
  end
  if dl < 1 then dl = 1 end
  -- events live in the rec_len timebase; plotting them against rec_len keeps
  -- the step-curve aligned with the playhead when motion_len retimes the loop.
  -- IDENTITY when not retimed (rec_len == loop_len == dl) or mid-first-pass.
  local el = mo.rec_len or 0
  if el < 1 then el = dl end
  -- quarter rails through the loop
  if lshown > 0 then
    screen.level(2)
    for k = 0, 4 do
      local x = gx0 + floor((gx1 - gx0) * k / 4)
      for y = top - 2, top + lshown * rh - 2, 2 do screen.rect(x, y, 1, 1) end
    end
    screen.fill()
  end
  local phx = gx0 + (clamp(mo.playhead, 0, dl) / dl) * (gx1 - gx0)
  for row = 1, shown do
    local li = off + row                  -- the row index this row shows
    if li > nlane then
      lfo_row(li - nlane, top + (row - 1) * rh + 8, li == sel, gx0)
      goto continue
    end
    local id = ids[li]
    local L = mo.lanes[id]
    local yb = top + (row - 1) * rh + 8   -- the lane's value baseline
    local selected = li == sel
    ptext(SHORT[id] or string.upper(id), 2, yb - 6, 1, selected and 11 or 5)
    if selected then
      screen.level(15)
      screen.move(0, yb - 8) screen.line(0, yb + 2)
      screen.stroke()
      screen.rect(1, yb - 8, 1, 1)
      screen.rect(1, yb + 2, 1, 1)
      screen.fill()
    end
    -- the recorded motion as a STEP CURVE (hold value between events)
    local n = L.n
    local lp = lookup_p(id)               -- once per lane, not once per event
    if n > 0 then
      screen.level(selected and 11 or 7)
      local py = yb - pnorm(lp, L.v[1]) * 8
      screen.move(gx0, py)
      if n <= gx1 - gx0 then
        for e = 1, n do
          local ex = gx0 + (L.f[e] / el) * (gx1 - gx0)
          local ey = yb - pnorm(lp, L.v[e]) * 8
          screen.line(ex, py)
          screen.line(ex, ey)
          py = ey
        end
      else
        -- more events than pixel columns (a long continuous gesture: up to
        -- 900 a lane). Drawing each one sent thousands of segments a frame
        -- through the screen for the same pixels, so collapse each COLUMN to
        -- one vertical over the values the curve visits there.
        local col, ylo, yhi
        for e = 1, n do
          local c = floor(gx0 + (L.f[e] / el) * (gx1 - gx0))
          local ey = yb - pnorm(lp, L.v[e]) * 8
          if c ~= col then
            if col then
              screen.line(col, ylo); screen.line(col, yhi); screen.line(col, py)
            end
            screen.line(c, py)            -- the hold, up to this column
            col, ylo, yhi = c, min(py, ey), max(py, ey)
          else
            if ey < ylo then ylo = ey end
            if ey > yhi then yhi = ey end
          end
          py = ey
        end
        screen.line(col, ylo); screen.line(col, yhi); screen.line(col, py)
      end
      screen.line(gx1, py)
      screen.stroke()
    end
    -- the value sounding right now, where the playhead crosses
    if ll > 0 then
      local vy = yb - pnorm(lp, pget(id, 0)) * 8
      screen.level(15)
      screen.rect(phx - 1, vy - 1, 3, 3)
      screen.fill()
    end
    ::continue::
  end
  -- one playhead crosses every lane
  if lshown > 0 and ll > 0 then
    screen.level(playing and 10 or 3)
    screen.move(phx, top - 3)
    screen.line(phx, top + lshown * rh - 3)
    screen.stroke()
  elseif lshown > 0 and armed then
    screen.level(15)
    screen.move(gx1, top - 3)
    screen.line(gx1, top + lshown * rh - 3)
    screen.stroke()
  end
  if armed and lshown > 0 then           -- armed frame, steady (header M blinks)
    screen.level(15)
    screen.rect(gx0 - 2.5, top - 4.5, gx1 - gx0 + 6, lshown * rh + 5)
    screen.stroke()
  end
  -- scrollbar (right edge): the VIS-row window's place in the whole stack
  if nrow > VIS then
    local sy0, sy1 = top - 2, top + shown * rh - 3
    screen.level(2)
    screen.rect(127, sy0, 1, sy1 - sy0)
    screen.fill()
    local th0 = sy0 + (sy1 - sy0) * (off / nrow)
    local th1 = sy0 + (sy1 - sy0) * ((off + VIS) / nrow)
    screen.level(9)
    screen.rect(127, th0, 1, max(1, th1 - th0))
    screen.fill()
  end
end

-- ============================================================================
-- 11 · SCENE — states and the way back (the slot row + the morph rail; undo
--     is the ◄ cell, a slot you can see)
-- ============================================================================
-- SCENE slot cells: an empty cell is a dotted box; the selected cell is
-- bracketed one pixel OUTSIDE its edge on both sides, on the slot row (y 20
-- and 35)
local function dotted_box(x0, x1, y0, y1)
  for xx = x0, x1, 2 do
    screen.rect(xx, y0, 1, 1)
    screen.rect(xx, y1, 1, 1)
  end
  for yy = y0, y1, 2 do
    screen.rect(x0, yy, 1, 1)
    screen.rect(x1, yy, 1, 1)
  end
  screen.fill()
end
local function slot_brackets(x0, x1)
  screen.level(15)
  screen.rect(x0, 20, 4, 1)
  screen.rect(x1 - 3, 20, 4, 1)
  screen.rect(x0, 35, 4, 1)
  screen.rect(x1 - 3, 35, 4, 1)
  screen.rect(x0, 21, 1, 2)
  screen.rect(x1, 21, 1, 2)
  screen.rect(x0, 33, 1, 2)
  screen.rect(x1, 33, 1, 2)
  screen.fill()
end

local function body_SCENE(frame)
  local sc = C.scene
  local sel = clamp(floor(pget("scene_slot", 1) + 0.5), 0, 8)
  local amt = pget("scene_morph_amt", 0)
  -- status row: the message line outranks the morph cue
  local msg_live = sc.msg ~= nil and (frame - sc.msg_at) < FPS * 1.2
  if msg_live then
    chip(sc.msg, 64 - floor((text_w(sc.msg, 1) + 5) / 2), 11)
  elseif amt >= 0.999 and sc.engaged and sc.unlanded(sel) then
    ptext_c("K2 TO LAND THE REST", 64, 13, 1, 5)
  else
    ptext_r(params:string("scene_recall_mode"), 126, 13, 1, 5)
  end
  -- the orbit lives here now (its knobs are this page's alt pair): a steady
  -- chip while the wander runs — the moving selector and rail are its motion
  if pget("orbit_on", 0) == 1 then
    chip("ORBIT", 2, 11)
  end
  -- the ◄ cell: the way back (the safe state, auto-marked by chaos)
  if sc.safe then
    screen.level(6)
    screen.rect(3, 22, 9, 12)
    screen.fill()
    ptext("<", 6, 25, 1, 0)
  else
    screen.level(2)
    dotted_box(3, 11, 22, 33)
    ptext("<", 6, 25, 1, 3)
  end
  if sel == 0 then slot_brackets(2, 12) end   -- the ◄ cell (x 3..11) is selected
  -- the refusal shake: a no-op action (an empty slot) shakes its cell for a
  -- beat — the instrument never silently ignores you, and needs no words
  local shake = 0
  if msg_live and (frame - sc.msg_at) < 4 and sc.msg
      and sc.msg:find("EMPTY") then
    shake = (frame % 2 == 0) and 1 or -1
  end
  -- the 8 slots
  local nfilled = 0
  for i = 1, 8 do
    local x = 16 + (i - 1) * 14
    if i == sc.msg_slot then x = x + shake end
    local filled = sc.slots[i] ~= nil
    if filled then nfilled = nfilled + 1 end
    local pending = sc.pending == i
    local flash = msg_live and sc.msg_slot == i
    if filled or pending or flash then
      -- a queued recall is steady and between the two (one blink: the header)
      screen.level(flash and 15 or (pending and 11 or 7))
      screen.rect(x, 22, 12, 12)
      screen.fill()
    else
      screen.level(2)
      dotted_box(x, x + 11, 22, 33)
    end
    ptext_c(tostring(i), x + 6, 25, 1, (filled or pending or flash) and 0 or 4)
    if i == sel then slot_brackets(x - 1, x + 12) end   -- cursor brackets
  end
  -- a queued recall: the emptying wedge counts down to the sync point
  -- (clock.get_beats is device-side; the sim has no clock, so no wedge)
  if sc.pending then
    local ok, beats = pcall(clock.get_beats)
    if ok and type(beats) == "number" then
      local mode = floor(pget("scene_recall_mode", 1) + 0.5)
      local span = mode == 3 and 4 or 1
      local frac = 1 - ((beats % span) / span)     -- time remaining
      local wx, wy = 124, 16
      screen.level(12)
      local a = -1.5708
      local a1 = -1.5708 + 6.2832 * clamp(frac, 0, 1)
      while a < a1 do
        screen.rect(wx + cos(a) * 3, wy + sin(a) * 3, 1, 1)
        screen.rect(wx + cos(a) * 2, wy + sin(a) * 2, 1, 1)
        a = a + 0.25
      end
      screen.fill()
    end
  end
  -- ◄ selected: the rail has no target — this cell is a recall, not a morph
  if sel == 0 then
    ptext_c(sc.safe and "K2 = THE WAY BACK" or "< FILLS ON RECALL/CHAOS",
      64, 44, 1, 5)
    return
  end
  -- the morph rail: LIVE toward the selected slot, from wherever you are
  if nfilled == 0 then
    ptext_c("EMPTY - K3 CAP", 64, 44, 1, 10)
    return
  end
  if not sc.slots[sel] then
    ptext_c("SLOT " .. sel .. " EMPTY - K3 CAP", 64, 44, 1, 10)
    return
  end
  local live = amt > 0.001 and amt < 0.999
  ptext("LIVE", 4, 43, 1, amt < 0.5 and 11 or 4)
  ptext_r(tostring(sel), 124, 43, 1, amt >= 0.5 and 11 or 4)
  local x0, x1 = 28, 108
  screen.level(3)
  screen.move(x0, 45.5) screen.line(x1, 45.5)
  screen.stroke()
  screen.level(10)
  local hx = x0 + amt * (x1 - x0)
  if amt > 0.001 then
    screen.move(x0, 45.5) screen.line(hx, 45.5)
    screen.stroke()
  end
  screen.level(12)                       -- the origin: where the sweep left
  screen.rect(x0 - 1, 44, 3, 3)
  screen.fill()
  screen.level(15)                       -- the handle, open
  screen.rect(hx - 2, 43, 5, 5)
  screen.fill()
  screen.level(live and 0 or 2)
  screen.rect(hx, 45, 1, 1)
  screen.fill()
end

-- each page draws its body through this dispatch table, selected by name;
-- built ONCE at load, so the redraw stays allocation-free
local BODY = {
  LAYERS = body_LAYERS,
  TAKE = body_TAKE, VOICE = body_VOICE, TAPE = body_TAPE,
  FILTER = body_FILTER, DELAY = body_DELAY, REVERB = body_REVERB, MIX = body_MIX,
  PADS = body_PADS, MOTION = body_MOTION, SCENE = body_SCENE,
  TRACK = body_TRACK, ROUTE = body_ROUTE,
}

local function draw_body()
  local f = BODY[PAGES[C.page]]
  if f then f(C.frame) end
end

-- the purity mark ◇ (doc/redesign.md §4): lit ONLY when the output
-- is the take, verbatim. conservative — it may stay dark when technically
-- pure, but it never lies pure.
local function purity()
  if not C.wave_any then return false end
  if pget("stop_all", 0) == 1 then return false end
  if pget("mode", 5) ~= 5 then return false end             -- PLAY only
  -- track 2 is a second engine source: switched on and audible, the output
  -- is not the take alone
  -- (and tracks 3 and 4; and a send moves sound between tracks even when
  -- the receiving track's own voice is off)
  for n = 2, 4 do
    if track_live(n) then return false end
  end
  if C.ROUTES then
    for _, r in ipairs(C.ROUTES) do
      if pget(r.id, 0) > 0.001 then return false end
    end
  end
  if abs(pget("pitch", 1) - 1) > 0.001 then return false end
  if abs(pget("scan", 1) - 1) > 0.001 then return false end
  -- pan reaches the PLAY voice's Balance2: off-center output is not the
  -- recording, however clean the rest of the path is
  if abs(pget("pan", 0)) > 0.001 then return false end
  if pget("drive", 0) > 0.001 or pget("delay_mix", 0) > 0.001
      or pget("rev_mix", 0) > 0.001 or pget("shimmer", 0) > 0.001
      or pget("clouds_fb", 0) > 0.001 or pget("resample", 0) > 0.001
      or pget("regen", 0) > 0.001
      -- erode belongs with the other buffer writers: the mark would otherwise
      -- claim "verbatim" at exactly the moment the erosion head is grinding
      -- the take away underneath it
      or pget("erode", 0) > 0.001 then return false end
  if pget("freeze", 0) == 1 or pget("pv_freeze", 0) == 1 then return false end
  -- a pad voice sounds on top of the take, and so does the sequencer that
  -- plays them (between its hits too: the voices release with a tail)
  if next(C.pad_held) ~= nil or pget("step_run", 0) == 1 then return false end
  -- a held beat repeat plays a captured slice, not the take
  if C.repeat_live and C.repeat_live() then return false end
  -- a modulator moving a knob: even at a zero crossing it is not the take
  if C.lfo and C.lfo.active() then return false end
  -- the take must be ALL of what you hear. dry_wet blends the live INPUT
  -- against the playback path, so anything short of full wet means the monitor
  -- is mixed in on top of the recording — and at 0 the take is not audible at
  -- all. This tested `dw > 0.001` and so lit at the 0.5 default (half and half)
  -- and at 0 (nothing but the input). The mark says "the recording, verbatim";
  -- it has to mean it, and it is supposed to be the conservative one.
  if pget("dry_wet", 0.5) < 0.999 then return false end
  -- ...and the filter must be out of the way
  if pget("filt_type", 1) ~= 1 or pget("cutoff", 20000) < 19000
      or pget("resonance", 0) > 0.02 then return false end
  -- the tape deck must not be adding its own material
  if C.twave_any and pget("mix", 0.5) > 0.02 then return false end
  -- ...and neither may the layer decks: material present and audibly playing
  -- means the output is not just the take (the same rule, per deck)
  local decks = C.layers
  if decks then
    for i = 1, #decks do
      local d = decks[i]
      if d.any and pget(C.deck_p(d, "play"), 1) == 1
          and pget(C.deck_p(d, "level"), 0.8) > 0.01 then return false end
    end
  end
  return true
end

-- header: TITLE ◇ flags ···· path dots. STOP inverts the title chip;
-- writes (R/T/M/L) carry the ONLY fast blink; holds and runs are steady.
-- The flags, in priority order: the writers (R the take, T the tape, M the
-- motion looper, L a layer deck), the holds (FZ, TF, RP a beat repeat), then
-- the machines that play on their own (SQ the pad sequencer, LF a
-- modulator). A flag that does not fit whole shrinks: a writer to its
-- blinking letter without the dot, the others to a 2px bar. Room is kept for
-- the short forms of the lit flags after it, so a lit state never drops off
-- the header. Built once: draw_header refreshes `on` (and RP's `lvl`), and
-- leaves `x` and `full` for the tests.
local HFLAGS = {
  { ch = "R", write = true }, { ch = "T", write = true },
  { ch = "M", write = true }, { ch = "L", write = true },
  { ch = "FZ", lvl = 10 }, { ch = "TF", lvl = 10 }, { ch = "RP", lvl = 12 },
  { ch = "SQ", lvl = 7 }, { ch = "LF", lvl = 7 },
  -- mangler2: the other tracks that sound: T2, T3, T23 ... T234 ("T" and the
  -- numbers, not bare digits: after a title a digit read as the page name)
  { ch = "T2", lvl = 9 },
}
M.HFLAGS = HFLAGS
local HF = {}
for _, f in ipairs(HFLAGS) do
  f.id = f.ch                                      -- ch can change (RP8)
  HF[f.id] = f
  f.w, f.on, f.x, f.full = 0, false, nil, false   -- w: set in init
end
-- RP carries the division it repeats: RP2 for a half note .. RP32. Built
-- once, indexed like the repeat_div option, widths measured in init.
local RP_CH = { "RP2", "RP4", "RP8", "RP16", "RP32" }
local RP_W = {}
-- the track flag's word per set of sounding tracks (bit 1 = track 2, 2 =
-- track 3, 4 = track 4), built once, widths measured in init
local TR_CH, TR_W = {}, {}
for mask = 1, 7 do
  local w = "T"
  if mask % 2 == 1 then w = w .. "2" end
  if math.floor(mask / 2) % 2 == 1 then w = w .. "3" end
  if mask >= 4 then w = w .. "4" end
  TR_CH[mask] = w
end
-- the width of a flag whole, and short (a writer's letter, or a bar)
local function hflag_w(f) return f.write and f.w + 8 or f.w + 3 end
-- (a bar's pip is 3: the 2px bar and a 1px gap, and a writer's letter keeps
-- a 1px gap too. They were 4 and 2, but mangler2's thirteen page dots and its
-- track flag left the worst case short of the dots.)
local function hflag_pip(f) return f.write and f.w + 1 or 3 end
local function any_layer_rec()
  local decks = C.layers
  if not decks then return false end
  for i = 1, #decks do
    if pget(C.deck_p(decks[i], "rec"), 0) == 1 then return true end
  end
  return false
end
-- draw the lit flags from x, keeping clear of `lim` (the page dots)
local function draw_hflags(x, lim, blink)
  local n = #HFLAGS
  for i = 1, n do
    local f = HFLAGS[i]
    f.x, f.full = nil, false
    if f.on then
      local rest = 0
      for j = i + 1, n do
        if HFLAGS[j].on then rest = rest + hflag_pip(HFLAGS[j]) end
      end
      f.x = x
      f.full = x + hflag_w(f) - 3 + rest <= lim
      if f.write then
        if blink and f.full then
          screen.level(15)
          screen.rect(x, 1, 3, 3)
          screen.fill()
          ptext(f.ch, x + 5, 1, 1, 15)
        elseif blink then
          ptext(f.ch, x, 1, 1, 15)
        end
      elseif f.full then
        ptext(f.ch, x, 1, 1, f.lvl)
      else
        screen.level(f.lvl)
        screen.rect(x, 1, 2, 5)      -- a bar at cap height, not a page dot
        screen.fill()
      end
      x = x + (f.full and hflag_w(f) or hflag_pip(f))
    end
  end
end
-- path dots, top-right. Every page has a fixed slot on one straight row: all
-- dots share rows y=4..5 and a 4px pitch, and no dot ever moves when the page
-- changes. The current page is a brighter, wider bar centred on its own slot,
-- so it stays on the row and clear of its neighbours. The row is RIGHT-ANCHORED
-- whatever the page count (a fixed left origin cropped the last dot once the
-- count reached twelve). Laid out once, in init.
local DOT_PITCH = 4
local DOT_OFF = {}
local function layout_dots()
  for i = 1, #PAGES do DOT_OFF[i] = (i - 1) * DOT_PITCH end
  -- the last dot ends 2px clear of the edge; its bar, 1px wider each way, ends
  -- 1px clear, and at the first slot it stays clear of the header flags
  M.DOT_X0 = 126 - ((DOT_OFF[#PAGES] or 0) + 2)
end
-- the page's name, with its track on VOICE and FILTER while track 2 is
-- selected (mangler2). Fixed strings: the redraw path allocates nothing.
local TITLE_N = {
  VOICE = { "VOICE", "VOICE 2", "VOICE 3", "VOICE 4" },
  FILTER = { "FILTER", "FILTER 2", "FILTER 3", "FILTER 4" },
  TRACK = { "TRACK 2", "TRACK 2", "TRACK 3", "TRACK 4" },
}
local function page_title()
  local name = PAGES[C.page]
  local t = TITLE_N[name]
  if t then
    if name == "TRACK" then return t[C.page_track and C.page_track() or 2] end
    return t[cur_track()]
  end
  return name
end
M.page_title = page_title

local function draw_header()
  local page, frame = C.page, C.frame
  local title = page_title()
  local x
  if pget("stop_all", 0) == 1 then
    screen.level(15)
    screen.rect(0, 0, text_w(title, 1) + 5, 8)
    screen.fill()
    ptext(title, 2, 2, 1, 0)
    x = text_w(title, 1) + 9
  else
    ptext(title, 2, 1, 1, 8)
    x = 2 + text_w(title, 1) + 4
  end
  if purity() then
    screen.level(15)
    screen.rect(x + 2, 0, 1, 1) screen.rect(x + 1, 1, 1, 1)
    screen.rect(x + 3, 1, 1, 1) screen.rect(x, 2, 1, 1)
    screen.rect(x + 4, 2, 1, 1) screen.rect(x + 1, 3, 1, 1)
    screen.rect(x + 3, 3, 1, 1) screen.rect(x + 2, 4, 1, 1)
    screen.fill()
    x = x + 8
  end
  local dx0 = M.DOT_X0
  HF.R.on = pget("rec", 0) == 1
  HF.T.on = pget("tape_rec", 0) == 1
  HF.M.on = pget("motion_rec", 0) == 1
  HF.L.on = any_layer_rec()
  HF.FZ.on = pget("pv_freeze", 0) == 1 or pget("freeze", 0) == 1
  HF.TF.on = pget("tape_freeze", 0) == 1
  -- RP bright while the engine loops, dim while a press waits for its beat
  HF.RP.on = pget("beat_repeat", 0) == 1
  HF.RP.lvl = (C.repeat_live and C.repeat_live()) and 12 or 4
  local rd = clamp(floor(pget("repeat_div", 3) + 0.5), 1, #RP_CH)
  HF.RP.ch, HF.RP.w = RP_CH[rd], RP_W[rd]
  HF.SQ.on = pget("step_run", 0) == 1
  HF.LF.on = C.lfo and C.lfo.active() or false
  local mask = (track_live(2) and 1 or 0) + (track_live(3) and 2 or 0)
    + (track_live(4) and 4 or 0)
  HF.T2.on = mask > 0
  if mask > 0 then HF.T2.ch, HF.T2.w = TR_CH[mask], TR_W[mask] end
  draw_hflags(x, dx0 - 2, (frame % 4) < 2)
  for i = 1, #PAGES do
    local dx = dx0 + DOT_OFF[i]
    if i == page then
      screen.level(15)
      screen.rect(dx - 1, 4, 4, 2)
    else
      screen.level(3)
      screen.rect(dx, 4, 2, 2)
    end
    screen.fill()
  end
end

-- idle dim: after two minutes without a key or encoder touch every level is
-- cut to keep the OLED from burning the static chrome in; the first touch
-- restores full brightness. one closure, made once.
local orig_level, dim_level
-- the page-name pop: E1 arms C.page_flash while stations scroll past, and the
-- destination's name reads BIG and centered for a beat. Eleven pages go by
-- faster than the 1x title reads, and finding the page mid-set should not
-- need squinting. Same framed-box idiom as the footer value swell, so it is
-- legible over any body; transient chrome, gone by itself.
local function draw_page_flash()
  if not (C.page_flash and C.frame < C.page_flash) then return end
  local name = page_title()
  framed2x(name, floor(64 - (text_w(name, 2) + 9) / 2 + 0.5), 23)
end

function M.redraw()
  if orig_level == nil then
    orig_level = screen.level
    dim_level = function(l)
      orig_level(l and l > 0 and max(1, floor(l * 0.4)) or 0)
    end
  end
  screen.level = C.idle_dim and dim_level or orig_level
  screen.clear()
  draw_header()
  draw_body()
  draw_footer()
  draw_page_flash()
  screen.update()
  screen.level = orig_level
end

function M.init(ctx)
  C = ctx
  W = ctx.wav
  pget, clamp, window_bounds = ctx.pget, ctx.clamp, ctx.window_bounds
  FPS, PAGES = ctx.FPS, ctx.PAGES
  amp_in, amp_out = ctx.amp_in, ctx.amp_out
  local F = ctx.font
  ptext, ptext_c, ptext_r, chip, text_w =
    F.ptext, F.ptext_c, F.ptext_r, F.chip, F.text_w
  for _, f in ipairs(HFLAGS) do f.w = text_w(f.ch, 1) end
  for i, ch in ipairs(RP_CH) do RP_W[i] = text_w(ch, 1) end
  for i, ch in ipairs(TR_CH) do TR_W[i] = text_w(ch, 1) end
  layout_dots()
end

return M

end)()

ctx.font = Mfont
ctx.wav = Mwav          -- the wav file layer; mpages paints strips through it
ctx.grid = Mgrid
ctx.motion = Mmotion
ctx.seq = Mseq
ctx.lfo = Mlfo
ctx.osc = Mosc
-- the tape display model lives in mpages; mtape clears it when a pset restores
-- an empty tape, so it needs a way to reach it
ctx.clear_twave = Mpages.clear_twave
-- ...and repaints it from the PSET wav on restore (plus the layer decks'
-- strips, which own their bins and hand them in)
ctx.repaint_twave = Mpages.repaint_twave
ctx.wave_from_file = Mpages.fill_wave_bins
ctx.clear_bins = Mpages.clear_bins     -- a deck erase stops its own repaint
ctx.wav_info = Mwav.wav_info

-- any hand on the instrument counts as presence for the idle dim: keys and
-- encoders here, the grid and MIDI in their own modules
function ctx.touch_input() ctx.last_input = ctx.frame end

-- THE TIMEBASE. These two numbers place everything in the instrument: every
-- window edge, pad slice, waveform bin and PSET bound is a fraction of them.
-- Both are set by the ENGINE (lib/Engine_Mangler2.sc allocates
-- `s.sampleRate * bufSecs`, and norns runs its server at 48k) and lua cannot
-- read either off the server — so they are mirrored ONCE here and shared
-- through ctx. They used to be bare literals in several modules plus the .sc:
-- miss one when the buffer length changes and PSET saves silently truncate the
-- take, or every waveform, window bracket and pad slice draws against the
-- wrong clock with no error anywhere.
ctx.BUF_SECS = 60        -- must match `bufSecs` in lib/Engine_Mangler2.sc
-- How many bytes per sample `write_take` puts on disk. MUST match the format
-- in that command (`int24`, so 3). The export works out how big the file
-- should be from this and waits for it to get there, so a number that is too
-- small calls the file finished while a third of it is still being written.
ctx.TAKE_BYTES = 3       -- must match write_take's format in Engine_Mangler2.sc
ctx.SERVER_SR = 48000    -- norns' scsynth sample rate
local BUF_SECS, SERVER_SR = ctx.BUF_SECS, ctx.SERVER_SR
Mwav.init(ctx)

-- THE tempo read. Guarded (the offscreen sim has no clock) and defaulted once,
-- so every caller agrees about what "the tempo" is.
function ctx.tempo()
  if clock and clock.get_tempo then
    local ok, t = pcall(clock.get_tempo)
    if ok and t and t > 0 then return t end
  end
  return 120
end

-- the EFFECTIVE softcut record source. cut_source is the knob; the layer
-- BOUNCE overrides it: while `layer_wet` is on and any layer is armed, the
-- decks record the processed engine output (WET), so "resample into a layer"
-- is just arming one — no trip to the TAPE page first. the send is global,
-- so the tape records the same thing while a bounce runs; both pages' SRC
-- flags read THIS, never the raw knob, so the override is never hidden.
function ctx.eff_cut_source()
  if pget("layer_wet", 1) == 1 then
    for _, d in ipairs(ctx.layers or {}) do
      if pget(Mdeck.p(d, "rec"), 0) == 1 then return 1 end
    end
  end
  return pget("cut_source", 0)
end

-- ONE writer for the softcut input sends: everything that can change the
-- effective source (the knob, a layer arming/disarming, the layer_wet toggle)
-- funnels through here, so the routing can never disagree with the flags.
function ctx.update_cut_source()
  Mtape.set_source(ctx.eff_cut_source())
end

-- what the softcut decks RECORD right now, for the meters: the ADC tap, the
-- engine output (WET), or the blend. one law for the tape picture (mpages)
-- and the layer decks' pictures (mdeck).
function ctx.cut_rec_amp()
  local cs = ctx.eff_cut_source()
  return max(ctx.amp_in[1], ctx.amp_in[2]) * (1 - cs)
    + max(ctx.amp_out[1], ctx.amp_out[2]) * cs
end

Mtape.init(ctx, Mdeck)   -- the tape borrows the deck mechanics (see mtape)
-- THE deck gain law (eng, tape, master) lives in mtape; the MIX page draws
-- the same numbers update_mix sends, so it reads them from here
ctx.mix_gains = Mtape.gains
ctx.TAPE_LEN = Mtape.TAPE_LEN         -- the tape's own length (not BUF_SECS)
ctx.paint_bins = Mpages.paint_bins    -- decks paint their own pictures
ctx.loop_secs = Mdeck.loop_secs       -- ...and the page prints the same law
ctx.set_pair = Mdeck.set_pair         -- THE way to move a start/end pair
ctx.deck_p = Mdeck.p                  -- a deck's param id (keymap-aware)
Mdeck.init(ctx)
-- TWO more loop decks beside the tape, on softcut voices the script does not
-- otherwise use. Their buffer regions start at 120s, leaving 60-120 clear:
-- the chain forge on `foundry` auditions cells at 70s, and picking around it
-- means the branches can merge without a silent buffer collision.
ctx.layers = {
  Mdeck.new({ id = "lay1", name = "L1", va = 3, vb = 4, from = 120, len = 60 }),
  Mdeck.new({ id = "lay2", name = "L2", va = 5, vb = 6, from = 180, len = 60 }),
}
ctx.deck_phase = Mdeck.on_phase
-- which layer the page and its encoders address
function ctx.layer_sel()
  return ctx.layers[math.floor(pget("layer_sel", 1) + 0.5)] or ctx.layers[1]
end
-- a compound encoder target ("@...") resolves to a REAL param id: the one the
-- footer should print and the dial should point at. Pair-movers report their
-- anchor, the low edge. ONE resolver, because the encoder, the footer value and
-- the footer dial each need the same answer and two of them used to not have it
-- (the layer targets read "--" and drew no pointer).
function ctx.enc_target(id)
  if id == "@win_move" then return "pos_start" end
  if id == "@mo_sel" then
    return pget("mod_focus", 1) > 1.5 and "mod_focus" or "motion_lane"
  end
  if id == "@lay_move" then return Mdeck.p(ctx.layer_sel(), "start") end
  if id == "@lay_level" then return Mdeck.p(ctx.layer_sel(), "level") end
  if id == "@lay_rate" then return Mdeck.p(ctx.layer_sel(), "rate") end
  if id == "@route_amt" then return ctx.route_cur().id end
  return id
end

-- re-send every deck's level: the master, the transport and the global STOP
-- all fold into it, so anything that moves one of those has to come through here
function ctx.layers_relevel()
  for _, d in ipairs(ctx.layers) do Mdeck.update_level(d) end
end

-- where a loop deck's MATERIAL is (Mdeck.extent), for the scene clamp:
-- "tape" or a layer id. nil = no material, which leaves a stored loop exactly
-- as it was.
function ctx.material(key)
  if key == "tape" then
    if not ctx.twave_any then return nil end
    return Mdeck.extent(Mtape.deck)
  end
  for _, d in ipairs(ctx.layers) do
    if d.id == key then
      if not d.any then return nil end
      return Mdeck.extent(d)   -- (two values: an `and ... or` would keep one)
    end
  end
end

-- ---------------------------------------------------------------------------
-- SNAP: put a layer's loop LENGTH on the grid
-- ---------------------------------------------------------------------------
-- Recording a layer gives you exactly the length you played, which is never
-- exactly the length you meant. Two loops of 3.97 and 4.02 seconds drift out
-- of time with each other within a minute. Two that are an exact double, half
-- or three-to-two of each other stay together indefinitely. SNAP is what gets
-- you from the first to the second.
--
-- It rounds the length to match whatever you are most likely playing along
-- with, looking in this order: the other deck if it has anything on it, then
-- the take, then a bar at the current tempo. It only ever moves the END of
-- the loop, because where a loop starts was decided by when you hit record
-- and that is not this code's business to second-guess. It also means you can
-- always undo it by hand.
local SNAP_RATIOS = {
  { 1 / 8, "1/8" }, { 1 / 6, "1/6" }, { 1 / 4, "1/4" }, { 1 / 3, "1/3" },
  { 1 / 2, "1/2" }, { 2 / 3, "2/3" }, { 3 / 4, "3/4" }, { 1, "1" },
  { 4 / 3, "4/3" }, { 3 / 2, "3/2" }, { 2, "2" }, { 3, "3" },
  { 4, "4" }, { 6, "6" }, { 8, "8" },
}
-- how close a hand-played length has to be for the automatic snap to take it.
-- 6% is the slop of someone trying to land on the beat; anything further out
-- is a length you chose, and it is left exactly as you played it.
local SNAP_TOL = math.log(1.06)

-- the musical ratio of `ref` nearest to `cur`, compared in LOG space so 1/2
-- and 2 are equally near, the way an ear hears them (a linear nearest would
-- pull everything toward the top). returns the ratio, its label, the error.
local function nearest_ratio(cur, ref)
  local best, label, err = 1, "1", math.huge
  for _, r in ipairs(SNAP_RATIOS) do
    local e = math.abs(math.log(cur / (ref * r[1])))
    if e < err then err, best, label = e, r[1], r[2] end
  end
  return best, label, err
end

-- a gesture loop's length on the clock: the nearest musical length to a bar
-- when what was played is already within the snap tolerance, else nil (a
-- length you clearly chose stays exactly as played). the motion looper asks
-- this when a first pass closes, the way the layers snap theirs.
function ctx.clock_length(secs)
  local bar = 240 / ctx.tempo()
  local best, _, err = nearest_ratio(secs, bar)
  if err > SNAP_TOL then return nil end
  return bar * best
end

-- This always hands back a real length. A deck whose loop has been squashed
-- down to nothing still reads as a tenth of a second, so it is skipped here
-- instead of being passed on for SNAP to reject; the take is checked the same
-- way; and four beats is 0.8 seconds even at the fastest tempo the clock
-- allows. Because of that, layer_snap needs no "there is no reference" case.
-- A key that fires, changes nothing and says nothing is the one thing this
-- page must never do.
local function snap_reference(d)
  for _, o in ipairs(ctx.layers) do
    -- ...and not one that is still being recorded. While a deck records its
    -- first pass its loop is held open at the full 60 seconds, and it counts
    -- as "has audio" the moment it hears anything, so it would offer 60
    -- seconds as the length to match. Record both layers at once and stop one
    -- of them: without this, it snapped to an eighth of 60 seconds, which is
    -- a number off the buffer and nothing to do with the music.
    if o ~= d and o.any and not o.arm_phase and Mdeck.loop_secs(o) > 0.1 then
      return Mdeck.loop_secs(o), o.name
    end
  end
  local _, _, span = window_bounds()
  if ctx.wave_any and span * BUF_SECS > 0.1 then
    return span * BUF_SECS, "TAKE"
  end
  return 240 / ctx.tempo(), "BAR"            -- four beats of the clock
end

-- One short line on the LAYERS page, and the full story printed to the log.
-- A snap that lands on the length you already had changes nothing you can
-- see, and a page that cannot say so looks exactly like a dead key. The
-- screen gets the short form because a line has to fit in 124 pixels.
--
-- The scene page has its own version of this (mscenes' `say`). Both hold the
-- same two things, the text and the frame it was set on, so merging them into
-- one shared helper later is straightforward. Their LOOK stays separate on
-- purpose: the scene page draws a small inverted box, which suits "SAVED 2"
-- but would be a 111-pixel slab for a sentence like the ones here.
local function layer_say(msg, detail)
  ctx.lay_msg, ctx.lay_msg_at = msg, ctx.frame or 0
  print("mangler: " .. (detail or msg))
end
-- the same for TAKE: what K3's SNAP and UNDO just did, on its top row
local function take_say(msg, detail)
  ctx.take_msg, ctx.take_msg_at = msg, ctx.frame or 0
  print("mangler: " .. (detail or msg))
end
ctx.take_say = take_say

-- tol = nil forces the snap; tol = a log-ratio only takes it when the length
-- was already that close (the automatic pass at the end of a record).
function ctx.layer_snap(d, tol)
  d = d or ctx.layer_sel()
  local ref, from = snap_reference(d)
  local cur = Mdeck.loop_secs(d)
  local best, label, err = nearest_ratio(cur, ref)
  if tol and err > tol then return end
  -- Measure from the LOWER of the two edges, not from "start". The loop
  -- points can legally be the other way round, and everything else that reads
  -- them sorts them first. Trusting "start" on a back-to-front loop moved it
  -- to a completely different stretch of the deck, while the message on
  -- screen said nothing had changed.
  local lo = math.min(clamp(pget(Mdeck.p(d, "start"), 0), 0, 1),
    clamp(pget(Mdeck.p(d, "end"), 1), 0, 1))
  local want = ref * best
  local len, room = want, (1 - lo) * d.len
  -- keep it inside the region by halving, because half of a musical length is
  -- still one. If not even that fits, REFUSE: manufacturing a 100ms loop and
  -- labelling it a ratio is worse than saying no, and it puts a grid in the
  -- message that the loop is not on.
  while len > room and len / 2 >= 0.1 do len = len / 2 end
  if len > room then
    layer_say(d.name .. " NO ROOM TO SNAP",
      string.format("%s SNAP refused: %.2fs left in the region, and the nearest"
        .. " %s x %s is %.2fs. Move the loop start back first.",
        d.name, room, label, from, want))
    return
  end
  Mdeck.set_loop(d, lo, clamp(lo + len / d.len, 0, 1))
  -- report what LANDED, not what was asked for. The region clamp and softcut's
  -- own 100ms floor can both move it, and this message is the only proof the
  -- key did anything, so it is the last thing that may guess.
  local got = Mdeck.loop_secs(d)
  local on = math.abs(got - want) < 0.005 and (label .. " x " .. from)
    or ("FIT " .. from)
  if math.abs(got - cur) < 0.005 then
    -- The loop did not move, so the playhead must not either. Sending it back
    -- to the start would restart the phrase mid-performance under a message
    -- saying nothing changed, and two decks only keep their timing against
    -- each other while both heads keep running. It is why MUTE lowers a
    -- deck's volume instead of stopping it.
    layer_say(string.format("%s ON GRID %s", d.name, on),
      string.format("%s SNAP: already %s (%.3fs)", d.name, on, cur))
  else
    Mdeck.jump(d, lo)
    layer_say(string.format("%s %.2f>%.2fS %s", d.name, cur, got, on),
      string.format("%s SNAP: %.3fs -> %.3fs (%s; %s = %.3fs)",
        d.name, cur, got, on, from, ref))
  end
end

-- the automatic pass, called by the loop-pedal close in lib/mdeck.lua
function ctx.layer_quantize(d) ctx.layer_snap(d, SNAP_TOL) end
Minput.init(ctx)
Mgrid.init(ctx)
Mmotion.init(ctx)
Mseq.init(ctx)
Mlfo.init(ctx)
Mout.init(ctx)
Mosc.init(ctx)
Mscenes.init(ctx)   -- sets ctx.scene (the module; its bank is ctx.scene.slots)
Mpages.init(ctx)

-- ============================================================================
-- keys: the punch law
-- ============================================================================
-- ONE physical rule for every key:
--   press = engage NOW · release within TAP_FRAMES = it latches ·
--   held past TAP_FRAMES = it was a punch, release disengages ·
--   already latched = any press turns it off.
-- defs come in two shapes:
--   { label, act }                 -- tap-cycle: fires on PRESS, no punch
--   { label, pon, poff, lit }      -- punchable; lit() feeds the footer
--   (gate = true                   -- always momentary, e.g. the PADS pad)
-- K1+K2 = STOP and K1+K3 = DRY (tap) / ERASE (1s arc) are GLOBAL — no page
-- claims them, so the rescue reflexes are unconditional muscle memory.

local TAP_FRAMES = 5     -- <=4 frames (~300ms at 15fps) reads as a tap
local ERASE_FRAMES = 15  -- K1+K3 held ~1s (the drawn arc) erases material

-- per-key press bookkeeping for the punch law: the def is resolved at the
-- PRESS and the release routes back to it, so an alt released mid-hold can
-- never hand the release to the wrong action (the grid learned this the hard way)
local key_state = { [2] = {}, [3] = {} }

-- punchable binary param: the common case
local function pk(label, id)
  return {
    label = label,
    lit = function() return pget(id, 0) > 0 end,
    pon = function() params:set(id, 1) end,
    poff = function() params:set(id, 0) end,
  }
end

-- throw: engage() applies a gesture and returns {id=prior} to restore on
-- disengage. hold = ride it and come back, tap = latch, tap again = back.
local throw_mem = {}

-- a throw's snapshot is only good until something ELSE moves the instrument.
-- A scene recall, a morph, a chaos throw or DRY installs values wholesale;
-- un-latching afterwards would write a snapshot taken BEFORE all that straight
-- over the top of it — silently undoing the recall. Drop the snapshots
-- instead. The pill goes dark, which is the honest signal: there is no longer
-- a "back" to come back to.
function ctx.throws_forget()
  for k in pairs(throw_mem) do throw_mem[k] = nil end
end

local function throw_restore(label)
  local mem = throw_mem[label]
  if not mem then return end
  throw_mem[label] = nil
  for id, v in pairs(mem) do params:set(id, v) end
end

-- a throw: `ids` are the params it owns, `apply` sets the new values, and the
-- snapshot to restore on release is built FROM ids — so what gets put back can
-- never drift from what gets set. Hold = ride it and come back, tap = latch,
-- tap again = back.
--
-- Engaging first un-latches any OTHER throw holding one of the same params,
-- restoring it. Two throws over one param used to STACK: the second cached
-- what the first had already displaced, so releasing them out of order left
-- the param at a value nobody chose under a lit pill. MIX's ENG/TAPE carried a
-- hand-written pair for exactly this and EROSION's HEAL/SCAR did not; keying
-- the conflict on the PARAMS makes it automatic for every throw, present and
-- future.
-- `key` (optional) names the snapshot when two throws share a word (OPEN on
-- either track); it defaults to the label.
local function throw(label, ids, apply, key)
  key = key or label
  return {
    label = label,
    lit = function() return throw_mem[key] ~= nil end,
    pon = function()
      for other, mem in pairs(throw_mem) do
        if other ~= key then
          for k = 1, #ids do
            if mem[ids[k]] ~= nil then throw_restore(other); break end
          end
        end
      end
      local mem = {}
      for k = 1, #ids do mem[ids[k]] = params:get(ids[k]) end
      throw_mem[key] = mem
      apply()
    end,
    poff = function() throw_restore(key) end,
  }
end

-- pulse a momentary param (the footswitch-shaped SCENE binaries: their
-- actions fire on the rising edge, so 1-then-0 is one clean press)
local function pulse(id)
  params:set(id, 1)
  params:set(id, 0)
end
-- the grid drives the same momentary params (read lazily at press time, so
-- defining it after the ctx wiring above is safe)
ctx.pulse = pulse

-- "open" cutoff for the current filter type — the ONE definition of what an
-- open filter means, shared by FILTER's OPEN throw and ctx.fx_dry
local function filter_open_cutoff(ft)
  return ft == 2 and 20 or (ft == 3 and 1000 or 20000)
end

-- TAKE K3: window full <-> back where you had it (a round trip, so a
-- fat-fingered snap is always recoverable)
local snap_mem

-- the window bounds SNAP remembers are only meaningful for the material they
-- were taken from. New audio in the buffer makes them a pointer into something
-- that no longer exists — a SNAP after CLR used to restore the erased take's
-- bounds — so whoever replaces the buffer forgets them.
function ctx.snap_forget() snap_mem = nil end

local function snap_window()
  local lo, hi = pget("pos_start", 0), pget("pos_end", 1)
  if hi < lo then lo, hi = hi, lo end
  if hi - lo > 0.98 then
    if snap_mem then
      params:set("pos_start", snap_mem[1])
      params:set("pos_end", snap_mem[2])
      take_say("SNAP - WINDOW BACK")
    else
      -- full window, nothing remembered — the state on every fresh load, where
      -- this key used to do nothing at all and say nothing about it. Snap to
      -- the TAKE instead: the same "window = what you recorded" law the
      -- rec-stop applies, which is the only useful meaning left here.
      local tl = ctx.take_len or 0
      if ctx.wave_any and tl > 0.001 and tl < 0.98 then
        snap_mem = { lo, hi }
        params:set("pos_start", 0)
        params:set("pos_end", tl)
        take_say("SNAP - WINDOW ON THE TAKE")
      else
        take_say("SNAP - ALREADY WHOLE",
          "SNAP — the window is already the whole buffer")
      end
    end
  else
    snap_mem = { lo, hi }
    params:set("pos_start", 0)
    params:set("pos_end", 1)
    take_say("SNAP - WHOLE BUFFER")
  end
end

-- ---- the tracks (mangler2) ------------------------------------------------
-- Four engine tracks. VOICE and FILTER address one at a time: `track_sel`
-- picks it, and a HOLD of K3 on either page steps it 1 > 2 > 3 > 4 > 1 (the
-- tap keeps MODE / TYPE, as TAKE's K3 keeps SNAP under its UNDO hold). On
-- track n the same knobs and keys reach the `t<n>_` params. What only track 1
-- has (the erosion) is out of reach there, and what all share (drive,
-- dry/wet) stays the same param. The TRACK page plays tracks 2 to 4 directly.
local NTRACKS = 4
local TRACK_PAGES = { VOICE = true, FILTER = true }
local function tsel() return clamp(math.floor(pget("track_sel", 1) + 0.5), 1, NTRACKS) end
local function track2() return tsel() > 1 end   -- any track but track 1
-- TID[n][id] = "t<n>_<id>", each string built once and cached: the redraw
-- path reads these every frame and must not allocate
local TID = {}
for n = 2, NTRACKS do
  TID[n] = setmetatable({}, { __index = function(t, id)
    local v = "t" .. n .. "_" .. id
    t[id] = v
    return v
  end })
end
-- track n's id for a track 1 id: itself on track 1, or when track n has no
-- such param
local function tid_n(n, id)
  if id and n > 1 then
    local t = TID[n][id]
    if params.lookup[t] then return t end
  end
  return id
end
local function tid(id) return tid_n(tsel(), id) end
ctx.tid, ctx.tid_n, ctx.tsel = tid, tid_n, tsel
-- the TRACK page's track: the selected one, or track 2 while track 1 is
-- selected (the page plays the OTHER tracks)
local function page_track() local n = tsel(); return n > 1 and n or 2 end
ctx.page_track = page_track
local function flash_page()
  -- the proof it worked: the page name pops, now with its track
  ctx.page_flash = ctx.frame + math.floor(FPS * 0.7)
end
local function switch_track()
  params:set("track_sel", tsel() % NTRACKS + 1)
  flash_page()
  print("mangler: VOICE and FILTER now on track " .. tsel())
end
local function next_extra()
  local n = page_track()
  params:set("track_sel", n < NTRACKS and n + 1 or 2)
  flash_page()
  print("mangler: TRACK now on track " .. tsel())
end
-- MODE cycles PLAY->GRAIN->WARP->PV, skipping OFF (a silence pothole
-- mid-set; stopping is STOP's job — OFF stays reachable in PARAMS). Tracks 2
-- to 4 start OFF, so their first tap lands on PLAY.
local function cycle_mode(id)
  local m = pget(id, 5)
  params:set(id, m >= 5 and 2 or (m < 2 and 5 or m + 1))
end
local function cycle_type(id) params:set(id, (pget(id, 1) % 3) + 1) end
-- per track: VOICE/FILTER keys on track n, the TRACK page's K2 (ON) and K3.
-- ON: a tap latches, a hold plays the track only while held (the punch law
-- of every key). Off remembers the mode, so on brings back the voice you
-- had; the first on is PLAY.
local T_KEYS, T_ON, T_K3 = {}, {}, {}
local last_mode = {}
for n = 2, NTRACKS do
  local pre = "t" .. n .. "_"
  local nxt = "TRK " .. (n % NTRACKS + 1)
  T_KEYS[n] = {
    VOICE = {
      k2 = pk("FRZ", pre .. "pv_freeze"),
      k3 = { label = "MODE", tap = function() cycle_mode(pre .. "mode") end,
        hold = switch_track, hold_label = nxt },
    },
    FILTER = {
      k2 = throw("OPEN", { pre .. "cutoff", pre .. "resonance" }, function()
        params:set(pre .. "cutoff", filter_open_cutoff(pget(pre .. "filt_type", 1)))
        params:set(pre .. "resonance", 0)
      end, "OPEN" .. n),
      k3 = { label = "TYPE", tap = function() cycle_type(pre .. "filt_type") end,
        hold = switch_track, hold_label = nxt },
    },
  }
  last_mode[n] = 5
  T_ON[n] = {
    label = "ON",
    lit = function() return pget(pre .. "mode", 1) ~= 1 end,
    pon = function() params:set(pre .. "mode", last_mode[n]) end,
    poff = function()
      local m = pget(pre .. "mode", 1)
      if m ~= 1 then last_mode[n] = m end
      params:set(pre .. "mode", 1)
    end,
  }
  T_K3[n] = { label = "MODE", tap = function() cycle_mode(pre .. "mode") end,
    hold = next_extra, hold_label = "TRK " .. (n < NTRACKS and n + 1 or 2) }
end

-- ---- the routing (mangler2) -------------------------------------------------
-- The S-4's sends: each track's filtered output can feed any other track's
-- filter, `send_<from>_<to>`, twelve in all. ROUTES walks them in the order
-- the ROUTE page's grid reads (row = from, column = to). `route_sel` is the
-- cell under the cursor.
local ROUTES = {}
for from = 1, NTRACKS do
  for to = 1, NTRACKS do
    if from ~= to then
      ROUTES[#ROUTES + 1] = { from = from, to = to, id = "send_" .. from .. "_" .. to }
    end
  end
end
ctx.ROUTES = ROUTES
local function route_cur() return ROUTES[clamp(math.floor(pget("route_sel", 1) + 0.5), 1, #ROUTES)] end
ctx.route_cur = route_cur
-- K2 PATCH: the selected send between off and its last level (half, the
-- first time). K3 tapped jumps to the next track's row; held to the arc it
-- clears every send.
local patch_mem = {}
local ROUTE_PATCH = {
  label = "PATCH",
  act = function()
    local r = route_cur()
    local v = pget(r.id, 0)
    if v > 0.001 then
      patch_mem[r.id] = v
      params:set(r.id, 0)
    else
      params:set(r.id, patch_mem[r.id] or 0.5)
    end
  end,
}
local function route_clear()
  for _, r in ipairs(ROUTES) do params:set(r.id, 0) end
  print("mangler: every send cleared")
end
local ROUTE_K3 = { label = "ROW",
  tap = function()
    local k = clamp(math.floor(pget("route_sel", 1) + 0.5), 1, #ROUTES)
    local row = math.floor((k - 1) / (NTRACKS - 1))
    params:set("route_sel", ((row + 1) % NTRACKS) * (NTRACKS - 1) + 1)
  end,
  hold = route_clear, hold_label = "CLEAR" }

-- page key defs (+ each page's `erase`: what the K1+K3 arc wipes)
local KEYS = {
  TAKE = {
    k2 = pk("REC", "rec"),
    -- tap = SNAP, hold to the arc = UNDO (the eraser's gesture, without K1).
    -- SNAP moved from the press to the release, so a hold never snaps first
    k3 = { label = "SNAP", tap = snap_window,
      hold = function() ctx.take_undo() end, hold_label = "UNDO" },
    erase = function() pulse("clear_rec") end,   -- audio: NOT undoable
  },
  VOICE = {
    k2 = pk("FRZ", "pv_freeze"),
    -- tap = MODE (cycle_mode), hold to the arc = the track switch
    k3 = { label = "MODE", tap = function() cycle_mode("mode") end,
      hold = switch_track, hold_label = "TRK 2" },
  },
  -- (the TRACK page's keys follow its track: key_def picks T_ON / T_K3;
  -- these are track 2's, the shape doc/controls.md documents)
  TRACK = { k2 = T_ON[2], k3 = T_K3[2] },
  ROUTE = { k2 = ROUTE_PATCH, k3 = ROUTE_K3 },
  TAPE = {
    k2 = pk("REC", "tape_rec"),
    k3 = pk("REV", "tape_reverse"),
    erase = function()
      -- disarm first, like the LAYERS erase: wiping while armed just
      -- re-records the input into the freshly cleared loop
      params:set("tape_rec", 0)
      Mtape.clear_buffer()
      ctx.clear_twave()
      params:set("tape_freeze", 0)
      params:set("loop_start", 0)
      params:set("loop_end", 1)
    end,
  },
  FILTER = {
    -- OPEN as a throw: hold = a sweep that returns by itself, tap = park
    -- it open, tap again = back to the carved tone
    k2 = throw("OPEN", { "cutoff", "resonance" }, function()
      params:set("cutoff", filter_open_cutoff(pget("filt_type", 1)))
      params:set("resonance", 0)
    end),
    k3 = { label = "TYPE", tap = function() cycle_type("filt_type") end,
      hold = switch_track, hold_label = "TRK 2" },
  },
  DELAY = {
    -- INF pins the feedback near max (a dub hold); KILL cuts the echo send.
    -- both round-trip: tap latches, tap again restores the prior value.
    k2 = throw("INF", { "delay_fb" }, function()   -- dub grab: pin the loop
      params:set("delay_fb", 1)   -- knob max -> ~0.98 fb, a self-sustaining hold
    end),
    k3 = throw("KILL", { "delay_mix" }, function()  -- cut the echo send
      params:set("delay_mix", 0)
    end),
  },
  REVERB = {
    -- WASH swells the tail to a near-infinite hall; BLOOM surges shimmer.
    k2 = throw("WASH", { "rev_decay" }, function()  -- freeze the space
      params:set("rev_decay", 30)
    end),
    -- BLOOM always INCREASES: it read a `ctx.shimmer_mem` that nothing in the
    -- codebase ever wrote, so it was permanently the 0.6 fallback — and pulling
    -- shimmer DOWN whenever it already sat above that, which is the opposite of
    -- a surge. Double it, floor at 0.6, ceiling at full.
    k3 = throw("BLOOM", { "shimmer" }, function() -- shimmer surge
      local now = pget("shimmer", 0)
      params:set("shimmer", math.min(1, math.max(0.6, now * 2)))
    end),
  },
  MIX = {
    -- ENG and TAPE are two throws of the same `mix`, so engaging one restores
    -- and un-latches the other first — both pills can never light at once and
    -- the crossfader always returns to its true home. That used to be written
    -- out here by hand; the throw engine now does it for any shared param.
    k2 = throw("ENG", { "mix" }, function()   -- crossfade stab to the engine
      params:set("mix", 0)
    end),
    k3 = throw("TAPE", { "mix" }, function()
      params:set("mix", 1)
    end),
  },
  PADS = {
    -- a pad under the punch law: hold = gate the slice, tap = fire it
    -- short. gate: the release ALWAYS closes the voice — a latched voice
    -- is a drone, and the drone already exists.
    k2 = { label = "PAD", gate = true,
      lit = function() return ctx.pad_held[8] ~= nil end,
      pon = function() ctx.pad_trigger(8, pget("seq_slice", 0), 1) end,
      poff = function() ctx.pad_trigger(8, 0, 0) end },
    -- notes -> pads (poly) or the drone. PADS has no material of its own (the
    -- take is TAKE's), so no page erase — K1+K3 stays the global DRY here.
    k3 = pk("ROUTE", "pad_input"),
  },
  MOTION = {
    k2 = pk("REC", "motion_rec"),
    k3 = pk("PLAY", "motion_play"),
    -- the selected row's: a lane is cleared, a modulator let go (OFF, depth 0)
    erase = function()
      local f = math.floor(pget("mod_focus", 1) + 0.5)
      if f > 1 then
        params:set("lfo" .. (f - 1) .. "_depth", 0)
        params:set("lfo" .. (f - 1) .. "_target", 1)
      else
        ctx.motion.clear_lane()
      end
    end,
  },
  LAYERS = {
    -- K2/K3 are per deck (LAYER_KEYS below): key_def picks the selected
    -- deck's pair at the PRESS, so the release lands on the same deck. K1+K3
    -- erases THIS layer only; the tape and the other layer are untouched
    -- (mdeck clears by region). The erase fires while K1 is held, when E2 is
    -- the rate knob rather than the layer selector, so it cannot retarget.
    erase = function()
      local d = ctx.layer_sel()
      -- Cancel any recording in progress BEFORE stopping it. Otherwise the
      -- deck sets a loop around audio we are one line away from erasing, and
      -- announces it on screen.
      Mdeck.abort_loop(d)
      params:set(Mdeck.p(d, "rec"), 0)
      Mdeck.clear(d)
      params:set(Mdeck.p(d, "start"), 0)
      params:set(Mdeck.p(d, "end"), 1)
      -- forget the loaded file too, like clear_recording forgets sample_file:
      -- a PSET saved after this erase must not resurrect the very file you
      -- wiped ("" is a no-op through layer_load's own guard)
      local fid = Mdeck.p(d, "file")
      if params.lookup[fid] and params:get(fid) ~= "" then
        params:set(fid, "")
      end
    end,
  },
  SCENE = {
    -- RCL under the punch law — hold = PEEK (borrow the scene via the
    -- morph engine; release sweeps you home), tap = COMMIT. on the ◄ cell
    -- (slot 0) a tap is the way back (safe restore). CAP captures into the
    -- selected slot — into ◄ it marks the way-back state by hand.
    k2 = { label = "RCL",
      lit = function() return ctx.peek_on == true end,
      pon = function()
        -- the slot is resolved at the PRESS: a running orbit re-aims the
        -- selector every leg, and the tap must recall what was under the
        -- finger, not what the wander picked a moment later
        local sel = math.floor(pget("scene_slot", 1) + 0.5)
        ctx.rcl_slot = sel
        if sel >= 1 and ctx.scene.slots[sel] then
          ctx.peek_on, ctx.peek_back, ctx.peek_at = true, false, ctx.frame
        end
      end,
      tap = function()
        ctx.peek_on = false
        if ctx.rcl_slot then params:set("scene_slot", ctx.rcl_slot) end
        -- the landing zeroes the morph amount itself (mscenes' land), and
        -- only once the scene has actually landed, so a BEAT/BAR queue
        -- does not bounce scene -> LIVE -> scene around the sync point
        pulse("scene_recall")
      end,
      poff = function()   -- punch release: it was borrowed — sweep home
        -- only when the peek actually engaged: pon declines on an empty slot
        -- and on ◄, and ramping "home" then would drag a morph someone parked
        -- (a latched sweep, a MIDI fader) down to zero for nothing
        if ctx.peek_on then
          ctx.peek_on = false
          ctx.peek_back = true
        end
      end },
    k3 = { label = "CAP", act = function() pulse("scene_capture") end },
    -- the slot selected when K1+K3 went DOWN, not when the arc lands a second
    -- later: a running orbit re-aims the selector every leg, and clearing the
    -- slot it wandered to would destroy a scene you did not pick
    erase = function() Mscenes.clear(ctx.k13_slot) end,
  },
}

-- LAYERS K2/K3, one fixed pair PER DECK. A shared def that looked the deck up
-- again at release sent the release to whichever deck was selected by then:
-- hold REC on L1, turn E2 to L2, let go, and L1 kept recording with no finger
-- on any key.
local function layer_keys(n)
  local d = ctx.layers[n]
  local play = Mdeck.p(d, "play")
  return {
    -- REC under the punch law: hold to record while you lean on it, tap to latch
    k2 = pk("REC", Mdeck.p(d, "rec")),
    -- MUTE rather than a transport stop: the head keeps rolling so the decks
    -- hold their drift against each other (see lib/mdeck.lua). Lit = muted.
    k3 = { label = "MUTE",
      lit = function() return pget(play, 1) == 0 end,
      pon = function() params:set(play, 0) end,
      poff = function() params:set(play, 1) end },
  }
end
local LAYER_KEYS = {}
for n = 1, #ctx.layers do LAYER_KEYS[n] = layer_keys(n) end

-- the global alt pair — identical on every page
local ALT_STOP = pk("STOP", "stop_all")
local ALT_DRY = { label = "DRY", dryerase = true }

-- HEAL parks the erosion decay (round-trips like every throw). It snapshots
-- regen as well as erode: raising erode ZEROES regen through the interlock,
-- so a throw that remembered only erode handed back an instrument with the
-- performer's regen setting silently gone. It lives on VOICE's K2 in PLAY
-- mode only — the one mode where erosion runs (FRZ, which it displaces, is
-- inert in PLAY: pv_freeze holds the PV/clouds voices). SCAR, the old
-- throw-to-full, retired to the erode knob itself (VOICE K1+E2 in PLAY).
local VOICE_HEAL = throw("HEAL", { "erode", "regen" }, function()
  params:set("erode", 0)
end)

local function key_def(n)
  if ctx.alt then
    return n == 2 and ALT_STOP or ALT_DRY
  end
  local page = PAGES[ctx.page]
  if TRACK_PAGES[page] and track2() then
    local tk = T_KEYS[tsel()][page]
    return n == 2 and tk.k2 or tk.k3
  end
  if page == "TRACK" then
    local t = page_track()
    return n == 2 and T_ON[t] or T_K3[t]
  end
  -- VOICE K2 is mode-contextual, like its encoders: PLAY = HEAL, else FRZ
  if page == "VOICE" and n == 2 and pget("mode", 5) == 5 then
    return VOICE_HEAL
  end
  if page == "LAYERS" then
    local lk = LAYER_KEYS[math.floor(pget("layer_sel", 1) + 0.5)] or LAYER_KEYS[1]
    return n == 2 and lk.k2 or lk.k3
  end
  local defs = KEYS[page]
  if not defs then return nil end
  return n == 2 and defs.k2 or defs.k3
end

-- what the eraser would wipe on the current page (nil = nothing here; the
-- footer only draws the arc when there is something to erase)
local function page_erase()
  local defs = KEYS[PAGES[ctx.page]]
  return defs and defs.erase or nil
end

-- ============================================================================
-- encoders
-- ============================================================================
-- which params each page's encoders address: { e2, e2_alt, e3, e3_alt }.
-- targets starting with "@" are compound gestures resolved in enc().
local ENC_MAP = {
  TAKE   = { "pos_start", "@win_move", "pos_end", "pos_jitter" },
  VOICE  = { "scan", "scan", "pitch", "pitch" }, -- face is mode-contextual
  -- mangler2: the TRACK page (its track's window, K1 its level and pitch;
  -- enc_param maps them onto the page's track) and the ROUTE grid
  TRACK = { "t2_pos_start", "t2_level", "t2_pos_end", "t2_pitch" },
  ROUTE = { "route_sel", nil, "@route_amt", nil },
  TAPE   = { "tape_rate", "tape_pre", "loop_end", "cut_source" },
  FILTER = { "cutoff", "drive", "resonance", "dry_wet" },
  DELAY  = { "delay_mix", "delay_time", "delay_fb", "delay_sync" },
  REVERB = { "rev_mix", "rev_size", "rev_decay", "rev_damp" },
  MIX    = { "mix", "input_level", "out_level", "monitor_level" },
  PADS   = { "seq_slice", "pad_voice", "pad_pitch", "voice_rel" },
  -- E2 walks the lanes and then the two modulator rows (@mo_sel); with a
  -- modulator row selected the other three are its own (MOTION_LFO below)
  MOTION = { "@mo_sel", "motion_len", "motion_depth", nil },
  -- the alt pair is the ORBIT: drift time + how far each leg reaches. the
  -- recall quantize (scene_recall_mode) moved to PARAMS — a set-and-forget
  -- config knob lost its encoder to a performance one.
  SCENE  = { "scene_slot", "orbit_rate", "scene_morph_amt", "orbit_reach" },
  LAYERS = { "layer_sel", "@lay_rate", "@lay_level", "@lay_move" },
}

-- VOICE face pair per engine mode (the S-4 move: the encoders always
-- control what you're hearing). mode options: OFF GRAIN WARP PV PLAY.
local VOICE_FACE = {
  { "scan", "pitch" },            -- OFF (the universal pair still)
  { "size", "density" },          -- GRAIN
  { "warp_window", "warp_rand" }, -- WARP
  { "scan", "pitch" },            -- PV
  { "scan", "pitch" },            -- PLAY
}

-- MOTION with a modulator row selected (mod_focus 2 or 3): E3 its depth,
-- K1+E2 its period, K1+E3 its target. E2 stays the row selector.
local MOTION_LFO = {
  { "@mo_sel", "lfo1_period", "lfo1_depth", "lfo1_target" },
  { "@mo_sel", "lfo2_period", "lfo2_depth", "lfo2_target" },
}

-- the param id addressed by encoder n (2 or 3), page + alt + mode aware
local function enc_param(n)
  local page = PAGES[ctx.page]
  if page == "MOTION" then
    local f = math.floor(pget("mod_focus", 1) + 0.5)
    local m = MOTION_LFO[f - 1]
    if m then
      if n == 2 then return ctx.alt and m[2] or m[1] end
      if n == 3 then return ctx.alt and m[4] or m[3] end
      return nil
    end
  end
  if page == "VOICE" and not ctx.alt then
    local f = VOICE_FACE[clamp(pget(tid("mode"), 5), 1, 5)]
    return tid(n == 2 and f[1] or f[2])
  end
  -- VOICE's alt pair is mode-contextual too: in PLAY mode the face already IS
  -- scan/pitch, so the alt copy was redundant there — it now carries the
  -- EROSION controls, which only ever work in PLAY mode (the engine runs its
  -- erosion head in PLAY alone). every other mode keeps alt scan/pitch, so
  -- pitch stays reachable under a GRAIN or WARP face.
  -- (track 2 has no erosion: its alt pair stays scan/pitch, below)
  if page == "VOICE" and ctx.alt and pget("mode", 5) == 5 and not track2() then
    return n == 2 and "erode" or "wear"
  end
  if page == "TRACK" then
    local t = page_track()
    if n == 2 then return tid_n(t, ctx.alt and "level" or "pos_start") end
    if n == 3 then return tid_n(t, ctx.alt and "pitch" or "pos_end") end
    return nil
  end
  local m = ENC_MAP[page]
  if not m then return nil end
  -- explicit, NOT `alt and m[2] or m[1]`: a nil alt slot (MOTION/SCENE) must be
  -- a genuine no-op, not fall through to the base param and edit it while K1 is
  -- held (which could wipe the wrong MOTION lane and leak a value in the footer)
  local id
  if n == 2 then
    if ctx.alt then id = m[2] else id = m[1] end
  elseif n == 3 then
    if ctx.alt then id = m[4] else id = m[3] end
  end
  if id and TRACK_PAGES[page] then return tid(id) end
  return id
end

-- compound encoder gesture: slide a lo/hi pair together, width preserved,
-- with the same span-scaled fine step the edges get. The two writes go
-- through Mdeck.set_pair, the one widening-edge-first writer.
local function move_pair(lo_id, hi_id, d)
  local lo, hi = pget(lo_id, 0), pget(hi_id, 1)
  if hi < lo then lo, hi = hi, lo end
  local p = params:lookup_param(lo_id)
  local q = (p and p.controlspec and p.controlspec.quantum) or 0.01
  local width = hi - lo
  local nlo = clamp(lo + fine_delta(lo_id, d) * q, 0, 1 - width)
  Mdeck.set_pair(lo_id, hi_id, nlo, nlo + width)
end

-- K1+K3 held to the arc: the erase fires AT the threshold (not on the
-- release), from the redraw clock, so the arc is a promise that lands.
-- the same tick animates the scene PEEK ramp: holding RCL drives the morph
-- amount toward the slot (~4 frames in), releasing sweeps it home — all
-- through the scene_morph_amt param, so motion capture and MIDI stay true.
-- The ramp waits until the press is a hold, in every recall mode: a tap
-- recalls, and a ramp that had already run would move the sound before the
-- recall is due (a BEAT or BAR queue) or turn a GLIDE into a jump.
local function tick_keys()
  -- a key held to the arc on a def with a `hold` (TAKE K3 = UNDO) fires AT
  -- the threshold, the same promise the eraser keeps
  for n = 2, 3 do
    local st = key_state[n]
    if st.def and st.def.hold and not st.fired then
      if ctx.page ~= st.page then
        st.fired, st.aborted = true, true   -- E1 left the page mid-hold: abort
      elseif ctx.frame - st.frame >= ERASE_FRAMES then
        st.fired = true
        st.def.hold()
      end
    end
  end
  if ctx.k13_frame and not ctx.k13_fired
      and ctx.frame - ctx.k13_frame >= ERASE_FRAMES then
    local e = page_erase()
    if e then e() end
    ctx.k13_fired = true
  end
  if ctx.peek_on then
    if ctx.frame - (ctx.peek_at or 0) >= TAP_FRAMES then
      local a = pget("scene_morph_amt", 0)
      if a < 1 then params:set("scene_morph_amt", clamp(a + 0.34, 0, 1)) end
    end
  elseif ctx.peek_back then
    local a = pget("scene_morph_amt", 0)
    if a > 0 then
      params:set("scene_morph_amt", clamp(a - 0.34, 0, 1))
    else
      ctx.peek_back = false
    end
  end
end

-- the footer draws what the encoders and keys currently address
ctx.enc_param = enc_param
ctx.key_def = key_def
ctx.page_erase = page_erase
ctx.ERASE_FRAMES = ERASE_FRAMES
ctx.TAP_FRAMES = TAP_FRAMES
-- the frame key n's hold began on, while a def with a `hold` is held on the
-- page that took the press (nil otherwise): the footer draws its arc from
-- it, full once the hold has fired, until the key comes up
-- The def comes back too: the arc's word is the press-time def's, never a
-- fresh lookup (K1 down would read the DRY def). An aborted hold draws none.
function ctx.hold_frame(n)
  local st = key_state[n]
  if st and st.def and st.def.hold and not st.aborted and st.page == ctx.page then
    return st.frame, st.def
  end
end

-- ============================================================================
-- polyphonic pad voices
-- ============================================================================
-- a pad's slice point: the centre of the i-th eighth OF THE TAKE — i.e. of
-- the current window, not of the 60s buffer. this is the one definition of
-- "slice i" in the instrument: the PADS audition and the MIDI/grid note pads
-- both resolve through here.
-- it was buffer-relative ((i+0.5)/8) until now, which meant a normal take —
-- record a phrase, the rec action snaps the window to it — left 7 of the 8
-- pads pointing at silence out in the empty buffer; this is that fix, shared.
-- rate stays fixed at 1 (per-pad rate is a later knob). type is per-pad.
-- SLICE voices are a PlayBuf reading FORWARD from the point, so they anchor
-- at the slice's START — the chop's attack (firing from the centre skipped
-- the transient the pad was chopped for). GRAIN clouds spread around the
-- point, so they keep the centre. one law, two anchors.
-- CHOPPED slices, when there are any: ctx.pad_cuts is a sorted list of
-- boundaries in buffer fractions, one more entry than there are slices (the
-- last is where the final slice ends). nil = the even law below.
-- Chopped boundaries are ABSOLUTE positions in the buffer, not window-relative,
-- so whoever replaces the material drops them (ctx.pads_uncut).
-- pad i -> its slice boundaries. A chop finds however many transients are
-- there, which is usually not eight, so the pads WRAP onto what exists — the
-- same "more keys than pads" idiom the MIDI and grid note paths already use.
-- With five slices, pads 6-8 replay slices 1-3 rather than falling back to
-- even eighths that would overlap the chopped ones.
local function pad_cut(i)
  local c = ctx.pad_cuts
  local n = c and (#c - 1) or 0
  if n < 1 then return nil end
  local j = i % n
  return c[j + 1], c[j + 2], j
end

local function pad_pos(i, at_start)
  local a, b = pad_cut(i)
  if a then return at_start and a or (a + (b - a) * 0.5) end
  local lo, _, span = window_bounds()
  return lo + (i + (at_start and 0 or 0.5)) / ctx.pad_n * span
end

-- how LONG a slice is, in the same buffer-fraction units as pad_pos. The
-- engine's slice voice needs this or its PlayBuf runs from the slice start
-- clean through the rest of the 60s buffer — a pad playing its chop and then
-- everything after it, while the PADS page draws eight bounded cells.
local function pad_len(i)
  local a, b = pad_cut(i)
  if a then return b - a end
  local _, _, span = window_bounds()
  return span / ctx.pad_n
end

-- which SLICE a pad plays (0-based). Differs from the pad number once a chop
-- has found fewer than eight, which is why the page labels cells with this.
function ctx.pad_slice_of(i)
  local _, _, j = pad_cut(i)
  return j or i
end

-- back to even slices. Chopped boundaries point at particular audio, so
-- anything that replaces the buffer has to let them go — the same rule the
-- window's SNAP memory follows.
function ctx.pads_uncut() ctx.pad_cuts = nil end

-- TIGHTEN: pull the window in onto the sound. Pressing REC and then playing
-- leaves your reaction time at the head of the take, and letting go late
-- leaves room tone at the tail — the rec-stop window snaps to where the record
-- HEADS were, which is not where the sound is.
-- NON-DESTRUCTIVE on purpose: this only moves pos_start/pos_end. It never
-- rewrites the buffer, so it is always undoable by moving the edges back (and
-- TAKE K3 SNAP remembers where you were).
-- Lua cannot read the engine buffer, so every analysis of the take works on a
-- dump of it: the empty check, the dump, the failure message and the temp
-- file live here once. `scan(tmp, lo, hi)` runs inside the dump's own
-- coroutine (so it can yield) over the CURRENT window; the temp file is
-- removed after it returns. Every scan shares the one temp file: take_to_wav
-- holds its guard until `scan` returns, so no second dump can overwrite the
-- file under a scan still reading it. `background`: see take_to_wav.
local function scan_take(tag, scan, background)
  if not ctx.wave_any then
    print("mangler: " .. tag .. " — nothing recorded yet")
    return
  end
  local tmp = norns.state.data .. "mscan-tmp.wav"
  ctx.take_to_wav(tmp, function(ok)
    if not ok then
      print("mangler: " .. tag .. " — the take dump did not land")
      return
    end
    local lo, hi = window_bounds()
    scan(tmp, lo, hi)
    os.remove(tmp)
  end, background)
end

function ctx.take_tighten()
  scan_take("TIGHTEN", function(tmp, lo, hi)
    local a, b = Mwav.onset_bounds(tmp, lo, hi, BUF_SECS, nil, ctx.task_yield)
    if not a then
      print("mangler: TIGHTEN — the window is silent, left alone")
      return
    end
    -- a hair of room either side so a soft attack is never clipped off
    local pad = 0.005 / BUF_SECS
    a = clamp(a - pad, lo, hi)
    b = clamp(b + pad, lo, hi)
    if b - a < 0.002 then
      print("mangler: TIGHTEN — too little sound to window, left alone")
      return
    end
    -- both edges move INWARD (a >= lo, b <= hi), so the pair cannot cross
    params:set("pos_start", a)
    params:set("pos_end", b)
    print(string.format("mangler: TIGHTEN — window is %.2fs of sound (was %.2fs)",
      (b - a) * BUF_SECS, (hi - lo) * BUF_SECS))
  end)
end

-- CHOP: put the pads on the material's own attacks instead of eight arbitrary
-- eighths. The transients are found in the dumped take (Mwav.transient_cuts).
-- The engine already takes a position AND a length per note, so nothing here
-- needs a new command — the slices just stop being uniform.
function ctx.pad_chop()
  scan_take("CHOP", function(tmp, lo, hi)
    local cuts = Mwav.transient_cuts(tmp, lo, hi, ctx.pad_n, BUF_SECS,
      ctx.task_yield)
    if not cuts or #cuts < 2 then
      ctx.pads_uncut()
      print("mangler: CHOP found no transients — pads back to even slices")
      return
    end
    cuts[#cuts + 1] = hi            -- the last slice runs to the window end
    ctx.pad_cuts = cuts
    print(string.format("mangler: CHOP — %d slices, on the attacks", #cuts - 1))
  end)
end

-- drop a voice id from the pad steal order (it is in there at most once)
local function pad_order_remove(id)
  local o = ctx.pad_order
  for k = 1, #o do
    if o[k] == id then table.remove(o, k); return end
  end
end

-- spawn/release a voice for pad `i` under a stable `id` (so note_off matches
-- the note_on that started it). z=1 press, z=0 release. `auto`: a machine
-- played it (the sequencer), which is not a hand on the instrument.
function ctx.pad_trigger(id, i, z, auto)
  -- playing pads counts as presence (idle dim)
  if not auto then ctx.last_input = ctx.frame end
  if z == 1 then
    if ctx.pad_held[id] and engine.note_off then engine.note_off(id) end
    if engine.note_on then
      -- per-pad SOUND-LOCK: this pad's own pitch (semitones -> rate) + voice, at
      -- the pad voice level (chord-safe default that won't slam the limiter)
      local pt = ctx.pad_type[i] or 0
      engine.note_on(id, pad_pos(i, pt > 0),
        2 ^ ((ctx.pad_pitch[i] or 0) / 12),
        pt, pget("pad_level", 0.3), pad_len(i))
    end
    -- the engine's noteOff + noteOn above moves a re-struck id to the END of
    -- its steal queue, so this mirror does exactly the same. Keeping the old
    -- position made the two steal DIFFERENT voices, and the one lua forgot
    -- kept sounding with nothing left that could release it.
    pad_order_remove(id)
    ctx.pad_order[#ctx.pad_order + 1] = id
    ctx.pad_held[id] = i    -- store the pad index (0 is truthy) for the display
    -- MIRROR the engine's voice steal. Over the cap it release-steals the
    -- OLDEST voice and tells lua nothing, so the PADS page went on drawing
    -- cells that had already stopped and the used/cap readout over-counted.
    -- Same cap, same order, so the picture matches what is sounding.
    local cap = math.floor(pget("voices", 8) + 0.5)
    while #ctx.pad_order > cap do
      local old = table.remove(ctx.pad_order, 1)
      ctx.pad_held[old] = nil
    end
  elseif ctx.pad_held[id] then
    if engine.note_off then engine.note_off(id) end
    ctx.pad_held[id] = nil
    pad_order_remove(id)
  end
end

-- MIDI/grid note routing: in pad mode a note plays pad (note mod 8) as a
-- polyphonic voice (note_off on release); otherwise it retunes the mono
-- drone `pitch` exactly as before. `pitch` is the chromatic rate the caller
-- already computed for the drone path.
function ctx.route_note(id, pitch, pad_idx, z)
  ctx.last_input = ctx.frame   -- MIDI/grid/typing notes count as presence
  if pget("pad_input", 0) == 1 then
    ctx.pad_trigger(id, pad_idx % ctx.pad_n, z)
  elseif z == 1 then
    params:set("pitch", pitch)
  end
end

-- release every sounding pad voice (leaving pad mode, cleanup, panic)
function ctx.pads_all_off()
  for id in pairs(ctx.pad_held) do
    if engine.note_off then engine.note_off(id) end
    ctx.pad_held[id] = nil
  end
  for k = #ctx.pad_order, 1, -1 do ctx.pad_order[k] = nil end
end

-- SOUND-LOCK editor sync: point the pad_voice/pad_pitch editor params at the pad
-- now under the cursor (guarded, so their actions don't write the value back).
function ctx.pad_edit_sync()
  local i = ctx.pad_cursor
  ctx.pad_sync = true
  if params.lookup["pad_voice"] then params:set("pad_voice", (ctx.pad_type[i] or 0) + 1) end
  if params.lookup["pad_pitch"] then params:set("pad_pitch", ctx.pad_pitch[i] or 0) end
  ctx.pad_sync = false
end

-- delete the recording, and load a source other than the live input. the
-- engine's 60s buffer is what everything slices (window, drone, pads). (the
-- TAPE deck's own CLR is on the TAPE page — that's the softcut loop, a
-- different deck entirely.)

-- THE TAKE'S GENERATION. Every writer that puts new material in the buffer (a
-- record pass, a clear, a load, a PSET restore) bumps it. A background
-- sample-rate conversion notes it when it starts and drops its result if it
-- moved: a conversion takes seconds on a Pi, and landing late used to
-- overwrite whatever had happened in the meantime, including a live take that
-- existed nowhere else.
local take_gen = 0

-- the strip needs a repaint once regen or erosion stops writing (see
-- tick_take_strip below). Declared here so a replacement can drop it.
local strip_stale, strip_quiet = false, 0
-- the take dump (ctx.take_to_wav, further down), declared here because
-- tick_take_strip waits for it
local export_clock
local export_bg = false   -- the running dump is a background one
local export_next         -- { out, done }: the dump waiting behind it

-- the one rule for "the buffer now holds different material". The erosion
-- age, the remembered SNAP window and the chop all belonged to the old
-- material, and take_len bounds what a PSET save writes: the new material's
-- length (`dur` seconds), or the whole buffer when the length is unknown.
-- Every replacer goes through here, so none can forget a part of it.
local function buffer_replaced(dur)
  take_gen = take_gen + 1
  strip_stale = false   -- the new material's strip is drawn from its own file
  Mpages.erosion_reset()
  ctx.snap_forget()
  ctx.pads_uncut()
  ctx.take_len = dur and clamp(dur / BUF_SECS, 0.002, 1) or 1
end

-- ...and a clear is a replacement by nothing: a later save writes nothing
-- (and deletes the stale pair)
local function buffer_cleared()
  buffer_replaced()
  ctx.take_len = 0
end

-- regen and erosion rewrite the buffer on the engine side, where lua cannot
-- see it, so the take's strip went on showing audio that was no longer there.
-- Once neither has written for a second, the take is dumped and the strip
-- repainted from the dump. Dropped if the take changed meanwhile (a clear, a
-- load, a new pass), so a late repaint can never draw old audio over new
-- material. It runs in the background: a performer's CHOP, TIGHTEN or EXPORT
-- that arrives during it waits for it instead of being refused.
function ctx.refresh_take_strip()
  if not ctx.wave_any then return end
  local g = take_gen
  scan_take("REPAINT", function(tmp)
    if g == take_gen then Mpages.repaint_wave(tmp) end
  end, true)
end

-- START ON SOUND. An arm records at once, as always, and this watches for
-- the first frame where what is written crosses `rec_thresh`. With `rec_wait`
-- on at that moment, the take starts there: from where the head stood on the
-- last QUIET frame, less one more frame. The onset came after that quiet
-- frame, and the extra frame covers rec_phase arriving a frame late. That
-- margin grows with a late frame, where a fixed pre-roll would not.
-- Recording from the arm, not from the crossing, is what keeps the attack.
-- The start only moves forward within the pass. A pass that wrapped past the
-- buffer end before the sound came starts at the buffer's start.
-- An overdub never waits: the old material under the new is the take too.
-- `rec_wait` is read every frame, not latched at the arm, so turning it on or
-- off while WAIT shows takes effect at once.
local REC_PREROLL = 1 / FPS
local rec_heard, rec_quiet = false, 0   -- this pass: sound seen, last quiet head
local rec_moved = false                 -- this pass's start moved to the sound
local function waits()
  return pget("rec_wait", 0) == 1 and pget("pre_level", 0) < 0.001
end
local function tick_rec_wait()
  if pget("rec", 0) ~= 1 or rec_heard then ctx.rec_waiting = false; return end
  ctx.rec_waiting = waits()
  -- a STOP or a freeze writes nothing, so a level then is not the take
  if pget("stop_all", 0) == 1 or pget("freeze", 0) == 1 then return end
  if ctx.rec_amp < pget("rec_thresh", 0.02) then
    rec_quiet = ctx.rec_phase
    return
  end
  rec_heard = true
  if not ctx.rec_waiting then return end
  ctx.rec_waiting = false
  local arm = ctx.rec_arm_phase
  local from = rec_quiet - REC_PREROLL / BUF_SECS
  from = rec_quiet >= arm and max(from, arm) or max(from, 0)
  ctx.rec_arm_phase, rec_moved = from, true
  print(string.format("mangler: sound at %.2fs into the pass, the take starts there",
    ((ctx.rec_phase - arm) % 1) * BUF_SECS))
end

-- POLLED each frame rather than run from the knobs' actions. The mode stops
-- erosion as surely as its knob does, because the erosion head only runs in
-- PLAY. The second of quiet means that a HEAL tap, a scene recall or a motion
-- lane crossing 0 does not dump the whole take (17 MB at full length) each
-- time it happens. The knobs' actions also mark the strip (strip_wrote): a
-- burst that starts and ends between two frames still wrote the buffer.
local function take_writing()
  return pget("regen", 0) > 0 or Mpages.eroding()
end
local function strip_wrote()
  strip_stale, strip_quiet = true, 0
end
local function tick_take_strip()
  if take_writing() then
    strip_wrote()
  elseif strip_stale then
    strip_quiet = strip_quiet + 1
    -- a performer's dump still running would refuse the repaint: wait it out
    if strip_quiet >= FPS and not export_clock then
      strip_stale = false
      ctx.refresh_take_strip()
      ctx.undo_mark()   -- what regen or erosion left is a finished take
    end
  end
end

-- wipe it. the engine zeroes the buffer; we clear the PICTURE with it and open
-- the window back up, so every page goes back to inviting a take instead of
-- drawing one that isn't there.
function ctx.clear_recording()
  if not engine.clear then
    print("mangler: engine has no `clear` — SYSTEM > RESTART for the new engine")
    return
  end
  -- disarm first, like the TAPE and LAYERS erases: wiping while armed kept
  -- recording into the freshly cleared buffer, and the rec-stop later built a
  -- window whose first seconds were the erased silence
  if pget("rec", 0) == 1 then params:set("rec", 0) end
  engine.clear()
  -- the engine's \clear released a held repeat with it. Through ctx: the
  -- local is declared further down, and read from here it would be a global
  ctx.repeat_release()
  Mpages.clear_wave()
  buffer_cleared()
  -- a clear must be SILENCE (S23 B2): regen would immediately re-record the
  -- OUTPUT — input monitor, ringing tails — into the freshly erased buffer,
  -- resurrecting what you just wiped. the engine's `clear` flushes the
  -- delay/reverb tails on its side; this stops the write head at the params.
  -- (buffer_cleared above dropped any pending strip repaint, so stopping
  -- regen here does not dump and repaint a buffer that is now empty)
  if pget("regen", 0) > 0 then params:set("regen", 0) end
  -- forget the loaded sample too. The take half already refuses to resurrect
  -- audio you cleared (take_pset_write deletes the pair), but a take that came
  -- from `load sample` lives in this path, and a PSET saved after a CLR would
  -- restore it on load — putting back the very sample you erased. "" is a
  -- no-op through load_sample's own guard.
  if params:get("sample_file") ~= "" then params:set("sample_file", "") end
  params:set("pos_start", 0)
  params:set("pos_end", 1)
  ctx.undo_mark()   -- empty is a state UNDO can go back from
  print("mangler: recording cleared")
end

-- put a file in the take buffer and make every page agree about it. The
-- display is read from the FILE: lua cannot see the SC buffer (Mpages.load_wave).
local function read_into_buffer(path, shown)
  engine.read_file(path)
  ctx.wave_any = true    -- audio is in the buffer now, drawable or not — never
                         -- lie "EMPTY" over an audible sample, even for formats
                         -- the preview can't draw
  local dur = Mpages.load_wave(path, BUF_SECS)
  buffer_replaced(dur)   -- the loaded length bounds a PSET save
  if dur then
    params:set("pos_start", 0)
    params:set("pos_end", clamp(dur / BUF_SECS, 0.002, 1))
    print(string.format("mangler: loaded %s (%.1fs) — window snapped to it",
      shown or path, dur))
  else
    -- audible, but no picture for this format (8-bit / aiff): leave the window
    -- for the performer to set rather than draw a lie
    print("mangler: loaded " .. (shown or path)
      .. " (playing; no waveform preview for this format)")
  end
  ctx.undo_mark()
end

-- LOAD AT THE SERVER RATE. Neither scsynth's nor softcut's buffer read does any
-- sample-rate conversion, so a file at any other rate plays varispeeded: a
-- 44.1k wav is 8.8% fast, over a semitone sharp, and every slice, pad and
-- window inherits the error. An off-rate file is resampled first, in the
-- background with the screen live. If the conversion cannot run or cannot
-- decode the file, it loads as-is: audible-but-sharp beats silence, and the
-- log says which happened. Shared by the take and the layer decks.
--   land(file, shown)  puts a file in place (`shown` = the name that was picked)
--   gen()              the target's generation: a conversion that finishes
--                      after it moved is dropped rather than landing on top
--   converting()       optional: runs once a conversion is going to start,
--                      before its generation is taken
local function load_at_rate(path, tmp, cap_secs, what, land, gen, converting)
  if path == nil or path == "" or path == "-" or path == _path.audio then return end
  if not util.file_exists(path) then
    print("mangler: no such file — " .. tostring(path))
    return
  end
  local okp, _, _, in_sr = pcall(Mwav.wav_info, path)
  if not (okp and in_sr and in_sr ~= SERVER_SR) then
    land(path)                     -- already at rate, or a format we can't probe
    return
  end
  print(string.format("mangler: %d Hz file — resampling to %d before the %s load"
    .. " (it would play at %.2fx otherwise)", in_sr, SERVER_SR, what,
    SERVER_SR / in_sr))
  if converting then converting() end
  local g = gen()
  ctx.run_task(function(yield)
    -- a job whose target moved on (while it waited in the queue, or between
    -- two blocks) stops here: converting tens of seconds of audio that will
    -- be dropped only delays the newer request queued behind it
    if gen() ~= g then return end
    -- capped at what the target can hold: converting past it is pure waste,
    -- and a corrupt rate header must never expand into gigabytes
    local ok, err = Mwav.convert_sr(path, tmp, SERVER_SR, function()
      yield()
      return gen() == g
    end, cap_secs)
    if not ok and gen() == g then error(err or "conversion failed", 0) end
  end, function(ok, err)
    if gen() ~= g then
      print("mangler: " .. path .. " dropped before it landed: the " .. what
        .. " changed meanwhile, the newer material stays")
      return
    end
    if ok then
      land(tmp, path)
    else
      print("mangler: resample failed (" .. tostring(err)
        .. ") — loading at the original rate, it will play sharp")
      land(path)
    end
  end)
end

-- load any wav as the sample (PARAMS > rec > load sample). it lands in the SAME
-- buffer a take does, so the window, drone and pads all work on it
-- identically — there is no "loaded sample" mode, it's just the sample. the
-- window snaps to the file's length.
local srconv_path
function ctx.load_sample(path)
  if path and path ~= "" and path ~= "-" and not engine.read_file then
    print("mangler: engine has no `read_file` — SYSTEM > RESTART for the new engine")
    return
  end
  take_gen = take_gen + 1     -- the newest request wins over one still converting
  srconv_path = srconv_path or (norns.state.data .. "mangler-srconv.wav")
  load_at_rate(path, srconv_path, BUF_SECS + 1, "take", read_into_buffer,
    function() return take_gen end)
end

-- load a wav into a LAYER deck (PARAMS > layers > L1/L2 load file, the answer
-- to "how do I get material into a layer without playing it in live"). Each
-- deck converts into its own temp, so a take load and a layer load can never
-- race over one file the server is still reading. `keep_loop`: a PSET restore
-- keeps the loop points it just restored instead of snapping to the file.
-- A conversion runs in the background, so the deck is cleared when it starts:
-- until the file lands the deck is silent and empty, not the previous audio
-- under the new file's name (an arm would otherwise overdub into it).
function ctx.layer_load(d, path, keep_loop)
  d.gen = (d.gen or 0) + 1
  load_at_rate(path, norns.state.data .. d.id .. "-srconv.wav", d.len + 1, d.name,
    function(file, shown) Mdeck.load_file(d, file, shown, keep_loop) end,
    function() return d.gen end,
    function() Mdeck.clear(d) end)
end

-- the live take rides the PSET as a private L/R pair beside the
-- pset file (take-N_L.wav / _R.wav), the same way mtape persists the tape
-- audio and mscenes the scene bank — the shared action_write/read/delete hook
-- calls each. the engine holds the buffer; lua only knows whether it has
-- CONTENT (ctx.wave_any — the has-a-take signal that also draws
-- "EMPTY - K2 REC"), so the write is gated on it: an empty take never leaves a
-- multi-MB silence file behind, and a fresh pset never resurrects one.
local function take_stem(number)
  return norns.state.data .. "take-" .. number
end

-- how many frames of the buffer a write should cover: the take_len high-water
-- mark (from frame 0), +50ms margin so rounding at the take boundary never clips
-- the tail, capped at the 60s buffer; take_len 0 (empty) -> the full buffer.
local function take_frames()
  local total = SERVER_SR * BUF_SECS
  local tl = ctx.take_len or 1
  return (tl > 0) and math.min(total, math.ceil(tl * total) + 2400) or total
end

function ctx.take_pset_write(number)
  if not engine.write_take then return end   -- old engine: no-op (like read_file)
  if not ctx.wave_any then
    -- nothing recorded: DELETE any take saved into this slot before, so a
    -- session the performer cleared and re-saved as empty can't resurrect the
    -- old audio on load (norns overwrite-save never calls action_delete).
    ctx.take_pset_delete(number)
    return
  end
  -- bound the write to the TAKE, not the full 60s buffer of mostly silence.
  engine.write_take(take_stem(number), take_frames())
end

function ctx.take_pset_read(number)
  if not engine.read_take then return end
  local stem = take_stem(number)
  -- no take file (a pset from before S22, or one saved with an empty buffer):
  -- leave the buffer alone, exactly like mtape when there's no wav — the
  -- pset's own params (window included) still load. BOTH halves must exist:
  -- /b_write is async, so an interrupted save can leave _L without _R, and
  -- reading that would zero both buffers then restore a left-only take.
  if not (util.file_exists(stem .. "_L.wav")
      and util.file_exists(stem .. "_R.wav")) then return end
  engine.read_take(stem)
  -- repaint from the file or the restored take is INVISIBLE (audio you can hear
  -- over "EMPTY - K2 REC"). do NOT snap the window — params:read already
  -- restored the saved pos_start/pos_end.
  local dur = Mpages.load_wave(stem .. "_L.wav", BUF_SECS)
  buffer_replaced(dur)  -- padlock_pset_read restores the pset's own cuts next
  ctx.wave_any = true   -- audio is in the buffer whether or not we could draw it
  ctx.undo_mark()
end

function ctx.take_pset_delete(number)
  local stem = take_stem(number)
  os.remove(stem .. "_L.wav")
  os.remove(stem .. "_R.wav")
end

-- ============================================================================
-- the take UNDO
-- ============================================================================
-- One step back, and one forward again. After every change to the take that
-- is FINISHED (a record pass stops, a load or a print lands, a PSET restores
-- it, regen or erosion goes quiet, a clear), the take as it now stands is
-- dumped as an L/R pair, and the state before it is kept as the one to go
-- back to. TAKE UNDO loads that one and swaps the two, so a second UNDO is a
-- redo. The window and the take length come back with it. A clear is a state
-- too (`empty`), so an UNDO after a clear brings the take back.
-- The dump is the engine's own write_take, the PSET's path, into one of THREE
-- slots (`undo-1..3`). A dump is async: the engine opens its file later than
-- this Lua turn, so files are never renamed (a rename ran before the file
-- existed and left a state's audio under another state's window). A new dump
-- goes into the one slot neither kept state uses, and the engine handles its
-- commands in order, so a read of a slot always follows its write.
-- UNDO while something writes first finishes that change: a pass stops (its
-- stop marks a state), regen or erosion stops and the take as they left it
-- is marked. So UNDO always goes back exactly one change.
-- `undo_keep` off writes nothing and forgets the kept states, so UNDO never
-- offers a take older than the last one you made.
local undo_cur, undo_prev     -- { slot, empty, lo, hi, take_len }
local function undo_stem(slot) return norns.state.data .. "undo-" .. slot end
local function free_slot()
  for k = 1, 3 do
    if not ((undo_cur and undo_cur.slot == k) or (undo_prev and undo_prev.slot == k)) then
      return k
    end
  end
end
function ctx.undo_mark()
  if pget("undo_keep", 1) ~= 1 or not engine.write_take then
    undo_cur, undo_prev = nil, nil
    return
  end
  undo_prev = undo_cur
  if not ctx.wave_any then
    undo_cur = { empty = true }
    return
  end
  local k = free_slot()
  engine.write_take(undo_stem(k), take_frames())
  undo_cur = { slot = k, lo = pget("pos_start", 0), hi = pget("pos_end", 1),
    take_len = ctx.take_len }
end
-- a fresh session: an undo pair left on the card by the last one is not
-- this session's take, so it is never offered, and its files go
function ctx.undo_forget()
  undo_cur, undo_prev = nil, nil
  for k = 1, 3 do
    os.remove(undo_stem(k) .. "_L.wav"); os.remove(undo_stem(k) .. "_R.wav")
  end
end
-- is there a state to go back to (TAKE draws its "<" while there is)
function ctx.undo_ready() return undo_prev ~= nil end
function ctx.take_undo()
  if not (undo_prev and engine.read_take) then
    ctx.take_say("UNDO - NOTHING TO GO BACK TO", "UNDO — nothing to go back to")
    return
  end
  -- finish a change still being written, so UNDO goes back exactly one.
  -- A pass's stop marks a state itself; regen and erosion are marked here
  if pget("rec", 0) == 1 then params:set("rec", 0) end
  local writing = pget("regen", 0) > 0 or Mpages.eroding()
  if pget("regen", 0) > 0 then params:set("regen", 0) end
  if Mpages.eroding() then params:set("erode", 0) end
  if writing then ctx.undo_mark() end
  local back = undo_prev
  if not back then               -- the mark above forgot them (undo_keep off)
    ctx.take_say("UNDO - NOTHING KEPT", "UNDO — keep an undo is off")
    return
  end
  undo_prev, undo_cur = undo_cur, back
  if back.empty then
    engine.clear()
    Mpages.clear_wave()
    buffer_cleared()
    Mdeck.set_pair("pos_start", "pos_end", 0, 1)
    -- as a clear does: a PSET saved now must not bring the loaded file back
    if params:get("sample_file") ~= "" then params:set("sample_file", "") end
    ctx.take_say("UNDO - EMPTY AGAIN", "UNDO — back to the empty buffer")
    return
  end
  engine.read_take(undo_stem(back.slot))
  local dur = Mpages.load_wave(undo_stem(back.slot) .. "_L.wav", BUF_SECS)
  buffer_replaced(dur)
  ctx.wave_any = true
  ctx.take_len = back.take_len
  Mdeck.set_pair("pos_start", "pos_end", back.lo, back.hi)
  ctx.take_say("UNDO - THE TAKE BEFORE",
    "UNDO — the take before the last change is back (UNDO again to return)")
end

-- SOUND-LOCKS ride the PSET like the take + scenes: the 8 per-pad voice+pitch
-- locks save as a small lua table beside the pset (params:read only restores the
-- editor params, i.e. the cursor pad — this restores all 8).
local function padlock_path(number)
  return norns.state.data .. "padlock-" .. number .. ".lua"
end

function ctx.padlock_pset_write(number)
  local t = { v = 1, type = {}, pitch = {}, cuts = ctx.pad_cuts }
  for i = 0, 7 do t.type[i] = ctx.pad_type[i] or 0; t.pitch[i] = ctx.pad_pitch[i] or 0 end
  -- guarded like every other pset writer here: a write failure must PRINT, not
  -- throw out of params.action_write and abort the rest of the save
  local ok, err = pcall(tab.save, t, padlock_path(number))
  if not ok then print("mangler: pad-lock save failed — " .. tostring(err)) end
end

function ctx.padlock_pset_read(number)
  local path = padlock_path(number)
  if not util.file_exists(path) then return end
  local ok, t = pcall(tab.load, path)
  if not (ok and type(t) == "table" and type(t.type) == "table") then return end
  for i = 0, 7 do
    ctx.pad_type[i] = t.type[i] or 0
    ctx.pad_pitch[i] = (t.pitch and t.pitch[i]) or 0
  end
  -- the chop belongs to the take, and the take rides the pset too — so the
  -- slice boundaries come back with the audio they were cut from. (this runs
  -- AFTER take_pset_read, which drops them along with the old material.)
  ctx.pad_cuts = (type(t.cuts) == "table" and #t.cuts > 1) and t.cuts or nil
  ctx.pad_edit_sync()   -- editor params -> the restored cursor pad
end

function ctx.padlock_pset_delete(number)
  os.remove(padlock_path(number))
end

-- hand back to the scheduler for one tick. Every long scan inside a clock
-- coroutine takes this, so the 15fps redraw (and motion, and scenes) keeps
-- running through a multi-second job instead of freezing.
function ctx.task_yield() clock.sleep(0) end

-- run long jobs as coroutines that yield, ONE AT A TIME, in the order they
-- were asked for. A job that arrives while another runs waits its turn: a PSET
-- can restore an off-rate take and an off-rate layer back to back, and both
-- have to convert (refusing the second loaded it out of tune). Each body runs
-- under pcall and its `on_done(ok, err)` ALWAYS runs: without that a throw
-- halfway through (a full card, a bad read) kills the coroutine with the
-- caller's state half-set and its file handles still open. A job whose
-- target changed stops itself and is dropped by the caller's generation
-- check (load_at_rate), not here.
local task_clock
local task_queue = {}
local function start_next_task()
  local job = table.remove(task_queue, 1)
  if not job then return end
  task_clock = clock.run(function()
    local ok, err = pcall(job[1], ctx.task_yield)
    task_clock = nil
    if not ok then print("mangler: background job failed — " .. tostring(err)) end
    if job[2] then job[2](ok, err) end
    start_next_task()
  end)
end

function ctx.run_task(fn, on_done)
  task_queue[#task_queue + 1] = { fn, on_done }
  if task_clock then
    print("mangler: queued behind the background job already running")
  else
    start_next_task()
  end
end

-- teardown only: no completion runs (cleanup is leaving), queued jobs included
function ctx.cancel_task()
  for k = #task_queue, 1, -1 do task_queue[k] = nil end
  if task_clock then clock.cancel(task_clock); task_clock = nil end
end

local function filesize(p)
  local f = io.open(p, "rb"); if not f then return nil end
  local s = f:seek("end"); f:close(); return s
end
-- the first free `<prefix>-NNN` stem in `dir`, NNN from 001, tested with `ext`.
-- Returns nil when all 999 are taken, and the caller then REFUSES and says so.
-- This was two copies of one loop, each handing back a "-000" name at
-- exhaustion — which quietly overwrote the performer's oldest recording.
function ctx.next_free(dir, prefix, ext)
  for n = 1, 999 do
    local stem = string.format("%s-%03d", prefix, n)
    if not util.file_exists(dir .. stem .. (ext or "")) then return stem end
  end
  return nil
end

local function next_audio_name(prefix)
  local stem = ctx.next_free(_path.audio, prefix, ".wav")
  return stem and (stem .. ".wav")
end

-- A RECORDING PASS: the system TAPE captures the MASTER out — engine + tape
-- deck + FX, everything you hear — into `path` for `secs`, calling `on_tick`
-- once per frame so a caller can automate a param ACROSS the pass. That last
-- part is what makes a pass more than a bounce: sweep the scene morph, or the
-- erosion, and the recording IS the sweep.
-- `done(finished, path)` runs after the writer has flushed; `finished` is false
-- if the pass was aborted.
-- The duration is LIVE: record_stop ends it now, record_limit re-aims the end.
local pass, pass_clock
function ctx.record_pass(path, secs, on_tick, done)
  if pass then print("mangler: a recording pass is already running"); return false end
  if not (audio.tape_record_open and audio.tape_record_start) then
    print("mangler: no system tape API — cannot record"); return false
  end
  -- recording a CHOKED output would capture silence, and a caller that then
  -- loads the result would wipe the take with nothing
  if pget("stop_all", 0) == 1 then
    print("mangler: pass refused — output is stopped (K1+K2 to start)")
    return false
  end
  pass = { n = math.max(1, math.floor(secs * FPS + 0.5)), i = 0 }
  audio.tape_record_open(path)
  audio.tape_record_start()
  pass_clock = clock.run(function()
    local aborted = false
    while pass and pass.i < pass.n do
      if on_tick then on_tick(pass.n > 1 and pass.i / (pass.n - 1) or 1) end
      clock.sleep(1 / FPS)
      pass.i = pass.i + 1
      -- the global STOP is the abort: the one key that always means silence
      -- has to mean "stop making this" too. Refusing to START while stopped is
      -- only half the guard — a STOP pressed mid-pass silences the master, and
      -- the rest of the recording would be digital silence.
      if pget("stop_all", 0) == 1 then aborted = true; break end
    end
    pcall(audio.tape_record_stop)
    clock.sleep(0.35)          -- let the tape writer flush + close the wav
    pass, pass_clock = nil, nil
    if done then done(not aborted, path) end
  end)
  return true
end

function ctx.record_stop()
  if pass then pass.n = pass.i end          -- the loop falls out next check
end

function ctx.record_limit(secs)
  if pass then
    pass.n = math.max(pass.i + 1, math.floor(secs * FPS + 0.5))
  end
end

-- teardown: kill a pass outright without running its `done`. Only cleanup()
-- wants this — everything else should let the pass finish or abort so the
-- caller's completion work still runs.
function ctx.record_cancel()
  if not pass_clock then return end
  clock.cancel(pass_clock)
  pcall(audio.tape_record_stop)
  pass, pass_clock = nil, nil
end

-- PRINT: the one-gesture full-mix resample. One pass of print_len seconds
-- (0 = AUTO, the current window length), and the bounce loads back as THE take
-- (engine.read_file via load_sample: window snaps, waveform draws). The print
-- wav stays in dust/audio, so the material is never lost even though the buffer
-- is replaced; older takes live in their PSETs. mangle -> print -> mangle.
-- `sweep` (optional) is handed straight to the pass as its per-frame hook, so a
-- caller can print a MOVE rather than a moment.
function ctx.print_take(sweep)
  local secs = pget("print_len", 0)
  if secs < 0.05 then
    local _, _, span = window_bounds()
    secs = clamp(span * BUF_SECS, 0.5, BUF_SECS)
  end
  local name = next_audio_name("mangler-print")
  if not name then
    print("mangler: 999 prints in dust/audio — clear some out first")
    return
  end
  local ok = ctx.record_pass(_path.audio .. name, secs, sweep,
    function(finished, path)
      if not finished then
        os.remove(path)        -- a part-silent bounce is not worth keeping
        print("mangler: PRINT aborted by STOP — the take is untouched")
        return
      end
      ctx.load_sample(path)
      print("mangler: PRINT done — " .. name .. " is the new take")
    end)
  if ok then
    print(string.format("mangler: PRINT — recording the master mix, %.1fs", secs))
  end
end

-- dump the live take to ONE stereo wav: write_take drops an L/R pair (bufL and
-- bufR are two MONO buffers and scsynth has no cheap non-realtime interleave),
-- we wait out the async /b_write, then zip them. `done(ok, path)` when the file
-- is there. Lua cannot read an SC buffer, so this file IS the API — the export
-- and the pad chopper are both built on it.
-- `background`: nobody waits on this dump (the strip repaint). A performer's
-- dump that arrives while a background one runs waits for it, in one slot.
function ctx.take_to_wav(out, done, background)
  if not engine.write_take then
    print("mangler: engine has no write_take — SYSTEM > RESTART")
    if done then done(false) end
    return
  end
  if not ctx.wave_any then
    print("mangler: nothing to render — the buffer is empty")
    if done then done(false) end
    return
  end
  -- REFUSE a second dump rather than cancelling the first. Both callers share
  -- this one clock and one tmp stem; cancelling killed the coroutine
  -- mid-interleave, leaving a TRUNCATED wav that looks finished in the browser,
  -- and the new dump would overwrite the files the cancelled one was reading.
  -- A dump queued behind the background repaint is not refused: it waits.
  if export_clock then
    if export_bg and not background and not export_next then
      export_next = { out, done }
      print("mangler: take dump queued behind the strip repaint")
      return
    end
    print("mangler: a take dump is already running")
    if done then done(false) end
    return
  end
  export_bg = background == true
  local tmp = norns.state.data .. "mexport-tmp"
  -- clear any leftover temp pair first: the names are fixed, so a stale half of
  -- an interrupted dump can satisfy the size-stability wait below and get
  -- interleaved into the new file.
  os.remove(tmp .. "_L.wav"); os.remove(tmp .. "_R.wav")
  engine.write_take(tmp, take_frames())   -- async dump to tmp_L.wav / tmp_R.wav
  -- How big each mono file should end up: one sample per frame, plus a 44
  -- byte header. We wait for both to REACH that size and then stop changing.
  -- Waiting for them to merely stop changing is not enough, because a slow SD
  -- card can pause mid-write and look finished at half a file. That is why
  -- the byte width has a name of its own: while it was stuck at 2 and the
  -- engine wrote 3, this check passed at two thirds and exported a cut-off
  -- take. The time limit scales with the take so a long one gets time to
  -- finish. It is only there to stop us waiting forever.
  local exp = take_frames() * ctx.TAKE_BYTES + 44
  local cap = math.max(100, math.ceil(exp / 200000) + 80)
  export_clock = clock.run(function()
    local pL, pR, stable = -1, -1, 0
    for _ = 1, cap do
      clock.sleep(0.05)
      local sL, sR = filesize(tmp .. "_L.wav"), filesize(tmp .. "_R.wav")
      if sL and sR and sL >= exp * 0.98 and sR >= exp * 0.98
        and sL == pL and sR == pR then
        stable = stable + 1; if stable >= 2 then break end
      else stable = 0 end
      pL, pR = sL, sR
    end
    -- yield between chunks so a large interleave doesn't freeze the UI thread
    local ok = Mwav.interleave_wav(tmp .. "_L.wav", tmp .. "_R.wav", out,
      ctx.task_yield)
    os.remove(tmp .. "_L.wav"); os.remove(tmp .. "_R.wav")
    -- the guard holds until `done` returns. A scan reads `out` in there for
    -- seconds, and a second dump started meanwhile would truncate the file
    -- under it. Under pcall, so a throw cannot leave the guard set forever.
    if done then
      local okd, err = pcall(done, ok, out)
      if not okd then print("mangler: the step after the take dump failed: " .. tostring(err)) end
    end
    export_clock, export_bg = nil, false
    local nxt = export_next
    export_next = nil
    if nxt then ctx.take_to_wav(nxt[1], nxt[2]) end
  end)
end

-- the browsable EXPORT: the same dump, into dust/audio under a name you can
-- find, as one stereo wav that reloads through `load sample`.
function ctx.export_take(name)
  name = name or next_audio_name("mangler")
  if not name then
    print("mangler: 999 exports in dust/audio — clear some out first")
    return
  end
  local out = _path.audio .. name
  ctx.take_to_wav(out, function(ok)
    print(ok and ("mangler: exported " .. out) or "mangler: export FAILED")
  end)
end

-- the window locked to the clock: with win_beats other than FREE, the
-- window's END is put at the start plus that many beats at the current tempo,
-- so a PLAY loop of the take stays in time with the synced delay, the decks
-- and the sequencer. It is put there when the lock is set, when a record
-- pass stops, when the tempo moves by more than half a percent (so MIDI clock
-- jitter does not write every frame), and when the START moves on its own
-- (so moving the start slides the whole window). A start that jumps past the
-- end moves the end in its own action, so the pair never stands crossed.
-- It does NOT own the end. An earlier version put the end back every frame,
-- like the synced delay's time, and a reviewer found what that broke: TAKE
-- SNAP could no longer go back, and a morph, a GLIDE or a motion lane on the
-- end fought it every frame, wobbling the read head. So a write that moves
-- the END (SNAP, TIGHTEN, a scene, the morph, a hand on E3, any pair write)
-- is left as it is, until the next of those moments.
-- A start too late for the length ends the window at the buffer's end.
local WIN_BEATS = { 0, 1, 2, 4, 8, 16, 32 }
local WIN_BEAT_NAMES = { "FREE", "1 BEAT", "2 BEAT", "1 BAR", "2 BAR", "4 BAR", "8 BAR" }
ctx.WIN_BEAT_NAMES = WIN_BEAT_NAMES
local win_tempo, win_lo, win_hi = 0, -1, -1   -- what the lock last saw
local function win_lock_beats()
  return WIN_BEATS[math.floor(pget("win_beats", 1) + 0.5)] or 0
end
local function apply_window_len()
  local b = win_lock_beats()
  if b <= 0 then return end
  local t = ctx.tempo()
  win_tempo = t
  local want = min(1, pget("pos_start", 0) + b * 60 / t / BUF_SECS)
  if math.abs(pget("pos_end", 1) - want) >= 1e-9 then
    params:set("pos_end", want)   -- only the end moves, outward of the start
    if ctx.motion and ctx.motion.account then ctx.motion.account("pos_end") end
  end
  win_lo, win_hi = pget("pos_start", 0), pget("pos_end", 1)
end
-- each frame: a tempo move, or the start moved while the end did not
local function sync_window_len()
  local lo, hi = pget("pos_start", 0), pget("pos_end", 1)
  if win_lock_beats() > 0 then
    local t = ctx.tempo()
    if math.abs(t - win_tempo) > win_tempo * 0.005
        or (lo ~= win_lo and hi == win_hi) then
      apply_window_len()
      return
    end
  end
  win_lo, win_hi = lo, hi
end

-- BEAT REPEAT (the engine's \mangler_repeat). Held, it waits for the next
-- division of the clock, then the engine captures that much of the output
-- and loops it until you let go: a stutter on the beat. Turning the division
-- while it holds re-captures at once (a roll to a shorter one). A STOP
-- releases it, as it silences everything, and an arm under STOP waits for
-- the next press. The engine places it after the record tap, so resample,
-- regen and PRINT never record it.
-- A press that waits for its beat is never cancelled: a cancel landing as the
-- sync fires is the norns clock race in CLAUDE.md, and a press let go before
-- its beat is common. Each press takes a generation, and a wait that wakes
-- to a newer press, or to the key let go, does nothing. Cleanup cancels.
local REPEAT_BEATS = { 2, 1, 0.5, 0.25, 0.125 }
local REPEAT_NAMES = { "1/2", "1/4", "1/8", "1/16", "1/32" }
local repeat_clock          -- the newest coroutine waiting for the division
local repeat_gen = 0        -- bumped by every press and every release
local repeat_on = false     -- the engine holds a repeat now
local function repeat_beats()
  return REPEAT_BEATS[math.floor(pget("repeat_div", 3) + 0.5)] or 0.5
end
local function repeat_secs()
  return min(2, repeat_beats() * 60 / ctx.tempo())
end
local function repeat_release()
  repeat_gen = repeat_gen + 1
  if repeat_on and engine.beat_repeat then engine.beat_repeat(0) end
  repeat_on = false
end
local function repeat_start()
  if not engine.beat_repeat then
    print("mangler: engine has no `beat_repeat` — SYSTEM > RESTART for the new engine")
    return
  end
  if pget("stop_all", 0) == 1 then return end
  repeat_gen = repeat_gen + 1
  local g, b = repeat_gen, repeat_beats()
  repeat_clock = clock.run(function()
    clock.sync(b)
    if g ~= repeat_gen or pget("beat_repeat", 0) ~= 1
        or pget("stop_all", 0) == 1 then return end
    engine.beat_repeat(repeat_secs())
    repeat_on = true
  end)
end
ctx.repeat_release = repeat_release
-- the engine is looping a slice now (not just held, waiting for its beat)
function ctx.repeat_live() return repeat_on end

-- tempo-synced delay: when delay_sync is not FREE, delay_time follows the
-- clock at the chosen division. computed here (Lua) so the ENGINE command
-- set is untouched; the engine's 0.2s time-lag turns tempo changes into a
-- tape-style glide, and times beyond the 2s delay line clamp there (2s so
-- a half note fits down to 60 BPM).
-- While synced the clock OWNS the time: anything else that writes it (a hand
-- on the knob, a scene, the morph, a motion lane) is put back on the grid the
-- next frame, so the echoes cannot sit off the beat until the tempo happens
-- to change. The redraw tick calls this each frame and it writes only when
-- the time is off by more than half a percent, so MIDI clock jitter does not
-- write every frame.
local SYNC_BEATS = { 0, 0.25, 0.5, 0.75, 1, 1.5, 2 }  -- FREE 1/16 1/8 1/8. 1/4 1/4. 1/2
local function sync_delay_time(force)
  local s = pget("delay_sync", 1)
  if s <= 1 then return end                          -- FREE
  local t = ctx.tempo()
  if not (t and t > 0) then return end
  local want = clamp(SYNC_BEATS[s] * 60 / t, 0.01, 2)
  if not force and math.abs(pget("delay_time", want) - want) <= want * 0.005 then
    return
  end
  params:set("delay_time", want)
  -- tell the gesture looper this wasn't a hand on the knob (its polling
  -- capture would otherwise punch a delay_time lane on every tempo move)
  if ctx.motion and ctx.motion.account then ctx.motion.account("delay_time") end
end

-- DRY throw (K1+K3 tap on any page, grid (7,2)): playback becomes the un-effected
-- sample — every "on top" color to zero (delay, reverb, shimmer, drive,
-- clouds feedback — the one wash the REVERB page can't kill) and the
-- filter thrown open (type-aware, same law as FILTER's OPEN key). the
-- take itself is always recorded clean; this clears the playback path.
function ctx.fx_dry()
  ctx.throws_forget()   -- DRY moves the wet path wholesale: no throw's "back"
                        -- survives it (a latched WASH would restore reverb)
  params:set("delay_mix", 0)
  params:set("rev_mix", 0)
  params:set("shimmer", 0)
  params:set("drive", 0)
  params:set("clouds_fb", 0)
  local ft = params:get("filt_type")
  params:set("cutoff", filter_open_cutoff(ft))
  params:set("resonance", 0)
end

-- ============================================================================
-- params  (single source of truth: keys, encoders, and MIDI all drive these)
-- ============================================================================
-- every param's action sends the engine command of the same id, so the
-- engine command table and these ids must stay in lockstep (see the .sc file).

-- `map` (optional) is a response curve applied to the param value before it
-- reaches the engine — e.g. the FX sends pass `square` so the engine's
-- equal-power .sqrt crossfade reads LINEAR in the knob (0 stays truthy in Lua,
-- so a 0 map result still short-circuits correctly).
-- the send map of each engine control, by id: the modulators (lib/mlfo.lua)
-- send the engine a swung value through the same map the action uses
ctx.eng_map = {}
local function add_eng_control(id, name, spec, map)
  ctx.eng_map[id] = map
  params:add_control(id, name, spec)
  params:set_action(id, function(v)
    -- a modulated knob sends its value WITH the swing, so a hand, a scene or
    -- a motion lane moving it between the modulator's frames never sends the
    -- plain value in between (a spike, and a zipper on every move)
    if Mlfo.swinging(id) then v = Mlfo.swung(id, v) end
    if engine[id] then engine[id](map and map(v) or v) end
  end)
end
local function square(v) return v * v end

-- delay feedback response. the raw knob is 0..1 but
-- audible repeat-count is a ln-law of the loop gain, so a LINEAR knob crams
-- every useful value into the top few percent ("~4 quiet repeats then jumps to
-- infinite"). this concave curve spreads the knob across the musical band —
-- quarter ~3 repeats, half ~6, three-quarter ~14, top a near-infinite hold —
-- and is SHARED with the DELAY page (ctx.delay_fb_curve) so the drawn echo
-- taps decay at the feedback you actually hear, not the raw knob.
local function fb_curve(v) return 0.98 * v ^ 0.6 end
ctx.delay_fb_curve = fb_curve

local function add_eng_binary(id, name)
  params:add_binary(id, name, "toggle", 0)
  params:set_action(id, function(v)
    if engine[id] then engine[id](v) end
  end)
end

-- an option whose engine command wants a 0-based index (norns options count
-- from 1), sent through the same guard as every other engine command
local function add_eng_option(id, name, options, default)
  params:add_option(id, name, options, default)
  params:set_action(id, function(v)
    if engine[id] then engine[id](v - 1) end
  end)
end

-- a MOMENTARY binary that fires `fn` on the press edge only: a stray 0 (from
-- params:bang or a pset read) must never do anything. momentary rather than a
-- trigger because a trigger cannot be MIDI-learned, and the point of most of
-- these is a footswitch.
local function add_momentary(id, name, fn)
  params:add_binary(id, name, "momentary", 0)
  params:set_action(id, function(v) if v == 1 then fn() end end)
end

-- a plain 0..1 knob, the commonest spec in the paramset; fine_unit adds the
-- 0.002 quantum the region edges use (fine_delta then scales it by the span:
-- the default 0.01 is 600ms of a 60s buffer, far too coarse to set a loop)
local function unit(default) return controlspec.new(0, 1, "lin", 0, default, "") end
local function fine_unit(default)
  local spec = unit(default)
  spec.quantum = 0.002
  return spec
end

local function init_params()
  params:add_separator("mangler")

  -- group ids must differ from every param id, and the declared count MUST
  -- match the adds that follow (a refused/missing add corrupts the paramset)
  params:add_group("grp_mix", "mix", 5)
  params:add_control("mix", "eng <> tape", unit(0.5))
  params:set_action("mix", Mtape.update_mix)
  params:add_control("out_level", "out level",
    controlspec.new(0, 1.5, "lin", 0, 1.0, ""))
  params:set_action("out_level", function()
    Mtape.update_mix()
    ctx.layers_relevel()   -- the master masters the layer decks too
  end)
  params:add_control("sc_level", "eng level", unit(1.0))
  params:set_action("sc_level", Mtape.update_mix)
  -- id "tape_level" is RESERVED by the system TAPE deck; "cut_level" avoids it
  params:add_control("cut_level", "tape level", unit(1.0))
  params:set_action("cut_level", Mtape.update_mix)
  -- master transport: STOP chokes every deck at the one place each level is
  -- computed and halts their heads (below), so START restores the exact mix
  -- from the exact spot. held pad voices are released. MIDI-map it for a stop
  -- pedal; SPACE on a typing keyboard and grid (8,2) drive it too.
  params:add_binary("stop_all", "stop all", "toggle", 0)
  params:set_action("stop_all", function(v)
    if v == 1 then ctx.pads_all_off(); repeat_release() end
    Mtape.update_mix()
    ctx.layers_relevel()   -- the layer decks choke with everything else
    -- TRUE STOP (S23 B1): the transports HALT too, not just the levels. every
    -- softcut head glides to rate 0 (the slew keeps it click-free) and START
    -- resumes each exactly where it stood — and because they all stop AS ONE,
    -- the decks' relative drift survives a stop/start. the rate/rec laws fold
    -- (1 - stop_all), so re-sending them applies it in both directions. the
    -- engine drone's head freezes on its own: its level lands at 0 and the
    -- read head runs on (level > 0), same law as the erosion/regen heads.
    Mtape.update_tape_rate()
    Mtape.update_tape_rec()
    for _, d in ipairs(ctx.layers) do
      Mdeck.update_rate(d)
      Mdeck.update_rec(d)
    end
    -- the engine record head pauses with everything else. the param stays
    -- armed, so START resumes the take mid-punch; the rec action gates its
    -- own sends the same way, so arming DURING a stop also waits for START.
    if engine.rec then engine.rec(v == 1 and 0 or pget("rec", 0)) end
  end)

  params:add_group("grp_rec", "take - record", 17)
  add_eng_binary("rec", "record")
  -- when capture stops, snap the window to the take just recorded so playback
  -- immediately loops what you played — not a 60s window of mostly silence
  params:set_action("rec", function(v)
    if engine.rec then
      -- under a STOP everything is halted, capture included: an arm made
      -- while stopped takes effect on START (the stop action re-sends it).
      -- the window bookkeeping below still runs — the head is frozen, so
      -- the arm position it records is exactly where START will resume.
      engine.rec(pget("stop_all", 0) == 1 and 0 or v)
    end
    if v == 1 then
      rec_open = true
      take_gen = take_gen + 1   -- a live pass outranks a conversion in flight
      ctx.rec_arm_phase = ctx.rec_phase
      -- a fresh pass for start on sound (see tick_rec_wait)
      rec_heard, rec_quiet, rec_moved = false, ctx.rec_phase, false
      ctx.rec_waiting = waits()
      return
    end
    -- the rec-stop bookkeeping runs only for a pass that was really OPENED.
    -- params:bang() at init fires this action with 0, and with pos_end at 1
    -- that set take_len to the whole buffer before anything was recorded, so
    -- the first take of every session saved, chopped and recalled scenes as
    -- if it were 60 seconds long.
    if not rec_open then return end
    rec_open = false
    if ctx.rec_waiting then
      ctx.rec_waiting = false
      print("mangler: no sound crossed the threshold — the take is the whole pass")
    end
    -- the window writes go through set_pair, widening edge first: a take
    -- laid down past the old window's end used to cross the pair for a moment
    if rec_moved and ctx.rec_phase >= ctx.rec_arm_phase then
      -- started on sound: a hit stopped soon after is still a take (at least
      -- the 0.3s floor below), not the previous take's window over silence
      local a = ctx.rec_arm_phase
      Mdeck.set_pair("pos_start", "pos_end", a, max(ctx.rec_phase, min(1, a + 0.005)))
    elseif ctx.rec_phase > ctx.rec_arm_phase + 0.005 then
      Mdeck.set_pair("pos_start", "pos_end", ctx.rec_arm_phase, ctx.rec_phase)
    elseif ctx.rec_phase < ctx.rec_arm_phase - 0.005 then
      -- the write head wrapped past the buffer end mid-take. a wrapped
      -- window (start > end) would be SORTED into the wrong slice by
      -- window_bounds, so fall back to the whole buffer — the take is in
      -- there, just split across the seam. (proper wrap-around windows
      -- need engine support.)
      Mdeck.set_pair("pos_start", "pos_end", 0, 1)
    end
    rec_moved = false
    -- the take bounds what a PSET save writes (the write head runs
    -- 0..pos_end). regen fills the whole buffer, so it forces a full save.
    -- GROW ONLY: this is a high-water mark, and a rec pass overwrites only
    -- the region it recorded — everything else is still in the buffer. A
    -- short punch-in over a narrowed window used to REPLACE the mark with
    -- that narrow pos_end, so the next PSET save wrote a few seconds and the
    -- rest of the take was gone on reload, with no error anywhere. Fresh
    -- material resets the mark on purpose (clear/load/print), never a punch.
    local bound = pget("regen", 0) > 0 and 1 or pget("pos_end", 1)
    if bound > (ctx.take_len or 0) then ctx.take_len = bound end
    apply_window_len()   -- a locked length: the new take is that long
    ctx.undo_mark()
  end)
  -- START ON SOUND: an arm records at once, and the take starts where the
  -- sound first crosses the threshold (see tick_rec_wait). The level is
  -- what is being written (the engine's rec_amp), so a resample counts too.
  params:add_binary("rec_wait", "start on sound", "toggle", 0)
  params:add_control("rec_thresh", "sound threshold",
    controlspec.new(0.002, 0.5, "exp", 0, 0.02, ""),
    function(p) return string.format("%.0f dB", 20 * math.log(p:get(), 10)) end)
  add_eng_control("rec_level", "rec level", unit(1.0))
  add_eng_control("pre_level", "overdub", unit(0.0))
  add_eng_binary("freeze", "freeze")
  add_eng_control("dry_wet", "dry/wet", unit(0.5))
  add_eng_control("resample", "resample (in<>out)", unit(0.0))
  -- self-resampling: continuous feedback of the processed OUTPUT back into
  -- the record buffer (Basinski-style regenerative decay). 0 = off (a fresh
  -- take stays dry). manual rec + freeze suspend it; engine-side it's a bounded
  -- convex crossfade so it can't run away.
  params:add_control("regen", "regen (self-resample)", unit(0.0))
  params:set_action("regen", function(v)
    -- the other half of the erode interlock (see grp_erode below)
    if v > 0 and pget("erode", 0) > 0 then params:set("erode", 0) end
    if engine.regen then engine.regen(v) end
    if v > 0 then strip_wrote() end
    -- regen's record head traverses the WHOLE buffer, so once it runs the take
    -- can be anywhere: force a full-buffer PSET save (sticky until the next
    -- fresh rec / load / clear resets take_len), never truncate its decay tail.
    if v > 0 then ctx.take_len = 1 end
  end)
  -- delete the take (the TAKE page's K1+K3 erase arc) and load one off the
  -- disk. clear is a MOMENTARY binary so a footswitch can wipe between takes;
  -- it fires on the press edge only, so a stray 0 from bang/pset does nothing.
  add_momentary("clear_rec", "clear recording", ctx.clear_recording)
  -- add_file opens norns' fileselect in the menu and the path rides the PSET,
  -- so a saved session reloads its sample
  params:add_file("sample_file", "load sample", _path.audio)
  params:set_action("sample_file", function(f) ctx.load_sample(f) end)
  -- export the take as a browsable stereo wav in dust/audio.
  -- momentary so a footswitch/grid can fire it; press edge only.
  add_momentary("export_take", "export take (wav)", ctx.export_take)
  -- pull the window in onto the sound (see ctx.take_tighten). momentary so a
  -- footswitch reaches it; non-destructive — it only moves the window edges.
  add_momentary("take_tighten", "tighten window to sound", ctx.take_tighten)
  -- UNDO: one step back to the take before the last finished change, and
  -- again to return (see ctx.take_undo). `undo_keep` off saves the card.
  add_momentary("take_undo", "undo take", ctx.take_undo)
  params:add_binary("undo_keep", "keep an undo", "toggle", 1)
  -- PRINT the master mix back into the buffer (see ctx.print_take). momentary
  -- so a footswitch fires the whole bounce; press edge only.
  add_momentary("print_take", "print mix -> take", ctx.print_take)
  params:add_control("print_len", "print length",
    controlspec.new(0, 16, "lin", 0.5, 0, "s"),
    function(p)
      local v = p:get()
      return v < 0.05 and "AUTO (window)" or string.format("%.1f s", v)
    end)

  params:add_group("grp_window", "take - window", 5)
  -- fine_unit: ~10ms nudges on a tight window once fine_delta scales it
  add_eng_control("pos_start", "win start", fine_unit(0.0))
  add_eng_control("pos_end", "win end", fine_unit(1.0))
  -- the window's LENGTH on the clock (see sync_window_len): FREE, or a
  -- length in beats that the start carries with it
  params:add_option("win_beats", "win length", WIN_BEAT_NAMES, 1)
  params:set_action("win_beats", function() apply_window_len() end)
  -- a start that jumps past a locked window's end takes the end with it at
  -- once (see sync_window_len), so the engine never reads a crossed pair
  params:set_action("pos_start", function(v)
    if engine.pos_start then engine.pos_start(v) end
    if win_lock_beats() > 0 and v >= pget("pos_end", 1) then apply_window_len() end
  end)
  add_eng_control("scan", "scan rate",
    controlspec.new(-2, 2, "lin", 0, 1.0, "x"))
  add_eng_control("pos_jitter", "jitter", unit(0.0))

  params:add_group("grp_grain", "voice - grain", 9)
  add_eng_control("size", "size",
    controlspec.new(0.01, 0.5, "exp", 0, 0.1, "s"))
  add_eng_control("density", "density",
    controlspec.new(1, 200, "exp", 0, 20, "hz"))
  -- pitch is playable chromatically: MIDI notes set it (see grp_keys), and
  -- pitch_quant snaps encoder/CC moves to semitones on the way to the engine
  -- (the param keeps the raw value; only the engine command is quantized)
  params:add_control("pitch", "pitch",
    controlspec.new(0.25, 4, "exp", 0, 1.0, "x"),
    function(p)
      local v = p:get()
      if pget("pitch_quant", 0) == 1 then
        return string.format("%+d st", util.round(12 * math.log(v, 2)))
      end
      return string.format("%.2f x", v)
    end)
  params:set_action("pitch", function(v)
    if pget("pitch_quant", 0) == 1 then
      v = 2 ^ (util.round(12 * math.log(v, 2)) / 12)
    end
    if engine.pitch then engine.pitch(v) end
  end)
  add_eng_control("spread", "spread", unit(0.5))
  add_eng_control("pan", "pan",
    controlspec.new(-1, 1, "lin", 0, 0.0, ""))
  add_eng_control("grain_level", "grain level",
    controlspec.new(0, 1.5, "lin", 0, 1.0, ""))
  -- granular character: per-grain size jitter + detune spread (both
  -- continuous from 0 = off), and a 3-way grain-envelope shape. shape is
  -- an option (engine wants 0/1/2, norns options are 1-based, so -1 in the
  -- action — same trick as `mode`).
  add_eng_control("grain_jitter", "grain jitter", unit(0.0))
  add_eng_control("grain_pitch_spread", "pitch spread",
    controlspec.new(0, 12, "lin", 0, 0.0, "st"))
  add_eng_option("grain_shape", "grain shape", { "HANN", "WELCH", "PERC" }, 1)

  -- MiClouds granular controls (GRAIN mode uses the Clouds voice when
  -- mi-UGens are installed; on the GrainBuf fallback these are stored but
  -- ignored — same guarded philosophy as the JPverb-only reverb params). the
  -- shared size/density/spread/pitch already remap to Clouds; these are the
  -- Clouds-specific attributes. PARAMS (and MIDI) only: VOICE's GRAIN face
  -- carries size/density.
  params:add_group("grp_clouds", "voice - clouds", 5)
  add_eng_control("clouds_pos", "grain position", unit(0.5))
  add_eng_control("clouds_tex", "grain texture", unit(0.5))
  add_eng_control("clouds_fb", "grain feedback", unit(0.0))
  add_eng_option("clouds_mode", "clouds mode",
    { "GRANULAR", "STRETCH", "LOOP", "SPECTRAL" }, 1)
  add_eng_control("clouds_lofi", "grain lofi", unit(0.0))

  params:add_group("grp_stretch", "voice - stretch", 5)
  -- mode swaps the playback synth in the engine: only the active algorithm
  -- costs CPU; OFF frees the SC voice entirely
  -- PLAY (clean straight loop = the exact recorded sample) is the
  -- DEFAULT so a fresh take plays back untouched; GRAIN/WARP/PV are switched
  -- on for mangling. appended (not reordered) so 1..4 keep their meaning.
  add_eng_option("mode", "mode", { "OFF", "GRAIN", "WARP", "PV", "PLAY" }, 5)
  add_eng_control("warp_window", "warp window",
    controlspec.new(0.05, 0.5, "exp", 0, 0.25, "s"))
  params:add_number("warp_overlaps", "warp overlaps", 1, 8, 4)
  params:set_action("warp_overlaps", function(v)
    if engine.warp_overlaps then engine.warp_overlaps(v) end
  end)
  add_eng_control("warp_rand", "warp rand", unit(0.0))
  add_eng_binary("pv_freeze", "pv freeze")

  -- ---- the layer decks ---------------------------------------------------
  -- Two more loop decks on softcut, beside the tape. Same shape, their own
  -- regions of the buffer. See doc/layers.md; the deck itself is lib/mdeck.lua.
  -- `pre` defaults to 1 (OVERDUB) unlike the tape's 0 (REPLACE): these are
  -- LAYERS, stacking is the job, and it is the loop-pedal gesture people
  -- already have in their hands. K1+K3 on the page erases one to start over.
  params:add_group("grp_layers", "layers", 26)
  params:add_number("layer_sel", "layer", 1, 2, 1)
  -- the BOUNCE: while ON (the default), arming a layer records the processed
  -- engine output instead of the raw input — resampling is just K2 on LAYERS.
  -- OFF = the decks follow cut_source like the tape always has. the SRC flag
  -- on TAPE and LAYERS shows the EFFECTIVE source either way.
  params:add_binary("layer_wet", "layers record the mix", "toggle", 1)
  params:set_action("layer_wet", function() ctx.update_cut_source() end)
  for n = 1, 2 do
    local id = "lay" .. n
    local function q(k) return id .. "_" .. k end
    local function deck() return ctx.layers[n] end
    -- load a wav straight into this deck (norns fileselect; the path rides the
    -- PSET, so a session reloads its layer material even with no deck wav)
    params:add_file(q("file"), "L" .. n .. " load file", _path.audio)
    params:set_action(q("file"), function(f) ctx.layer_load(deck(), f) end)
    params:add_binary(q("rec"), "L" .. n .. " record", "toggle", 0)
    params:set_action(q("rec"), function(v)
      -- arming: settle the record SOURCE before the head opens (the bounce
      -- may throw it WET), and open the loop so nothing you play is cut off;
      -- disarming: close the head, then close the loop around what you played
      if v == 1 then
        ctx.update_cut_source()
        Mdeck.arm_loop(deck())
        Mdeck.update_rec(deck())
      else
        Mdeck.update_rec(deck())
        Mdeck.close_loop(deck())
        ctx.update_cut_source()
      end
    end)
    params:add_binary(q("play"), "L" .. n .. " play", "toggle", 1)
    params:set_action(q("play"), function() Mdeck.update_level(deck()) end)
    params:add_control(q("level"), "L" .. n .. " level", unit(0.8))
    params:set_action(q("level"), function() Mdeck.update_level(deck()) end)
    params:add_control(q("rate"), "L" .. n .. " rate",
      controlspec.new(0.25, 4, "exp", 0, 1.0, "x"))
    params:set_action(q("rate"), function() Mdeck.update_rate(deck()) end)
    params:add_binary(q("reverse"), "L" .. n .. " reverse", "toggle", 0)
    params:set_action(q("reverse"), function() Mdeck.update_rate(deck()) end)
    params:add_control(q("start"), "L" .. n .. " loop start", fine_unit(0.0))
    params:set_action(q("start"), function() Mdeck.update_loop(deck()) end)
    params:add_control(q("end"), "L" .. n .. " loop end", fine_unit(1.0))
    params:set_action(q("end"), function() Mdeck.update_loop(deck()) end)
    params:add_control(q("pre"), "L" .. n .. " overdub", unit(1.0))
    params:set_action(q("pre"), function() Mdeck.update_rec(deck()) end)
    -- The join where the loop starts over. Short is a clean cut and a hard
    -- downbeat; long is a blend that hides the join landing mid-note.
    params:add_control(q("fade"), "L" .. n .. " seam",
      controlspec.new(0.001, 0.5, "exp", 0, 0.02, "s"))
    params:set_action(q("fade"), function() Mdeck.update_fade(deck()) end)
    -- Stereo width: 1 is the deck's own full left and right, 0 folds it to
    -- the middle. Two decks playing related material, both at full width, is
    -- a wall of sound with no room to hear either one.
    params:add_control(q("width"), "L" .. n .. " width", unit(1.0))
    params:set_action(q("width"), function() Mdeck.update_width(deck()) end)
    -- A momentary switch, so a footswitch can reach it. There is no key left
    -- for this: LAYERS already uses K2 and K3, and holding K1 is reserved for
    -- stop and erase on every page. So it lives in PARAMS, on MIDI and on the
    -- grid, the same as pad_chop. The automatic snap when a recording ends
    -- needs no key at all.
    add_momentary(q("snap"), "L" .. n .. " snap loop",
      function() ctx.layer_snap(deck()) end)
  end

  params:add_group("grp_tape", "tape", 9)
  params:add_binary("tape_rec", "tape record", "toggle", 0)
  -- mirror the SC side's workflow: arming with no overdub opens the loop to
  -- the full tape for a fresh take; stopping snaps the loop around the take
  -- and jumps the head to its start, so it plays back tight immediately.
  -- The layer decks do the same thing through Mdeck.arm_loop / close_loop.
  -- This is the older, hand-written copy, still here on purpose: lib/mtape.lua
  -- explains why and lists where the two differ. Change one, change both.
  params:set_action("tape_rec", function(v)
    if v == 1 then
      -- Replace means "record a new take", overdub means "add to the one you
      -- already have". Only the first of those is allowed to re-cut the loop
      -- when you stop. Without this mark, stopping an overdub set the loop to
      -- whatever stretch happened to go by, so every layer you stacked made
      -- the loop shorter, down towards a tenth of a second, with all the
      -- audio still sitting in the buffer. Mdeck.arm_loop draws the same line
      -- by asking whether the deck already holds anything.
      tape_arm_phase, tape_arm_was = nil, nil
      if pget("tape_pre", 0) == 0 then
        -- remember the loop this pass widens: a pass too short to be a loop
        -- puts it back (Mdeck.arm_loop does the same with arm_was)
        tape_arm_was = { pget("loop_start", 0), pget("loop_end", 1) }
        if (pget("loop_end", 1) - pget("loop_start", 0)) < 0.99 then
          Mtape.set_loop(0, 1)
        end
        tape_arm_phase = ctx.tape_phase
      end
    elseif not tape_arm_phase then
      -- an overdub, or a pass this action never opened: leave the loop alone
    elseif ctx.tape_phase > tape_arm_phase + 0.005 then
      Mtape.set_loop(tape_arm_phase, ctx.tape_phase)
      Mtape.jump_to(tape_arm_phase)
    elseif ctx.tape_phase < tape_arm_phase - 0.005 then
      -- head wrapped past the tape end mid-take: softcut loops can't cross
      -- the seam, so keep the full tape rather than snapping a wrong slice
      Mtape.set_loop(0, 1)
    elseif tape_arm_was then
      -- too short to be a loop (a mis-tap): give back the loop it widened
      -- instead of leaving the whole 60s tape playing
      Mtape.set_loop(tape_arm_was[1], tape_arm_was[2])
    end
    if v == 0 then tape_arm_phase, tape_arm_was = nil, nil end
    Mtape.update_tape_rec()
  end)
  params:add_control("tape_rate", "tape rate",
    controlspec.new(-2, 2, "lin", 0, 1.0, "x"))
  params:set_action("tape_rate", Mtape.update_tape_rate)
  params:add_binary("tape_reverse", "tape reverse", "momentary", 0)
  params:set_action("tape_reverse", Mtape.update_tape_rate)
  -- same fine quantum + span-scaled deltas as the window edges
  params:add_control("loop_start", "loop start", fine_unit(0.0))
  params:set_action("loop_start", Mtape.update_tape_loop)
  params:add_control("loop_end", "loop end", fine_unit(1.0))
  params:set_action("loop_end", Mtape.update_tape_loop)
  params:add_control("tape_pre", "tape overdub", unit(0.0))
  params:set_action("tape_pre", Mtape.update_tape_rec)
  params:add_binary("tape_freeze", "tape freeze", "toggle", 0)
  params:set_action("tape_freeze", Mtape.update_tape_rec)
  params:add_control("tape_fade", "tape fade",
    controlspec.new(0.001, 0.5, "exp", 0, 0.05, "s"))
  params:set_action("tape_fade", Mtape.set_fade)
  -- tape RECORD SOURCE (K1+E3 on TAPE): 0 = DRY raw input .. 1 = WET post-FX
  -- engine output — the tape as a print / resample stage. default DRY = the classic parallel-ADC tap, so nothing changes until
  -- you reach for it.
  params:add_control("cut_source", "tape source", unit(0.0))
  -- through the one source writer: while a layer bounce holds the send WET,
  -- turning the knob re-resolves rather than silently fighting it
  params:set_action("cut_source", function() ctx.update_cut_source() end)

  params:add_group("grp_filter", "filter", 4)
  add_eng_option("filt_type", "filter type", { "LP", "HP", "BP" }, 1)
  add_eng_control("cutoff", "cutoff",
    controlspec.new(20, 20000, "exp", 0, 20000, "hz"))
  add_eng_control("resonance", "resonance", unit(0.0))
  -- post-filter tanh saturation with makeup: louder AND dirtier up
  add_eng_control("drive", "drive", unit(0.0))

  -- ---- tracks 2 to 4 (mangler2) -------------------------------------------
  -- more engine drones on the same take: each its own mode, window, pitch,
  -- grain knobs, filter and level. Each id is track 1's with a `t<n>_`
  -- prefix, with the same range, so a knob means the same thing on every
  -- track. OFF by default: a track costs nothing until it is switched on.
  params:add_group("grp_tracks", "tracks", 2)
  -- which track VOICE and FILTER address (K3 held on either page steps it),
  -- and the ROUTE grid's cursor
  params:add_number("track_sel", "track (voice, filter)", 1, NTRACKS, 1)
  params:add_number("route_sel", "route cell", 1, #ROUTES, 1)
  for n = 2, NTRACKS do
    local pre, lab = "t" .. n .. "_", "t" .. n .. " "
    params:add_group("grp_t" .. n, "track " .. n, 26)
    add_eng_option(pre .. "mode", lab .. "mode", { "OFF", "GRAIN", "WARP", "PV", "PLAY" }, 1)
    add_eng_control(pre .. "level", lab .. "level", controlspec.new(0, 1.5, "lin", 0, 1.0, ""))
    add_eng_control(pre .. "pos_start", lab .. "win start", fine_unit(0.0))
    add_eng_control(pre .. "pos_end", lab .. "win end", fine_unit(1.0))
    add_eng_control(pre .. "scan", lab .. "scan rate", controlspec.new(-2, 2, "lin", 0, 1.0, "x"))
    add_eng_control(pre .. "pitch", lab .. "pitch", controlspec.new(0.25, 4, "exp", 0, 1.0, "x"))
    add_eng_control(pre .. "pan", lab .. "pan", controlspec.new(-1, 1, "lin", 0, 0.0, ""))
    add_eng_control(pre .. "pos_jitter", lab .. "jitter", unit(0.0))
    add_eng_control(pre .. "size", lab .. "size", controlspec.new(0.01, 0.5, "exp", 0, 0.1, "s"))
    add_eng_control(pre .. "density", lab .. "density", controlspec.new(1, 200, "exp", 0, 20, "hz"))
    add_eng_control(pre .. "spread", lab .. "spread", unit(0.5))
    add_eng_control(pre .. "grain_jitter", lab .. "grain jitter", unit(0.0))
    add_eng_control(pre .. "grain_pitch_spread", lab .. "pitch spread",
      controlspec.new(0, 12, "lin", 0, 0.0, "st"))
    add_eng_option(pre .. "grain_shape", lab .. "grain shape", { "HANN", "WELCH", "PERC" }, 1)
    add_eng_control(pre .. "clouds_pos", lab .. "grain position", unit(0.5))
    add_eng_control(pre .. "clouds_tex", lab .. "grain texture", unit(0.5))
    add_eng_control(pre .. "clouds_fb", lab .. "grain feedback", unit(0.0))
    add_eng_option(pre .. "clouds_mode", lab .. "clouds mode",
      { "GRANULAR", "STRETCH", "LOOP", "SPECTRAL" }, 1)
    add_eng_control(pre .. "clouds_lofi", lab .. "grain lofi", unit(0.0))
    add_eng_control(pre .. "warp_window", lab .. "warp window",
      controlspec.new(0.05, 0.5, "exp", 0, 0.25, "s"))
    params:add_number(pre .. "warp_overlaps", lab .. "warp overlaps", 1, 8, 4)
    params:set_action(pre .. "warp_overlaps", function(v)
      local f = engine[pre .. "warp_overlaps"]
      if f then f(v) end
    end)
    add_eng_control(pre .. "warp_rand", lab .. "warp rand", unit(0.0))
    add_eng_binary(pre .. "pv_freeze", lab .. "pv freeze")
    add_eng_option(pre .. "filt_type", lab .. "filter type", { "LP", "HP", "BP" }, 1)
    add_eng_control(pre .. "cutoff", lab .. "cutoff", controlspec.new(20, 20000, "exp", 0, 20000, "hz"))
    add_eng_control(pre .. "resonance", lab .. "resonance", unit(0.0))
  end
  -- the sends: one track's filtered output into another track's filter
  params:add_group("grp_routing", "routing", #ROUTES)
  for _, r in ipairs(ROUTES) do
    add_eng_control(r.id, "send " .. r.from .. " > " .. r.to, unit(0.0))
  end

  params:add_group("grp_delay", "delay", 4)
  add_eng_control("delay_time", "delay time",
    controlspec.new(0.01, 2, "exp", 0, 0.3, "s"))
  -- tempo sync (DELAY K1+E3): FREE = the time knob; a division = delay_time
  -- follows the clock (re-asserted on tempo changes from the redraw tick)
  params:add_option("delay_sync", "delay sync",
    { "FREE", "1/16", "1/8", "1/8.", "1/4", "1/4.", "1/2" }, 1)
  params:set_action("delay_sync", function() sync_delay_time(true) end)
  -- 0..1 knob curved to the actual 0..0.98 feedback coefficient (fb_curve):
  -- a smooth "few -> many (10+) -> near-infinite" sweep, not a top-end cliff.
  add_eng_control("delay_fb", "feedback", unit(0.3), fb_curve)
  -- FX SEND response curve: the engine crossfades the wet with an equal-power
  -- .sqrt (Engine_Mangler2.sc), so a raw 3% knob already reads ~17% wet ("way too
  -- blunt"). `square` makes the effective wet gain LINEAR in the knob — a
  -- progressive fade (dry stays ~full at the bottom, full wet at 1). same reverb.
  add_eng_control("delay_mix", "delay mix", unit(0.0), square)

  -- the reverb is JPverb's FULL attribute set (guarded → FreeVerb
  -- fallback in the engine). every knob maps to a real JPverb arg — nothing
  -- hardcoded. REVERB face reaches mix/size/decay/damp (E2/E3 + K1 alt);
  -- the other 11 (early/mod/EQ/cuts/shimmer) live in PARAMS + the WASH/BLOOM
  -- throws. shimmer surges on the BLOOM key.
  params:add_group("grp_reverb", "reverb", 15)
  add_eng_control("rev_decay", "reverb decay",
    controlspec.new(0.1, 30, "exp", 0, 2.0, "s"))
  add_eng_control("rev_damp", "reverb damp", unit(0.3))
  add_eng_control("rev_size", "reverb size",
    controlspec.new(0.5, 5, "lin", 0, 1.0, ""))
  add_eng_control("rev_early", "early diffusion", unit(0.7))
  add_eng_control("rev_moddepth", "mod depth", unit(0.1))
  add_eng_control("rev_modfreq", "mod freq",
    controlspec.new(0, 10, "lin", 0, 2.0, "hz"))
  add_eng_control("rev_low", "low decay", unit(1.0))
  add_eng_control("rev_mid", "mid decay", unit(1.0))
  add_eng_control("rev_high", "high decay", unit(1.0))
  add_eng_control("rev_lowcut", "low crossover",
    controlspec.new(20, 2000, "exp", 0, 500, "hz"))
  add_eng_control("rev_highcut", "high crossover",
    controlspec.new(200, 20000, "exp", 0, 2000, "hz"))
  add_eng_control("rev_mix", "reverb mix",
    unit(0.0), square)   -- progressive fade (see delay_mix)
  -- shimmer: pitch-shifted reverb feedback (climbs in octaves into a pad)
  add_eng_control("shimmer", "shimmer", unit(0.0))
  add_eng_control("shimmer_pitch", "shimmer pitch",
    controlspec.new(-12, 24, "lin", 1, 12, "st"))
  add_eng_control("shimmer_tone", "shimmer tone",
    controlspec.new(500, 12000, "exp", 0, 4500, "hz"))

  -- the BEAT REPEAT (see repeat_start): held, a stutter on the clock.
  -- momentary, so a footswitch or a MIDI note holds it
  params:add_group("grp_repeat", "beat repeat", 2)
  params:add_binary("beat_repeat", "beat repeat", "momentary", 0)
  params:set_action("beat_repeat", function(v)
    if v == 1 then repeat_start() else repeat_release() end
  end)
  params:add_option("repeat_div", "repeat length", REPEAT_NAMES, 3)
  params:set_action("repeat_div", function()
    -- a new division while it holds: re-capture now (a roll), or wait on it
    if pget("beat_repeat", 0) ~= 1 then return end
    if repeat_on then engine.beat_repeat(repeat_secs()) else repeat_start() end
  end)

  -- polyphonic voices: the per-note/per-pad layer that coexists with the
  -- drone. `pad_input` reroutes MIDI + grid note-pads to voices instead of
  -- the mono drone pitch (default OFF = existing behavior). voices = poly
  -- cap (oldest-steal in the engine), voice_atk/voice_rel shape each note.
  params:add_group("grp_voice", "pads - voices", 10)
  params:add_binary("pad_input", "pad input", "toggle", 0)
  params:set_action("pad_input", function(v)
    if v == 0 then ctx.pads_all_off() end   -- don't strand voices on switch
  end)
  -- the PADS slice SELECTOR (id kept as `seq_slice` — ids are never renamed, so
  -- PMAP/PSET references survive; the sequencer that shared it is gone). its
  -- action is the ONLY writer of ctx.pad_cursor, so the sound-lock editors
  -- (pad_voice/pad_pitch) follow the selected slice.
  params:add_number("seq_slice", "slice", 0, 7, 0)
  params:set_action("seq_slice", function(v)
    ctx.pad_cursor = v
    ctx.pad_edit_sync()
  end)
  -- SOUND-LOCK EDITORS (Elektron data-knob style): pad_voice + pad_pitch read/
  -- write the pad under pad_cursor, so selecting a pad and turning these edits
  -- THAT pad's lock. GRAIN = granular texture, SLICE = clean chop. MIDI-map them
  -- to edit the current pad live; the 8 locks ride the PSET (padlock_pset_*).
  params:add_option("pad_voice", "pad voice (sel)", { "GRAIN", "SLICE" }, 1)
  params:set_action("pad_voice", function(v)
    if not ctx.pad_sync then ctx.pad_type[ctx.pad_cursor] = v - 1 end
  end)
  params:add_number("pad_pitch", "pad pitch (sel)", -24, 24, 0,
    function(p) local v = p:get(); return (v >= 0 and "+" or "") .. v .. "st" end)
  params:set_action("pad_pitch", function(v)
    if not ctx.pad_sync then ctx.pad_pitch[ctx.pad_cursor] = v end
  end)
  params:add_number("voices", "poly voices", 1, 16, 8)
  params:set_action("voices", function(v)
    if engine.voices then engine.voices(v) end
  end)
  add_eng_control("voice_atk", "voice attack",
    controlspec.new(0.001, 1, "exp", 0, 0.005, "s"))
  add_eng_control("voice_rel", "voice release",
    controlspec.new(0.01, 4, "exp", 0, 0.6, "s"))
  -- pad voice LEVEL (per-note amp): the chord-safe default (0.3, the
  -- level that stops poly stacks slamming the master limiter). read at note-on.
  params:add_control("pad_level", "pad level", unit(0.3))
  -- CHOP the pads onto the take's own attacks. momentary (not a trigger) so it
  -- is MIDI-learnable — the whole point is a footswitch. Firing it with no
  -- transients found, or on a fresh buffer, puts the pads back to even slices.
  add_momentary("pad_chop", "chop to transients", ctx.pad_chop)
  add_momentary("pad_even", "back to even slices", function()
    ctx.pads_uncut()
    print("mangler: pads back to even slices")
  end)

  -- the pad SEQUENCER (lib/mseq.lua): a generated pattern on the clock that
  -- plays the pads. Every knob rebuilds the pattern in its action, so the
  -- PADS page reads it at rest and no frame computes it.
  params:add_group("grp_steps", "pads - sequencer", 7)
  params:add_binary("step_run", "sequencer run", "toggle", 0)
  params:set_action("step_run", function(v)
    if v == 1 then
      Mseq.start()
      print("mangler: sequencer running — " .. math.floor(pget("step_fill", 4) + 0.5)
        .. " of " .. math.floor(pget("step_len", 4) + 0.5) .. " steps play the pads")
    else
      Mseq.stop()
    end
  end)
  params:add_option("step_div", "step length",
    { "2 BAR", "1 BAR", "1/2", "1/4", "1/8", "1/16" }, 2)
  params:set_action("step_div", function() Mseq.restart() end)
  params:add_number("step_len", "steps", 1, 16, 4)
  params:set_action("step_len", function() Mseq.rebuild() end)
  params:add_number("step_fill", "steps that play", 0, 16, 4)
  params:set_action("step_fill", function() Mseq.rebuild() end)
  params:add_option("step_order", "pad order", Mseq.ORDERS, 1)
  params:set_action("step_order", function() Mseq.rebuild() end)
  params:add_control("step_chance", "step chance", unit(1.0))
  params:add_control("step_gate", "step gate",
    controlspec.new(0.05, 1, "lin", 0, 1, ""),
    function(p)
      local v = p:get()
      return v >= 0.999 and "LEGATO" or string.format("%d%%", math.floor(v * 100 + 0.5))
    end)

  -- chromatic note input (MIDI notes + typing keyboard): all of it drives
  -- the same `pitch` param as the encoder and any mapped CC, in lockstep
  params:add_group("grp_keys", "keys", 5)
  params:add_binary("keys_enable", "note input", "toggle", 1)
  params:add_number("midi_channel", "midi channel", 0, 16, 0,
    function(p)
      local v = p:get()
      return v == 0 and "any" or tostring(v)
    end)
  params:add_number("root_note", "root note", 0, 127, 60,
    function(p) return mu.note_num_to_name(p:get(), true) end)
  -- typing-keyboard octave (Z/X); MIDI keyboards shift octaves themselves
  params:add_number("kb_octave", "keys octave", -3, 3, 0,
    function(p) return string.format("%+d", p:get()) end)
  params:add_binary("pitch_quant", "pitch quantize", "toggle", 0)
  params:set_action("pitch_quant", function()
    -- re-send pitch so the engine snaps (or unsnaps) immediately
    params:lookup_param("pitch"):bang()
  end)

  -- gesture looper: records the param stream (MOTION_IDS) and replays it
  -- (see lib/mmotion). rec/play are binaries so a footswitch can punch overdubs
  -- and start/stop the loop; lane/depth drive the MOTION page. all Lua-only —
  -- no engine command, so the fingerprint is unchanged.
  params:add_group("grp_motion", "motion", 6)
  params:add_binary("motion_rec", "motion record", "toggle", 0)
  params:set_action("motion_rec", function(v) ctx.motion.set_armed(v == 1) end)
  params:add_binary("motion_play", "motion play", "toggle", 0)
  params:set_action("motion_play", function(v) ctx.motion.set_playing(v == 1) end)
  -- one lane per recordable param at most, so the selector reaches them all
  params:add_number("motion_lane", "motion lane", 0, #ctx.motion.MOTION_IDS, 0,
    function(p)
      local ids = ctx.motion.lane_ids
      local n = #ids
      local v = math.min(p:get(), n)
      if n == 0 or v == 0 then return "-" end
      return ids[v]
    end)
  -- which rows MOTION's encoders address: the lanes, or one modulator
  params:add_option("mod_focus", "motion focus", { "LANES", "LFO 1", "LFO 2" }, 1)
  params:add_control("motion_depth", "motion depth", unit(1.0))
  -- settable loop length (K1+E2 on MOTION). 0 = AUTO (the recorded length);
  -- >0 retimes the loop's playback SPEED without touching the stored gesture.
  params:add_control("motion_len", "motion length",
    controlspec.new(0, 60, "lin", 0.5, 0, "s"))
  params:set_action("motion_len", function(v) ctx.motion.set_len(v) end)

  -- scenes / morph / safe state (see lib/mscenes). all Lua-only — no
  -- engine command, so the fingerprint is unchanged. the ACTIONS here are
  -- momentary binaries rather than triggers: a trigger can't be MIDI-learned,
  -- and the whole point is a footswitch that captures, recalls, rescues or
  -- throws. every action fires on the press edge (v == 1) only — a stray 0
  -- from params:bang() or a pset read must never do anything.
  params:add_group("grp_scene", "scenes", 12)
  -- ONE selector, three jobs: the slot K2 recalls, K3 captures into, and the
  -- morph aims at. (there used to be two more — `morph A`/`morph B` — on the
  -- alt layer, where you couldn't see them. see mscenes' morph_from.)
  -- slot 0 is the ◄ cell — the way back (mscenes branches on it)
  params:add_number("scene_slot", "scene slot", 0, 8, 1)
  params:set_action("scene_slot", function()
    -- re-aim a sweep in progress; at rest, picking a slot must stay silent
    if pget("scene_morph_amt", 0) > 0 then Mscenes.touch() end
  end)
  -- THE performance knob: sweeps from the sound you have toward the selected
  -- slot. MIDI-map it to a fader/pedal, or record it with the gesture looper
  -- (it's in MOTION_IDS — one lane replays the whole sweep). only this writes
  -- params, and only from the next frame's tick (mscenes coalesces so a fast
  -- CC can't flood the engine).
  params:add_control("scene_morph_amt", "morph amount", unit(0.0))
  params:set_action("scene_morph_amt", function() Mscenes.touch() end)
  -- when a recall lands: NOW, on the next BEAT or BAR, or GLIDE (the morph
  -- sweeps there over `scene_glide` beats, then the scene lands)
  params:add_option("scene_recall_mode", "recall quantize",
    { "NOW", "BEAT", "BAR", "GLIDE" }, 1)
  params:add_number("scene_glide", "glide beats", 1, 16, 4)
  -- what CAP stores: the whole mangle, or just the wet path (an FX preset
  -- that lands over whatever material is playing — Octatrack-style)
  params:add_option("scene_scope", "capture scope", { "ALL", "FX" }, 1)
  -- actions on the selected slot (also the SCENE page's K2/K3)
  add_momentary("scene_capture", "capture to slot", Mscenes.capture)
  add_momentary("scene_recall", "recall slot", Mscenes.recall)
  -- stomp through a set: advance to the next FILLED slot and recall it
  -- (cycling; honors BEAT/BAR quantize). MIDI-map a footswitch.
  add_momentary("scene_next", "next scene", Mscenes.next)
  add_momentary("scene_clear", "clear slot", Mscenes.clear)
  -- the safety net (the ◄ cell's two actions, for a footswitch): mark a
  -- state, then get back to it. control state only — it never touches the
  -- buffer or the tape audio.
  add_momentary("scene_safe_capture", "mark safe state", Mscenes.safe_capture)
  add_momentary("scene_safe_restore", "restore safe state", Mscenes.safe_restore)
  -- chaos: HOLD it for a bounded random throw, release to land back on the
  -- safe state (it marks one for you if you never did). a footswitch or grid
  -- pad you can lean on — the release is what makes it safe to press.
  params:add_binary("chaos_throw", "chaos throw", "momentary", 0)
  params:set_action("chaos_throw", function(v)
    if v == 1 then Mscenes.chaos() else Mscenes.chaos_release() end
  end)

  -- ORBIT: the instrument wanders between your captured scenes by itself,
  -- one partial morph leg at a time, never fully arriving. all Lua, driven
  -- through the same morph engine and params as a hand on the knob.
  -- (these groups MUST sit after grp_scene's last param, chaos_throw — a
  -- group's declared count claims the params that FOLLOW it, and an insert
  -- mid-group silently corrupts the whole PARAMS menu on device.)
  params:add_group("grp_orbit", "orbit", 3)
  params:add_binary("orbit_on", "orbit run", "toggle", 0)
  params:set_action("orbit_on", function(v) Mscenes.orbit_set(v == 1) end)
  params:add_control("orbit_rate", "orbit drift",
    controlspec.new(2, 60, "lin", 1, 12, "s"))
  params:add_control("orbit_reach", "orbit reach",
    controlspec.new(0.05, 1, "lin", 0, 0.5, ""))

  -- EROSION: window-synced decay in PLAY mode. `erode` is how much of each
  -- loop pass is rewritten aged; `wear` is how dark the aging filter sits.
  params:add_group("grp_erode", "erosion", 2)
  params:add_control("erode", "erode", unit(0.0))
  params:set_action("erode", function(v)
    -- interlock: erode and regen are both free-running write heads on the
    -- same buffer. engaging one disengages the other, so the conflict is
    -- impossible rather than documented. no recursion: each interlock only
    -- acts when its own value is rising.
    if v > 0 and pget("regen", 0) > 0 then params:set("regen", 0) end
    if engine.erode then engine.erode(v) end
    if Mpages.eroding() then strip_wrote() end
  end)
  add_eng_control("wear", "wear", unit(0.5))

  -- the two modulators (lib/mlfo.lua). LAST, so every target already exists
  -- and the target option can carry the targets' own names.
  Mlfo.add_params(function(id, name, n) params:add_group(id, name, n) end)
  Mout.add_params()   -- ...and the modulation out, which reads them
  Mosc.add_params()   -- ...and the visuals link (OSC), which reads the rest

  -- PSETs persist the audio too: PARAMS > PSET > SAVE/LOAD/DELETE round-trip
  -- the softcut buffers (mtape) AND the granular engine's record
  -- buffer — the live take, as an L/R wav pair beside the pset (ctx.take_pset_*
  -- → engine write_take/read_take). the hooks are SHARED: each module/helper
  -- does its own half (mtape the tape audio, mscenes the scene bank + safe
  -- snapshot as a lua table, the take helpers the engine buffer).
  -- ONE list of the parts, walked by all three hooks, so a new part cannot be
  -- added to two of them. Each part runs under pcall: one that throws (a full
  -- card on the tape wav) must not silently skip the parts after it. ORDER
  -- matters on read: the take restores before the pad locks, which bring
  -- back the chop the take restore drops.
  local PSET_PARTS = {
    { Mtape.pset_write, Mtape.pset_read, Mtape.pset_delete, "tape" },
    { Mdeck.pset_write, Mdeck.pset_read, Mdeck.pset_delete, "layers" },
    { Mscenes.pset_write, Mscenes.pset_read, Mscenes.pset_delete, "scenes" },
    { Mmotion.pset_write, Mmotion.pset_read, Mmotion.pset_delete, "motion" },
    { ctx.take_pset_write, ctx.take_pset_read, ctx.take_pset_delete, "take" },
    { ctx.padlock_pset_write, ctx.padlock_pset_read, ctx.padlock_pset_delete,
      "pad locks" },
  }
  local function each_part(k, number)
    for _, part in ipairs(PSET_PARTS) do
      local ok, err = pcall(part[k], number)
      if not ok then
        print("mangler: pset " .. part[4] .. " failed — " .. tostring(err))
      end
    end
  end
  params.action_write = function(filename, name, number) each_part(1, number) end
  params.action_read = function(filename, silent, number)
    -- params:read fires tape_rec before the loop points (file order), so a
    -- PSET saved while the tape recorded opened a pass against the OLD
    -- session; its disarm then re-cut the loop just restored. The deck twin
    -- of this is Mdeck.pset_read's abort_loop.
    tape_arm_phase, tape_arm_was = nil, nil
    -- norns saves a momentary binary like any other, so a PSET saved while
    -- a footswitch held the repeat loads it held, with no release to come
    if pget("beat_repeat", 0) == 1 then params:set("beat_repeat", 0) end
    -- the OSC link is about this room, not a sound: a PSET never changes it
    Mosc.cfg_reload()
    each_part(2, number)
  end
  params.action_delete = function(filename, name, number) each_part(3, number) end

  params:bang()
end

-- ============================================================================
-- norns callbacks
-- ============================================================================

function init()
  print("mangler: init() called")
  init_params()
  ctx.undo_forget()   -- an undo pair from the last session is not this one's
  Mtape.init_tape()
  for _, d in ipairs(ctx.layers) do Mdeck.start(d) end
  Minput.init_midi()
  Mgrid.connect()
  -- a Launchpad plugged in (or out) after load is picked up: norns calls
  -- these on MIDI hot-plug. the previous callbacks are kept and restored.
  prev_midi_add, prev_midi_remove = midi.add, midi.remove
  midi.add = function(dev)
    if prev_midi_add then prev_midi_add(dev) end
    Mgrid.hotplug()
  end
  midi.remove = function(dev)
    if prev_midi_remove then prev_midi_remove(dev) end
    Mgrid.hotplug(dev)   -- still in midi.devices while this runs
  end
  print("mangler: init() done, params built")

  -- the norns SYSTEM aux reverb sits after the engine and colors everything;
  -- if another script left it on, "dry" playback isn't — say so at load
  if params.lookup["reverb"]
      and tostring(params:string("reverb")):lower() ~= "off" then
    print("mangler: NOTE — the SYSTEM reverb is ON; it adds reverb mangler"
      .. " does not control (turn it off under PARAMS > REVERB)")
  end

  local function watch(name, fn)
    -- poll.set returns nil when the engine doesn't expose the poll (stale
    -- compiled engine after a deploy without restart) — warn, don't crash
    local p = poll.set(name, fn)
    if p == nil then
      print("mangler: poll '" .. name .. "' missing — old engine? RESTART needed")
      return
    end
    p.time = 1 / FPS
    p:start()
    polls[#polls + 1] = p
  end
  watch("play_phase", function(v) ctx.play_phase = v end)
  watch("play_phase2", function(v) ctx.play_phase2 = v; ctx.play_phases[2] = v end)
  watch("play_phase3", function(v) ctx.play_phases[3] = v end)
  watch("play_phase4", function(v) ctx.play_phases[4] = v end)
  watch("rec_phase", function(v) ctx.rec_phase = v end)
  watch("rec_amp", function(v) ctx.rec_amp = v end)
  watch("amp_in_l", function(v) ctx.amp_in[1] = v end)
  watch("amp_in_r", function(v) ctx.amp_in[2] = v end)
  watch("amp_out_l", function(v) ctx.amp_out[1] = v end)
  watch("amp_out_r", function(v) ctx.amp_out[2] = v end)

  -- one frame of the instrument
  local function frame_tick()
    ctx.frame = ctx.frame + 1
    ctx.idle_dim = ctx.frame - ctx.last_input > FPS * 120
    sync_delay_time()    -- keep a synced delay on the clock (writes when off)
    sync_window_len()    -- ...and a locked window's length, on a tempo move
    tick_rec_wait()        -- a start-on-sound take begins at the sound
    Mpages.erosion_tick()  -- count loop passes while the take erodes
    tick_take_strip()      -- repaint the strip once regen and erosion stop
    Mwav.load_tick()   -- fill a loaded/restored waveform a batch/frame
    Mpages.update_wave()
    Mpages.update_tape_wave()
    -- the modulators: they send the engine a swung value and never write a
    -- param, so nothing below (motion, scenes) can see or record them
    Mlfo.tick(max(ctx.amp_in[1], ctx.amp_in[2]))
    Mmotion.tick()   -- advance + replay the gesture loop
    -- apply a pending morph sweep. AFTER motion, which may have just
    -- replayed a recorded scene_morph_amt move for us to act on.
    Mscenes.tick()
    Mout.tick()   -- after the morph and the LFOs moved: send what they are now
    Mosc.tick()   -- the visuals link: the same frame's state, as OSC
    tick_keys()  -- the K1+K3 erase arc fires AT its threshold
    -- never draw over the system menu; the grid stays live inside it
    if norns.menu.status() == false then redraw() end
    Mgrid.redraw()
  end
  -- every per-frame job runs in this ONE coroutine, so an error must not end
  -- it: a dead clock freezes the screen, the morph, motion and the grid
  -- together, and with the frame counter stopped every key press reads as a
  -- tap. The frame is caught, reported (at most every 5 seconds, not 15 times
  -- a second) and the next one runs.
  local last_err_frame = -1e9
  redraw_clock = clock.run(function()
    while true do
      clock.sleep(1 / FPS)
      local ok, err = pcall(frame_tick)
      if not ok and ctx.frame - last_err_frame >= FPS * 5 then
        last_err_frame = ctx.frame
        print("mangler: frame error, the instrument keeps running — " .. tostring(err))
      end
    end
  end)

  redraw()
  Mgrid.redraw()
end

function cleanup()
  for _, p in ipairs(polls) do p:stop() end
  if redraw_clock then clock.cancel(redraw_clock) end
  if export_clock then clock.cancel(export_clock) end  -- stop a pending export
  export_clock, export_next = nil, nil
  ctx.cancel_task()     -- ...and a conversion in flight
  ctx.record_cancel()   -- a recording pass mid-flight: stop the tape with it
  Mwav.cancel_load()  -- close any in-flight waveform read
  Mseq.stop()          -- the sequencer's clock, and its voice
  repeat_release()     -- a held beat repeat...
  if repeat_clock then clock.cancel(repeat_clock) end   -- ...and its clock
  Mlfo.restore_all()   -- every modulated knob's own value back to the engine
  ctx.pads_all_off()   -- release any held pad voices before teardown
  Minput.cleanup()
  midi.add, midi.remove = prev_midi_add, prev_midi_remove
  Mgrid.cleanup()
  Mtape.cleanup()      -- (softcut voices are reset by norns after cleanup)
  Mscenes.cleanup()    -- cancel a queued (quantized) scene recall, same reason
end


-- step through the stations (E1, and the Launchpad's arrows). The page name
-- pops big for a moment: the stations scroll past faster than the 1x title
-- reads, and finding the page mid-set should not need squinting (mpages
-- draws the overlay while this is armed).
function ctx.step_page(d)
  ctx.page = clamp(ctx.page + d, 1, #PAGES)
  ctx.page_flash = ctx.frame + math.floor(FPS * 0.7)
end

function enc(n, d)
  ctx.last_input = ctx.frame
  if n == 1 then
    if ctx.alt then
      -- K1+E1 = the everything-knob: morph toward the selected scene from
      -- ANY page (sweeping home to 0 lands exactly where you started)
      if params.lookup["scene_morph_amt"] then
        params:delta("scene_morph_amt", d)
        ctx.flash_id = "scene_morph_amt"
        ctx.flash_until = ctx.frame + math.floor(FPS * 1.2)
      end
    else
      ctx.step_page(d)
    end
  else
    local id = enc_param(n)
    if id == "@win_move" then
      move_pair("pos_start", "pos_end", d)
    -- the LAYERS encoders address whichever deck is selected, so they resolve
    -- to a param id at turn time rather than being fixed in ENC_MAP
    elseif id == "@lay_level" or id == "@lay_rate" or id == "@route_amt" then
      -- delta the REAL param, but keep `id` as the compound target: the footer
      -- matches its flash against the slot's id, and the resolver turns it back
      -- into a value for display. (@win_move works for exactly this reason.)
      local real = ctx.enc_target(id)
      params:delta(real, fine_delta(real, d))
    elseif id == "@lay_move" then
      local dk = ctx.layer_sel()
      move_pair(Mdeck.p(dk, "start"), Mdeck.p(dk, "end"), d)
    elseif id == "@mo_sel" then
      -- one walk over the rows MOTION draws: no lane (0), the lanes, then
      -- the two modulators
      local n = #ctx.motion.lane_ids
      local f = math.floor(pget("mod_focus", 1) + 0.5)
      local cur = f > 1 and n + f - 1
        or clamp(math.floor(pget("motion_lane", 0) + 0.5), 0, n)
      local nxt = clamp(cur + d, 0, n + 2)
      if nxt > n then
        params:set("mod_focus", nxt - n + 1)
      else
        params:set("mod_focus", 1)
        params:set("motion_lane", nxt)
      end
    elseif id and params.lookup[id] then
      params:delta(id, fine_delta(id, d))
    else
      id = nil
    end
    if id then
      -- mark the param actively-turning: its footer value swells for ~1.2s
      ctx.flash_id, ctx.flash_until = id, ctx.frame + math.floor(FPS * 1.2)
    end
  end
  redraw()
end

function key(n, z)
  ctx.last_input = ctx.frame
  if n == 1 then
    ctx.alt = (z == 1)
    -- K1 down during a tap-or-hold key (TAKE K3) aborts it: K1+K3 is the
    -- eraser's gesture, and the hold must not land under another word
    if z == 1 then
      for k = 2, 3 do
        local st = key_state[k]
        if st.def and st.def.hold and not st.fired then
          st.fired, st.aborted = true, true
        end
      end
    end
    -- releasing K1 ABORTS a pending K1+K3 erase. the arc is gated on K1, so
    -- letting go reads as "abort" — honour that instead of firing anyway. (you
    -- can't navigate stations while K1 is held — K1+E1 is the morph — so the
    -- erase can also never retarget onto a different station's material.)
    if z == 0 and ctx.k13_frame and not ctx.k13_fired then
      -- mark it RESOLVED (not just clear the arc) so the still-held K3's release
      -- doesn't fall into the dry/erase tap branch and fire DRY after the abort.
      ctx.k13_frame, ctx.k13_fired = nil, true
    end
    redraw()
    return
  end
  local st = key_state[n]
  ctx.held[n] = (z == 1)
  if z == 1 then
    local def = key_def(n)
    st.def, st.frame, st.engaged, st.unlatched = def, ctx.frame, false, false
    st.fired, st.aborted, st.page = false, false, ctx.page
    if def then
      if def.hold then
        -- tap or hold: nothing fires on the press (tick_keys and the release)
      elseif def.dryerase then          -- K1+K3: DRY on tap, ERASE at the arc
        ctx.k13_frame, ctx.k13_fired = ctx.frame, false
        -- what the arc will erase is fixed NOW (SCENE: the slot under the
        -- finger, before a running orbit can re-aim the selector)
        ctx.k13_slot = math.floor(pget("scene_slot", 1) + 0.5)
      elseif def.pon then           -- punchable
        if def.lit and def.lit() then
          def.poff()                -- already latched: press = off
          -- and REMEMBER that this press cancelled. It leaves engaged false,
          -- same as a pon that declined — but the release must not then run
          -- def.tap() and undo the cancel.
          st.unlatched = true
        else
          def.pon()
          st.engaged = true
        end
      elseif def.act then           -- tap-cycle: fires on the press
        def.act()
      end
    end
  else
    local def = st.def
    st.def = nil
    if def then
      if def.hold then
        -- tap = the def's tap; between the tap and the arc = the abort zone
        if not st.fired and ctx.frame - st.frame < TAP_FRAMES then def.tap() end
        st.fired = false
      elseif def.dryerase then
        local dt = ctx.frame - (ctx.k13_frame or ctx.frame)
        -- tap = DRY; the frames between tap and arc = the abort zone
        if not ctx.k13_fired and dt < TAP_FRAMES then ctx.fx_dry() end
        ctx.k13_frame, ctx.k13_fired = nil, false
      elseif st.engaged then
        local dt = ctx.frame - st.frame
        if dt < TAP_FRAMES and def.tap then
          def.tap()               -- tap with its own meaning (RCL = commit)
        elseif def.poff and (def.gate or dt >= TAP_FRAMES) then
          def.poff()
        end
        -- else: a tap — it latches, still engaged with the finger off
      elseif def.tap and not st.unlatched
             and ctx.frame - st.frame < TAP_FRAMES then
        def.tap()                 -- tap on a def whose pon declined to engage
      end
    end
    -- belt-and-braces: the PADS audition voice must never strand
    if n == 2 and ctx.pad_held[8] then ctx.pad_trigger(8, 0, 0) end
  end
  redraw()
end

function redraw()
  Mpages.redraw()
end
